CREATE OR REPLACE FUNCTION "app_private"."access_profile_can_delegate_institution"("p_permission_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.has_platform_permission(delegation.platform_permission_code)
  from app_private.access_profile_institution_delegations delegation
  where delegation.institution_permission_id=p_permission_id and delegation.status='active'
$$;


ALTER FUNCTION "app_private"."access_profile_can_delegate_institution"("p_permission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_can_delegate_principal"("p_capability_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(bool_or(app_private.has_platform_permission(delegation.platform_permission_code)),false)
  from app_private.access_profile_principal_delegations delegation
  where delegation.capability_id=p_capability_id and delegation.status='active'
$$;


ALTER FUNCTION "app_private"."access_profile_can_delegate_principal"("p_capability_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_capability_catalog_guard"("p_domain" "text", "p_profile_id" "uuid" DEFAULT NULL::"uuid", "p_assignment_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actual_profile_id uuid:=p_profile_id;valid_pair boolean:=true;
begin
  if p_assignment_id is not null then
    if p_domain='platform' then
      select membership.role_id, p_profile_id is null or membership.role_id=p_profile_id
        into actual_profile_id,valid_pair from public.platform_memberships membership where membership.id=p_assignment_id;
    elsif p_domain='institution' then
      select assignment.role_id, p_profile_id is null or assignment.role_id=p_profile_id
        into actual_profile_id,valid_pair from public.institution_role_assignments assignment where assignment.id=p_assignment_id;
    elsif p_domain='principal' then
      select context_permission.source_template_id,
        p_profile_id is null or context_permission.source_template_id=p_profile_id
        into actual_profile_id,valid_pair from public.guardian_context_permissions context_permission where context_permission.id=p_assignment_id;
    else raise invalid_parameter_value using message='unsupported profile domain';end if;
    if actual_profile_id is null or not coalesce(valid_pair,false) then
      raise no_data_found using message='assignment does not belong to profile';end if;
  end if;
  return app_private.superadmin_access_profile_capability_catalog(p_domain,actual_profile_id,p_assignment_id);
end $$;


ALTER FUNCTION "app_private"."access_profile_capability_catalog_guard"("p_domain" "text", "p_profile_id" "uuid", "p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_create_internal"("p_actor" "uuid", "p_draft" "jsonb", "p_source_template_id" "uuid" DEFAULT NULL::"uuid", "p_source_template_version" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare domain text:=p_draft->>'domain';profile_id uuid;generated_code text;
  capability jsonb;capabilities jsonb:=coalesce(p_draft->'capabilities','[]'::jsonb);permission_id uuid;
begin
  if p_actor is distinct from app_private.current_person_id() or domain not in('platform','institution')
    or nullif(btrim(p_draft->>'name'),'') is null or char_length(btrim(p_draft->>'name'))>120
    or jsonb_typeof(capabilities)<>'array' or jsonb_array_length(capabilities)>500 then
    raise invalid_parameter_value using message='invalid profile draft';
  end if;
  generated_code:=trim(both '-' from regexp_replace(lower(btrim(p_draft->>'name')),'[^a-z0-9]+','-','g'))
    ||'-'||left(replace(gen_random_uuid()::text,'-',''),8);
  if domain='platform' then
    if coalesce(p_draft->>'max_scope_kind','platform') not in('platform','institution') then
      raise invalid_parameter_value using message='invalid platform profile scope';end if;
    for capability in select value from jsonb_array_elements(capabilities) loop
      if capability->>'effect' not in('allow','deny') or not exists(select 1 from public.platform_permissions
        where code=capability->>'code' and status='active') then raise invalid_parameter_value using message='unknown or invalid capability';end if;
      if capability->>'effect'='allow' and not app_private.has_platform_permission(capability->>'code') then
        raise insufficient_privilege using message='cannot delegate capability operator does not hold';end if;
    end loop;
    insert into public.platform_roles(code,name,description,status,is_system,created_by,max_scope_kind,source_template_id,source_template_version)
    values(generated_code,btrim(p_draft->>'name'),nullif(btrim(p_draft->>'description'),''),
      coalesce(p_draft->>'status','inactive')::public.record_status,false,p_actor,
      coalesce(p_draft->>'max_scope_kind','platform'),p_source_template_id,p_source_template_version) returning id into profile_id;
    insert into public.platform_role_permissions(role_id,permission_id,effect,conditions_json,granted_by,status)
    select profile_id,permission_record.id,(item.value->>'effect')::public.permission_effect,'{}',p_actor,'active'
    from jsonb_array_elements(capabilities) item join public.platform_permissions permission_record on permission_record.code=item.value->>'code';
  else
    if coalesce(p_draft->>'max_scope_kind','institution') not in('institution','unit','group') then
      raise invalid_parameter_value using message='invalid institution profile scope';end if;
    for capability in select value from jsonb_array_elements(capabilities) loop
      select id into permission_id from public.institution_permissions where code=capability->>'code' and status='active';
      if capability->>'effect' not in('allow','deny') or permission_id is null then
        raise invalid_parameter_value using message='unknown or invalid capability';end if;
      if capability->>'effect'='allow' and not app_private.access_profile_can_delegate_institution(permission_id) then
        raise insufficient_privilege using message='cannot delegate capability operator does not hold';end if;
    end loop;
    insert into public.institution_roles(institution_id,code,name,description,status,is_system,max_scope_kind,source_template_id,source_template_version)
    values(null,generated_code,btrim(p_draft->>'name'),nullif(btrim(p_draft->>'description'),''),
      coalesce(p_draft->>'status','inactive')::public.record_status,false,
      coalesce(p_draft->>'max_scope_kind','institution'),p_source_template_id,p_source_template_version) returning id into profile_id;
    insert into public.institution_role_permissions(role_id,permission_id,effect,conditions_json,granted_by,status)
    select profile_id,permission_record.id,(item.value->>'effect')::public.permission_effect,'{}',p_actor,'active'
    from jsonb_array_elements(capabilities) item join public.institution_permissions permission_record on permission_record.code=item.value->>'code';
  end if;
  return app_private.access_profile_detail_v2(domain,profile_id);
end $$;


ALTER FUNCTION "app_private"."access_profile_create_internal"("p_actor" "uuid", "p_draft" "jsonb", "p_source_template_id" "uuid", "p_source_template_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_csv_cell"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select '"'||replace(case when coalesce(p_value,'') ~ '^[=+@-]' then ''''||coalesce(p_value,'') else coalesce(p_value,'') end,'"','""')||'"'
$$;


ALTER FUNCTION "app_private"."access_profile_csv_cell"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_detail_v2"("p_domain" "text", "p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform app_private.require_profile_authority(p_domain);
  if p_domain='platform' then
    select to_jsonb(role_record)||jsonb_build_object('domain','platform',
      'linked_people_count',(select count(*) from public.platform_memberships membership
        where membership.role_id=role_record.id and membership.status='active' and membership.revoked_at is null),
      'capability_count',(select count(*) from public.platform_role_permissions grant_record
        where grant_record.role_id=role_record.id and grant_record.status='active' and grant_record.revoked_at is null))
    into result from public.platform_roles role_record where role_record.id=p_profile_id;
  elsif p_domain='institution' then
    select to_jsonb(role_record)||jsonb_build_object('domain','institution',
      'linked_people_count',(select count(*) from public.institution_role_assignments assignment
        where assignment.role_id=role_record.id and assignment.status='active'
          and (assignment.expires_at is null or assignment.expires_at>now())),
      'capability_count',(select count(*) from public.institution_role_permissions grant_record
        where grant_record.role_id=role_record.id and grant_record.status='active' and grant_record.revoked_at is null))
    into result from public.institution_roles role_record where role_record.id=p_profile_id;
  else raise invalid_parameter_value using message='unsupported profile domain'; end if;
  if result is null then raise no_data_found using message='access profile not found'; end if;
  return result;
end $$;


ALTER FUNCTION "app_private"."access_profile_detail_v2"("p_domain" "text", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_replay"("p_request_id" "uuid", "p_actor" "uuid", "p_command" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare receipt app_private.access_profile_command_receipts_v2%rowtype;
  wanted_hash bytea:=extensions.digest(convert_to(p_payload::text,'UTF8'),'sha256');
begin
  if p_request_id is null then raise invalid_parameter_value using message='request id required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,0));
  select * into receipt from app_private.access_profile_command_receipts_v2
    where request_id=p_request_id for update;
  if receipt.request_id is null then return null; end if;
  if receipt.actor_person_id<>p_actor then raise insufficient_privilege using message='idempotency receipt actor mismatch'; end if;
  if receipt.command_kind<>p_command or receipt.request_hash<>wanted_hash then
    raise invalid_parameter_value using message='idempotency key reused';
  end if;
  return receipt.result_json||jsonb_build_object('replayed',true);
end $$;


ALTER FUNCTION "app_private"."access_profile_replay"("p_request_id" "uuid", "p_actor" "uuid", "p_command" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_require_mutation"("target_domain" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id(); required_permission text;
begin
  required_permission:=case target_domain when 'platform' then 'platform.roles.manage'
    when 'institution' then 'institution.roles.manage'
    when 'principal' then 'institution.roles.manage' end;
  if actor is null or required_permission is null or not app_private.has_platform_permission(required_permission) then
    raise insufficient_privilege using message='profile management permission required';
  end if;
  if not app_private.has_mfa_aal2() then raise insufficient_privilege using message='MFA AAL2 required'; end if;
  return actor;
end $$;


ALTER FUNCTION "app_private"."access_profile_require_mutation"("target_domain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_profile_store_receipt"("p_request_id" "uuid", "p_actor" "uuid", "p_command" "text", "p_payload" "jsonb", "p_result" "jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  insert into app_private.access_profile_command_receipts_v2(
    request_id,actor_person_id,command_kind,request_hash,result_json
  ) values(p_request_id,p_actor,p_command,
    extensions.digest(convert_to(p_payload::text,'UTF8'),'sha256'),p_result)
$$;


ALTER FUNCTION "app_private"."access_profile_store_receipt"("p_request_id" "uuid", "p_actor" "uuid", "p_command" "text", "p_payload" "jsonb", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."access_scope_rank"("value" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case value when 'platform' then 4 when 'institution' then 3
    when 'unit' then 2 when 'group' then 1 else -1 end
$$;


ALTER FUNCTION "app_private"."access_scope_rank"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."activity_management_payload"("p_activity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select to_jsonb(activity)||jsonb_build_object(
  'institution_name',institution.public_name,
  'active_unit_count',(select count(*) from public.activity_unit_links link
    where link.activity_id=activity.id and link.status='active'),
  'active_group_count',(select count(*) from public.activity_group_links link
    where link.activity_id=activity.id and link.status='active'),
  'active_professional_count',(select count(distinct assignment.person_id)
    from public.activity_group_assignments assignment
    join public.activity_group_links link on link.id=assignment.activity_group_link_id
    where link.activity_id=activity.id and link.status='active'
     and assignment.status='active' and assignment.revoked_at is null),
  'active_participant_count',(select count(*)
    from public.activity_group_participants participant
    join public.activity_group_links link on link.id=participant.activity_group_link_id
    where link.activity_id=activity.id and link.status='active'
     and participant.status='active' and participant.removed_at is null),
  'location_names',coalesce((select jsonb_agg(distinct location.name order by location.name)
    from public.activity_unit_links link join public.activity_locations location
     on location.unit_id=link.unit_id and location.institution_id=link.institution_id
    where link.activity_id=activity.id and link.status='active'
     and location.status='active'),'[]'::jsonb),
  'linked_units',coalesce((select jsonb_agg(jsonb_build_object(
    'id',unit.id,'name',unit.name,'institution_id',unit.institution_id)
    order by unit.name)
    from public.activity_unit_links link join public.units unit on unit.id=link.unit_id
    where link.activity_id=activity.id and link.status='active'),'[]'::jsonb),
  'linked_groups',coalesce((select jsonb_agg(jsonb_build_object(
    'id',group_record.id,'name',group_record.name,'unit_id',group_record.unit_id,
    'unit_name',unit.name) order by unit.name,group_record.name)
    from public.activity_group_links link
    join public.groups group_record on group_record.id=link.group_id
    join public.units unit on unit.id=group_record.unit_id
    where link.activity_id=activity.id and link.status='active'),'[]'::jsonb),
  'activity_unit_links',coalesce((select jsonb_agg(
    to_jsonb(link)||jsonb_build_object('units',
      jsonb_build_object('id',unit.id,'name',unit.name,'institution_id',unit.institution_id))
    order by unit.name)
    from public.activity_unit_links link join public.units unit on unit.id=link.unit_id
    where link.activity_id=activity.id),'[]'::jsonb),
  'activity_group_links',coalesce((select jsonb_agg(
    to_jsonb(link)||jsonb_build_object(
      'groups',jsonb_build_object('id',group_record.id,'name',group_record.name),
      'units',jsonb_build_object('id',unit.id,'name',unit.name),
      'activity_group_assignments',coalesce((select jsonb_agg(to_jsonb(assignment))
        from public.activity_group_assignments assignment
        where assignment.activity_group_link_id=link.id),'[]'::jsonb),
      'activity_group_participants',coalesce((select jsonb_agg(to_jsonb(participant))
        from public.activity_group_participants participant
        where participant.activity_group_link_id=link.id),'[]'::jsonb))
    order by unit.name,group_record.name)
    from public.activity_group_links link
    join public.groups group_record on group_record.id=link.group_id
    join public.units unit on unit.id=group_record.unit_id
    where link.activity_id=activity.id),'[]'::jsonb),
  'unit_ids',coalesce((select jsonb_agg(link.unit_id order by link.unit_id)
    from public.activity_unit_links link
    where link.activity_id=activity.id and link.status='active'),'[]'::jsonb),
  'group_ids',coalesce((select jsonb_agg(link.group_id order by link.group_id)
    from public.activity_group_links link
    where link.activity_id=activity.id and link.status='active'),'[]'::jsonb),
  'locations',coalesce((select jsonb_agg(to_jsonb(location) order by location.name)
    from public.activity_locations location
    join public.activity_unit_links link on link.unit_id=location.unit_id
     and link.institution_id=location.institution_id and link.activity_id=activity.id
     and link.status='active' where location.status='active'),'[]'::jsonb)
 ) from public.activity_definitions activity
 join public.institutions institution on institution.id=activity.institution_id
 where activity.id=p_activity_id
$$;


ALTER FUNCTION "app_private"."activity_management_payload"("p_activity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."activity_request_uuid"("p_namespace" "text", "p_request_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select (
  substr(hash,1,8)||'-'||substr(hash,9,4)||'-'||substr(hash,13,4)||'-'||
  substr(hash,17,4)||'-'||substr(hash,21,12)
 )::uuid
 from (select md5(p_namespace||':'||p_request_id::text) hash) generated
$$;


ALTER FUNCTION "app_private"."activity_request_uuid"("p_namespace" "text", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."activity_slugify"("value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select trim(both '-' from regexp_replace(
  translate(lower(coalesce(value,'')),
   'áàâãäéèêëíìîïóòôõöúùûüçñ',
   'aaaaaeeeeiiiiooooouuuucn'),
  '[^a-z0-9]+','-','g'))
$$;


