CREATE OR REPLACE FUNCTION "app_private"."apply_institution_management_children"("p_institution_id" "uuid", "p_actor_person_id" "uuid", "p_payload" "jsonb", "p_plan_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  merged jsonb;
  email_value text;
  phone_value text;
  mobile_value text;
  website_value text;
  whatsapp_value text;
begin
  if p_payload ? 'address' then
    select coalesce(to_jsonb(address_record), '{}'::jsonb)
      || (p_payload -> 'address') into merged
    from (select 1) seed
    left join public.institution_addresses address_record
      on address_record.institution_id = p_institution_id;
    insert into public.institution_addresses(
      institution_id, country, state, city, district, street, number,
      complement, postal_code, status, updated_at
    ) values (
      p_institution_id, coalesce(nullif(btrim(merged ->> 'country'), ''), 'BR'),
      nullif(btrim(merged ->> 'state'), ''),
      nullif(btrim(merged ->> 'city'), ''),
      nullif(btrim(merged ->> 'district'), ''),
      nullif(btrim(merged ->> 'street'), ''),
      nullif(btrim(merged ->> 'number'), ''),
      nullif(btrim(merged ->> 'complement'), ''),
      nullif(btrim(merged ->> 'postal_code'), ''), 'active', clock_timestamp()
    ) on conflict (institution_id) do update set
      country = excluded.country, state = excluded.state, city = excluded.city,
      district = excluded.district, street = excluded.street,
      number = excluded.number, complement = excluded.complement,
      postal_code = excluded.postal_code, status = 'active',
      updated_at = excluded.updated_at;
  end if;

  if p_payload ? 'contact' then
    select coalesce(to_jsonb(contact_record), '{}'::jsonb)
      || (p_payload -> 'contact') into merged
    from (select 1) seed
    left join public.institution_contacts contact_record
      on contact_record.institution_id = p_institution_id;
    email_value := nullif(btrim(merged ->> 'email'), '');
    phone_value := nullif(btrim(merged ->> 'phone'), '');
    mobile_value := nullif(btrim(merged ->> 'mobile_phone'), '');
    website_value := nullif(btrim(merged ->> 'website_url'), '');
    whatsapp_value := nullif(btrim(merged ->> 'whatsapp_number'), '');
    if num_nonnulls(
      email_value, phone_value, mobile_value, website_value, whatsapp_value
    ) = 0 then
      delete from public.institution_contacts
      where institution_id = p_institution_id;
    else
      insert into public.institution_contacts(
        institution_id, email, phone, mobile_phone, website_url,
        whatsapp_number, status, updated_at
      ) values (
        p_institution_id, email_value, phone_value, mobile_value,
        website_value, whatsapp_value, 'active', clock_timestamp()
      ) on conflict (institution_id) do update set
        email = excluded.email, phone = excluded.phone,
        mobile_phone = excluded.mobile_phone,
        website_url = excluded.website_url,
        whatsapp_number = excluded.whatsapp_number,
        status = 'active', updated_at = excluded.updated_at;
    end if;
  end if;

  if p_payload ? 'branding' then
    select coalesce(to_jsonb(branding_record), '{}'::jsonb)
      || (p_payload -> 'branding') into merged
    from (select 1) seed
    left join public.institution_branding branding_record
      on branding_record.institution_id = p_institution_id;
    insert into public.institution_branding(
      institution_id, display_name, logo_media_asset_id, cover_media_asset_id,
      accent_color, secondary_color, tertiary_color, text_color,
      secondary_text_color, tertiary_text_color, surface_color,
      approval_status, profile_bio, profile_links, updated_by, updated_at
    ) values (
      p_institution_id, nullif(btrim(merged ->> 'display_name'), ''),
      nullif(merged ->> 'logo_media_asset_id', '')::uuid,
      nullif(merged ->> 'cover_media_asset_id', '')::uuid,
      nullif(btrim(merged ->> 'accent_color'), ''),
      nullif(btrim(merged ->> 'secondary_color'), ''),
      nullif(btrim(merged ->> 'tertiary_color'), ''),
      nullif(btrim(merged ->> 'text_color'), ''),
      nullif(btrim(merged ->> 'secondary_text_color'), ''),
      nullif(btrim(merged ->> 'tertiary_text_color'), ''),
      nullif(btrim(merged ->> 'surface_color'), ''),
      coalesce(nullif(btrim(merged ->> 'approval_status'), ''), 'draft'),
      nullif(merged ->> 'profile_bio', ''),
      coalesce(merged -> 'profile_links', '[]'::jsonb),
      p_actor_person_id, clock_timestamp()
    ) on conflict (institution_id) do update set
      display_name = excluded.display_name,
      logo_media_asset_id = excluded.logo_media_asset_id,
      cover_media_asset_id = excluded.cover_media_asset_id,
      accent_color = excluded.accent_color,
      secondary_color = excluded.secondary_color,
      tertiary_color = excluded.tertiary_color,
      text_color = excluded.text_color,
      secondary_text_color = excluded.secondary_text_color,
      tertiary_text_color = excluded.tertiary_text_color,
      surface_color = excluded.surface_color,
      approval_status = excluded.approval_status,
      profile_bio = excluded.profile_bio,
      profile_links = excluded.profile_links,
      updated_by = excluded.updated_by,
      updated_at = excluded.updated_at;
  end if;

  if p_payload ? 'subscription' then
    insert into public.institution_subscriptions(
      institution_id, plan_id, status, starts_at, trial_ends_at,
      manual_reason, changed_by, paused_at, cancelled_at
    ) values (
      p_institution_id, p_plan_id,
      coalesce(p_payload -> 'subscription' ->> 'status', 'draft')
        ::public.subscription_status,
      nullif(p_payload -> 'subscription' ->> 'starts_at', '')::timestamptz,
      nullif(p_payload -> 'subscription' ->> 'trial_ends_at', '')::timestamptz,
      nullif(btrim(p_payload -> 'subscription' ->> 'manual_reason'), ''),
      p_actor_person_id,
      nullif(p_payload -> 'subscription' ->> 'paused_at', '')::timestamptz,
      nullif(p_payload -> 'subscription' ->> 'cancelled_at', '')::timestamptz
    );
  end if;
end;
$$;


ALTER FUNCTION "app_private"."apply_institution_management_children"("p_institution_id" "uuid", "p_actor_person_id" "uuid", "p_payload" "jsonb", "p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_access_profile_assignment_delegable"("p_domain" "text", "p_profile_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare missing_code text;
begin
  if p_domain='platform' then
    select permission_record.code into missing_code
    from public.platform_role_permissions grant_record
    join public.platform_permissions permission_record on permission_record.id=grant_record.permission_id
    where grant_record.role_id=p_profile_id and grant_record.effect='allow'
      and grant_record.status='active' and grant_record.revoked_at is null
      and not app_private.has_platform_permission(permission_record.code) limit 1;
  elsif p_domain='institution' then
    select permission_record.code into missing_code
    from public.institution_role_permissions grant_record
    join public.institution_permissions permission_record on permission_record.id=grant_record.permission_id
    where grant_record.role_id=p_profile_id and grant_record.effect='allow'
      and grant_record.status='active' and grant_record.revoked_at is null
      and not app_private.access_profile_can_delegate_institution(permission_record.id) limit 1;
  elsif p_domain='principal' then
    perform app_private.assert_access_profile_template_delegable(p_profile_id,'principal');
    return;
  else
    raise invalid_parameter_value using message='unsupported profile domain';
  end if;
  if missing_code is not null then
    raise insufficient_privilege using message='cannot delegate capability operator does not hold';
  end if;
end $$;


ALTER FUNCTION "app_private"."assert_access_profile_assignment_delegable"("p_domain" "text", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_access_profile_template_delegable"("p_template_id" "uuid", "p_domain" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare missing_code text;
begin
  if p_domain='platform' then
    select permission_record.code into missing_code
    from public.access_profile_template_platform_permissions item
    join public.platform_permissions permission_record on permission_record.id=item.permission_id
    where item.template_id=p_template_id and item.effect='allow'
      and not app_private.has_platform_permission(permission_record.code) limit 1;
  elsif p_domain='institution' then
    select permission_record.code into missing_code
    from public.access_profile_template_institution_permissions item
    join public.institution_permissions permission_record on permission_record.id=item.permission_id
    where item.template_id=p_template_id and item.effect='allow'
      and not app_private.access_profile_can_delegate_institution(permission_record.id) limit 1;
  elsif p_domain='principal' then
    select capability.code into missing_code
    from public.access_profile_template_principal_capabilities item
    join public.guardian_permission_capabilities capability on capability.id=item.capability_id
    where item.template_id=p_template_id and item.effect='allow'
      and not app_private.access_profile_can_delegate_principal(capability.id) limit 1;
  else
    raise invalid_parameter_value using message='unsupported profile domain';
  end if;
  if missing_code is not null then
    raise insufficient_privilege using message='cannot delegate capability operator does not hold';
  end if;
end $$;


ALTER FUNCTION "app_private"."assert_access_profile_template_delegable"("p_template_id" "uuid", "p_domain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_agenda_context"("p_institution_id" "uuid", "p_kind" "text", "p_context_id" "uuid", "p_audience" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_kind='institution' and p_context_id<>p_institution_id then raise exception using errcode='22023',message='invalid_institution_context'; end if;
  if p_kind='unit' and not exists(select 1 from public.units u where u.id=p_context_id and u.institution_id=p_institution_id) then raise exception using errcode='22023',message='invalid_unit_context'; end if;
  if p_kind='group' and not exists(select 1 from public.groups g join public.units u on u.id=g.unit_id where g.id=p_context_id and u.institution_id=p_institution_id) then raise exception using errcode='22023',message='invalid_group_context'; end if;
  if p_kind='activity' and not exists(select 1 from public.activity_definitions a where a.id=p_context_id and a.institution_id=p_institution_id) then raise exception using errcode='22023',message='invalid_activity_context'; end if;
  if exists(select 1 from jsonb_array_elements_text(coalesce(p_audience->'unitIds','[]'::jsonb)) x where not exists(select 1 from public.units u where u.id=x.value::uuid and u.institution_id=p_institution_id)) then raise exception using errcode='22023',message='cross_tenant_unit_audience'; end if;
  if exists(select 1 from jsonb_array_elements_text(coalesce(p_audience->'groupIds','[]'::jsonb)) x where not exists(select 1 from public.groups g join public.units u on u.id=g.unit_id where g.id=x.value::uuid and u.institution_id=p_institution_id)) then raise exception using errcode='22023',message='cross_tenant_group_audience'; end if;
  if exists(select 1 from jsonb_array_elements_text(coalesce(p_audience->'activityIds','[]'::jsonb)) x where not exists(select 1 from public.activity_definitions a where a.id=x.value::uuid and a.institution_id=p_institution_id)) then raise exception using errcode='22023',message='cross_tenant_activity_audience'; end if;
end; $$;


ALTER FUNCTION "app_private"."assert_agenda_context"("p_institution_id" "uuid", "p_kind" "text", "p_context_id" "uuid", "p_audience" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_agenda_permission"("p_permission" "text", "p_require_aal2" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid;
begin
  if (select auth.uid()) is null then raise exception using errcode='28000',message='authentication_required'; end if;
  v_actor:=app_private.current_person_id();
  if v_actor is null then raise exception using errcode='42501',message='internal_actor_required'; end if;
  if not app_private.has_platform_permission(p_permission) then raise exception using errcode='42501',message='agenda_permission_denied'; end if;
  if p_require_aal2 and not app_private.has_mfa_aal2() then raise exception using errcode='42501',message='mfa_aal2_required'; end if;
  return v_actor;
end; $$;


ALTER FUNCTION "app_private"."assert_agenda_permission"("p_permission" "text", "p_require_aal2" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_agenda_questions"("p_questions" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v_question jsonb;
begin
  if jsonb_typeof(p_questions)<>'array' or jsonb_array_length(p_questions)>30 then raise exception using errcode='22023',message='invalid_questions'; end if;
  for v_question in select value from jsonb_array_elements(p_questions) loop
    if v_question->>'type' not in ('shortText','yesNo') or coalesce(char_length(trim(v_question->>'title')),0) not between 1 and 240 then raise exception using errcode='22023',message='invalid_question'; end if;
    if lower(v_question->>'title') ~ '(cpf|rg|diagn[oó]stico|medica[cç][aã]o|senha|biometria|cart[aã]o|conta banc[aá]ria)' then raise exception using errcode='22023',message='sensitive_question_not_allowed'; end if;
  end loop;
end; $$;


ALTER FUNCTION "app_private"."assert_agenda_questions"("p_questions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_full_authority_remains"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not exists(
    select 1 from public.platform_memberships membership
    join public.platform_roles role_record on role_record.id=membership.role_id
    where membership.status='active' and membership.revoked_at is null
      and membership.mfa_required and role_record.status='active'
      and membership.scope_kind='platform'
      and membership.scope_institution_id is null
      and not exists(
        select 1 from public.platform_member_permission_overrides override_record
        where override_record.membership_id=membership.id
          and override_record.effect='deny'
          and override_record.status='active'
          and (override_record.starts_at is null or override_record.starts_at<=now())
          and (override_record.expires_at is null or override_record.expires_at>now())
      )
      and not exists(
        select 1 from public.platform_role_permissions denied_grant
        where denied_grant.role_id=role_record.id
          and denied_grant.effect='deny'
          and denied_grant.status='active'
          and denied_grant.revoked_at is null
      )
      and not exists(
        select 1 from public.platform_permissions permission_record
        where permission_record.status='active' and not exists(
          select 1 from public.platform_role_permissions grant_record
          where grant_record.role_id=role_record.id
            and grant_record.permission_id=permission_record.id
            and grant_record.status='active' and grant_record.revoked_at is null
            and grant_record.effect='allow'
        )
      )
  ) then
    raise check_violation using
      message='active full-authority MFA replacement required';
  end if;
end $$;


ALTER FUNCTION "app_private"."assert_full_authority_remains"() OWNER TO "postgres";


