CREATE OR REPLACE FUNCTION "app_private"."assert_institution_identity_access"("p_institution_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.current_person_id();
begin
  if (select auth.uid()) is null or actor is null or not app_private.has_mfa_aal2() then
    raise insufficient_privilege using message='authenticated AAL2 required';
  end if;
  if not app_private.has_platform_permission('institution.update') then
    raise insufficient_privilege using message='institution identity permission required';
  end if;
  if not exists(
    select 1 from public.institutions i
    where i.id=p_institution_id and i.deleted_at is null
  ) then
    raise no_data_found using message='institution not found';
  end if;
  return actor;
end
$$;


