CREATE OR REPLACE FUNCTION "app_private"."assert_people_permission"("permission_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null
     or not (select app_private.has_platform_permission(permission_code)) then
    raise insufficient_privilege using message = 'people permission denied';
  end if;
  if not (select app_private.has_mfa_aal2()) then
    raise insufficient_privilege using message = 'people permission requires aal2';
  end if;
end
$$;


ALTER FUNCTION "app_private"."assert_people_permission"("permission_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_plan_permission"("p_permission" "text", "p_require_aal2" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid;
begin
  if (select auth.uid()) is null then raise exception using errcode='28000',message='authentication_required'; end if;
  v_actor := app_private.current_person_id();
  if v_actor is null then raise exception using errcode='42501',message='internal_actor_required'; end if;
  if not app_private.has_platform_permission(p_permission) then raise exception using errcode='42501',message='permission_denied'; end if;
  if p_require_aal2 and not app_private.has_mfa_aal2() then raise exception using errcode='42501',message='mfa_aal2_required'; end if;
  return v_actor;
end; $$;


ALTER FUNCTION "app_private"."assert_plan_permission"("p_permission" "text", "p_require_aal2" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_unit_file_access"("p_permission" "text", "p_institution_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();
begin
 if (select auth.uid()) is null or actor is null or not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='authenticated AAL2 required';
 end if;
 if p_institution_id is null then
  if not app_private.has_platform_permission(p_permission) then
   raise insufficient_privilege using message='unit file permission required';
  end if;
 elsif not app_private.has_scoped_platform_permission(p_permission,p_institution_id) then
  raise insufficient_privilege using message='unit file scope denied';
 end if;
 return actor;
end $$;


