CREATE OR REPLACE FUNCTION "app_private"."can_access_institution_identity_object"("p_path" "text", "p_operation" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare media public.institution_identity_media%rowtype;
begin
  select * into media
  from public.institution_identity_media m
  where m.storage_path=p_path;
  if media.id is null then return false; end if;
  perform app_private.assert_institution_identity_access(media.institution_id);
  return case p_operation
    when 'insert' then media.state='pending' and media.created_by=app_private.current_person_id()
    when 'select' then media.state='active'
    when 'delete' then media.state='archived'
    else false
  end;
exception when others then
  return false;
end
$$;


