CREATE OR REPLACE FUNCTION "app_private"."change_unit_handle_for_superadmin"("p_request_id" "uuid", "p_unit_id" "uuid", "p_expected_version" bigint, "p_requested_handle" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor uuid:=app_private.current_person_id();u public.units%rowtype;n text;prior public.unit_handle_history%rowtype;begin
select*into u from public.units where id=p_unit_id for update;if u.id is null then raise no_data_found using message='unit not found';end if;
if actor is null or not app_private.has_platform_permission('units.handle.manage')
or not app_private.has_scoped_platform_permission('units.update',u.institution_id)or not app_private.has_mfa_aal2()
then raise insufficient_privilege using message='units.handle.manage and AAL2 required';end if;
n:=lower(regexp_replace(btrim(p_requested_handle),'^@','','g'));select*into prior from public.unit_handle_history where request_id=p_request_id;
if prior.id is not null then if prior.unit_id<>p_unit_id or prior.new_handle<>n then raise invalid_parameter_value using message='request replay mismatch';end if;
return app_private.unit_form_payload(p_unit_id);end if;
if u.management_version<>p_expected_version then raise serialization_failure using message='stale unit version';end if;
if u.handle_last_changed_at is not null and u.handle_last_changed_at>now()-interval'15 days'
then raise check_violation using message='unit handle can only change every 15 days';end if;
if n!~'^[a-z0-9][a-z0-9._]{1,28}[a-z0-9]$'then raise invalid_parameter_value using message='invalid handle';end if;
update public.units set handle=n,handle_last_changed_at=now(),management_version=management_version+1,updated_at=now()where id=p_unit_id;
insert into public.unit_handle_history(request_id,unit_id,institution_id,old_handle,new_handle,changed_by_person_id)
values(p_request_id,p_unit_id,u.institution_id,u.handle,n,actor);
insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome)
values(actor,'aal2','unit.handle.change','unit',p_unit_id,u.institution_id,'success');return app_private.unit_form_payload(p_unit_id);end$_$;


ALTER FUNCTION "app_private"."change_unit_handle_for_superadmin"("p_request_id" "uuid", "p_unit_id" "uuid", "p_expected_version" bigint, "p_requested_handle" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."circular_actor"("p_institution_id" "uuid", "p_permission" "text", "p_unit_id" "uuid", "p_group_id" "uuid") RETURNS TABLE("person_id" "uuid", "membership_id" "uuid", "role_code" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null then raise insufficient_privilege using message='authentication_required'; end if;
  if not app_private.has_institution_permission(p_institution_id,p_permission,p_unit_id,p_group_id,false)
  then raise insufficient_privilege using message='circular_permission_denied'; end if;
  return query
  select link.person_id,membership.id,membership.role_code
  from public.person_auth_links link
  join public.institution_memberships membership on membership.person_id=link.person_id
  where link.auth_user_id=(select auth.uid()) and link.status='active'
    and membership.institution_id=p_institution_id and membership.status='active'
    and membership.revoked_at is null
  order by membership.created_at limit 1;
  if not found then raise insufficient_privilege using message='active_membership_required'; end if;
end $$;


ALTER FUNCTION "app_private"."circular_actor"("p_institution_id" "uuid", "p_permission" "text", "p_unit_id" "uuid", "p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."circular_audience_matches_role"("p_role" "text", "p_audience" "public"."circular_audience_kind") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when lower(coalesce(p_role,'')) in ('guardian','responsible','responsavel','parent','family') then p_audience in ('families','guardians_only')
    when lower(coalesce(p_role,'')) in ('student','aluno') then p_audience='students'
    when lower(coalesce(p_role,'')) in ('professional','institution_admin','unit_admin','teacher','coordinator') then p_audience='school_staff'
    else false
  end
$$;


ALTER FUNCTION "app_private"."circular_audience_matches_role"("p_role" "text", "p_audience" "public"."circular_audience_kind") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."circular_audience_rules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "circular_id" "uuid" NOT NULL,
    "revision_id" "uuid" NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "audience_kind" "public"."circular_audience_kind" NOT NULL,
    "scope_kind" "public"."circular_scope_kind" NOT NULL,
    "unit_id" "uuid",
    "group_id" "uuid",
    "activity_id" "uuid",
    CONSTRAINT "circular_audience_rules_check" CHECK (((("scope_kind" = 'institution'::"public"."circular_scope_kind") AND ("unit_id" IS NULL) AND ("group_id" IS NULL) AND ("activity_id" IS NULL)) OR (("scope_kind" = 'unit'::"public"."circular_scope_kind") AND ("unit_id" IS NOT NULL) AND ("group_id" IS NULL) AND ("activity_id" IS NULL)) OR (("scope_kind" = 'group'::"public"."circular_scope_kind") AND ("unit_id" IS NOT NULL) AND ("group_id" IS NOT NULL) AND ("activity_id" IS NULL)) OR (("scope_kind" = 'activity'::"public"."circular_scope_kind") AND ("unit_id" IS NULL) AND ("group_id" IS NULL) AND ("activity_id" IS NOT NULL))))
);

ALTER TABLE ONLY "public"."circular_audience_rules" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."circular_audience_rules" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."circular_audience_scope_contained"("p_root_unit_id" "uuid", "p_root_group_id" "uuid", "p_root_activity_id" "uuid", "p_audience" "public"."circular_audience_rules") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when p_root_activity_id is not null then
      p_audience.scope_kind='activity' and p_audience.activity_id=p_root_activity_id
    when p_root_group_id is not null then
      (p_audience.scope_kind='group' and p_audience.group_id=p_root_group_id)
      or (p_audience.scope_kind='activity' and exists (
        select 1 from public.activity_group_links link
        where link.activity_id=p_audience.activity_id and link.group_id=p_root_group_id
          and link.status='active' and link.starts_at<=now()
          and (link.ends_at is null or link.ends_at>now())
      ))
    when p_root_unit_id is not null then
      (p_audience.scope_kind='unit' and p_audience.unit_id=p_root_unit_id)
      or (p_audience.scope_kind='group' and p_audience.unit_id=p_root_unit_id)
      or (p_audience.scope_kind='activity' and exists (
        select 1 from public.activity_group_links link
        join public.groups target_group on target_group.id=link.group_id
        where link.activity_id=p_audience.activity_id and target_group.unit_id=p_root_unit_id
          and link.status='active' and link.starts_at<=now()
          and (link.ends_at is null or link.ends_at>now())
      ))
    else true
  end
$$;


ALTER FUNCTION "app_private"."circular_audience_scope_contained"("p_root_unit_id" "uuid", "p_root_group_id" "uuid", "p_root_activity_id" "uuid", "p_audience" "public"."circular_audience_rules") OWNER TO "postgres";


