    CONSTRAINT "circulars_check" CHECK ((("unit_id" IS NOT NULL) OR ("group_id" IS NULL))),
    CONSTRAINT "circulars_check1" CHECK ((("status" = 'draft'::"public"."circular_status") OR ("publish_at" IS NOT NULL))),
    CONSTRAINT "circulars_management_version_check" CHECK (("management_version" > 0))
);

