CREATE OR REPLACE FUNCTION "app_private"."decide_child_unit_transfer"("target_request_id" "uuid", "target_decision" "text", "target_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid := app_private.current_person_id();
  request_record public.child_unit_transfer_requests%rowtype;
  item_record record;
  destination_link_id uuid;
begin
  if target_decision not in ('accepted','rejected','changes_requested') then
    raise exception 'invalid transfer decision';
  end if;
  select * into request_record from public.child_unit_transfer_requests
  where id = target_request_id and status = 'pending' for update;
  if request_record.id is null then raise exception 'pending transfer not found'; end if;
  if not app_private.has_context_permission(
    request_record.institution_id, 'transfers.manage',
    request_record.destination_unit_id, null, null, null, false
  ) then raise exception 'destination authorization required'; end if;

  update public.child_unit_transfer_requests
  set status = target_decision, decision_reason = nullif(btrim(target_reason), ''),
      decided_by_person_id = actor_person_id, decided_at = now(), updated_at = now()
  where id = target_request_id;

  if target_decision = 'accepted' then
    for item_record in
      select item.*, source_link.child_context_id
      from public.child_unit_transfer_items item
      join public.child_unit_links source_link on source_link.id = item.child_unit_link_id
      where item.transfer_request_id = target_request_id and item.status = 'pending'
      for update of item
    loop
      update public.child_group_links
      set status = 'inactive', ends_at = coalesce(ends_at, now()), updated_at = now()
      where child_unit_link_id = item_record.child_unit_link_id and status = 'active';
      update public.child_unit_links
      set status = 'inactive', revoked_at = now(), updated_at = now()
      where id = item_record.child_unit_link_id;

      insert into public.child_unit_links(
        child_context_id, unit_id, status, accepted_by, accepted_at
      ) values (
        item_record.child_context_id, request_record.destination_unit_id,
        case when item_record.suggested_group_id is null
          then 'awaiting_allocation'::public.child_unit_link_status
          else 'active'::public.child_unit_link_status end,
        actor_person_id, now()
      )
      on conflict (child_context_id, unit_id) do update set
        status = excluded.status, accepted_by = excluded.accepted_by,
        accepted_at = excluded.accepted_at, revoked_at = null, updated_at = now()
      returning id into destination_link_id;

      if item_record.suggested_group_id is not null then
        insert into public.child_group_links(child_unit_link_id, group_id, starts_at)
        values (destination_link_id, item_record.suggested_group_id, now())
        on conflict (child_unit_link_id, group_id) do update set
          status = 'active', starts_at = excluded.starts_at, ends_at = null,
          updated_at = now();
      end if;
      update public.child_unit_transfer_items
      set status = 'accepted', destination_child_unit_link_id = destination_link_id,
          updated_at = now()
      where id = item_record.id;
    end loop;
  else
    update public.child_unit_transfer_items set status = 'rejected', updated_at = now()
    where transfer_request_id = target_request_id and status = 'pending';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."decide_child_unit_transfer"("target_request_id" "uuid", "target_decision" "text", "target_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."decide_unit_type_request_for_superadmin"("p_type_request_id" "uuid", "p_decision" "text", "p_approved_unit_type_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();r public.unit_type_requests%rowtype;begin
select*into r from public.unit_type_requests where id=p_type_request_id for update;if r.id is null then raise no_data_found using message='type request not found';end if;
if actor is null or not app_private.has_platform_permission('unit_types.request')or not app_private.has_mfa_aal2()
then raise insufficient_privilege using message='Superadmin AAL2 required';end if;
if r.status<>'pending'or p_decision not in('approved','rejected')
or(p_decision='approved'and not exists(select 1 from public.unit_types where id=p_approved_unit_type_id and status='active'))
or(p_decision='rejected'and nullif(btrim(p_reason),'')is null)then raise invalid_parameter_value using message='invalid type request decision';end if;
update public.unit_type_requests set status=p_decision::public.unit_type_request_status,
approved_unit_type_id=case when p_decision='approved'then p_approved_unit_type_id end,
reviewed_by_person_id=actor,reviewed_at=now(),review_reason=nullif(btrim(p_reason),''),updated_at=now()
where id=p_type_request_id returning*into r;
insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome)
values(actor,'aal2','unit_type_request.'||p_decision,'unit_type_request',r.id,r.institution_id,'success');return to_jsonb(r);end$$;


ALTER FUNCTION "app_private"."decide_unit_type_request_for_superadmin"("p_type_request_id" "uuid", "p_decision" "text", "p_approved_unit_type_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_activity_active_unit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  target_activity_id uuid;
  row_data jsonb;
begin
  row_data := case
    when tg_op = 'DELETE' then to_jsonb(old)
    else to_jsonb(new)
  end;
  target_activity_id := coalesce(
    (row_data ->> 'activity_id')::uuid,
    (row_data ->> 'id')::uuid
  );

  if not exists (
    select 1
    from public.activity_definitions activity
    where activity.id = target_activity_id
  ) then
    return coalesce(new, old);
  end if;

  if not exists (
    select 1
    from public.activity_unit_links unit_link
    where unit_link.activity_id = target_activity_id
      and unit_link.status = 'active'
      and (unit_link.ends_at is null or unit_link.ends_at > pg_catalog.now())
  ) then
    raise check_violation using
      message = 'activity must retain at least one active unit link';
  end if;

  return coalesce(new, old);
end
$$;


ALTER FUNCTION "app_private"."enforce_activity_active_unit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_institution_handle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor uuid;
begin
  new.slug:=app_private.normalize_institution_handle(new.slug);
  if new.slug !~ '^[a-z0-9][a-z0-9._-]{2,29}$' then
    raise check_violation using message='institution handle must have 3 to 30 allowed characters';
  end if;
  if tg_op='INSERT' then
    new.handle_last_changed_at:=coalesce(new.handle_last_changed_at,now());
    return new;
  end if;
  if new.slug is distinct from old.slug then
    if old.handle_last_changed_at is not null
       and old.handle_last_changed_at > now()-interval '15 days' then
      raise check_violation using message='institution handle can only change every 15 days';
    end if;
    actor:=app_private.current_person_id();
    new.handle_last_changed_at:=now();
    insert into public.institution_handle_history(
      institution_id,previous_handle,new_handle,changed_by
    ) values(old.id,old.slug,new.slug,actor);
  end if;
  return new;
end
$_$;


ALTER FUNCTION "app_private"."enforce_institution_handle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_person_handle_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  person_kind public.person_type;
  last_correction_at timestamptz;
begin
  new.normalized_handle := app_private.normalize_person_handle(
    new.normalized_handle
  );

  select person.person_type
  into person_kind
  from public.people person
  where person.id = new.person_id
    and person.deleted_at is null;

  if person_kind is null then
    raise foreign_key_violation using message = 'active person required';
  end if;
  if person_kind not in ('adult', 'child') then
    raise check_violation using message = 'handles belong only to adults or children';
  end if;
  if person_kind = 'child' and new.visibility <> 'private' then
    raise check_violation using message = 'child handles must remain private';
  end if;

  if tg_op = 'UPDATE' and old.revoked_at is not null then
    raise check_violation using message = 'revoked handles are immutable';
  end if;

  if tg_op = 'INSERT'
     or new.normalized_handle is distinct from old.normalized_handle then
    select max(ledger.changed_at)
    into last_correction_at
    from app_private.person_identity_correction_ledger ledger
    where ledger.person_id = new.person_id
      and ledger.correction_kind = 'handle';

    if last_correction_at is not null
       and last_correction_at > clock_timestamp() - interval '15 days' then
      raise check_violation using
        message = 'person handle can be changed only once every 15 days';
    end if;
    if tg_op = 'UPDATE'
       and old.last_changed_at > clock_timestamp() - interval '15 days' then
      raise check_violation using
        message = 'person handle can be changed only once every 15 days';
    end if;
    new.last_changed_at := clock_timestamp();
  else
    new.last_changed_at := old.last_changed_at;
  end if;

  new.updated_at := clock_timestamp();
  return new;
end
$$;


ALTER FUNCTION "app_private"."enforce_person_handle_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enforce_unit_branding_identity_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.logo_media_asset_id is not null and not exists (
    select 1
    from public.unit_identity_media media
    where media.id = new.logo_media_asset_id
      and media.unit_id = new.unit_id
      and media.media_kind = 'profile'
      and media.status = 'active'
  ) then
    raise foreign_key_violation
      using message = 'unit branding profile media must be active and owned by the unit';
  end if;

  if new.cover_media_asset_id is not null and not exists (
    select 1
    from public.unit_identity_media media
    where media.id = new.cover_media_asset_id
      and media.unit_id = new.unit_id
      and media.media_kind = 'cover'
      and media.status = 'active'
  ) then
    raise foreign_key_violation
      using message = 'unit branding cover media must be active and owned by the unit';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."enforce_unit_branding_identity_ownership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_actor_has_export_permission"("p_actor" "uuid", "p_export_kind" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with target_permission as (
    select permission_row.id
      from public.platform_permissions permission_row
     where permission_row.code = case
       when p_export_kind = 'anonymous_participation'
         then 'forms.anonymous_participation.export'
       else 'forms.responses.export'
     end
       and permission_row.status = 'active'
  ), memberships as (
    select membership.id, membership.role_id, role_row.code as role_code
      from public.platform_memberships membership
      join public.platform_roles role_row on role_row.id = membership.role_id
     where membership.person_id = p_actor
       and membership.status = 'active'
       and membership.revoked_at is null
       and membership.scope_kind = 'platform'
       and membership.scope_institution_id is null
       and role_row.status = 'active'
  ), effects as (
    select grant_row.effect
      from memberships
      join public.platform_role_permissions grant_row
        on grant_row.role_id = memberships.role_id
       and grant_row.status = 'active'
       and grant_row.revoked_at is null
      join target_permission on target_permission.id = grant_row.permission_id
    union all
    select override_row.effect
      from memberships
      join public.platform_member_permission_overrides override_row
        on override_row.membership_id = memberships.id
       and override_row.status = 'active'
       and (override_row.starts_at is null or override_row.starts_at <= now())
       and (override_row.expires_at is null or override_row.expires_at > now())
      join target_permission on target_permission.id = override_row.permission_id
  )
  select exists(select 1 from effects where effect = 'allow')
     and not exists(select 1 from effects where effect = 'deny')
     and (
       p_export_kind <> 'anonymous_participation'
       or exists(select 1 from memberships where role_code = 'owner')
     );
$$;


ALTER FUNCTION "app_private"."form_actor_has_export_permission"("p_actor" "uuid", "p_export_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_anonymous_participation_lookup"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.anonymous_participation.read');
declare result jsonb;
begin
  perform app_private.form_assert_payload_keys(
    p_query, array['form_id','occurrence_id','justification','cursor_name','cursor_id','limit'],
    'anonymous participation query'
  );
  perform app_private.form_require_owner(actor, 'forms.anonymous_participation.read');
  if char_length(btrim(coalesce(p_query ->> 'justification', ''))) < 10 then
    raise invalid_parameter_value using message = 'auditable justification required';
  end if;
  if not exists(
    select 1 from public.forms where id = (p_query ->> 'form_id')::uuid and identity_mode = 'anonymous'
  ) then
    raise no_data_found using message = 'anonymous form unavailable';
  end if;
  result := app_private.form_list_monitor_people(p_query);
  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id, institution_id,
    outcome, reason, after_json
  )
  select actor, auth.jwt() ->> 'aal', 'forms.anonymous_participation.read', 'form', form_row.id,
         form_row.institution_id, 'success', btrim(p_query ->> 'justification'),
         jsonb_build_object('occurrence_id', p_query ->> 'occurrence_id')
    from public.forms form_row where form_row.id = (p_query ->> 'form_id')::uuid;
  return result;
end;
$$;


ALTER FUNCTION "app_private"."form_anonymous_participation_lookup"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_application_projection"("p_application_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', application.id,
    'form_id', application.form_id,
    'institution_id', application.institution_id,
    'name', application.name,
    'status', application.status,
    'opens_for_days', application.opens_for_days,
    'management_version', application.management_version,
    'audience_rules', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rule.id, 'kind', rule.rule_kind, 'mode', rule.rule_mode, 'target_id', rule.target_id
      ) order by rule.position, rule.id)
        from (
          select source_rule.* from public.form_audience_rules source_rule
           where source_rule.application_id = application.id
           order by source_rule.position, source_rule.id
           limit 50
        ) rule
    ), '[]'::jsonb),
    'schedules', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', schedule.id,
        'status', schedule.status,
        'management_version', schedule.management_version,
        'starts_at_local', schedule.starts_at_local,
        'time_zone', schedule.time_zone,
        'recurrence', jsonb_build_object(
          'kind', schedule.recurrence_kind,
          'interval', schedule.interval_value,
          'weekdays', to_jsonb(schedule.weekdays),
          'day', schedule.monthly_day,
          'use_last_day', schedule.monthly_last_day
        ),
        'end', jsonb_build_object(
          'kind', schedule.end_kind,
          'date', schedule.ends_on,
          'count', schedule.occurrence_count
        ),
        'reminders', coalesce((
          select jsonb_agg(jsonb_build_object('kind', reminder.reminder_kind, 'amount', reminder.amount)
                           order by reminder.position, reminder.id)
            from (
              select source_reminder.* from public.form_schedule_reminders source_reminder
               where source_reminder.schedule_id = schedule.id
               order by source_reminder.position, source_reminder.id
               limit 3
            ) reminder
        ), '[]'::jsonb)
      ) order by schedule.starts_at_local, schedule.id)
        from (
          select source_schedule.* from public.form_schedules source_schedule
           where source_schedule.application_id = application.id
             and source_schedule.status = 'active'
           order by source_schedule.starts_at_local, source_schedule.id
           limit 20
        ) schedule
    ), '[]'::jsonb)
  )
    from public.form_applications application
   where application.id = p_application_id;
$$;


ALTER FUNCTION "app_private"."form_application_projection"("p_application_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_archive_or_delete"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.manage');
declare form_row public.forms;
declare replay jsonb;
declare deleted boolean := false;
begin
  perform app_private.form_assert_payload_keys(p_payload, array['form_id','action'], 'form archive or delete');
  replay := app_private.form_begin_command(p_request_id, actor, 'form_archive_or_delete', p_expected_version, p_payload);
  if replay is not null then return replay; end if;
  select * into form_row from public.forms where id = (p_payload ->> 'form_id')::uuid for update;
  if form_row.id is null then raise no_data_found using message = 'form unavailable'; end if;
  if form_row.management_version <> p_expected_version then
    raise serialization_failure using message = 'expected_version mismatch';
  end if;
  if p_payload ->> 'action' = 'delete'
     and form_row.first_published_at is null
     and not exists(select 1 from public.form_applications where form_id = form_row.id)
     and not exists(select 1 from public.form_responses where form_id = form_row.id) then
    delete from public.forms where id = form_row.id;
    deleted := true;
  elsif p_payload ->> 'action' in ('delete', 'archive') then
    update public.forms set status = 'archived', archived_at = now(),
      management_version = management_version + 1, updated_by_person_id = actor, updated_at = now()
    where id = form_row.id;
  else
    raise invalid_parameter_value using message = 'invalid archive action';
  end if;
  return app_private.form_complete_command(
    p_request_id, jsonb_build_object('form_id', form_row.id, 'deleted', deleted)
  );
end;
$$;


ALTER FUNCTION "app_private"."form_archive_or_delete"("p_request_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_assert_application_payload_limits"("p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if jsonb_typeof(p_payload -> 'rules') <> 'array' then
    raise invalid_parameter_value using message = 'application rules must be an array';
  end if;
  if jsonb_array_length(p_payload -> 'rules') > 50 then
    raise check_violation using message = 'maximum 50 form audience rules';
  end if;
end;
$$;


