CREATE TABLE IF NOT EXISTS "public"."form_responses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "occurrence_id" "uuid" NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "form_id" "uuid" NOT NULL,
    "form_version_id" "uuid" NOT NULL,
    "identity_mode" "text" NOT NULL,
    "respondent_person_id" "uuid",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "management_version" bigint DEFAULT 1 NOT NULL,
    "anonymous_edit_secret_hash" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "submitted_at" timestamp with time zone,
    CONSTRAINT "form_responses_anonymity_ck" CHECK (((("identity_mode" = 'anonymous'::"text") AND ("respondent_person_id" IS NULL) AND ("anonymous_edit_secret_hash" IS NOT NULL)) OR (("identity_mode" = 'identified'::"text") AND ("respondent_person_id" IS NOT NULL) AND ("anonymous_edit_secret_hash" IS NULL)))),
    CONSTRAINT "form_responses_identity_ck" CHECK (("identity_mode" = ANY (ARRAY['identified'::"text", 'anonymous'::"text"]))),
    CONSTRAINT "form_responses_status_ck" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text"]))),
    CONSTRAINT "form_responses_submission_ck" CHECK (((("status" = 'draft'::"text") AND ("submitted_at" IS NULL)) OR (("status" = 'submitted'::"text") AND ("submitted_at" IS NOT NULL)))),
    CONSTRAINT "form_responses_version_ck" CHECK (("management_version" > 0))
);

ALTER TABLE ONLY "public"."form_responses" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."form_responses" OWNER TO "postgres";


COMMENT ON TABLE "public"."form_responses" IS 'Anonymous responses intentionally have no participation_id, person_id, response unit key, or shared correlation key.';



CREATE OR REPLACE FUNCTION "app_private"."form_assert_required_response_answers"("p_response" "public"."form_responses") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (
    select 1
      from public.form_items item
     where item.form_version_id = p_response.form_version_id
       and item.is_required
       and (
         not exists (
           select 1 from public.form_question_conditions condition_row
            where condition_row.target_item_id = item.id
         )
         or exists (
           select 1
             from public.form_question_conditions condition_row
             join public.form_answers source_answer
               on source_answer.response_id = p_response.id
              and source_answer.item_id = condition_row.source_item_id
            where condition_row.target_item_id = item.id
              and (
                (condition_row.condition_kind = 'yes_no'
                 and source_answer.yes_no_value = condition_row.expected_yes_no)
                or (condition_row.condition_kind = 'choice' and exists (
                  select 1 from public.form_answer_options selected
                   where selected.answer_id = source_answer.id
                     and selected.option_id = condition_row.source_option_id
                ))
              )
         )
       )
       and not exists (
         select 1
           from public.form_answers answer
          where answer.response_id = p_response.id
            and answer.item_id = item.id
            and case
              when item.kind = 'short_text' then nullif(btrim(answer.text_value), '') is not null
              when item.kind in ('single_choice', 'multiple_choice') then exists (
                select 1 from public.form_answer_options selected where selected.answer_id = answer.id
              )
              when item.kind in ('photo', 'gallery') then exists (
                select 1 from public.form_answer_assets attached where attached.answer_id = answer.id
              )
              else true
            end
       )
  ) then
    raise check_violation using message = 'required visible form answers are missing';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."form_assert_required_response_answers"("p_response" "public"."form_responses") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_assert_response_actor"("p_response" "public"."form_responses", "p_actor" "uuid", "p_edit_secret" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_response.identity_mode = 'identified' then
    if p_response.respondent_person_id <> p_actor then
      raise no_data_found using message = 'form response unavailable';
    end if;
  elsif nullif(p_edit_secret, '') is null
     or not app_private.form_verify_anonymous_edit_secret(
       p_edit_secret, p_response.anonymous_edit_secret_hash
     ) then
    raise no_data_found using message = 'form response unavailable';
  end if;
end;
$$;


