CREATE OR REPLACE FUNCTION "app_private"."form_item_config_valid"("p_kind" "text", "p_config" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  value_min numeric;
  value_max numeric;
  date_min date;
  date_max date;
  selection_min integer;
  selection_max integer;
  image_min integer;
  image_max integer;
  scale_min integer;
  scale_max integer;
  max_length integer;
begin
  if jsonb_typeof(p_config) <> 'object' or exists (
    select 1 from jsonb_object_keys(p_config) as key
     where key not in (
       'max_length', 'min_value', 'max_value', 'decimal_places', 'currency',
       'min_selections', 'max_selections', 'scale_min', 'scale_max',
       'scale_min_label', 'scale_max_label', 'allow_camera', 'allow_existing',
       'min_images', 'max_images'
     )
  ) then return false; end if;

  if p_kind = 'short_text' then
    if p_config - 'max_length' <> '{}'::jsonb
       or (p_config ? 'max_length' and (jsonb_typeof(p_config -> 'max_length') <> 'number'
           or (p_config ->> 'max_length')::numeric <> trunc((p_config ->> 'max_length')::numeric))) then return false; end if;
    max_length := coalesce((p_config ->> 'max_length')::integer, 1000);
    return max_length between 1 and 10000;
  elsif p_kind in ('integer', 'decimal', 'money') then
    if p_config - (case when p_kind = 'decimal' then array['min_value','max_value','decimal_places']
                       when p_kind = 'money' then array['min_value','max_value','currency']
                       else array['min_value','max_value'] end) <> '{}'::jsonb
       or (p_config ? 'min_value' and jsonb_typeof(p_config -> 'min_value') <> 'number')
       or (p_config ? 'max_value' and jsonb_typeof(p_config -> 'max_value') <> 'number') then return false; end if;
    value_min := (p_config ->> 'min_value')::numeric; value_max := (p_config ->> 'max_value')::numeric;
    if (p_kind in ('integer','money') and ((value_min is not null and value_min <> trunc(value_min)) or (value_max is not null and value_max <> trunc(value_max))))
       or (value_min is not null and value_max is not null and value_min > value_max) then return false; end if;
    return p_kind <> 'decimal' or not (p_config ? 'decimal_places')
      or (jsonb_typeof(p_config -> 'decimal_places') = 'number'
          and (p_config ->> 'decimal_places')::numeric = trunc((p_config ->> 'decimal_places')::numeric)
          and (p_config ->> 'decimal_places')::integer between 0 and 6);
  elsif p_kind = 'date' then
    if p_config - array['min_value','max_value'] <> '{}'::jsonb
       or (p_config ? 'min_value' and (jsonb_typeof(p_config -> 'min_value') <> 'string' or p_config ->> 'min_value' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'))
       or (p_config ? 'max_value' and (jsonb_typeof(p_config -> 'max_value') <> 'string' or p_config ->> 'max_value' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')) then return false; end if;
    date_min := (p_config ->> 'min_value')::date; date_max := (p_config ->> 'max_value')::date;
    return date_min is null or date_max is null or date_min <= date_max;
  elsif p_kind = 'multiple_choice' then
    if p_config - array['min_selections','max_selections'] <> '{}'::jsonb
       or (p_config ? 'min_selections' and jsonb_typeof(p_config -> 'min_selections') <> 'number')
       or (p_config ? 'max_selections' and jsonb_typeof(p_config -> 'max_selections') <> 'number')
       or (p_config ? 'min_selections' and (p_config ->> 'min_selections')::numeric <> trunc((p_config ->> 'min_selections')::numeric))
       or (p_config ? 'max_selections' and (p_config ->> 'max_selections')::numeric <> trunc((p_config ->> 'max_selections')::numeric)) then return false; end if;
    selection_min := coalesce((p_config ->> 'min_selections')::integer, 1);
    selection_max := coalesce((p_config ->> 'max_selections')::integer, 50);
    return selection_min between 1 and 50 and selection_max between selection_min and 50;
  elsif p_kind = 'scale' then
    if p_config - array['scale_min','scale_max','scale_min_label','scale_max_label'] <> '{}'::jsonb
       or (p_config ? 'scale_min' and jsonb_typeof(p_config -> 'scale_min') <> 'number')
       or (p_config ? 'scale_max' and jsonb_typeof(p_config -> 'scale_max') <> 'number')
       or (p_config ? 'scale_min' and (p_config ->> 'scale_min')::numeric <> trunc((p_config ->> 'scale_min')::numeric))
       or (p_config ? 'scale_max' and (p_config ->> 'scale_max')::numeric <> trunc((p_config ->> 'scale_max')::numeric)) then return false; end if;
    scale_min := coalesce((p_config ->> 'scale_min')::integer, 1);
    scale_max := coalesce((p_config ->> 'scale_max')::integer, 10);
    if scale_min <> 1 or scale_max not in (5, 10) then
      raise check_violation using message = 'scale configuration must be 1-5 or 1-10';
    end if;
    return true;
  elsif p_kind in ('photo','gallery') then
    if p_config - (case when p_kind = 'photo' then array['allow_camera','min_images','max_images']
                       else array['allow_existing','min_images','max_images'] end) <> '{}'::jsonb
       or (p_kind = 'photo' and p_config ? 'allow_camera' and jsonb_typeof(p_config -> 'allow_camera') <> 'boolean')
       or (p_kind = 'gallery' and p_config ? 'allow_existing' and jsonb_typeof(p_config -> 'allow_existing') <> 'boolean')
       or (p_config ? 'min_images' and jsonb_typeof(p_config -> 'min_images') <> 'number')
       or (p_config ? 'max_images' and jsonb_typeof(p_config -> 'max_images') <> 'number')
       or (p_config ? 'min_images' and (p_config ->> 'min_images')::numeric <> trunc((p_config ->> 'min_images')::numeric))
       or (p_config ? 'max_images' and (p_config ->> 'max_images')::numeric <> trunc((p_config ->> 'max_images')::numeric)) then return false; end if;
    image_min := coalesce((p_config ->> 'min_images')::integer, 1);
    image_max := coalesce((p_config ->> 'max_images')::integer, case when p_kind = 'photo' then 1 else 5 end);
    return image_min between 1 and 5 and image_max between image_min and 5
      and (p_kind <> 'photo' or (image_min = 1 and image_max = 1));
  end if;
  return p_config = '{}'::jsonb;
exception when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow then
  return false;
end;
$_$;


ALTER FUNCTION "app_private"."form_item_config_valid"("p_kind" "text", "p_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_list"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.read');
declare page_limit integer := least(greatest(coalesce((p_query ->> 'limit')::integer, 25), 1), 100);
declare cursor_updated timestamptz;
declare cursor_id uuid;
begin
  perform app_private.form_assert_payload_keys(
    p_query,
    array['institution_id','search','statuses','operational_statuses','kinds','starts_on_or_after','ends_on_or_before','cursor_updated_at','cursor_id','limit'],
    'form directory query'
  );
  cursor_updated := (p_query ->> 'cursor_updated_at')::timestamptz;
  cursor_id := (p_query ->> 'cursor_id')::uuid;
  return (
    with candidate_forms as (
      select form_row.*
        from public.forms form_row
       where ((p_query ->> 'institution_id') is null
              or form_row.institution_id = (p_query ->> 'institution_id')::uuid)
         and (nullif(p_query ->> 'search', '') is null
              or lower(form_row.title) like
                 '%' || lower(app_private.form_escape_like(p_query ->> 'search')) || '%' escape '\')
         and (coalesce(jsonb_array_length(p_query -> 'statuses'), 0) = 0 or form_row.status in (
           select jsonb_array_elements_text(p_query -> 'statuses')
         ))
         and (coalesce(jsonb_array_length(p_query -> 'kinds'), 0) = 0 or form_row.kind in (
           select jsonb_array_elements_text(p_query -> 'kinds')
         ))
    ), occurrence_windows as (
      select candidate.id as form_id,
             bool_or(
               occurrence_row.status in ('scheduled', 'open')
               and occurrence_row.opens_at <= now()
               and occurrence_row.closes_at > now()
             ) as is_active,
             bool_or(
               occurrence_row.status in ('scheduled', 'open')
               and occurrence_row.opens_at > now()
             ) as is_scheduled,
             bool_or(occurrence_row.opens_at::date >= (p_query ->> 'starts_on_or_after')::date)
               filter (where (p_query ->> 'starts_on_or_after') is not null) as matches_start,
             bool_or(occurrence_row.closes_at::date <= (p_query ->> 'ends_on_or_before')::date)
               filter (where (p_query ->> 'ends_on_or_before') is not null) as matches_end
        from candidate_forms candidate
        left join public.form_occurrences occurrence_row
          on occurrence_row.form_id = candidate.id
         and occurrence_row.institution_id = candidate.institution_id
       group by candidate.id
    ), operational as (
      select candidate.*,
             case
               when candidate.status = 'archived' then 'archived'
               when candidate.status = 'draft' then 'draft'
               when coalesce(occurrence_window.is_active, false) then 'active'
               when coalesce(occurrence_window.is_scheduled, false) then 'scheduled'
               else 'closed'
             end as operational_status
        from candidate_forms candidate
        join occurrence_windows occurrence_window on occurrence_window.form_id = candidate.id
       where ((p_query ->> 'starts_on_or_after') is null or coalesce(occurrence_window.matches_start, false))
         and ((p_query ->> 'ends_on_or_before') is null or coalesce(occurrence_window.matches_end, false))
    ), page as (
      select operational.*
        from operational
       where (coalesce(jsonb_array_length(p_query -> 'operational_statuses'), 0) = 0
              or operational_status in (select jsonb_array_elements_text(p_query -> 'operational_statuses')))
         and (cursor_updated is null or (updated_at, id) < (cursor_updated, cursor_id))
       order by updated_at desc, id desc
       limit page_limit + 1
    ), visible as (select * from page limit page_limit)
    select jsonb_build_object(
      'items', coalesce(jsonb_agg(jsonb_build_object(
        'id', id, 'title', title, 'kind', kind, 'status', status,
        'operational_status', operational_status, 'identity_mode', identity_mode,
        'updated_at', updated_at, 'management_version', management_version
      ) order by updated_at desc, id desc), '[]'::jsonb),
      'has_more', (select count(*) > page_limit from page),
      'next_cursor', (select jsonb_build_object('updated_at', updated_at, 'id', id)
                        from visible order by updated_at, id limit 1)
    ) from visible
  );
end;
$$;


ALTER FUNCTION "app_private"."form_list"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."form_list_audience_candidates"("p_query" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := app_private.require_forms_actor('forms.manage_applications');
declare page_limit integer := least(greatest(coalesce((p_query ->> 'limit')::integer, 25), 1), 100);
declare candidate_kind text := p_query ->> 'kind';
begin
  perform app_private.form_assert_payload_keys(
    p_query, array['institution_id','kind','search','cursor_label','cursor_id','limit'],
    'form audience candidates query'
  );
  return (
    with candidates as (
      select person.id, person.display_name as label, candidate_kind::text as kind
        from public.people person
        join public.institution_memberships membership on membership.person_id = person.id
       where candidate_kind in ('person','guardian','teacher','employee','profile')
         and membership.institution_id = (p_query ->> 'institution_id')::uuid
         and membership.status = 'active'
         and membership.revoked_at is null
      union all
      select unit_row.id, unit_row.name, 'unit'
        from public.units unit_row
       where candidate_kind = 'unit'
         and unit_row.institution_id = (p_query ->> 'institution_id')::uuid
      union all
      select group_row.id, group_row.name, 'group'
        from public.groups group_row
       where candidate_kind = 'group'
         and group_row.institution_id = (p_query ->> 'institution_id')::uuid
      union all
      select activity_row.id, activity_row.name, 'activity'
        from public.activity_definitions activity_row
       where candidate_kind = 'activity'
         and activity_row.institution_id = (p_query ->> 'institution_id')::uuid
      union all
      select institution_row.id, institution_row.public_name, 'institution'
        from public.institutions institution_row
       where candidate_kind = 'institution'
         and institution_row.id = (p_query ->> 'institution_id')::uuid
    ), filtered as (
      select * from candidates
       where (nullif(p_query ->> 'search', '') is null
              or label ilike '%' || app_private.form_escape_like(p_query ->> 'search') || '%' escape '\')
         and ((p_query ->> 'cursor_label') is null
              or (lower(label), id) > (lower(p_query ->> 'cursor_label'), (p_query ->> 'cursor_id')::uuid))
       order by lower(label), id limit page_limit + 1
    ), visible as (select * from filtered limit page_limit)
    select jsonb_build_object(
      'items', coalesce(jsonb_agg(jsonb_build_object('id', id, 'label', label, 'kind', kind)
                                  order by lower(label), id), '[]'::jsonb),
      'has_more', (select count(*) > page_limit from filtered),
      'next_cursor', (select jsonb_build_object('label', label, 'id', id)
                        from visible order by lower(label) desc, id desc limit 1)
    ) from visible
  );
end;
$$;


