CREATE OR REPLACE FUNCTION "app_private"."guard_access_profile_institution_delegation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if app_private.current_person_id() is not null
    and new.status='active' and new.revoked_at is null
    and not app_private.access_profile_can_delegate_institution(new.permission_id) then
    raise insufficient_privilege using message='cannot delegate institution capability';
  end if;
  return new;
end $$;


