CREATE OR REPLACE FUNCTION "app_private"."guard_access_profile_platform_override_delegation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare permission_code text;
begin
  if new.status='active' and new.effect='allow' then
    select code into permission_code from public.platform_permissions where id=new.permission_id;
    if permission_code is null or not app_private.has_platform_permission(permission_code) then
      raise insufficient_privilege using message='cannot delegate capability operator does not hold';
    end if;
  end if;
  return new;
end $$;


