CREATE OR REPLACE FUNCTION "app_private"."guardian_has_capability"("target_child_context_id" "uuid", "target_capability_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.child_contexts child_context
    join public.guardian_links guardian
      on guardian.child_person_id = child_context.child_person_id
     and guardian.guardian_person_id = app_private.current_person_id()
     and guardian.status = 'active'
     and guardian.revoked_at is null
    join public.guardian_context_permissions context_permission
      on context_permission.guardian_link_id = guardian.id
     and context_permission.child_context_id = child_context.id
     and context_permission.status = 'active'
     and (context_permission.starts_at is null
          or context_permission.starts_at <= pg_catalog.now())
     and (context_permission.expires_at is null
          or context_permission.expires_at > pg_catalog.now())
    join public.guardian_context_permission_grants capability_grant
      on capability_grant.guardian_context_permission_id = context_permission.id
     and capability_grant.status = 'active'
     and capability_grant.revoked_at is null
     and capability_grant.effect = 'allow'
    join public.guardian_permission_capabilities capability
      on capability.id = capability_grant.capability_id
     and capability.code = target_capability_code
     and capability.status = 'active'
    where child_context.id = target_child_context_id
  )
$$;


ALTER FUNCTION "app_private"."guardian_has_capability"("target_child_context_id" "uuid", "target_capability_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."happens_actor"("p_institution_id" "uuid", "p_permission" "text", "p_unit_id" "uuid", "p_group_id" "uuid") RETURNS TABLE("person_id" "uuid", "membership_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null then raise insufficient_privilege using message='authentication_required'; end if;
  if not app_private.has_institution_permission(p_institution_id,p_permission,p_unit_id,p_group_id,false)
  then raise insufficient_privilege using message='happens_permission_denied'; end if;
  return query select link.person_id,membership.id
  from public.person_auth_links link join public.institution_memberships membership on membership.person_id=link.person_id
  where link.auth_user_id=(select auth.uid()) and link.status='active' and membership.institution_id=p_institution_id
    and membership.status='active' and membership.revoked_at is null order by membership.created_at limit 1;
  if not found then raise insufficient_privilege using message='active_membership_required'; end if;
end $$;


ALTER FUNCTION "app_private"."happens_actor"("p_institution_id" "uuid", "p_permission" "text", "p_unit_id" "uuid", "p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."happens_audience_matches_role"("p_role_code" "text", "p_audience" "public"."happens_audience_kind") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when lower(coalesce(p_role_code,'')) in ('guardian','responsible','responsavel','parent','family')
      then p_audience in ('families','guardians_only')
    when lower(coalesce(p_role_code,'')) in ('student','aluno')
      then p_audience='students'
    else p_audience='school_staff'
  end
$$;


