    AS $$
 select jsonb_build_object(
  'job_id',job.id,'domain',job.target_domain,'format',job.source_format,
  'state',job.processing_state,'summary',job.summary,
  'valid_count',coalesce((job.summary->>'valid_count')::integer,0),
  'rejected_count',coalesce((job.summary->>'rejected_count')::integer,0),
  'errors',coalesce((
    select jsonb_agg(jsonb_build_object(
      'row_number',e.row_number,'field',e.column_name,'code',e.error_code,'message',e.message
    ) order by e.row_number,e.column_name)
    from public.import_errors e where e.import_job_id=job.id
  ),'[]'::jsonb)
 )
 from public.import_jobs job where job.id=p_job_id
$$;


