CREATE OR REPLACE FUNCTION "app_private"."institution_profile_links_are_valid"("links" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
begin
  if links is null
     or pg_catalog.jsonb_typeof(links) <> 'array'
     or pg_catalog.jsonb_array_length(links) > 3 then
    return false;
  end if;

  return not exists (
    select 1
    from pg_catalog.jsonb_array_elements(links) as entry(value)
    where pg_catalog.jsonb_typeof(entry.value) <> 'object'
       or not (entry.value ? 'label' and entry.value ? 'url')
       or pg_catalog.jsonb_typeof(entry.value -> 'label') <> 'string'
       or pg_catalog.jsonb_typeof(entry.value -> 'url') <> 'string'
       or pg_catalog.btrim(entry.value ->> 'label') = ''
       or pg_catalog.char_length(entry.value ->> 'label') > 60
       or pg_catalog.btrim(entry.value ->> 'url') = ''
       or pg_catalog.char_length(entry.value ->> 'url') > 2048
       or pg_catalog.btrim(entry.value ->> 'url')
            !~* '^https?://[[:alnum:]]([[:alnum:].-]*[[:alnum:]])?(:[0-9]{1,5})?([/?#][^[:space:]]*)?$'
       or exists (
         select 1
         from pg_catalog.jsonb_object_keys(entry.value) as object_key(key)
         where object_key.key not in ('label', 'url')
       )
  );
end;
$_$;


ALTER FUNCTION "app_private"."institution_profile_links_are_valid"("links" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."list_superadmin_people"("p_search" "text" DEFAULT NULL::"text", "p_person_types" "public"."person_type"[] DEFAULT NULL::"public"."person_type"[], "p_statuses" "public"."record_status"[] DEFAULT NULL::"public"."record_status"[], "p_institution_id" "uuid" DEFAULT NULL::"uuid", "p_unit_id" "uuid" DEFAULT NULL::"uuid", "p_group_id" "uuid" DEFAULT NULL::"uuid", "p_role_code" "text" DEFAULT NULL::"text", "p_has_auth" boolean DEFAULT NULL::boolean, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
begin
  perform app_private.assert_people_permission('people.read');

  if p_page < 1 then
    raise invalid_parameter_value using message = 'page must be positive';
  end if;
  if p_page_size not in (20, 50, 100) then
    raise invalid_parameter_value using message = 'page_size must be 20, 50 or 100';
  end if;
  if p_unit_id is not null and not exists (
    select 1 from public.units unit
    where unit.id = p_unit_id
      and (p_institution_id is null or unit.institution_id = p_institution_id)
  ) then
    raise check_violation using message = 'unit does not belong to institution';
  end if;
  if p_group_id is not null and not exists (
    select 1 from public.groups group_row
    where group_row.id = p_group_id
      and (p_institution_id is null or group_row.institution_id = p_institution_id)
      and (p_unit_id is null or group_row.unit_id = p_unit_id)
  ) then
    raise check_violation using message = 'group does not belong to requested context';
  end if;

  with filtered as (
    select person.*
    from public.people person
    where person.deleted_at is null
      and (
        p_search is null
        or btrim(p_search) = ''
        or person.display_name ilike '%' || btrim(p_search) || '%'
        or person.first_name ilike '%' || btrim(p_search) || '%'
        or person.last_name ilike '%' || btrim(p_search) || '%'
      )
      and (p_person_types is null or person.person_type = any(p_person_types))
      and (p_statuses is null or person.status = any(p_statuses))
      and (
        p_has_auth is null
        or p_has_auth = exists (
          select 1
          from public.person_auth_links auth_link
          where auth_link.person_id = person.id
            and auth_link.status = 'active'
            and auth_link.revoked_at is null
        )
      )
      and (
        (
          p_institution_id is null
          and p_unit_id is null
          and p_group_id is null
          and p_role_code is null
        )
        or (
          person.person_type in ('adult', 'service')
          and exists (
            select 1
            from public.institution_memberships membership
            left join public.institution_role_assignments assignment
              on assignment.membership_id = membership.id
              and assignment.status = 'active'
            left join public.institution_roles role
              on role.id = assignment.role_id
            where membership.person_id = person.id
              and membership.status = 'active'
              and membership.revoked_at is null
              and (
                p_institution_id is null
                or membership.institution_id = p_institution_id
              )
              and (
                p_unit_id is null
                or membership.scope_unit_id = p_unit_id
                or assignment.scope_unit_id = p_unit_id
              )
              and (
                p_group_id is null
                or membership.scope_group_id = p_group_id
                or assignment.scope_group_id = p_group_id
              )
              and (
                p_role_code is null
                or membership.role_code = p_role_code
                or role.code = p_role_code
              )
          )
        )
        or (
          person.person_type = 'child'
          and p_role_code is null
          and exists (
            select 1
            from public.child_contexts child_context
            left join public.child_unit_links unit_link
              on unit_link.child_context_id = child_context.id
              and unit_link.status in ('pending', 'awaiting_allocation', 'active')
              and unit_link.revoked_at is null
            left join public.child_group_links group_link
              on group_link.child_unit_link_id = unit_link.id
              and group_link.status = 'active'
            where child_context.child_person_id = person.id
              and child_context.status = 'active'
              and (
                p_institution_id is null
                or child_context.institution_id = p_institution_id
              )
              and (p_unit_id is null or unit_link.unit_id = p_unit_id)
              and (p_group_id is null or group_link.group_id = p_group_id)
          )
        )
      )
  ),
  page_rows as (
    select *
    from filtered
    order by lower(display_name), id
    offset (p_page - 1) * p_page_size
    limit p_page_size
  )
  select jsonb_build_object(
    'items',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', row.id,
            'person_type', row.person_type,
            'display_name', row.display_name,
            'status', row.status,
            'updated_at', row.updated_at,
            'has_active_login', exists (
              select 1
              from public.person_auth_links auth_link
              where auth_link.person_id = row.id
                and auth_link.status = 'active'
                and auth_link.revoked_at is null
            ),
            'institution_count', (
              select count(distinct scope.institution_id)
              from (
                select membership.institution_id
                from public.institution_memberships membership
                where membership.person_id = row.id
                  and membership.status = 'active'
                  and membership.revoked_at is null
                union
                select child_context.institution_id
                from public.child_contexts child_context
                where child_context.child_person_id = row.id
                  and child_context.status = 'active'
              ) scope
            )
          )
          order by lower(row.display_name), row.id
        )
        from page_rows row
      ),
      '[]'::jsonb
    ),
    'page', p_page,
    'page_size', p_page_size,
    'total', (select count(*) from filtered)
  )
  into result;

  return result;
end
$$;


ALTER FUNCTION "app_private"."list_superadmin_people"("p_search" "text", "p_person_types" "public"."person_type"[], "p_statuses" "public"."record_status"[], "p_institution_id" "uuid", "p_unit_id" "uuid", "p_group_id" "uuid", "p_role_code" "text", "p_has_auth" boolean, "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."list_units_for_superadmin"("p_search" "text", "p_institution_ids" "uuid"[], "p_institution_type_ids" "uuid"[], "p_unit_type_ids" "uuid"[], "p_unit_statuses" "text"[], "p_plan_ids" "text"[], "p_states" "text"[], "p_cities" "text"[], "p_districts" "text"[], "p_sort" "text", "p_ascending" boolean, "p_offset" integer, "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$declare r jsonb;s text;begin
if(select auth.uid())is null or app_private.current_person_id()is null then raise insufficient_privilege using message='authentication required';end if;
if p_offset<0 or p_limit not between 1 and 100 then raise invalid_parameter_value using message='invalid pagination';end if;s:=app_private.normalize_unit_sort(p_sort);
with f as(select*from public.unit_directory d where app_private.has_scoped_platform_permission('units.read',d.institution_id)
and(nullif(btrim(p_search),'')is null or d.name ilike'%'||p_search||'%'or d.institution_name ilike'%'||p_search||'%'or d.handle ilike'%'||regexp_replace(p_search,'^@','','g')||'%')
and(app_private.unit_filter_is_empty(p_institution_ids)or d.institution_id=any(p_institution_ids))
and(app_private.unit_filter_is_empty(p_institution_type_ids)or d.institution_type_id=any(p_institution_type_ids))
and(app_private.unit_filter_is_empty(p_unit_type_ids)or d.unit_type_id=any(p_unit_type_ids))
and(app_private.unit_filter_is_empty(p_unit_statuses)or d.unit_status=any(p_unit_statuses))
and(app_private.unit_filter_is_empty(p_plan_ids)or d.effective_plan_id::text=any(p_plan_ids)or d.effective_plan_code=any(p_plan_ids))
and(app_private.unit_filter_is_empty(p_states)or d.address->>'state'=any(p_states))
and(app_private.unit_filter_is_empty(p_cities)or d.address->>'city'=any(p_cities))
and(app_private.unit_filter_is_empty(p_districts)or d.address->>'district'=any(p_districts))),
q as(select*from f order by
case when p_ascending and s='name'then lower(name)end,case when not p_ascending and s='name'then lower(name)end desc,
case when p_ascending and s='institution_name'then lower(institution_name)end,case when not p_ascending and s='institution_name'then lower(institution_name)end desc,
case when p_ascending and s='institution_type_name'then lower(coalesce(institution_type_name,''))end,case when not p_ascending and s='institution_type_name'then lower(coalesce(institution_type_name,''))end desc,
case when p_ascending and s='unit_type_name'then lower(unit_type_name)end,case when not p_ascending and s='unit_type_name'then lower(unit_type_name)end desc,
case when p_ascending and s='unit_status'then unit_status end,case when not p_ascending and s='unit_status'then unit_status end desc,
case when p_ascending and s='plan_name'then lower(coalesce(effective_plan_name,''))end,case when not p_ascending and s='plan_name'then lower(coalesce(effective_plan_name,''))end desc,
case when p_ascending and s='groups_count'then groups_count end,case when not p_ascending and s='groups_count'then groups_count end desc,
case when p_ascending and s='activities_count'then activities_count end,case when not p_ascending and s='activities_count'then activities_count end desc,
case when p_ascending and s='updated_at'then updated_at end,case when not p_ascending and s='updated_at'then updated_at end desc,
case when p_ascending and s='contact_email'then lower(coalesce(contact->>'email',''))end,case when not p_ascending and s='contact_email'then lower(coalesce(contact->>'email',''))end desc,
case when p_ascending and s='contact_phone'then coalesce(contact->>'phone','')end,case when not p_ascending and s='contact_phone'then coalesce(contact->>'phone','')end desc,
case when p_ascending and s='contact_mobile_phone'then coalesce(contact->>'mobile_phone','')end,case when not p_ascending and s='contact_mobile_phone'then coalesce(contact->>'mobile_phone','')end desc,
case when p_ascending and s='street'then lower(coalesce(address->>'street',''))end,case when not p_ascending and s='street'then lower(coalesce(address->>'street',''))end desc,
case when p_ascending and s='address_number'then lower(coalesce(address->>'number',''))end,case when not p_ascending and s='address_number'then lower(coalesce(address->>'number',''))end desc,
case when p_ascending and s='complement'then lower(coalesce(address->>'complement',''))end,case when not p_ascending and s='complement'then lower(coalesce(address->>'complement',''))end desc,
case when p_ascending and s='district'then lower(coalesce(address->>'district',''))end,case when not p_ascending and s='district'then lower(coalesce(address->>'district',''))end desc,
case when p_ascending and s='postal_code'then coalesce(address->>'postal_code','')end,case when not p_ascending and s='postal_code'then coalesce(address->>'postal_code','')end desc,
case when p_ascending and s='city'then lower(coalesce(address->>'city',''))end,case when not p_ascending and s='city'then lower(coalesce(address->>'city',''))end desc,
case when p_ascending and s='state'then lower(coalesce(address->>'state',''))end,case when not p_ascending and s='state'then lower(coalesce(address->>'state',''))end desc,id offset p_offset limit p_limit)
select jsonb_build_object('items',coalesce((select jsonb_agg(app_private.unit_directory_row_payload(to_jsonb(q)))from q),'[]'::jsonb),'total_count',(select count(*)from f))into r;return r;end$$;


