CREATE OR REPLACE FUNCTION "app_private"."preview_unit_institution_transfer"("p_unit_id" "uuid", "p_destination_institution_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare source uuid;unit_slug text;deps jsonb;blocked jsonb;begin
select institution_id,slug into source,unit_slug from public.units where id=p_unit_id;if source is null then raise no_data_found using message='unit not found';end if;
if source=p_destination_institution_id or not exists(select 1 from public.institutions where id=p_destination_institution_id and deleted_at is null)
then raise invalid_parameter_value using message='invalid destination';end if;
if not app_private.has_scoped_platform_permission('units.transfer',source)
or not app_private.has_scoped_platform_permission('units.transfer',p_destination_institution_id)
then raise insufficient_privilege using message='units.transfer required in both institutions';end if;
deps:=jsonb_build_object('groups',(select count(*)from public.groups where unit_id=p_unit_id),
'institution_role_assignments',(select count(*)from public.institution_role_assignments where scope_unit_id=p_unit_id),
'child_unit_links',(select count(*)from public.child_unit_links where unit_id=p_unit_id),
'activity_unit_links',(select count(*)from public.activity_unit_links where unit_id=p_unit_id),
'invitations',(select count(*)from public.invitations where unit_id=p_unit_id),
'slug_conflicts',(select count(*)from public.units where institution_id=p_destination_institution_id and slug=unit_slug));
select coalesce(jsonb_agg(key),'[]'::jsonb)into blocked from jsonb_each_text(deps)where value::bigint>0;
return jsonb_build_object('unit_id',p_unit_id,'source_institution_id',source,
'destination_institution_id',p_destination_institution_id,'dependencies',deps,
'incompatible_dependencies',blocked,'can_transfer',jsonb_array_length(blocked)=0);end$$;


ALTER FUNCTION "app_private"."preview_unit_institution_transfer"("p_unit_id" "uuid", "p_destination_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."profile_about_allowed_field"("p_subject_type" "text", "p_key" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select case p_subject_type
  when 'institution' then p_key=any(array['display_name','display_address','precise_location','phone','mobile','email','website','service_hours','city_state','founded_on','institution_type','visible_links','identity_institutional'])
  when 'unit' then p_key=any(array['display_name','display_address','precise_location','phone','mobile','email','website','service_hours','city_state','visible_links','unit_link','inheritance_origin'])
  when 'group' then p_key=any(array['display_name','description','proposal','general_hours','unit_link','institution_link','activity_links','team_links','important_information'])
  when 'activity' then p_key=any(array['display_name','description','objective','audience','general_hours','institutional_location','methodology','materials','general_guidance','team_links'])
  when 'person' then p_key=any(array['display_name','city_state','professional_role','visible_links'])
  else false end
$$;


ALTER FUNCTION "app_private"."profile_about_allowed_field"("p_subject_type" "text", "p_key" "text") OWNER TO "postgres";


