CREATE TABLE IF NOT EXISTS "public"."profile_about_pages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "subject_type" "text" NOT NULL,
    "institution_subject_id" "uuid",
    "unit_subject_id" "uuid",
    "group_subject_id" "uuid",
    "activity_subject_id" "uuid",
    "person_subject_id" "uuid",
    "state" "text" DEFAULT 'draft'::"text" NOT NULL,
    "version" bigint DEFAULT 0 NOT NULL,
    "created_by_person_id" "uuid" NOT NULL,
    "updated_by_person_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "published_at" timestamp with time zone,
    CONSTRAINT "profile_about_pages_state_check" CHECK (("state" = ANY (ARRAY['draft'::"text", 'published'::"text", 'archived'::"text"]))),
    CONSTRAINT "profile_about_pages_subject_check" CHECK ((("num_nonnulls"("institution_subject_id", "unit_subject_id", "group_subject_id", "activity_subject_id", "person_subject_id") = 1) AND ((("subject_type" = 'institution'::"text") AND ("institution_subject_id" = "institution_id")) OR (("subject_type" = 'unit'::"text") AND ("unit_subject_id" IS NOT NULL)) OR (("subject_type" = 'group'::"text") AND ("group_subject_id" IS NOT NULL)) OR (("subject_type" = 'activity'::"text") AND ("activity_subject_id" IS NOT NULL)) OR (("subject_type" = 'person'::"text") AND ("person_subject_id" IS NOT NULL))))),
    CONSTRAINT "profile_about_pages_subject_type_check" CHECK (("subject_type" = ANY (ARRAY['institution'::"text", 'unit'::"text", 'group'::"text", 'activity'::"text", 'person'::"text"]))),
    CONSTRAINT "profile_about_pages_version_check" CHECK (("version" >= 0))
);

ALTER TABLE ONLY "public"."profile_about_pages" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."profile_about_pages" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."profile_about_page_for"("p_subject_type" "text", "p_subject_id" "uuid") RETURNS "public"."profile_about_pages"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select p.* from public.profile_about_pages p where p.subject_type=p_subject_type and
  case p_subject_type when 'institution' then p.institution_subject_id=p_subject_id
   when 'unit' then p.unit_subject_id=p_subject_id when 'group' then p.group_subject_id=p_subject_id
   when 'activity' then p.activity_subject_id=p_subject_id when 'person' then p.person_subject_id=p_subject_id else false end
$$;


ALTER FUNCTION "app_private"."profile_about_page_for"("p_subject_type" "text", "p_subject_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."profile_about_publication_max_video_seconds"("p_institution_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  result integer := 30;
begin
  if pg_catalog.to_regprocedure('app_private.now_max_video_seconds(uuid)') is not null then
    execute 'select app_private.now_max_video_seconds($1)'
      into result
      using p_institution_id;
  end if;
  return greatest(coalesce(result, 30), 1);
end
$_$;


