CREATE OR REPLACE FUNCTION "app_private"."promote_activity_to_institution_standard"("target_activity_id" "uuid", "target_governance_kind" "text", "target_reason" "text") RETURNS "public"."activity_definitions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid := app_private.current_person_id();
  activity_record public.activity_definitions%rowtype;
begin
  if target_governance_kind not in ('optional','mandatory','fixed') then
    raise exception 'invalid governance kind';
  end if;
  select * into activity_record from public.activity_definitions
  where id = target_activity_id for update;
  if activity_record.id is null then raise exception 'activity not found'; end if;
  if not app_private.has_context_permission(
    activity_record.institution_id, 'activities.manage',
    null, null, activity_record.id, null, true
  ) then raise exception 'institution activity management required'; end if;

  update public.activity_definitions
  set distribution_scope = 'institution_standard',
      governance_kind = target_governance_kind,
      promoted_by_person_id = coalesce(promoted_by_person_id, actor_person_id),
      promoted_at = coalesce(promoted_at, now()),
      updated_at = now()
  where id = target_activity_id
  returning * into activity_record;

  insert into audit.audit_logs(
    actor_person_id, action_code, object_type, object_id, institution_id,
    reason, after_json
  ) values (
    actor_person_id, 'activity.promoted', 'activity_definition',
    activity_record.id, activity_record.institution_id,
    nullif(btrim(target_reason), ''), to_jsonb(activity_record)
  );
  return activity_record;
end;
$$;


ALTER FUNCTION "app_private"."promote_activity_to_institution_standard"("target_activity_id" "uuid", "target_governance_kind" "text", "target_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."prune_expired_institution_management_receipts"("p_limit" integer DEFAULT 1000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  deleted_count integer;
begin
  if p_limit is null or p_limit < 1 or p_limit > 10000 then
    raise invalid_parameter_value using
      message = 'receipt prune limit must be between 1 and 10000';
  end if;

  with expired_receipts as (
    select receipt.request_id
    from app_private.institution_management_command_receipts receipt
    where receipt.expires_at <= pg_catalog.clock_timestamp()
    order by receipt.expires_at, receipt.request_id
    limit p_limit
    for update skip locked
  ), deleted_receipts as (
    delete from app_private.institution_management_command_receipts receipt
    using expired_receipts expired
    where receipt.request_id = expired.request_id
    returning 1
  )
  select count(*)::integer
  into deleted_count
  from deleted_receipts;

  return deleted_count;
end;
$$;


ALTER FUNCTION "app_private"."prune_expired_institution_management_receipts"("p_limit" integer) OWNER TO "postgres";


