     or new.evidence_reference is distinct from old.evidence_reference
     or new.decision_reason is distinct from old.decision_reason then
    insert into app_private.health_domain_release_gate_events(
      gate_id,
      previous_status,
      new_status,
      evidence_reference,
      decision_reason,
      actor_person_id
    )
    values (
      new.id,
      old.gate_status,
      new.gate_status,
      new.evidence_reference,
      new.decision_reason,
      new.decided_by_person_id
    );
  end if;
  new.updated_at := clock_timestamp();
  return new;
end
$$;


