    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT'
     or new.normalized_handle is distinct from old.normalized_handle then
    insert into app_private.person_identity_correction_ledger(
      person_id,
      correction_kind,
      old_value,
      new_value,
      changed_by_auth_user_id,
      change_reason
    )
    values (
      new.person_id,
      'handle',
      case when tg_op = 'UPDATE' then old.normalized_handle else null end,
      new.normalized_handle,
      (select auth.uid()),
      nullif(current_setting('coelo.identity_change_reason', true), '')
    );
  end if;
  return new;
end
