    "body_text" "text",
    "body_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "message_type" "text" DEFAULT 'text'::"text" NOT NULL,
    "status" "public"."record_status" DEFAULT 'active'::"public"."record_status" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "author_membership_id" "uuid",
    "author_experience_kind" "text",
    "author_role_snapshot" "text",
    CONSTRAINT "messages_author_experience_kind_check" CHECK (("author_experience_kind" = ANY (ARRAY['family'::"text", 'professional'::"text"])))
);


ALTER TABLE "public"."messages" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."send_context_message"("target_conversation_id" "uuid", "target_body_text" "text", "target_child_context_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[]) RETURNS "public"."messages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid:=app_private.current_person_id();
  participant_record public.conversation_participants%rowtype;
  created_message public.messages%rowtype;
begin
  if nullif(btrim(target_body_text),'') is null then
    raise exception 'message body required';
  end if;
  if not app_private.can_access_conversation(target_conversation_id,true) then
    raise exception 'conversation is not writable';
  end if;
  select * into participant_record
  from public.conversation_participants
  where conversation_id=target_conversation_id and person_id=actor_person_id
    and status='active' and left_at is null
  order by joined_at desc limit 1;
  if participant_record.id is null then
    raise exception 'active participant required to send';
  end if;
  if exists (
    select 1 from unnest(target_child_context_ids) child_id
    where not exists (
      select 1 from public.conversation_child_contexts conversation_child
      where conversation_child.conversation_id=target_conversation_id
        and conversation_child.child_context_id=child_id
    )
  ) then raise exception 'message child is outside conversation'; end if;

  insert into public.messages(
    conversation_id,author_person_id,body_text,message_type,
    author_membership_id,author_experience_kind,author_role_snapshot
  ) values (
    target_conversation_id,actor_person_id,btrim(target_body_text),'text',
    participant_record.membership_id,participant_record.experience_kind,
    participant_record.role_snapshot
  ) returning * into created_message;

  insert into public.message_child_contexts(message_id,child_context_id)
  select distinct created_message.id,child_id
  from unnest(target_child_context_ids) child_id;
  return created_message;
end;
$$;


ALTER FUNCTION "app_private"."send_context_message"("target_conversation_id" "uuid", "target_body_text" "text", "target_child_context_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."set_activity_canonical_handle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare source_slug text; institution_slug text;
begin
 new.handle_stem:=lower(btrim(new.handle_stem));
 if new.handle_stem !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
    or length(new.handle_stem) not between 3 and 64 then
  raise invalid_parameter_value using message='invalid activity handle stem';
 end if;
 select institution.slug into institution_slug from public.institutions institution
  where institution.id=new.institution_id;
 if institution_slug is null then raise foreign_key_violation using message='institution not found'; end if;
 if new.origin_scope_kind='unit' then
  select unit.slug into source_slug from public.units unit
   where unit.id=new.origin_unit_id and unit.institution_id=new.institution_id;
  if source_slug is null then raise foreign_key_violation using message='unit outside institution'; end if;
  source_slug:=source_slug||'.'||institution_slug;
 else source_slug:=institution_slug;
 end if;
 new.canonical_handle:=new.handle_stem||'.'||lower(source_slug);
 if exists(select 1 from public.activity_handle_aliases alias_record
   where lower(alias_record.alias)=lower(new.canonical_handle)
     and alias_record.activity_id<>new.id) then
  raise unique_violation using message='activity handle reserved by alias';
 end if;
 return new;
end $_$;


ALTER FUNCTION "app_private"."set_activity_canonical_handle"() OWNER TO "postgres";


