CREATE OR REPLACE FUNCTION "app_private"."submit_attendance_notice"("target_child_group_link_id" "uuid", "target_notice_type" "text", "target_starts_at" timestamp with time zone, "target_ends_at" timestamp with time zone, "target_reason_id" "uuid", "target_reason_detail" "text", "target_note" "text", "target_attachment_media_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_person_id uuid:=app_private.current_person_id();
  context_record record;
  guardian_link_id uuid;
  created_notice_id uuid;
  notification_id uuid;
begin
  perform notification_id; -- Notification insert identity is intentionally not returned.
  if target_notice_type not in (
    'absence','expected_presence','late_arrival','early_departure'
  ) then raise exception 'invalid attendance notice type'; end if;
  select child_context.id child_context_id,child_context.institution_id,
         child_unit.unit_id,child_group.group_id,child_context.child_person_id
    into context_record
  from public.child_group_links child_group
  join public.child_unit_links child_unit on child_unit.id=child_group.child_unit_link_id
  join public.child_contexts child_context on child_context.id=child_unit.child_context_id
  where child_group.id=target_child_group_link_id
    and child_group.status='active'
    and child_unit.status in ('active','awaiting_allocation')
    and child_context.status='active';
  if context_record.child_context_id is null then raise exception 'child context not active'; end if;
  if not app_private.guardian_has_capability(
    context_record.child_context_id,'manage_attendance_notices'
  ) then raise exception 'guardian cannot submit attendance notice'; end if;
  select id into guardian_link_id from public.guardian_links
  where guardian_person_id=actor_person_id
    and child_person_id=context_record.child_person_id
    and status='active' and revoked_at is null;

  insert into public.attendance_notices(
    institution_id,unit_id,group_id,child_context_id,child_group_link_id,
    guardian_link_id,notice_type,starts_at,ends_at,reason_id,reason_detail,
    note,created_by_person_id
  ) values (
    context_record.institution_id,context_record.unit_id,context_record.group_id,
    context_record.child_context_id,target_child_group_link_id,guardian_link_id,
    target_notice_type,target_starts_at,target_ends_at,target_reason_id,
    nullif(btrim(target_reason_detail),''),nullif(btrim(target_note),''),
    actor_person_id
  ) returning id into created_notice_id;

  if target_attachment_media_id is not null then
    insert into public.attendance_notice_attachments(
      attendance_notice_id,media_asset_id
    ) values (created_notice_id,target_attachment_media_id);
  end if;

  insert into public.context_notification_events(
    institution_id,unit_id,group_id,child_context_id,event_code,object_type,
    object_id,payload_json,created_by_person_id
  ) values (
    context_record.institution_id,context_record.unit_id,context_record.group_id,
    context_record.child_context_id,'attendance_notice_created',
    'attendance_notice',created_notice_id,
    jsonb_build_object('notice_type',target_notice_type,'review_status','pending'),
    actor_person_id
  );

  if target_starts_at>now()+interval '1 day' then
    insert into public.context_notification_events(
      institution_id,unit_id,group_id,child_context_id,event_code,object_type,
      object_id,payload_json,deliver_at,created_by_person_id
    ) values (
      context_record.institution_id,context_record.unit_id,context_record.group_id,
      context_record.child_context_id,'attendance_notice_reminder',
      'attendance_notice',created_notice_id,
      jsonb_build_object('notice_type',target_notice_type),
      target_starts_at-interval '1 day',actor_person_id
    );
  end if;
  return created_notice_id;
end;
$$;


ALTER FUNCTION "app_private"."submit_attendance_notice"("target_child_group_link_id" "uuid", "target_notice_type" "text", "target_starts_at" timestamp with time zone, "target_ends_at" timestamp with time zone, "target_reason_id" "uuid", "target_reason_detail" "text", "target_note" "text", "target_attachment_media_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_assignment_candidates"("p_profile_id" "uuid", "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 25, "p_after_name" "text" DEFAULT NULL::"text", "p_after_person_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare domain text;size_no int:=least(greatest(coalesce(p_limit,25),1),100);result jsonb;
begin
  domain:=case when exists(select 1 from public.platform_roles where id=p_profile_id) then 'platform'
    when exists(select 1 from public.institution_roles where id=p_profile_id) then 'institution'
    when exists(select 1 from public.access_profile_templates where id=p_profile_id and domain='principal') then 'principal' end;
  perform app_private.require_profile_authority(domain);
  if not app_private.has_platform_permission('people.read') then raise insufficient_privilege using message='people read permission required';end if;
  if domain='platform' then
    with rows as(select person_record.id person_id,person_record.display_name,null::uuid membership_id,
      null::uuid institution_id,null::uuid guardian_context_permission_id
      from public.people person_record where person_record.status='active' and person_record.deleted_at is null
        and (nullif(btrim(p_query),'') is null or person_record.display_name ilike '%'||btrim(p_query)||'%')
        and (p_after_name is null or (lower(person_record.display_name),person_record.id)>(lower(p_after_name),p_after_person_id))
        and not exists(select 1 from public.platform_memberships membership where membership.person_id=person_record.id
          and membership.role_id=p_profile_id and membership.status='active' and membership.revoked_at is null)),
    page as(select * from rows order by lower(display_name),person_id limit size_no+1)
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page)-'row_number' order by lower(display_name),person_id)
      filter(where row_number<=size_no),'[]'),'next_cursor',case when count(*)>size_no then
      (select jsonb_build_object('name',display_name,'id',person_id) from page order by lower(display_name),person_id offset size_no-1 limit 1) end)
    into result from(select page.*,row_number() over(order by lower(display_name),person_id) row_number from page) page;
  elsif domain='institution' then
    with rows as(select person_record.id person_id,person_record.display_name,membership.id membership_id,
      membership.institution_id,null::uuid guardian_context_permission_id
      from public.institution_memberships membership join public.people person_record on person_record.id=membership.person_id
      join public.institution_roles role_record on role_record.id=p_profile_id
      where membership.status='active' and membership.revoked_at is null and person_record.deleted_at is null
        and (role_record.institution_id is null or role_record.institution_id=membership.institution_id)
        and (nullif(btrim(p_query),'') is null or person_record.display_name ilike '%'||btrim(p_query)||'%')
        and (p_after_name is null or (lower(person_record.display_name),person_record.id)>(lower(p_after_name),p_after_person_id))
        and not exists(select 1 from public.institution_role_assignments assignment where assignment.membership_id=membership.id
          and assignment.role_id=p_profile_id and assignment.status='active'
          and (assignment.expires_at is null or assignment.expires_at>now()))),
    page as(select * from rows order by lower(display_name),person_id limit size_no+1)
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page)-'row_number' order by lower(display_name),person_id)
      filter(where row_number<=size_no),'[]'),'next_cursor',case when count(*)>size_no then
      (select jsonb_build_object('name',display_name,'id',person_id) from page order by lower(display_name),person_id offset size_no-1 limit 1) end)
    into result from(select page.*,row_number() over(order by lower(display_name),person_id) row_number from page) page;
  elsif domain='principal' then
    with rows as(select guardian.guardian_person_id person_id,person_record.display_name,null::uuid membership_id,
      child_context.institution_id,context_permission.id guardian_context_permission_id
      from public.guardian_context_permissions context_permission
      join public.guardian_links guardian on guardian.id=context_permission.guardian_link_id
        and guardian.status='active' and guardian.revoked_at is null
      join public.people person_record on person_record.id=guardian.guardian_person_id
      join public.child_contexts child_context on child_context.id=context_permission.child_context_id
      where context_permission.status='active' and person_record.deleted_at is null
        and (context_permission.source_template_id is distinct from p_profile_id)
        and (nullif(btrim(p_query),'') is null or person_record.display_name ilike '%'||btrim(p_query)||'%')
        and (p_after_name is null or (lower(person_record.display_name),person_record.id)>(lower(p_after_name),p_after_person_id))),
    page as(select * from rows order by lower(display_name),person_id limit size_no+1)
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page)-'row_number' order by lower(display_name),person_id)
      filter(where row_number<=size_no),'[]'),'next_cursor',case when count(*)>size_no then
      (select jsonb_build_object('name',display_name,'id',person_id) from page order by lower(display_name),person_id offset size_no-1 limit 1) end)
    into result from(select page.*,row_number() over(order by lower(display_name),person_id) row_number from page) page;
  else raise invalid_parameter_value using message='access profile not found';end if;
  return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_assignment_candidates"("p_profile_id" "uuid", "p_query" "text", "p_limit" integer, "p_after_name" "text", "p_after_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_assignment_link"("p_request_id" "uuid", "p_draft" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare profile_id uuid:=nullif(p_draft->>'profile_id','')::uuid;domain text;actor uuid;replay jsonb;
  person_id uuid:=nullif(p_draft->>'person_id','')::uuid;membership public.institution_memberships%rowtype;
  assignment_id uuid;result jsonb;scope_kind text:=coalesce(p_draft->>'scope_kind','institution');
  template public.access_profile_templates%rowtype;context_record record;profile_version bigint;
  expected_profile_version bigint:=nullif(p_draft->>'profile_version','')::bigint;
  unit_id uuid:=nullif(p_draft->>'unit_id','')::uuid;group_id uuid:=nullif(p_draft->>'group_id','')::uuid;
begin
  domain:=case when exists(select 1 from public.platform_roles where id=profile_id) then 'platform'
    when exists(select 1 from public.institution_roles where id=profile_id) then 'institution'
    when exists(select 1 from public.access_profile_templates where id=profile_id and domain='principal') then 'principal' end;
  actor:=app_private.access_profile_require_mutation(domain);
  replay:=app_private.access_profile_replay(p_request_id,actor,'assignment_link',p_draft);if replay is not null then return replay;end if;
  perform app_private.assert_access_profile_assignment_delegable(domain,profile_id);
  if domain='platform' then
    select version into profile_version from public.platform_roles where id=profile_id and status='active' for update;
    if profile_version is null then raise no_data_found using message='active profile not found';end if;
    if expected_profile_version is null or expected_profile_version<>profile_version then
      raise serialization_failure using message='stale profile version';end if;
    if scope_kind not in('platform','institution')
      or (scope_kind='platform' and nullif(p_draft->>'institution_id','') is not null)
      or (scope_kind='institution' and not exists(select 1 from public.institutions institution
        where institution.id=nullif(p_draft->>'institution_id','')::uuid and institution.status='active')) then
      raise invalid_parameter_value using message='invalid platform assignment scope';end if;
    perform 1 from public.people where id=person_id and status='active' and deleted_at is null for update;
    if not found then raise no_data_found using message='person not found';end if;
    insert into public.platform_memberships(person_id,role_id,status,scope_kind,scope_institution_id,mfa_required,invited_by)
    values(person_id,profile_id,'active',scope_kind,nullif(p_draft->>'institution_id','')::uuid,true,actor)
    returning id into assignment_id;
  elsif domain='institution' then
    select * into membership from public.institution_memberships where id=nullif(p_draft->>'membership_id','')::uuid for update;
    select version into profile_version from public.institution_roles role_record where role_record.id=profile_id
      and role_record.status='active' and (role_record.institution_id is null or role_record.institution_id=membership.institution_id) for update;
    if membership.id is null or membership.person_id<>person_id or membership.status<>'active' or membership.revoked_at is not null
      or profile_version is null then raise no_data_found using message='authorized membership or profile not found';end if;
    if expected_profile_version is null or expected_profile_version<>profile_version then
      raise serialization_failure using message='stale profile version';end if;
    if scope_kind not in('institution','unit','group')
      or (scope_kind='institution' and (unit_id is not null or group_id is not null))
      or (scope_kind='unit' and (unit_id is null or group_id is not null or not exists(select 1 from public.units unit_record
        where unit_record.id=unit_id and unit_record.institution_id=membership.institution_id and unit_record.status='active')))
      or (scope_kind='group' and (group_id is null or not exists(select 1 from public.groups group_record
        where group_record.id=group_id and group_record.institution_id=membership.institution_id and group_record.status='active'
          and (unit_id is null or group_record.unit_id=unit_id)))) then
      raise invalid_parameter_value using message='invalid institution assignment scope';end if;
    insert into public.institution_role_assignments(membership_id,role_id,scope_kind,scope_unit_id,scope_group_id,
      starts_at,expires_at,granted_by,status) values(membership.id,profile_id,scope_kind,unit_id,group_id,
      nullif(p_draft->>'starts_at','')::timestamptz,nullif(p_draft->>'expires_at','')::timestamptz,actor,'active')
    returning id into assignment_id;
  elsif domain='principal' then
    select * into template from public.access_profile_templates
      where id=profile_id and domain='principal' and status='active' for update;
    if expected_profile_version is null or template.id is null or template.version<>expected_profile_version then
      raise serialization_failure using message='stale profile model version';end if;
    select context_permission.*,guardian.guardian_person_id as selected_guardian_person_id,child_context.status as selected_child_context_status into context_record
    from public.guardian_context_permissions context_permission
    join public.guardian_links guardian on guardian.id=context_permission.guardian_link_id
      and guardian.status='active' and guardian.revoked_at is null
    join public.child_contexts child_context on child_context.id=context_permission.child_context_id
    where context_permission.id=nullif(p_draft->>'guardian_context_permission_id','')::uuid
      and context_permission.status='active' and (context_permission.expires_at is null or context_permission.expires_at>now())
    for update of context_permission;
    if context_record.id is null or context_record.selected_context_record.selected_guardian_person_id<>person_id or context_record.selected_context_record.selected_child_context_status<>'active' then
      raise no_data_found using message='authorized Principal context not found';end if;
    insert into public.guardian_context_permission_grants(guardian_context_permission_id,capability_id,effect,status,
      changed_by_person_id,reason) select context_record.id,item.capability_id,item.effect,'active',actor,
      coalesce(nullif(btrim(p_draft->>'reason'),''),'Modelo Principal copiado como snapshot.')
    from public.access_profile_template_principal_capabilities item where item.template_id=template.id
    on conflict(guardian_context_permission_id,capability_id) do update set effect=excluded.effect,status='active',
      changed_by_person_id=actor,reason=excluded.reason,revoked_at=null,updated_at=now();
    update public.guardian_context_permissions set source_template_id=template.id,source_template_version=template.version,
      starts_at=coalesce(nullif(p_draft->>'starts_at','')::timestamptz,starts_at),
      expires_at=coalesce(nullif(p_draft->>'expires_at','')::timestamptz,expires_at),version=version+1,updated_at=now()
    where id=context_record.id returning id,version into assignment_id,profile_version;
  else raise invalid_parameter_value using message='unsupported profile assignment';end if;
  result:=jsonb_build_object('assignment_id',assignment_id,'profile_id',profile_id,'domain',domain,'person_id',person_id,
    'membership_id',case when domain='institution' then membership.id end,
    'institution_id',case when domain='institution' then membership.institution_id
      when domain='platform' then nullif(p_draft->>'institution_id','')::uuid end,
    'unit_id',unit_id,'group_id',group_id,
    'guardian_context_permission_id',case when domain='principal' then assignment_id end,
    'scope_kind',case when domain='principal' then 'child_context' else scope_kind end,
    'starts_at',nullif(p_draft->>'starts_at',''),'expires_at',nullif(p_draft->>'expires_at',''),
    'version',case when domain='principal' then profile_version::text else '1' end,'replayed',false);
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,reason,after_json)
  values(actor,'aal2','membership_changed',domain||'_access_profile_assignment',assignment_id,'success',
    coalesce(nullif(btrim(p_draft->>'reason'),''),'Vínculo de pessoa ao perfil.'),result);
  perform app_private.access_profile_store_receipt(p_request_id,actor,'assignment_link',p_draft,result);return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_assignment_link"("p_request_id" "uuid", "p_draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_assignment_overrides_save"("p_request_id" "uuid", "p_assignment_id" "uuid", "p_expected_version" bigint, "p_overrides" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare domain text;actor uuid;payload jsonb:=jsonb_build_object('assignment_id',p_assignment_id,
  'expected_version',p_expected_version,'overrides',p_overrides,'reason',p_reason);replay jsonb;
  assignment public.institution_role_assignments%rowtype;membership public.institution_memberships%rowtype;
  item jsonb;permission public.institution_permissions%rowtype;capability public.guardian_permission_capabilities%rowtype;
  current_version bigint;result jsonb;platform_membership public.platform_memberships%rowtype;platform_permission public.platform_permissions%rowtype;
begin
  if jsonb_typeof(p_overrides)<>'array' or nullif(btrim(p_reason),'') is null then raise invalid_parameter_value using message='invalid overrides';end if;
  domain:=case when exists(select 1 from public.platform_memberships where id=p_assignment_id) then 'platform'
    when exists(select 1 from public.institution_role_assignments where id=p_assignment_id) then 'institution'
    when exists(select 1 from public.guardian_context_permissions where id=p_assignment_id) then 'principal' end;
  actor:=app_private.access_profile_require_mutation(domain);
  replay:=app_private.access_profile_replay(p_request_id,actor,'overrides_save',payload);if replay is not null then return replay;end if;
  if domain='platform' then
    select * into platform_membership from public.platform_memberships where id=p_assignment_id for update;
    if platform_membership.version<>p_expected_version then raise serialization_failure using message='stale assignment version';end if;
    for item in select value from jsonb_array_elements(p_overrides) loop
      if item->>'intent' not in('inherit','allow','deny') then raise invalid_parameter_value using message='invalid override intent';end if;
      select * into platform_permission from public.platform_permissions where code=item->>'capability_code' and status='active';
      if platform_permission.id is null then raise invalid_parameter_value using message='unknown capability';end if;
      if platform_membership.person_id=actor and item->>'intent'='allow' and not app_private.has_platform_permission(platform_permission.code) then
        raise insufficient_privilege using message='cannot elevate own access';end if;
      if item->>'intent'='inherit' then update public.platform_member_permission_overrides set status='inactive'
        where membership_id=p_assignment_id and permission_id=platform_permission.id;
      else insert into public.platform_member_permission_overrides(membership_id,permission_id,effect,conditions_json,granted_by,status)
        values(p_assignment_id,platform_permission.id,(item->>'intent')::public.permission_effect,'{}',actor,'active')
        on conflict(membership_id,permission_id) do update set effect=excluded.effect,status='active',granted_by=actor;end if;
    end loop;
    update public.platform_memberships set version=version+1 where id=p_assignment_id returning version into current_version;
  elsif domain='institution' then
    select * into assignment from public.institution_role_assignments where id=p_assignment_id for update;
    if assignment.version<>p_expected_version then raise serialization_failure using message='stale assignment version';end if;
    select * into membership from public.institution_memberships where id=assignment.membership_id;
    for item in select value from jsonb_array_elements(p_overrides) loop
      if item->>'intent' not in('inherit','allow','deny') then raise invalid_parameter_value using message='invalid override intent';end if;
      select * into permission from public.institution_permissions where code=item->>'capability_code' and status='active';
      if permission.id is null then raise invalid_parameter_value using message='unknown capability';end if;
      if membership.person_id=actor and item->>'intent'='allow' and not app_private.has_context_permission(
        membership.institution_id,permission.code,assignment.scope_unit_id,assignment.scope_group_id) then
        raise insufficient_privilege using message='cannot elevate own access';end if;
      if item->>'intent'='inherit' then update public.institution_member_permission_overrides set status='inactive',revoked_at=now(),
        changed_by_person_id=actor where membership_id=membership.id and permission_code=permission.code
          and institution_id=membership.institution_id and scope_kind=assignment.scope_kind
          and scope_unit_id is not distinct from assignment.scope_unit_id and scope_group_id is not distinct from assignment.scope_group_id;
      else insert into public.institution_member_permission_overrides(membership_id,permission_code,effect,scope_kind,scope_id,
        reason,status,changed_by_person_id,institution_id,scope_unit_id,scope_group_id)
        values(membership.id,permission.code,(item->>'intent')::public.permission_effect,assignment.scope_kind,
          case assignment.scope_kind when 'unit' then assignment.scope_unit_id when 'group' then assignment.scope_group_id end,
          p_reason,'active',actor,membership.institution_id,assignment.scope_unit_id,assignment.scope_group_id)
        on conflict(membership_id,permission_code,scope_kind,(coalesce(scope_id,'00000000-0000-0000-0000-000000000000'::uuid)))
          where status='active' and revoked_at is null do update set effect=excluded.effect,reason=excluded.reason,
            changed_by_person_id=actor,updated_at=now();end if;
    end loop;
    update public.institution_role_assignments set version=version+1,updated_at=now() where id=p_assignment_id returning version into current_version;
  elsif domain='principal' then
    select version into current_version from public.guardian_context_permissions where id=p_assignment_id for update;
    if current_version<>p_expected_version then raise serialization_failure using message='stale assignment version';end if;
    for item in select value from jsonb_array_elements(p_overrides) loop
      if item->>'intent' not in('inherit','allow','deny') then raise invalid_parameter_value using message='invalid override intent';end if;
      select * into capability from public.guardian_permission_capabilities where code=item->>'capability_code' and status='active';
      if capability.id is null then raise invalid_parameter_value using message='unknown capability';end if;
      if item->>'intent'='inherit' then update public.guardian_context_permission_grants set status='inactive',revoked_at=now(),
        changed_by_person_id=actor,updated_at=now() where guardian_context_permission_id=p_assignment_id and capability_id=capability.id;
      else insert into public.guardian_context_permission_grants(guardian_context_permission_id,capability_id,effect,status,
        changed_by_person_id,reason) values(p_assignment_id,capability.id,(item->>'intent')::public.permission_effect,'active',actor,p_reason)
        on conflict(guardian_context_permission_id,capability_id) do update set effect=excluded.effect,status='active',
          changed_by_person_id=actor,reason=p_reason,revoked_at=null,updated_at=now();end if;
    end loop;
    update public.guardian_context_permissions set version=version+1,updated_at=now() where id=p_assignment_id returning version into current_version;
  else raise no_data_found using message='assignment not found';end if;
  result:=jsonb_build_object('assignment_id',p_assignment_id,'domain',domain,'version',current_version,'replayed',false,
    'capabilities',app_private.superadmin_access_profile_capability_catalog(domain,null,p_assignment_id));
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,reason,after_json)
  values(actor,'aal2','permission_changed',domain||'_access_profile_override',p_assignment_id,'success',p_reason,result-'capabilities');
  perform app_private.access_profile_store_receipt(p_request_id,actor,'overrides_save',payload,result);return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_assignment_overrides_save"("p_request_id" "uuid", "p_assignment_id" "uuid", "p_expected_version" bigint, "p_overrides" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_assignment_unlink"("p_request_id" "uuid", "p_assignment_id" "uuid", "p_expected_version" bigint, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare domain text;actor uuid;payload jsonb:=jsonb_build_object('assignment_id',p_assignment_id,
  'expected_version',p_expected_version,'reason',p_reason);replay jsonb;current_version bigint;result jsonb;
begin
  domain:=case when exists(select 1 from public.platform_memberships where id=p_assignment_id) then 'platform'
    when exists(select 1 from public.institution_role_assignments where id=p_assignment_id) then 'institution'
    when exists(select 1 from public.guardian_context_permissions where id=p_assignment_id) then 'principal' end;
  actor:=app_private.access_profile_require_mutation(domain);
  replay:=app_private.access_profile_replay(p_request_id,actor,'assignment_unlink',payload);if replay is not null then return replay;end if;
  if nullif(btrim(p_reason),'') is null then raise invalid_parameter_value using message='reason required';end if;
  if domain='platform' then
    perform pg_advisory_xact_lock(hashtextextended('access-profile-full-authority',0));
    select version into current_version from public.platform_memberships where id=p_assignment_id for update;
    if current_version is distinct from p_expected_version then raise serialization_failure using message='stale assignment version';end if;
    update public.platform_memberships set status='inactive',revoked_at=now(),version=version+1 where id=p_assignment_id;
    perform app_private.assert_full_authority_remains();
  elsif domain='institution' then
    select version into current_version from public.institution_role_assignments where id=p_assignment_id for update;
    if current_version is distinct from p_expected_version then raise serialization_failure using message='stale assignment version';end if;
    update public.institution_role_assignments set status='inactive',version=version+1,updated_at=now() where id=p_assignment_id;
  elsif domain='principal' then
    select version into current_version from public.guardian_context_permissions where id=p_assignment_id for update;
    if current_version is distinct from p_expected_version then raise serialization_failure using message='stale assignment version';end if;
    update public.guardian_context_permissions set status='inactive',version=version+1,updated_at=now() where id=p_assignment_id;
  else raise no_data_found using message='assignment not found';end if;
  result:=jsonb_build_object('assignment_id',p_assignment_id,'domain',domain,'version',current_version+1,'replayed',false);
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,reason,after_json)
  values(actor,'aal2','membership_changed',domain||'_access_profile_assignment',p_assignment_id,'success',p_reason,result);
  perform app_private.access_profile_store_receipt(p_request_id,actor,'assignment_unlink',payload,result);return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_assignment_unlink"("p_request_id" "uuid", "p_assignment_id" "uuid", "p_expected_version" bigint, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_assignments_cursor"("p_profile_id" "uuid", "p_limit" integer DEFAULT 25, "p_after_name" "text" DEFAULT NULL::"text", "p_after_person_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare domain text;size_no int:=least(greatest(coalesce(p_limit,25),1),100);result jsonb;
begin
  domain:=case when exists(select 1 from public.platform_roles where id=p_profile_id) then 'platform'
    when exists(select 1 from public.institution_roles where id=p_profile_id) then 'institution'
    when exists(select 1 from public.access_profile_templates where id=p_profile_id and domain='principal') then 'principal' end;
  perform app_private.require_profile_authority(domain);
  if domain='platform' then
    with rows as(select membership.id assignment_id,p_profile_id profile_id,'platform'::text domain,
      membership.person_id,person_record.display_name,null::uuid membership_id,membership.scope_kind,
      membership.scope_institution_id institution_id,null::uuid unit_id,null::uuid group_id,
      null::uuid guardian_context_permission_id,null::timestamptz starts_at,null::timestamptz expires_at,
      membership.version::text version
      from public.platform_memberships membership join public.people person_record on person_record.id=membership.person_id
      where membership.role_id=p_profile_id and membership.status='active' and membership.revoked_at is null
        and (p_after_name is null or (lower(person_record.display_name),person_record.id)>(lower(p_after_name),p_after_person_id))),
    page as(select * from rows order by lower(display_name),person_id limit size_no+1)
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page)-'row_number' order by lower(display_name),person_id)
      filter(where row_number<=size_no),'[]'),'next_cursor',case when count(*)>size_no then
      (select jsonb_build_object('name',display_name,'id',person_id) from page order by lower(display_name),person_id offset size_no-1 limit 1) end)
    into result from(select page.*,row_number() over(order by lower(display_name),person_id) row_number from page) page;
  elsif domain='institution' then
    with rows as(select assignment.id assignment_id,p_profile_id profile_id,'institution'::text domain,
      membership.person_id,person_record.display_name,membership.id membership_id,assignment.scope_kind,
      membership.institution_id,assignment.scope_unit_id unit_id,assignment.scope_group_id group_id,
      null::uuid guardian_context_permission_id,assignment.starts_at,assignment.expires_at,assignment.version::text version
      from public.institution_role_assignments assignment join public.institution_memberships membership on membership.id=assignment.membership_id
      join public.people person_record on person_record.id=membership.person_id where assignment.role_id=p_profile_id
        and assignment.status='active' and (assignment.expires_at is null or assignment.expires_at>now())
        and (p_after_name is null or (lower(person_record.display_name),person_record.id)>(lower(p_after_name),p_after_person_id))),
    page as(select * from rows order by lower(display_name),person_id limit size_no+1)
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page)-'row_number' order by lower(display_name),person_id)
      filter(where row_number<=size_no),'[]'),'next_cursor',case when count(*)>size_no then
      (select jsonb_build_object('name',display_name,'id',person_id) from page order by lower(display_name),person_id offset size_no-1 limit 1) end)
    into result from(select page.*,row_number() over(order by lower(display_name),person_id) row_number from page) page;
  else
    with rows as(select context_permission.id assignment_id,p_profile_id profile_id,'principal'::text domain,
      guardian.guardian_person_id person_id,person_record.display_name,null::uuid membership_id,'child_context'::text scope_kind,
      child_context.institution_id,null::uuid unit_id,null::uuid group_id,
      context_permission.id guardian_context_permission_id,context_permission.starts_at,context_permission.expires_at,
      context_permission.version::text version
      from public.guardian_context_permissions context_permission
      join public.guardian_links guardian on guardian.id=context_permission.guardian_link_id
      join public.people person_record on person_record.id=guardian.guardian_person_id
      join public.child_contexts child_context on child_context.id=context_permission.child_context_id
      where context_permission.source_template_id=p_profile_id and context_permission.status='active'
        and (context_permission.expires_at is null or context_permission.expires_at>now())
        and guardian.status='active' and guardian.revoked_at is null
        and (p_after_name is null or (lower(person_record.display_name),person_record.id)>(lower(p_after_name),p_after_person_id))),
    page as(select * from rows order by lower(display_name),person_id limit size_no+1)
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page)-'row_number' order by lower(display_name),person_id)
      filter(where row_number<=size_no),'[]'),'next_cursor',case when count(*)>size_no then
      (select jsonb_build_object('name',display_name,'id',person_id) from page order by lower(display_name),person_id offset size_no-1 limit 1) end)
    into result from(select page.*,row_number() over(order by lower(display_name),person_id) row_number from page) page;
  end if;return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_assignments_cursor"("p_profile_id" "uuid", "p_limit" integer, "p_after_name" "text", "p_after_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_capability_catalog"("p_domain" "text", "p_profile_id" "uuid" DEFAULT NULL::"uuid", "p_assignment_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;catalog_version bigint;profile_version bigint;
begin
  perform app_private.require_profile_authority(p_domain);
  select version into catalog_version from app_private.access_profile_catalog_versions where domain=p_domain;
  if p_domain='platform' then
    select version into profile_version from public.platform_roles where id=p_profile_id;
    select jsonb_build_object('catalog_version',catalog_version::text,'profile_version',profile_version::text,
      'items',coalesce(jsonb_agg(jsonb_build_object('id',permission_record.id,'code',permission_record.code,
        'module_code',permission_record.module_code,'module_label',permission_record.module_label,
        'screen_code',coalesce(permission_record.screen_code,permission_record.module_code),'screen_label',permission_record.screen_label,
        'action_code',case permission_record.action_code when 'read' then 'view' when 'update' then 'edit' else permission_record.action_code end,
        'action_label',permission_record.action_label,'description',permission_record.description,'risk',permission_record.risk_level,
        'requires_mfa',permission_record.requires_mfa,'configured_effect',coalesce(profile_grant.effect::text,'inherit'),
        'inherited_effect','none','effective_effect',case when assignment_override.effect='deny' then 'deny'
          when assignment_override.effect='allow' then 'allow' when profile_grant.effect='allow' then 'allow' else 'deny' end,
        'origin_code',case when assignment_override.effect is not null then 'member_override'
          when profile_grant.effect is not null then 'profile' else 'default_deny' end,
        'origin_label',case when assignment_override.effect is not null then 'Personalização da pessoa'
          when profile_grant.effect is not null then 'Perfil' else 'Negado por padrão' end,
        'grantable',app_private.has_platform_permission(permission_record.code),
        'disabled_reason',case when app_private.has_platform_permission(permission_record.code) then null
          else 'Você não pode conceder uma permissão que não possui.' end)
        order by permission_record.module_code,permission_record.screen_code,permission_record.action_code,permission_record.code),'[]'::jsonb))
    into result from public.platform_permissions permission_record
    left join public.platform_role_permissions profile_grant on profile_grant.role_id=p_profile_id
      and profile_grant.permission_id=permission_record.id and profile_grant.status='active' and profile_grant.revoked_at is null
    left join public.platform_member_permission_overrides assignment_override on assignment_override.membership_id=p_assignment_id
      and assignment_override.permission_id=permission_record.id and assignment_override.status='active'
      and (assignment_override.starts_at is null or assignment_override.starts_at<=now())
      and (assignment_override.expires_at is null or assignment_override.expires_at>now())
    where permission_record.status='active';
  elsif p_domain='institution' then
    select version into profile_version from public.institution_roles where id=p_profile_id;
    select jsonb_build_object('catalog_version',catalog_version::text,'profile_version',profile_version::text,
      'items',coalesce(jsonb_agg(jsonb_build_object('id',permission_record.id,'code',permission_record.code,
        'module_code',permission_record.module_code,'module_label',permission_record.module_label,
        'screen_code',coalesce(permission_record.screen_code,permission_record.module_code),'screen_label',permission_record.screen_label,
        'action_code',case permission_record.action_code when 'read' then 'view' when 'update' then 'edit' else permission_record.action_code end,
        'action_label',permission_record.action_label,'description',permission_record.description,'risk',permission_record.risk_level,
        'requires_mfa',permission_record.requires_mfa,'configured_effect',coalesce(profile_grant.effect::text,'inherit'),
        'inherited_effect',coalesce(profile_grant.effect::text,'none'),
        'effective_effect',case when override_summary.effect='deny' then 'deny'
          when override_summary.effect='allow' then 'allow' when profile_grant.effect='allow' then 'allow' else 'deny' end,
        'origin_code',case when override_summary.effect is not null then 'member_override'
          when profile_grant.effect is not null then 'profile' else 'default_deny' end,
        'origin_label',case when override_summary.effect is not null then 'Personalização da pessoa'
          when profile_grant.effect is not null then 'Perfil' else 'Negado por padrão' end,
        'grantable',app_private.has_platform_permission('institution.roles.manage'),
        'disabled_reason',case when app_private.has_platform_permission('institution.roles.manage') then null
          else 'Você não pode conceder permissões administrativas.' end)
        order by permission_record.module_code,permission_record.screen_code,permission_record.action_code,permission_record.code),'[]'::jsonb))
    into result from public.institution_permissions permission_record
    left join public.institution_role_permissions profile_grant on profile_grant.role_id=p_profile_id
      and profile_grant.permission_id=permission_record.id and profile_grant.status='active' and profile_grant.revoked_at is null
    left join public.institution_role_assignments assignment on assignment.id=p_assignment_id
    left join lateral(
      select case when bool_or(override_record.effect='deny') then 'deny'
        when bool_or(override_record.effect='allow') then 'allow' end effect
      from public.institution_member_permission_overrides override_record
      where override_record.membership_id=assignment.membership_id
        and override_record.permission_code=permission_record.code
        and override_record.status='active' and override_record.revoked_at is null
        and (override_record.starts_at is null or override_record.starts_at<=now())
        and (override_record.expires_at is null or override_record.expires_at>now())
        and (override_record.scope_kind='institution'
          or (override_record.scope_kind='unit' and override_record.scope_unit_id=assignment.scope_unit_id)
          or (override_record.scope_kind='group' and override_record.scope_group_id=assignment.scope_group_id))
    ) override_summary on true
    where permission_record.status='active';
  elsif p_domain='principal' then
    select version into profile_version from public.guardian_context_permissions where id=p_assignment_id;
    select jsonb_build_object('catalog_version',catalog_version::text,'profile_version',profile_version::text,
      'items',coalesce(jsonb_agg(jsonb_build_object('id',capability.id,'code',capability.code,
        'module_code',capability.module_code,'module_label',capability.module_label,'screen_code',capability.screen_code,
        'screen_label',capability.screen_label,'action_code',capability.action_code,'action_label',capability.action_label,
        'description',capability.description,'risk',capability.risk_level,'requires_mfa',capability.requires_mfa,
        'configured_effect',coalesce(context_grant.effect::text,'inherit'),'inherited_effect','none',
        'effective_effect',case when context_grant.effect='allow' then 'allow' else 'deny' end,
        'origin_code',case when context_grant.effect is not null then 'guardian_grant' else 'default_deny' end,
        'origin_label',case when context_grant.effect is not null then 'Permissão do contexto' else 'Negado por padrão' end,
        'grantable',app_private.has_platform_permission('institution.roles.manage'),
        'disabled_reason',case when app_private.has_platform_permission('institution.roles.manage') then null
          else 'Você não pode conceder permissões familiares.' end)
        order by capability.screen_code,capability.action_code,capability.code),'[]'::jsonb))
    into result from public.guardian_permission_capabilities capability
    left join public.guardian_context_permission_grants context_grant
      on context_grant.guardian_context_permission_id=p_assignment_id and context_grant.capability_id=capability.id
      and context_grant.status='active' and context_grant.revoked_at is null
    where capability.status='active';
  else raise invalid_parameter_value using message='unsupported profile domain';end if;
  return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_capability_catalog"("p_domain" "text", "p_profile_id" "uuid", "p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_create"("p_request_id" "uuid", "p_draft" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; replay jsonb; profile jsonb; result jsonb; domain text:=p_draft->>'domain';
begin
  actor:=app_private.access_profile_require_mutation(domain);
  replay:=app_private.access_profile_replay(p_request_id,actor,'create',p_draft);if replay is not null then return replay;end if;
  profile:=app_private.access_profile_create_internal(actor,p_draft);
  result:=jsonb_build_object('profile',profile,'profile_id',profile->>'id','domain',domain,
    'version',(profile->>'version')::bigint,'replayed',false);
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,reason,after_json)
  values(actor,'aal2','permission_changed',domain||'_access_profile',(profile->>'id')::uuid,'success',
    coalesce(nullif(btrim(p_draft->>'reason'),''),'Criação de perfil.'),profile);
  perform app_private.access_profile_store_receipt(p_request_id,actor,'create',p_draft,result);
  return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_create"("p_request_id" "uuid", "p_draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_create_from_model"("p_request_id" "uuid", "p_draft" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare template public.access_profile_templates%rowtype;actor uuid;replay jsonb;profile jsonb;result jsonb;
  capabilities jsonb;context_id uuid;before_data jsonb;expected_model_version bigint:=nullif(p_draft->>'model_version','')::bigint;
  guardian_person_id uuid;child_context_status public.record_status;
begin
  select * into template from public.access_profile_templates where id=nullif(p_draft->>'model_id','')::uuid for update;
  if template.id is null or template.status<>'active' then raise no_data_found using message='access profile model not found';end if;
  if expected_model_version is null or template.version<>expected_model_version then
    raise serialization_failure using message='stale access profile model version';end if;
  actor:=app_private.access_profile_require_mutation(template.domain);
  replay:=app_private.access_profile_replay(p_request_id,actor,'create_from_model',p_draft);if replay is not null then return replay;end if;
  perform app_private.assert_access_profile_template_delegable(template.id,template.domain);
  if template.domain='platform' then
    select coalesce(jsonb_agg(jsonb_build_object('code',permission_record.code,'effect',item.effect::text) order by permission_record.code),'[]')
      into capabilities from public.access_profile_template_platform_permissions item
      join public.platform_permissions permission_record on permission_record.id=item.permission_id where item.template_id=template.id;
  elsif template.domain='institution' then
    select coalesce(jsonb_agg(jsonb_build_object('code',permission_record.code,'effect',item.effect::text) order by permission_record.code),'[]')
      into capabilities from public.access_profile_template_institution_permissions item
      join public.institution_permissions permission_record on permission_record.id=item.permission_id where item.template_id=template.id;
  else
    context_id:=nullif(p_draft->>'guardian_context_permission_id','')::uuid;
    select to_jsonb(context_permission),guardian.guardian_person_id,child_context.status
      into before_data,guardian_person_id,child_context_status
    from public.guardian_context_permissions context_permission
    join public.guardian_links guardian on guardian.id=context_permission.guardian_link_id
      and guardian.status='active' and guardian.revoked_at is null
    join public.child_contexts child_context on child_context.id=context_permission.child_context_id
    where context_permission.id=context_id and context_permission.status='active'
      and (context_permission.expires_at is null or context_permission.expires_at>now()) for update of context_permission;
    if before_data is null or child_context_status<>'active'
      or (nullif(p_draft->>'person_id','') is not null and guardian_person_id<>nullif(p_draft->>'person_id','')::uuid) then
      raise no_data_found using message='authorized Principal context not found';end if;
    insert into public.guardian_context_permission_grants(guardian_context_permission_id,capability_id,effect,status,changed_by_person_id,reason)
    select context_id,item.capability_id,item.effect,'active',actor,'Modelo copiado como snapshot.'
    from public.access_profile_template_principal_capabilities item where item.template_id=template.id
    on conflict(guardian_context_permission_id,capability_id) do update set effect=excluded.effect,status='active',
      changed_by_person_id=excluded.changed_by_person_id,reason=excluded.reason,revoked_at=null,updated_at=now();
    update public.guardian_context_permissions set source_template_id=template.id,source_template_version=template.version,
      version=version+1,updated_at=now() where id=context_id;
    profile:=jsonb_build_object('id',context_id,'domain','principal','version',
      (select version from public.guardian_context_permissions where id=context_id),
      'source_template_id',template.id,'source_template_version',template.version);
    result:=jsonb_build_object('profile',profile,'profile_id',context_id,'domain','principal','version',profile->'version','replayed',false);
    insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,reason,before_json,after_json)
    values(actor,'aal2','permission_changed','principal_context_permissions',context_id,'success',
      coalesce(nullif(btrim(p_draft->>'reason'),''),'Aplicação de modelo Principal.'),before_data,profile);
    perform app_private.access_profile_store_receipt(p_request_id,actor,'create_from_model',p_draft,result);return result;
  end if;
  profile:=app_private.access_profile_create_internal(actor,jsonb_build_object('domain',template.domain,
    'name',coalesce(nullif(btrim(p_draft->>'name'),''),template.name),'description',coalesce(p_draft->>'description',template.description),
    'status','inactive','max_scope_kind',coalesce(p_draft->>'max_scope_kind',template.max_scope_kind),'capabilities',capabilities),
    template.id,template.version);
  result:=jsonb_build_object('profile',profile,'profile_id',profile->>'id','domain',template.domain,
    'version',(profile->>'version')::bigint,'replayed',false);
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,reason,after_json)
  values(actor,'aal2','permission_changed',template.domain||'_access_profile',(profile->>'id')::uuid,'success',
    coalesce(nullif(btrim(p_draft->>'reason'),''),'Criação a partir de modelo.'),profile);
  perform app_private.access_profile_store_receipt(p_request_id,actor,'create_from_model',p_draft,result);return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_create_from_model"("p_request_id" "uuid", "p_draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_delete_and_reassign"("p_request_id" "uuid", "p_domain" "text", "p_profile_id" "uuid", "p_expected_version" bigint, "p_replacement_profile_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid;payload jsonb:=jsonb_build_object('domain',p_domain,'profile_id',p_profile_id,
  'expected_version',p_expected_version,'replacement_profile_id',p_replacement_profile_id,'reason',p_reason);
  replay jsonb;current_version bigint;is_system boolean;link_count bigint;before_data jsonb;result jsonb;
begin
  actor:=app_private.access_profile_require_mutation(p_domain);
  replay:=app_private.access_profile_replay(p_request_id,actor,'delete_and_reassign',payload);if replay is not null then return replay;end if;
  if p_profile_id is null or p_expected_version is null or nullif(btrim(p_reason),'') is null
    or p_replacement_profile_id=p_profile_id then raise invalid_parameter_value using message='invalid delete request';end if;
  if p_domain='platform' then
    perform pg_advisory_xact_lock(hashtextextended('access-profile-full-authority',0));
    select version,platform_roles.is_system,to_jsonb(platform_roles) into current_version,is_system,before_data
      from public.platform_roles where id=p_profile_id for update;
    if current_version is null then raise no_data_found using message='access profile not found';end if;
    if is_system then raise insufficient_privilege using message='system profile is protected';end if;
    if current_version<>p_expected_version then raise serialization_failure using message='stale profile version';end if;
    select count(*) into link_count from public.platform_memberships where role_id=p_profile_id and status='active' and revoked_at is null;
    if link_count>0 and not exists(select 1 from public.platform_roles where id=p_replacement_profile_id and status='active') then
      raise check_violation using message='active replacement required';end if;
    update public.platform_memberships set role_id=p_replacement_profile_id,version=version+1 where role_id=p_profile_id;
    delete from public.platform_roles where id=p_profile_id;perform app_private.assert_full_authority_remains();
  elsif p_domain='institution' then
    select version,institution_roles.is_system,to_jsonb(institution_roles) into current_version,is_system,before_data
      from public.institution_roles where id=p_profile_id for update;
    if current_version is null then raise no_data_found using message='access profile not found';end if;
    if is_system then raise insufficient_privilege using message='system profile is protected';end if;
    if current_version<>p_expected_version then raise serialization_failure using message='stale profile version';end if;
    select count(*) into link_count from public.institution_role_assignments where role_id=p_profile_id and status='active';
    if link_count>0 and not exists(select 1 from public.institution_roles replacement
      join public.institution_roles removed on removed.id=p_profile_id where replacement.id=p_replacement_profile_id
        and replacement.status='active' and (replacement.institution_id is null or replacement.institution_id=removed.institution_id)
        and not exists(select 1 from public.institution_role_assignments assignment where assignment.role_id=p_profile_id
          and app_private.access_scope_rank(assignment.scope_kind)>app_private.access_scope_rank(replacement.max_scope_kind))) then
      raise check_violation using message='compatible active replacement required';end if;
    update public.institution_role_assignments set role_id=p_replacement_profile_id,version=version+1,updated_at=now()
      where role_id=p_profile_id;delete from public.institution_roles where id=p_profile_id;
  else raise invalid_parameter_value using message='unsupported profile domain';end if;
  result:=jsonb_build_object('domain',p_domain,'deleted_profile_id',p_profile_id,
    'replacement_profile_id',p_replacement_profile_id,'reassigned_count',link_count,'replayed',false);
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,reason,before_json,after_json)
  values(actor,'aal2','membership_changed',p_domain||'_access_profile',p_profile_id,'success',p_reason,before_data,result);
  perform app_private.access_profile_store_receipt(p_request_id,actor,'delete_and_reassign',payload,result);return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_delete_and_reassign"("p_request_id" "uuid", "p_domain" "text", "p_profile_id" "uuid", "p_expected_version" bigint, "p_replacement_profile_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_duplicate"("p_request_id" "uuid", "p_draft" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare source_id uuid:=nullif(p_draft->>'source_profile_id','')::uuid;domain text;actor uuid;replay jsonb;
  source jsonb;capabilities jsonb;profile jsonb;result jsonb;expected_version bigint:=nullif(p_draft->>'expected_version','')::bigint;
begin
  if p_draft ? 'source_model_id' then
    return app_private.superadmin_access_profile_create_from_model(p_request_id,
      (p_draft-'source_model_id')||jsonb_build_object('model_id',p_draft->>'source_model_id'));
  end if;
  select case when exists(select 1 from public.platform_roles where id=source_id) then 'platform'
    when exists(select 1 from public.institution_roles where id=source_id) then 'institution' end into domain;
  actor:=app_private.access_profile_require_mutation(domain);
  replay:=app_private.access_profile_replay(p_request_id,actor,'duplicate',p_draft);if replay is not null then return replay;end if;
  source:=app_private.access_profile_detail_v2(domain,source_id);
  if expected_version is null or (source->>'version')::bigint<>expected_version then
    raise serialization_failure using message='stale source profile version';end if;
  perform app_private.assert_access_profile_assignment_delegable(domain,source_id);
  if domain='platform' then
    select coalesce(jsonb_agg(jsonb_build_object('code',permission_record.code,'effect',grant_record.effect::text)),'[]') into capabilities
    from public.platform_role_permissions grant_record join public.platform_permissions permission_record on permission_record.id=grant_record.permission_id
    where grant_record.role_id=source_id and grant_record.status='active' and grant_record.revoked_at is null;
  else
    select coalesce(jsonb_agg(jsonb_build_object('code',permission_record.code,'effect',grant_record.effect::text)),'[]') into capabilities
    from public.institution_role_permissions grant_record join public.institution_permissions permission_record on permission_record.id=grant_record.permission_id
    where grant_record.role_id=source_id and grant_record.status='active' and grant_record.revoked_at is null;
  end if;
  profile:=app_private.access_profile_create_internal(actor,jsonb_build_object('domain',domain,
    'name',coalesce(nullif(btrim(p_draft->>'name'),''),source->>'name'||' (cópia)'),
    'description',coalesce(p_draft->>'description',source->>'description'),'status','inactive',
    'max_scope_kind',source->>'max_scope_kind','capabilities',capabilities));
  result:=jsonb_build_object('profile',profile,'profile_id',profile->>'id','domain',domain,
    'version',(profile->>'version')::bigint,'replayed',false);
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,reason,before_json,after_json)
  values(actor,'aal2','permission_changed',domain||'_access_profile',(profile->>'id')::uuid,'success',
    coalesce(nullif(btrim(p_draft->>'reason'),''),'Duplicação de perfil.'),source,profile);
  perform app_private.access_profile_store_receipt(p_request_id,actor,'duplicate',p_draft,result);return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_duplicate"("p_request_id" "uuid", "p_draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_export_materialize"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();job public.import_jobs%rowtype;csv text;domain text;
  query_filter text;status_filter text;scope_filter text;
begin
  select * into job from public.import_jobs where id=p_job_id for update;
  if job.id is null or job.target_domain<>'access_profiles_export' or job.created_by<>actor then
    raise no_data_found using message='export job unavailable';end if;
  domain:=job.summary#>>'{filters,domain}';query_filter:=nullif(btrim(job.summary#>>'{filters,query}'),'');
  status_filter:=nullif(job.summary#>>'{filters,status}','');scope_filter:=nullif(job.summary#>>'{filters,scope}','');
  if domain not in('platform','institution') or char_length(coalesce(query_filter,''))>120
    or (status_filter is not null and status_filter not in('active','inactive','archived'))
    or (domain='platform' and scope_filter is not null and scope_filter not in('platform','institution'))
    or (domain='institution' and scope_filter is not null and scope_filter not in('institution','unit','group')) then
    raise invalid_parameter_value using message='invalid export filters';end if;
  if not app_private.has_platform_permission(case domain when 'platform' then 'platform.roles.export' else 'institution.roles.export' end)
    or not app_private.has_mfa_aal2() then raise insufficient_privilege using message='profile export permission and MFA required';end if;
  if domain='platform' then
    select 'format_version,domain,name,description,max_scope_kind,status,capabilities'||E'\n'||coalesce(string_agg(
      app_private.access_profile_csv_cell('access-profiles-v1')||','||app_private.access_profile_csv_cell('platform')||','||
      app_private.access_profile_csv_cell(role_record.name)||','||app_private.access_profile_csv_cell(role_record.description)||','||
      app_private.access_profile_csv_cell(role_record.max_scope_kind)||','||app_private.access_profile_csv_cell(role_record.status::text)||','||
      app_private.access_profile_csv_cell(coalesce((select string_agg(permission_record.code||':'||grant_record.effect,'|' order by permission_record.code)
        from public.platform_role_permissions grant_record join public.platform_permissions permission_record on permission_record.id=grant_record.permission_id
        where grant_record.role_id=role_record.id and grant_record.status='active' and grant_record.revoked_at is null),'')),E'\n' order by lower(role_record.name),role_record.id),'')
    into csv from public.platform_roles role_record where (query_filter is null or role_record.name ilike '%'||query_filter||'%')
      and (status_filter is null or role_record.status::text=status_filter) and (scope_filter is null or role_record.max_scope_kind=scope_filter);
  else
    select 'format_version,domain,name,description,max_scope_kind,status,capabilities'||E'\n'||coalesce(string_agg(
      app_private.access_profile_csv_cell('access-profiles-v1')||','||app_private.access_profile_csv_cell('institution')||','||
      app_private.access_profile_csv_cell(role_record.name)||','||app_private.access_profile_csv_cell(role_record.description)||','||
      app_private.access_profile_csv_cell(role_record.max_scope_kind)||','||app_private.access_profile_csv_cell(role_record.status::text)||','||
      app_private.access_profile_csv_cell(coalesce((select string_agg(permission_record.code||':'||grant_record.effect,'|' order by permission_record.code)
        from public.institution_role_permissions grant_record join public.institution_permissions permission_record on permission_record.id=grant_record.permission_id
        where grant_record.role_id=role_record.id and grant_record.status='active' and grant_record.revoked_at is null),'')),E'\n' order by lower(role_record.name),role_record.id),'')
    into csv from public.institution_roles role_record where (query_filter is null or role_record.name ilike '%'||query_filter||'%')
      and (status_filter is null or role_record.status::text=status_filter) and (scope_filter is null or role_record.max_scope_kind=scope_filter);
  end if;
  update public.import_jobs set processing_state='PROCESSANDO',started_at=coalesce(started_at,now()),version=version+1,
    summary=summary||jsonb_build_object('phase','materialized','row_count',greatest(array_length(string_to_array(csv,E'\n'),1)-1,0)),updated_at=now()
  where id=job.id returning * into job;
  return jsonb_build_object('job_id',job.id,'version',job.version,'path',job.summary->>'storage_path','csv',csv,
    'format','csv','template_version','access-profiles-v1');
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_export_materialize"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_export_request"("p_request_id" "uuid", "p_filters" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();domain text:=coalesce(p_filters->>'domain','platform');job public.import_jobs%rowtype;
  request_hash bytea:=extensions.digest(convert_to(p_filters::text,'UTF8'),'sha256');required_permission text;
begin
  required_permission:=case domain when 'platform' then 'platform.roles.export' else 'institution.roles.export' end;
  if actor is null or domain not in('platform','institution') or not app_private.has_platform_permission(required_permission)
    or not app_private.has_mfa_aal2() then raise insufficient_privilege using message='profile export permission and MFA required';end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,0));
  select * into job from public.import_jobs where request_id=p_request_id for update;
  if job.id is not null then
    if job.created_by<>actor or job.request_hash<>request_hash or job.target_domain<>'access_profiles_export' then
      raise invalid_parameter_value using message='idempotency key reused';end if;
    return app_private.superadmin_access_profile_file_job(job.id);
  end if;
  insert into public.import_jobs(request_id,request_hash,target_domain,target_table,source_format,source_locale,target_locale,
    status,processing_state,summary,created_by)
  values(p_request_id,request_hash,'access_profiles_export','access_profiles','csv','pt-BR','pt-BR','draft','PENDENTE',
    jsonb_build_object('format_version','access-profiles-v1','phase','queued','filters',p_filters),actor) returning * into job;
  update public.import_jobs set summary=summary||jsonb_build_object('storage_bucket','coelo-operations','storage_path',
    'access-profile-files/'||actor||'/'||job.id||'/output/access-profiles-v1.csv') where id=job.id returning * into job;
  return jsonb_build_object('job_id',job.id,'status',job.processing_state,'version',job.version,
    'format_version','access-profiles-v1','bucket','coelo-operations','path',job.summary->>'storage_path');
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_export_request"("p_request_id" "uuid", "p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_file_complete"("p_job_id" "uuid", "p_checksum_sha256" "text", "p_size_bytes" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor uuid:=app_private.current_person_id();job public.import_jobs%rowtype;
begin
  select * into job from public.import_jobs where id=p_job_id for update;
  if job.id is null or job.created_by<>actor or job.target_domain<>'access_profiles_export'
    or not app_private.has_mfa_aal2() then raise insufficient_privilege using message='export job unavailable';end if;
  if p_checksum_sha256!~'^[0-9A-Fa-f]{64}$' or p_size_bytes<1 or p_size_bytes>5242880 then
    raise invalid_parameter_value using message='invalid export file evidence';end if;
  insert into public.import_files(import_job_id,storage_path,file_name,mime_type,size_bytes,checksum_sha256,expires_at)
  values(job.id,job.summary->>'storage_path','access-profiles-v1.csv','text/csv',p_size_bytes,lower(p_checksum_sha256),now()+interval '24 hours');
  update public.import_jobs set processing_state='SUCESSO',status='active',finished_at=now(),version=version+1,
    updated_at=now(),summary=summary||jsonb_build_object('phase','completed','checksum_sha256',lower(p_checksum_sha256),
      'size_bytes',p_size_bytes) where id=job.id;
  return app_private.superadmin_access_profile_file_job(job.id)||jsonb_build_object('format','csv','template_version','access-profiles-v1');
end $_$;


ALTER FUNCTION "app_private"."superadmin_access_profile_file_complete"("p_job_id" "uuid", "p_checksum_sha256" "text", "p_size_bytes" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_file_job"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();job public.import_jobs%rowtype;
begin
  select * into job from public.import_jobs where id=p_job_id;
  if job.id is null or job.target_domain not in('access_profiles_import','access_profiles_export') or job.created_by<>actor then
    raise no_data_found using message='file job not found';end if;
  return jsonb_build_object('job_id',job.id,'kind',job.target_domain,'status',job.processing_state,
    'version',job.version,'format_version','access-profiles-v1','phase',job.summary->>'phase',
    'bucket',job.summary->>'storage_bucket','path',job.summary->>'storage_path','summary',job.summary,
    'result',(select to_jsonb(result_record) from public.import_results result_record where result_record.import_job_id=job.id),
    'error_count',(select count(*) from public.import_errors where import_job_id=job.id));
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_file_job"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_import_confirm"("p_request_id" "uuid", "p_job_id" "uuid", "p_expected_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();job public.import_jobs%rowtype;row_record record;
  created_count int:=0;profile jsonb;result jsonb;payload jsonb:=jsonb_build_object('job_id',p_job_id,'version',p_expected_version);replay jsonb;
begin
  if actor is null or not app_private.has_mfa_aal2() then raise insufficient_privilege using message='MFA AAL2 required';end if;
  replay:=app_private.access_profile_replay(p_request_id,actor,'import_confirm',payload);if replay is not null then return replay;end if;
  select * into job from public.import_jobs where id=p_job_id for update;
  if job.id is null or job.target_domain<>'access_profiles_import' or job.created_by<>actor or job.summary->>'phase'<>'preview_ready' then
    raise no_data_found using message='import job unavailable';end if;
  if job.version<>p_expected_version then raise serialization_failure using message='stale import version';end if;
  if exists(select 1 from public.import_errors where import_job_id=job.id) then raise check_violation using message='import validation errors must be resolved';end if;
  for row_record in select * from public.import_rows where import_job_id=job.id and error_code is null order by row_number loop
    if row_record.payload_json->>'domain'='platform' and not app_private.has_platform_permission('platform.roles.import') then
      raise insufficient_privilege using message='platform profile import permission required';
    elsif row_record.payload_json->>'domain'='institution' and not app_private.has_platform_permission('institution.roles.import') then
      raise insufficient_privilege using message='institution profile import permission required';end if;
    perform app_private.access_profile_require_mutation(row_record.payload_json->>'domain');
    profile:=app_private.access_profile_create_internal(actor,row_record.payload_json||jsonb_build_object('status','inactive'));
    created_count:=created_count+1;
  end loop;
  insert into public.import_results(import_job_id,created_count,completed_at) values(job.id,created_count,now())
    on conflict(import_job_id) do update set created_count=excluded.created_count,completed_at=excluded.completed_at;
  update public.import_jobs set processing_state='SUCESSO',status='active',finished_at=now(),version=version+1,updated_at=now(),
    summary=summary||jsonb_build_object('phase','completed','created_count',created_count) where id=job.id returning * into job;
  result:=jsonb_build_object('job_id',job.id,'status',job.processing_state,'version',job.version,
    'created_count',created_count,'format','csv','template_version','access-profiles-v1','replayed',false);
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,reason,after_json)
  values(actor,'aal2','permission_changed','access_profile_import',job.id,'success','Confirmação de importação access-profiles-v1.',result);
  perform app_private.access_profile_store_receipt(p_request_id,actor,'import_confirm',payload,result);return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_import_confirm"("p_request_id" "uuid", "p_job_id" "uuid", "p_expected_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_import_create"("p_request_id" "uuid", "p_file_name" "text", "p_file_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor uuid:=app_private.current_person_id();job public.import_jobs%rowtype;payload jsonb;
  request_hash bytea;safe_name text:=btrim(p_file_name);
begin
  if actor is null or (not app_private.has_platform_permission('platform.roles.import')
    and not app_private.has_platform_permission('institution.roles.import')) or not app_private.has_mfa_aal2() then
    raise insufficient_privilege using message='profile import permission and MFA required';end if;
  if safe_name is null or char_length(safe_name)>128 or safe_name!~'^[^/\\]+[.]csv$'
    or p_file_sha256!~'^[0-9A-Fa-f]{64}$' then raise invalid_parameter_value using message='invalid CSV file metadata';end if;
  payload:=jsonb_build_object('file_name',safe_name,'sha256',lower(p_file_sha256),'format_version','access-profiles-v1');
  request_hash:=extensions.digest(convert_to(payload::text,'UTF8'),'sha256');
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,0));
  select * into job from public.import_jobs where request_id=p_request_id for update;
  if job.id is not null then
    if job.created_by<>actor or job.request_hash<>request_hash or job.target_domain<>'access_profiles_import' then
      raise invalid_parameter_value using message='idempotency key reused';end if;
    return app_private.superadmin_access_profile_file_job(job.id);
  end if;
  insert into public.import_jobs(request_id,request_hash,target_domain,target_table,source_format,source_locale,target_locale,
    status,processing_state,summary,created_by)
  values(p_request_id,request_hash,'access_profiles_import','access_profiles','csv','pt-BR','pt-BR','draft','PENDENTE',
    jsonb_build_object('format_version','access-profiles-v1','phase','awaiting_upload','source_name',safe_name),actor)
  returning * into job;
  update public.import_jobs set summary=summary||jsonb_build_object('storage_bucket','coelo-operations','storage_path',
    'access-profile-files/'||actor||'/'||job.id||'/input/access-profiles-v1.csv') where id=job.id returning * into job;
  insert into public.import_files(import_job_id,storage_path,file_name,mime_type,checksum_sha256,expires_at)
  values(job.id,job.summary->>'storage_path',safe_name,'text/csv',lower(p_file_sha256),now()+interval '24 hours');
  return jsonb_build_object('job_id',job.id,'status',job.processing_state,'version',job.version,
    'format_version','access-profiles-v1','bucket','coelo-operations','path',job.summary->>'storage_path');
end $_$;


ALTER FUNCTION "app_private"."superadmin_access_profile_import_create"("p_request_id" "uuid", "p_file_name" "text", "p_file_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_import_preview"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();job public.import_jobs%rowtype;
begin
  select * into job from public.import_jobs where id=p_job_id;
  if job.id is null or job.target_domain<>'access_profiles_import' or job.created_by<>actor then
    raise insufficient_privilege using message='import job unavailable';end if;
  return jsonb_build_object('job_id',job.id,'status',job.processing_state,'version',job.version,
    'format_version','access-profiles-v1','phase',job.summary->>'phase','summary',job.summary,
    'rows',coalesce((select jsonb_agg(jsonb_build_object('row_number',row_record.row_number,
      'payload',row_record.payload_json,'valid',row_record.error_code is null,'error_code',row_record.error_code)
      order by row_record.row_number) from public.import_rows row_record where row_record.import_job_id=job.id),'[]'),
    'errors',coalesce((select jsonb_agg(jsonb_build_object('row_number',error_record.row_number,
      'column',error_record.column_name,'code',error_record.error_code,'message',error_record.message)
      order by error_record.row_number,error_record.id) from public.import_errors error_record where error_record.import_job_id=job.id),'[]'));
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_import_preview"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_import_stage"("p_job_id" "uuid", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare job public.import_jobs%rowtype;file_record record;row_item jsonb;row_no int:=0;
  invalid_reason text;valid_count int:=0;error_count int:=0;capability_item jsonb;
begin
  if coalesce(auth.jwt()->>'role','')<>'service_role' then raise insufficient_privilege using message='trusted import worker required';end if;
  if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>500 then raise invalid_parameter_value using message='invalid import rows';end if;
  select * into job from public.import_jobs where id=p_job_id for update;
  if job.id is null or job.target_domain<>'access_profiles_import' or job.summary->>'phase'<>'awaiting_upload' then
    raise no_data_found using message='import job unavailable';end if;
  select import_file.*,(storage_object.metadata->>'size')::bigint as storage_size,storage_object.metadata->>'mimetype' as storage_mime into file_record
  from public.import_files import_file join storage.objects storage_object
    on storage_object.bucket_id='coelo-operations' and storage_object.name=import_file.storage_path
  where import_file.import_job_id=job.id;
  if file_record.id is null or file_record.mime_type<>'text/csv' or file_record.storage_mime not in('text/csv','application/csv','text/plain')
    or file_record.storage_size is null or file_record.storage_size<1 or file_record.storage_size>5242880
    or file_record.checksum_sha256!~'^[0-9a-f]{64}$' then raise check_violation using message='uploaded CSV evidence unavailable';end if;
  delete from public.import_errors where import_job_id=job.id;delete from public.import_rows where import_job_id=job.id;
  for row_item in select value from jsonb_array_elements(p_rows) loop
    row_no:=row_no+1;invalid_reason:=null;
    if row_item->>'format_version'<>'access-profiles-v1' then invalid_reason:='unsupported_format_version';
    elsif row_item->>'domain' not in('platform','institution') then invalid_reason:='unsupported_domain';
    elsif nullif(btrim(row_item->>'name'),'') is null or char_length(btrim(row_item->>'name'))>120 then invalid_reason:='invalid_name';
    elsif row_item->>'status' not in('active','inactive') then invalid_reason:='invalid_status';
    elsif jsonb_typeof(coalesce(row_item->'capabilities','[]'))<>'array' then invalid_reason:='invalid_capabilities';
    else for capability_item in select value from jsonb_array_elements(coalesce(row_item->'capabilities','[]')) loop
      if capability_item->>'effect' not in('allow','deny')
        or (row_item->>'domain'='platform' and not exists(select 1 from public.platform_permissions where code=capability_item->>'code' and status='active'))
        or (row_item->>'domain'='institution' and not exists(select 1 from public.institution_permissions where code=capability_item->>'code' and status='active')) then
        invalid_reason:='unknown_capability';exit;end if;end loop;end if;
    insert into public.import_rows(import_job_id,row_number,payload_json,status,error_code)
    values(job.id,row_no,row_item,case when invalid_reason is null then 'active' else 'inactive' end,invalid_reason);
    if invalid_reason is null then valid_count:=valid_count+1;else error_count:=error_count+1;
      insert into public.import_errors(import_job_id,row_number,error_code,message)
      values(job.id,row_no,invalid_reason,'Linha inválida para access-profiles-v1.');end if;
  end loop;
  update public.import_jobs set version=version+1,updated_at=now(),summary=summary||jsonb_build_object(
    'phase','preview_ready','valid_count',valid_count,'error_count',error_count,'storage_size',file_record.storage_size,
    'storage_object_id',file_record.id,'checksum_sha256',file_record.checksum_sha256)
  where id=job.id returning * into job;
  return app_private.superadmin_access_profile_import_preview(job.id);
end $_$;


ALTER FUNCTION "app_private"."superadmin_access_profile_import_stage"("p_job_id" "uuid", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_models_cursor"("p_query" "text" DEFAULT NULL::"text", "p_domain" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_scope" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 25, "p_after_name" "text" DEFAULT NULL::"text", "p_after_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare size_no int:=least(greatest(coalesce(p_limit,25),1),100);result jsonb;
begin
  if p_domain not in('platform','institution','principal') then raise invalid_parameter_value using message='unsupported profile domain';end if;
  perform app_private.require_profile_authority(p_domain);
  with rows as(
    select template.id,template.domain,template.code,template.name,template.description,
      template.status::text,template.max_scope_kind,template.version,template.is_system,
      case template.domain when 'platform' then (select count(*) from public.access_profile_template_platform_permissions item where item.template_id=template.id)
        when 'institution' then (select count(*) from public.access_profile_template_institution_permissions item where item.template_id=template.id)
        else (select count(*) from public.access_profile_template_principal_capabilities item where item.template_id=template.id) end::int capability_count,
      case template.domain
        when 'platform' then coalesce((select jsonb_agg(jsonb_build_object('code',summary.code,'label',summary.label) order by summary.code)
          from(select permission_record.code,permission_record.screen_label label
            from public.access_profile_template_platform_permissions item
            join public.platform_permissions permission_record on permission_record.id=item.permission_id
            where item.template_id=template.id order by permission_record.code limit 4) summary),'[]'::jsonb)
        when 'institution' then coalesce((select jsonb_agg(jsonb_build_object('code',summary.code,'label',summary.label) order by summary.code)
          from(select permission_record.code,permission_record.screen_label label
            from public.access_profile_template_institution_permissions item
            join public.institution_permissions permission_record on permission_record.id=item.permission_id
            where item.template_id=template.id order by permission_record.code limit 4) summary),'[]'::jsonb)
        else coalesce((select jsonb_agg(jsonb_build_object('code',summary.code,'label',summary.label) order by summary.code)
          from(select capability.code,capability.screen_label label
            from public.access_profile_template_principal_capabilities item
            join public.guardian_permission_capabilities capability on capability.id=item.capability_id
            where item.template_id=template.id order by capability.code limit 4) summary),'[]'::jsonb)
      end capability_summary
    from public.access_profile_templates template
    where template.domain=p_domain and (nullif(btrim(p_query),'') is null or template.name ilike '%'||btrim(p_query)||'%')
      and (p_status is null or template.status::text=p_status) and (p_scope is null or template.max_scope_kind=p_scope)
      and (p_after_name is null or (lower(template.name),template.id)>(lower(p_after_name),p_after_id))
  ),page as(select * from rows order by lower(name),id limit size_no+1)
  select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page)-'row_number' order by lower(name),id)
    filter(where row_number<=size_no),'[]'::jsonb),'next_cursor',case when count(*)>size_no then
    (select jsonb_build_object('name',name,'id',id) from page order by lower(name),id offset size_no-1 limit 1) end)
  into result from(select page.*,row_number() over(order by lower(name),id) row_number from page) page;
  return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_models_cursor"("p_query" "text", "p_domain" "text", "p_status" "text", "p_scope" "text", "p_limit" integer, "p_after_name" "text", "p_after_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profile_update"("p_request_id" "uuid", "p_draft" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare domain text:=p_draft->>'domain';profile_id uuid:=nullif(p_draft->>'id','')::uuid;actor uuid;
  replay jsonb;before_data jsonb;profile jsonb;result jsonb;capability jsonb;
  expected_version bigint:=nullif(p_draft->>'expected_version','')::bigint;
begin
  actor:=app_private.access_profile_require_mutation(domain);
  replay:=app_private.access_profile_replay(p_request_id,actor,'update',p_draft);if replay is not null then return replay;end if;
  perform pg_advisory_xact_lock(hashtextextended('access-profile-full-authority',0));
  before_data:=app_private.access_profile_detail_v2(domain,profile_id);
  if (before_data->>'is_system')::boolean then raise insufficient_privilege using message='system profile is protected';end if;
  if (before_data->>'version')::bigint is distinct from expected_version then raise serialization_failure using message='stale profile version';end if;
  if jsonb_typeof(coalesce(p_draft->'capabilities','[]'))<>'array' then raise invalid_parameter_value using message='invalid capabilities';end if;
  if domain='platform' then
    for capability in select value from jsonb_array_elements(coalesce(p_draft->'capabilities','[]')) loop
      if capability->>'effect' not in('allow','deny') or not exists(select 1 from public.platform_permissions where code=capability->>'code' and status='active') then
        raise invalid_parameter_value using message='unknown or invalid capability';end if;
      if capability->>'effect'='allow' and not app_private.has_platform_permission(capability->>'code') then
        raise insufficient_privilege using message='cannot delegate capability operator does not hold';end if;
    end loop;
    update public.platform_roles set name=btrim(p_draft->>'name'),description=nullif(btrim(p_draft->>'description'),''),
      status=coalesce(p_draft->>'status',status::text)::public.record_status,
      max_scope_kind=coalesce(p_draft->>'max_scope_kind',max_scope_kind),version=version+1,updated_at=now() where id=profile_id;
    update public.platform_role_permissions set status='inactive',revoked_at=now() where role_id=profile_id and status='active';
    insert into public.platform_role_permissions(role_id,permission_id,effect,conditions_json,granted_by,status)
    select profile_id,permission_record.id,(item.value->>'effect')::public.permission_effect,'{}',actor,'active'
    from jsonb_array_elements(coalesce(p_draft->'capabilities','[]')) item
    join public.platform_permissions permission_record on permission_record.code=item.value->>'code'
    on conflict(role_id,permission_id) do update set effect=excluded.effect,status='active',revoked_at=null,granted_by=actor;
    perform app_private.assert_full_authority_remains();
  elsif domain='institution' then
    for capability in select value from jsonb_array_elements(coalesce(p_draft->'capabilities','[]')) loop
      if capability->>'effect' not in('allow','deny') or not exists(select 1 from public.institution_permissions where code=capability->>'code' and status='active') then
        raise invalid_parameter_value using message='unknown or invalid capability';end if;
    end loop;
    update public.institution_roles set name=btrim(p_draft->>'name'),description=nullif(btrim(p_draft->>'description'),''),
      status=coalesce(p_draft->>'status',status::text)::public.record_status,
      max_scope_kind=coalesce(p_draft->>'max_scope_kind',max_scope_kind),version=version+1,updated_at=now() where id=profile_id;
    update public.institution_role_permissions set status='inactive',revoked_at=now() where role_id=profile_id and status='active';
    insert into public.institution_role_permissions(role_id,permission_id,effect,conditions_json,granted_by,status)
    select profile_id,permission_record.id,(item.value->>'effect')::public.permission_effect,'{}',actor,'active'
    from jsonb_array_elements(coalesce(p_draft->'capabilities','[]')) item
    join public.institution_permissions permission_record on permission_record.code=item.value->>'code'
    on conflict(role_id,permission_id) do update set effect=excluded.effect,status='active',revoked_at=null,granted_by=actor;
  else raise invalid_parameter_value using message='unsupported profile domain';end if;
  profile:=app_private.access_profile_detail_v2(domain,profile_id);
  result:=jsonb_build_object('profile',profile,'profile_id',profile_id,'domain',domain,
    'version',(profile->>'version')::bigint,'replayed',false);
  insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,reason,before_json,after_json)
  values(actor,'aal2','permission_changed',domain||'_access_profile',profile_id,'success',
    coalesce(nullif(btrim(p_draft->>'reason'),''),'Atualização de perfil.'),before_data,profile);
  perform app_private.access_profile_store_receipt(p_request_id,actor,'update',p_draft,result);return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profile_update"("p_request_id" "uuid", "p_draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_access_profiles_cursor"("p_query" "text" DEFAULT NULL::"text", "p_domain" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_scope" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 25, "p_after_name" "text" DEFAULT NULL::"text", "p_after_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare size_no int:=least(greatest(coalesce(p_limit,25),1),100); result jsonb;
begin
  if p_domain not in('platform','institution') then raise invalid_parameter_value using message='unsupported profile domain'; end if;
  perform app_private.require_profile_authority(p_domain);
  if p_domain='platform' then
    with rows as(select role_record.id,'platform'::text domain,role_record.code,role_record.name,
      role_record.description,role_record.status::text,role_record.max_scope_kind,role_record.version,
      role_record.source_template_id,role_record.source_template_version,role_record.is_system,
      (select count(*) from public.platform_memberships membership where membership.role_id=role_record.id
        and membership.status='active' and membership.revoked_at is null)::int linked_people_count,
      (select count(*) from public.platform_role_permissions grant_record where grant_record.role_id=role_record.id
        and grant_record.status='active' and grant_record.revoked_at is null)::int capability_count
      from public.platform_roles role_record where (nullif(btrim(p_query),'') is null or role_record.name ilike '%'||btrim(p_query)||'%')
        and (p_status is null or role_record.status::text=p_status) and (p_scope is null or role_record.max_scope_kind=p_scope)
        and (p_after_name is null or (lower(role_record.name),role_record.id)>(lower(p_after_name),p_after_id))),
    page as(select * from rows order by lower(name),id limit size_no+1)
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) order by lower(name),id)
      filter(where row_number<=size_no),'[]'::jsonb),'next_cursor',case when count(*)>size_no then
      (select jsonb_build_object('name',name,'id',id) from page order by lower(name),id offset size_no-1 limit 1) end)
    into result from (select page.*,row_number() over(order by lower(name),id) row_number from page) page;
  else
    with rows as(select role_record.id,'institution'::text domain,role_record.code,role_record.name,
      role_record.description,role_record.status::text,role_record.max_scope_kind,role_record.version,
      role_record.source_template_id,role_record.source_template_version,role_record.is_system,
      (select count(*) from public.institution_role_assignments assignment where assignment.role_id=role_record.id
        and assignment.status='active' and (assignment.expires_at is null or assignment.expires_at>now()))::int linked_people_count,
      (select count(*) from public.institution_role_permissions grant_record where grant_record.role_id=role_record.id
        and grant_record.status='active' and grant_record.revoked_at is null)::int capability_count
      from public.institution_roles role_record where (nullif(btrim(p_query),'') is null or role_record.name ilike '%'||btrim(p_query)||'%')
        and (p_status is null or role_record.status::text=p_status) and (p_scope is null or role_record.max_scope_kind=p_scope)
        and (p_after_name is null or (lower(role_record.name),role_record.id)>(lower(p_after_name),p_after_id))),
    page as(select * from rows order by lower(name),id limit size_no+1)
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(page) order by lower(name),id)
      filter(where row_number<=size_no),'[]'::jsonb),'next_cursor',case when count(*)>size_no then
      (select jsonb_build_object('name',name,'id',id) from page order by lower(name),id offset size_no-1 limit 1) end)
    into result from (select page.*,row_number() over(order by lower(name),id) row_number from page) page;
  end if;
  return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_access_profiles_cursor"("p_query" "text", "p_domain" "text", "p_status" "text", "p_scope" "text", "p_limit" integer, "p_after_name" "text", "p_after_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_activity_detail"("p_activity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
 if (select auth.uid()) is null or
    not app_private.has_platform_permission('activities.read') then
  raise insufficient_privilege using message='activities.read required';
 end if;
 result:=app_private.activity_management_payload(p_activity_id);
 if result is null then raise no_data_found using message='activity not found'; end if;
 return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_activity_detail"("p_activity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_activity_directory"("p_search" "text", "p_institution_ids" "uuid"[], "p_unit_ids" "uuid"[], "p_group_ids" "uuid"[], "p_statuses" "text"[], "p_origins" "text"[], "p_limit" integer, "p_offset" integer, "p_sort" "text", "p_sort_ascending" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; normalized_search text:=lower(nullif(btrim(p_search),''));
begin
 if (select auth.uid()) is null or
    not app_private.has_platform_permission('activities.read') then
  raise insufficient_privilege using message='activities.read required';
 end if;
 if p_limit not between 1 and 100 or p_offset<0
    or p_sort not in ('name','institution','status','created_at','updated_at') then
  raise invalid_parameter_value using message='invalid directory parameters';
 end if;
 if exists(select 1 from unnest(coalesce(p_statuses,'{}')) value
   where value not in ('draft','active','inactive','suspended','archived'))
   or exists(select 1 from unnest(coalesce(p_origins,'{}')) value
   where value not in ('institution','unit')) then
  raise invalid_parameter_value using message='invalid directory filter';
 end if;
 with filtered as (
  select activity.*,institution.public_name institution_name,
    unit.name origin_unit_name,taxonomy.name taxonomy_name,
    coalesce((select jsonb_agg(jsonb_build_object(
      'id',linked_unit.id,'name',linked_unit.name,
      'institution_id',linked_unit.institution_id) order by linked_unit.name)
      from public.activity_unit_links unit_link
      join public.units linked_unit on linked_unit.id=unit_link.unit_id
       and linked_unit.institution_id=unit_link.institution_id
      where unit_link.activity_id=activity.id and unit_link.status='active'),'[]'::jsonb)
      linked_units,
    coalesce((select jsonb_agg(jsonb_build_object(
      'id',linked_group.id,'name',linked_group.name,'unit_id',linked_group.unit_id,
      'unit_name',group_unit.name) order by group_unit.name,linked_group.name)
      from public.activity_group_links group_link
      join public.groups linked_group on linked_group.id=group_link.group_id
      join public.units group_unit on group_unit.id=linked_group.unit_id
      where group_link.activity_id=activity.id and group_link.status='active'),'[]'::jsonb)
      linked_groups,
    coalesce((select jsonb_agg(distinct location.name order by location.name)
      from public.activity_unit_links unit_link
      join public.activity_locations location on location.unit_id=unit_link.unit_id
       and location.institution_id=unit_link.institution_id and location.status='active'
      where unit_link.activity_id=activity.id and unit_link.status='active'),'[]'::jsonb)
      location_names,
    (select count(distinct assignment.person_id)
      from public.activity_group_assignments assignment
      join public.activity_group_links group_link
       on group_link.id=assignment.activity_group_link_id
      where group_link.activity_id=activity.id and group_link.status='active'
       and assignment.status='active' and assignment.revoked_at is null)
      active_professional_count,
    (select count(*) from public.activity_group_participants participant
      join public.activity_group_links group_link
       on group_link.id=participant.activity_group_link_id
      where group_link.activity_id=activity.id and group_link.status='active'
       and participant.status='active' and participant.removed_at is null)
      active_participant_count
  from public.activity_definitions activity
  join public.institutions institution on institution.id=activity.institution_id
  left join public.units unit on unit.id=activity.origin_unit_id
   and unit.institution_id=activity.institution_id
  left join public.activity_taxonomies taxonomy on taxonomy.id=activity.taxonomy_id
  where (normalized_search is null
    or position(normalized_search in lower(activity.name||' '||activity.canonical_handle))>0
    or exists(select 1 from public.activity_handle_aliases alias_record
      where alias_record.activity_id=activity.id
       and position(normalized_search in lower(alias_record.alias))>0))
   and (cardinality(coalesce(p_institution_ids,'{}'))=0
     or activity.institution_id=any(p_institution_ids))
   and (cardinality(coalesce(p_unit_ids,'{}'))=0 or exists(
     select 1 from public.activity_unit_links unit_link
      where unit_link.activity_id=activity.id and unit_link.status='active'
       and unit_link.unit_id=any(p_unit_ids)))
   and (cardinality(coalesce(p_group_ids,'{}'))=0 or exists(
     select 1 from public.activity_group_links group_link
      where group_link.activity_id=activity.id and group_link.status='active'
       and group_link.group_id=any(p_group_ids)))
   and (cardinality(coalesce(p_statuses,'{}'))=0 or activity.status::text=any(p_statuses))
   and (cardinality(coalesce(p_origins,'{}'))=0 or activity.origin_scope_kind::text=any(p_origins))
 ), ordered as (
  select filtered.*,count(*) over() total_count from filtered
  order by
   case when p_sort='name' and p_sort_ascending then lower(name) end asc,
   case when p_sort='name' and not p_sort_ascending then lower(name) end desc,
   case when p_sort='institution' and p_sort_ascending then lower(institution_name) end asc,
   case when p_sort='institution' and not p_sort_ascending then lower(institution_name) end desc,
   case when p_sort='status' and p_sort_ascending then status::text end asc,
   case when p_sort='status' and not p_sort_ascending then status::text end desc,
   case when p_sort='created_at' and p_sort_ascending then created_at end asc,
   case when p_sort='created_at' and not p_sort_ascending then created_at end desc,
   case when p_sort='updated_at' and p_sort_ascending then updated_at end asc,
   case when p_sort='updated_at' and not p_sort_ascending then updated_at end desc,id
  limit p_limit offset p_offset
 )
 select jsonb_build_object(
  'items',coalesce(jsonb_agg(to_jsonb(ordered)-'total_count'),'[]'::jsonb),
  'total_count',coalesce(max(total_count),0)
 ) into result from ordered;
 return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_activity_directory"("p_search" "text", "p_institution_ids" "uuid"[], "p_unit_ids" "uuid"[], "p_group_ids" "uuid"[], "p_statuses" "text"[], "p_origins" "text"[], "p_limit" integer, "p_offset" integer, "p_sort" "text", "p_sort_ascending" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_activity_export_complete"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare job public.import_jobs%rowtype;
begin
 if p_storage_path not like 'exports/'||p_import_job_id::text||'/%'
    or nullif(btrim(p_file_name),'') is null or length(p_file_name)>180
    or p_mime_type not in (
      'text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    or p_size_bytes not between 1 and 5242880
    or p_checksum_sha256 !~ '^[0-9a-f]{64}$'
    or p_row_count not between 0 and 50000 then
  raise invalid_parameter_value using message='invalid export result';
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_import_job_id::text,0));
 select * into job from public.import_jobs job_record
  where job_record.id=p_import_job_id for update;
 if job.id is null or job.target_domain<>'activities'
    or job.target_table<>'activity_definitions'
    or job.summary->>'operation'<>'export' then
  raise no_data_found using message='activity export job not found';
 end if;
 if job.processing_state='SUCESSO' then
  return jsonb_build_object('job_id',job.id,'state','SUCESSO','summary',job.summary);
 end if;
 insert into public.import_files(
  import_job_id,storage_path,file_name,mime_type,size_bytes,checksum_sha256,expires_at
 ) values(job.id,p_storage_path,p_file_name,p_mime_type,p_size_bytes,
  p_checksum_sha256,now()+interval '24 hours');
 update public.import_results set created_count=p_row_count,completed_at=now()
  where import_job_id=job.id;
 update public.import_jobs set processing_state='SUCESSO',finished_at=now(),
  summary=summary||jsonb_build_object('progress',100,'row_count',p_row_count,
   'storage_path',p_storage_path,'expires_at',now()+interval '24 hours'),
  updated_at=now() where id=job.id;
 update app_private.import_processing_queue set state='SUCESSO',
  locked_at=null,locked_by=null,updated_at=now() where import_job_id=job.id;
 insert into audit.audit_logs(
  actor_person_id,action_code,object_type,object_id,outcome,after_json
 ) values(job.created_by,'activity.export.complete','import_job',job.id,'success',
  jsonb_build_object('rows',p_row_count,'state','SUCESSO'));
 return jsonb_build_object('job_id',job.id,'state','SUCESSO',
  'storage_path',p_storage_path,'row_count',p_row_count);
end $_$;


ALTER FUNCTION "app_private"."superadmin_activity_export_complete"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_activity_export_prepare"("p_import_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare job public.import_jobs%rowtype; filters jsonb; result jsonb;
 institution_ids uuid[]; unit_ids uuid[]; group_ids uuid[]; statuses text[]; origins text[];
begin
 perform pg_advisory_xact_lock(hashtextextended(p_import_job_id::text,0));
 select * into job from public.import_jobs job_record
  where job_record.id=p_import_job_id for update;
 if job.id is null or job.target_domain<>'activities'
    or job.target_table<>'activity_definitions'
    or job.summary->>'operation'<>'export' then
  raise no_data_found using message='activity export job not found';
 end if;
 filters:=coalesce(job.summary->'filters','{}'::jsonb);
 select coalesce(array_agg(value::uuid),'{}') into institution_ids
  from jsonb_array_elements_text(coalesce(filters->'institution_ids','[]'));
 select coalesce(array_agg(value::uuid),'{}') into unit_ids
  from jsonb_array_elements_text(coalesce(filters->'unit_ids','[]'));
 select coalesce(array_agg(value::uuid),'{}') into group_ids
  from jsonb_array_elements_text(coalesce(filters->'group_ids','[]'));
 select coalesce(array_agg(value),'{}') into statuses
  from jsonb_array_elements_text(coalesce(filters->'statuses','[]'));
 select coalesce(array_agg(value),'{}') into origins
  from jsonb_array_elements_text(coalesce(filters->'origins','[]'));
 select jsonb_build_object('job_id',job.id,'format',job.source_format,
  'rows',coalesce(jsonb_agg(jsonb_build_object(
   'id',activity.id,'institution_id',activity.institution_id,
   'institution_name',app_private.csv_safe(institution.public_name),
   'name',app_private.csv_safe(activity.name),
   'canonical_handle',app_private.csv_safe(activity.canonical_handle),
   'description',app_private.csv_safe(activity.description),
   'taxonomy',app_private.csv_safe(taxonomy.name),
   'governance',activity.governance_kind,'status',activity.status,
   'origin',activity.origin_scope_kind,'updated_at',activity.updated_at
  ) order by activity.name,activity.id),'[]'::jsonb)) into result
 from public.activity_definitions activity
 join public.institutions institution on institution.id=activity.institution_id
 left join public.activity_taxonomies taxonomy on taxonomy.id=activity.taxonomy_id
 where (nullif(btrim(filters->>'search'),'') is null
   or position(lower(btrim(filters->>'search')) in lower(
      activity.name||' '||activity.canonical_handle))>0)
  and (cardinality(institution_ids)=0 or activity.institution_id=any(institution_ids))
  and (cardinality(unit_ids)=0 or exists(select 1 from public.activity_unit_links link
    where link.activity_id=activity.id and link.status='active'
     and link.unit_id=any(unit_ids)))
  and (cardinality(group_ids)=0 or exists(select 1 from public.activity_group_links link
    where link.activity_id=activity.id and link.status='active'
     and link.group_id=any(group_ids)))
  and (cardinality(statuses)=0 or activity.status::text=any(statuses))
  and (cardinality(origins)=0 or activity.origin_scope_kind::text=any(origins));
 if jsonb_array_length(result->'rows')>50000 then
  raise program_limit_exceeded using message='export exceeds row limit';
 end if;
 update public.import_jobs set processing_state='PROCESSANDO',
  started_at=coalesce(started_at,now()),
  summary=summary||jsonb_build_object('progress',50),updated_at=now()
 where id=job.id;
 update app_private.import_processing_queue set state='PROCESSANDO',
  attempts=attempts+1,locked_at=now(),locked_by='group-files',updated_at=now()
 where import_job_id=job.id;
 return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_activity_export_prepare"("p_import_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_activity_filter_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
 if (select auth.uid()) is null or
    not app_private.has_platform_permission('activities.read') then
  raise insufficient_privilege using message='activities.read required';
 end if;
 select jsonb_build_object(
  'institutions',coalesce((select jsonb_agg(jsonb_build_object(
    'id',institution.id,'label',institution.public_name) order by institution.public_name)
    from public.institutions institution where institution.deleted_at is null),'[]'::jsonb),
  'units',coalesce((select jsonb_agg(jsonb_build_object(
    'id',unit.id,'label',unit.name,'institution_id',unit.institution_id) order by unit.name)
    from public.units unit where unit.status<>'archived'),'[]'::jsonb),
  'groups',coalesce((select jsonb_agg(jsonb_build_object(
    'id',group_record.id,'label',group_record.name,'unit_id',group_record.unit_id)
    order by group_record.name)
    from public.groups group_record where group_record.status<>'archived'),'[]'::jsonb)
 ) into result;
 return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_activity_filter_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_activity_import_apply"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_file" "jsonb", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare job public.import_jobs%rowtype; source_row jsonb; row_index bigint;
 row_number_value integer; target_activity_id uuid; target_institution_id uuid;
 target_taxonomy_id uuid; target_origin_unit_id uuid; selected_unit_ids uuid[];
 existing public.activity_definitions%rowtype; v_created_count integer:=0;
 v_updated_count integer:=0; v_rejected_count integer:=0; apply_hash bytea;
begin
 if p_request_id is null or p_import_job_id is null
    or jsonb_typeof(p_file)<>'object' or jsonb_typeof(p_rows)<>'array'
    or jsonb_array_length(p_rows) not between 1 and 5000 then
  raise invalid_parameter_value using message='invalid import payload';
 end if;
 if p_file-array['storage_path','file_name','mime_type','size_bytes','checksum_sha256']
      <>'{}'::jsonb
    or p_file->>'storage_path' not like 'imports/'||p_import_job_id::text||'/%'
    or length(coalesce(p_file->>'file_name',''))>180
    or coalesce((p_file->>'size_bytes')::bigint,0) not between 1 and 5242880
    or p_file->>'mime_type' not in (
      'text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    or p_file->>'checksum_sha256' !~ '^[0-9a-f]{64}$' then
  raise invalid_parameter_value using message='invalid import file metadata';
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_import_job_id::text,0));
 apply_hash:=extensions.digest(convert_to(
   jsonb_build_object('file',p_file,'rows',p_rows)::text,'UTF8'),'sha256');
 select * into job from public.import_jobs job_record
  where job_record.id=p_import_job_id for update;
 if job.id is null or job.target_domain<>'activities'
    or job.target_table<>'activity_definitions'
    or job.summary->>'operation'<>'import' then
  raise no_data_found using message='activity import job not found';
 end if;
 if job.apply_request_id is not null then
  if job.apply_request_id<>p_request_id or job.apply_request_hash<>apply_hash then
   raise invalid_parameter_value using message='import already applied';
  end if;
  return jsonb_build_object('job_id',job.id,'state',job.processing_state,'summary',job.summary);
 end if;
 update public.import_jobs set apply_request_id=p_request_id,
  apply_request_hash=apply_hash,processing_state='PROCESSANDO',status='active',
  started_at=coalesce(started_at,now()),
  summary=summary||jsonb_build_object('progress',1),updated_at=now()
 where id=job.id;
 delete from public.import_errors where import_job_id=job.id;
 delete from public.import_rows where import_job_id=job.id;

 for source_row,row_index in
  select value,ordinality from jsonb_array_elements(p_rows)
   with ordinality item(value,ordinality)
 loop
  begin
   row_number_value:=coalesce(nullif(source_row->>'row_number','')::integer,
     row_index::integer+1);
   if jsonb_typeof(source_row)<>'object'
      or source_row-array[
       'row_number','id','institution_id','name','description','handle_stem',
       'origin_scope_kind','origin_unit_id','governance_kind','status',
       'taxonomy_code','taxonomy_other_description','unit_ids'
      ]<>'{}'::jsonb or row_number_value<2 then
    raise invalid_parameter_value using message='unknown import column';
   end if;
   target_activity_id:=nullif(source_row->>'id','')::uuid;
   target_institution_id:=nullif(source_row->>'institution_id','')::uuid;
   target_origin_unit_id:=nullif(source_row->>'origin_unit_id','')::uuid;
   select taxonomy.id into target_taxonomy_id from public.activity_taxonomies taxonomy
    where taxonomy.code=source_row->>'taxonomy_code' and taxonomy.status='active';
   if target_institution_id is null or target_taxonomy_id is null
      or nullif(btrim(source_row->>'name'),'') is null
      or length(btrim(source_row->>'name'))>160
      or coalesce(source_row->>'origin_scope_kind','institution') not in ('institution','unit')
      or coalesce(source_row->>'governance_kind','optional') not in ('optional','mandatory')
      or coalesce(source_row->>'status','draft') not in (
       'draft','active','inactive','suspended','archived')
      or not exists(select 1 from public.institutions institution
       where institution.id=target_institution_id) then
    raise invalid_parameter_value using message='invalid activity fields';
   end if;
   if coalesce(source_row->>'origin_scope_kind','institution')='unit'
      and not exists(select 1 from public.units unit
       where unit.id=target_origin_unit_id
        and unit.institution_id=target_institution_id) then
    raise foreign_key_violation using message='origin unit outside institution';
   end if;
   if exists(select 1 from public.activity_taxonomies taxonomy
      where taxonomy.id=target_taxonomy_id and taxonomy.code='outros')
      and nullif(btrim(source_row->>'taxonomy_other_description'),'') is null then
    raise invalid_parameter_value using message='other taxonomy description required';
   end if;

   if target_activity_id is null then
    target_activity_id:=gen_random_uuid();
    insert into public.activity_definitions(
     id,institution_id,name,description,handle_stem,origin_scope_kind,origin_unit_id,
     governance_kind,status,taxonomy_id,taxonomy_other_description,identity_mode,
     identity_initials,identity_color,created_by_person_id
    ) values(
     target_activity_id,target_institution_id,btrim(source_row->>'name'),
     nullif(btrim(source_row->>'description'),''),
     coalesce(nullif(app_private.activity_slugify(coalesce(
      nullif(source_row->>'handle_stem',''),source_row->>'name')),''),'atividade')||'-'||left(target_activity_id::text,6),
     coalesce(source_row->>'origin_scope_kind','institution')::public.activity_origin_scope,
     target_origin_unit_id,coalesce(source_row->>'governance_kind','optional'),
     coalesce(source_row->>'status','draft')::public.record_status,target_taxonomy_id,
     nullif(btrim(source_row->>'taxonomy_other_description'),''),
     'initials',upper(left(regexp_replace(source_row->>'name','[^[:alnum:]]','','g'),2)),
     '#D63C00',job.created_by);
    v_created_count:=v_created_count+1;
   else
    select * into existing from public.activity_definitions activity
     where activity.id=target_activity_id for update;
    if existing.id is null then raise no_data_found using message='activity not found'; end if;
    if existing.institution_id<>target_institution_id then
     raise insufficient_privilege using message='activity outside institution';
    end if;
    update public.activity_definitions set name=btrim(source_row->>'name'),
     description=nullif(btrim(source_row->>'description'),''),
     handle_stem=coalesce(nullif(app_private.activity_slugify(coalesce(
      nullif(source_row->>'handle_stem',''),source_row->>'name')),''),
      'atividade-'||left(target_activity_id::text,6)),
     origin_scope_kind=coalesce(source_row->>'origin_scope_kind','institution')::public.activity_origin_scope,
     origin_unit_id=target_origin_unit_id,
     governance_kind=coalesce(source_row->>'governance_kind','optional'),
     status=coalesce(source_row->>'status','draft')::public.record_status,
     taxonomy_id=target_taxonomy_id,
     taxonomy_other_description=nullif(btrim(source_row->>'taxonomy_other_description'),''),
     management_version=management_version+1,updated_at=now()
    where id=target_activity_id;
    v_updated_count:=v_updated_count+1;
   end if;
   if source_row?'unit_ids' then
    select coalesce(array_agg(distinct value::uuid),'{}'::uuid[]) into selected_unit_ids
     from jsonb_array_elements_text(source_row->'unit_ids');
    if (select count(*) from public.units unit
      where unit.id=any(selected_unit_ids)
       and unit.institution_id=target_institution_id)<>cardinality(selected_unit_ids) then
     raise foreign_key_violation using message='unit outside institution';
    end if;
    insert into public.activity_unit_links(
     activity_id,institution_id,unit_id,linked_by_person_id,status
    ) select target_activity_id,target_institution_id,unit_id,job.created_by,'active'
      from unnest(selected_unit_ids) unit_id
    on conflict(activity_id,unit_id) do update set status='active',ends_at=null,updated_at=now();
   end if;
   insert into public.import_rows(import_job_id,row_number,payload_json,status)
    values(job.id,row_number_value,source_row,'active');
  exception when others then
   v_rejected_count:=v_rejected_count+1;
   insert into public.import_rows(
    import_job_id,row_number,payload_json,status,error_code
   ) values(job.id,coalesce(row_number_value,row_index::integer+1),
    source_row,'inactive',sqlstate)
   on conflict(import_job_id,row_number) do update set payload_json=excluded.payload_json,
    status=excluded.status,error_code=excluded.error_code;
   insert into public.import_errors(
    import_job_id,row_number,error_code,message
   ) values(job.id,coalesce(row_number_value,row_index::integer+1),sqlstate,
    'Linha rejeitada pela validação do backend.');
  end;
  row_number_value:=null;
 end loop;

 insert into public.import_files(
  import_job_id,storage_path,file_name,mime_type,size_bytes,checksum_sha256,expires_at
 ) values(job.id,p_file->>'storage_path',p_file->>'file_name',p_file->>'mime_type',
  (p_file->>'size_bytes')::bigint,p_file->>'checksum_sha256',now()+interval '24 hours');
 update public.import_results set created_count = v_created_count,updated_count = v_updated_count,rejected_count = v_rejected_count,completed_at=now() where import_job_id=job.id;
 update public.import_jobs set
  processing_state=case when v_rejected_count>0 then 'REJEICAO'::public.import_processing_state
   else 'SUCESSO'::public.import_processing_state end,
  finished_at=now(),summary=summary||jsonb_build_object(
   'progress',100,'created',v_created_count,'updated',v_updated_count,
   'rejected',v_rejected_count),updated_at=now() where id=job.id;
 update app_private.import_processing_queue set
  state=case when v_rejected_count>0 then 'REJEICAO'::public.import_processing_state
   else 'SUCESSO'::public.import_processing_state end,
  locked_at=null,locked_by=null,updated_at=now() where import_job_id=job.id;
 insert into audit.audit_logs(
  actor_person_id,action_code,object_type,object_id,outcome,after_json
 ) values(job.created_by,'activity.import.complete','import_job',job.id,'success',
  jsonb_build_object('created',v_created_count,'updated',v_updated_count,'rejected',v_rejected_count));
 return jsonb_build_object('job_id',job.id,
  'state',case when v_rejected_count>0 then 'REJEICAO' else 'SUCESSO' end,
  'created',v_created_count,'updated',v_updated_count,'rejected',v_rejected_count);
end $_$;


ALTER FUNCTION "app_private"."superadmin_activity_import_apply"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_file" "jsonb", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_activity_template_options"("p_institution_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
 if (select auth.uid()) is null
    or not app_private.has_platform_permission('activities.read') then
  raise insufficient_privilege using message='activities.read required';
 end if;
 if p_institution_id is not null and not exists(
  select 1 from public.institutions institution
  where institution.id=p_institution_id
 ) then
  raise no_data_found using message='institution not found';
 end if;
 select jsonb_build_object(
  'institutions',coalesce((select jsonb_agg(jsonb_build_object(
    'id',institution.id,'name',institution.public_name)
    order by institution.public_name)
    from public.institutions institution
    where p_institution_id is null or institution.id=p_institution_id),'[]'::jsonb),
  'taxonomy',coalesce((select jsonb_agg(jsonb_build_object(
    'id',category.id,'label',category.name,'is_other',category.code='outros',
    'subtypes',coalesce((select jsonb_agg(jsonb_build_object(
      'id',subtype.id,'label',subtype.name)
      order by subtype.sort_order,subtype.name)
      from public.activity_taxonomies subtype
      where subtype.parent_id=category.id and subtype.status='active'),'[]'::jsonb))
    order by category.sort_order,category.name)
    from public.activity_taxonomies category
    where category.taxonomy_kind='category'
     and category.status='active'),'[]'::jsonb),
  'templates',coalesce((select jsonb_agg(jsonb_build_object(
    'id',template.id,'name',template.name,
    'description',template.description,
    'scope_kind',template.scope_kind,
    'institution_id',template.institution_id,
    'governance_kind',template.governance_kind,
    'taxonomy_id',coalesce(taxonomy.parent_id,taxonomy.id),
    'subtype_id',case when taxonomy.taxonomy_kind='subtype' then taxonomy.id end)
    order by template.scope_kind desc,template.name)
    from public.activity_templates template
    join public.activity_taxonomies taxonomy on taxonomy.id=template.taxonomy_id
    where template.status='active'
     and (template.scope_kind='platform'
      or (p_institution_id is not null
       and template.institution_id=p_institution_id))),'[]'::jsonb)
 ) into result;
 return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_activity_template_options"("p_institution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_authorize_activity_file_job"("p_import_job_id" "uuid", "p_action" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 actor uuid:=app_private.current_person_id();
 job public.import_jobs%rowtype;
 required_capability text;
begin
 if (select auth.uid()) is null or actor is null then
  raise insufficient_privilege using message='authentication required';
 end if;
 if p_action not in ('import','export') then
  raise invalid_parameter_value using message='invalid activity file action';
 end if;
 required_capability:=case p_action
  when 'import' then 'activities.import' else 'activities.export' end;
 if not app_private.has_platform_permission(required_capability) then
  raise insufficient_privilege using message=required_capability||' required';
 end if;
 if not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='MFA AAL2 required';
 end if;
 select * into job from public.import_jobs job_record
 where job_record.id=p_import_job_id
  and job_record.created_by=actor
  and job_record.target_domain='activities'
  and job_record.target_table='activity_definitions'
  and job_record.summary->>'operation'=p_action;
 if job.id is null then
  raise insufficient_privilege using message='activity file job unavailable';
 end if;
 return jsonb_build_object(
  'authorized',true,'job_id',job.id,'action',p_action,
  'state',job.processing_state
 );
end $$;


ALTER FUNCTION "app_private"."superadmin_authorize_activity_file_job"("p_import_job_id" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_complete_institution_export"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare job public.import_jobs%rowtype;
begin
 select * into job from public.import_jobs where id=p_import_job_id for update;
 if job.id is null or job.target_domain<>'institutions_export' then
  raise no_data_found using message='institution export not found';
 end if;
 if p_storage_path!~('^exports/institutions/'||job.id||'/[0-9a-f-]+\.(csv|xlsx)$')
    or p_mime_type not in('text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    or p_size_bytes not between 1 and 5242880
    or p_row_count not between 1 and 5000
    or p_checksum_sha256!~'^[0-9a-f]{64}$' then
  raise invalid_parameter_value using message='invalid institution export artifact';
 end if;
 insert into public.import_files(import_job_id,storage_path,file_name,mime_type,size_bytes)
 values(job.id,p_storage_path,left(p_file_name,180),p_mime_type,p_size_bytes);
 update public.import_results set created_count=p_row_count,completed_at=now()
 where import_job_id=job.id;
 update public.import_jobs set processing_state='SUCESSO',status='active',finished_at=now(),
  summary=summary||jsonb_build_object(
    'phase','complete','storage_path',p_storage_path,
    'checksum_sha256',p_checksum_sha256,'row_count',p_row_count
  ),updated_at=now() where id=job.id;
 return app_private.institution_file_job_payload(job.id);
end
$_$;


ALTER FUNCTION "app_private"."superadmin_complete_institution_export"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_complete_unit_file_job"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  job public.import_jobs%rowtype;
  object_metadata jsonb;
begin
  select *
  into job
  from public.import_jobs
  where id = p_import_job_id
  for update;

  if job.id is null or job.target_domain <> 'units_export' then
    raise no_data_found using message = 'unit export not found';
  end if;

  if p_storage_path !~ (
      '^exports/units/' || job.id || '/[0-9a-f-]+\.(csv|xlsx)$'
    )
    or p_mime_type not in (
      'text/csv',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    )
    or p_size_bytes not between 1 and 5242880
    or p_row_count < 0
    or p_checksum_sha256 !~ '^[0-9a-f]{64}$'
    or length(coalesce(p_file_name, '')) not between 1 and 180
  then
    raise invalid_parameter_value using message = 'invalid unit export artifact';
  end if;

  select object_record.metadata
  into object_metadata
  from storage.objects object_record
  where object_record.bucket_id = 'coelo-operations'
    and object_record.name = p_storage_path;

  if not found
    or coalesce((object_metadata ->> 'size')::bigint, -1) <> p_size_bytes
    or coalesce(object_metadata ->> 'mimetype', '') <> p_mime_type
  then
    raise check_violation using message = 'unit export object attestation mismatch';
  end if;

  if job.processing_state = 'SUCESSO' then
    return app_private.unit_file_job_payload(job.id);
  end if;

  insert into public.import_files(
    import_job_id,
    storage_path,
    file_name,
    mime_type,
    size_bytes
  ) values (
    job.id,
    p_storage_path,
    left(p_file_name, 180),
    p_mime_type,
    p_size_bytes
  );

  update public.import_results
  set created_count = p_row_count,
      completed_at = now()
  where import_job_id = job.id;

  update public.import_jobs
  set processing_state = 'SUCESSO',
      status = 'active',
      finished_at = now(),
      summary = summary || jsonb_build_object(
        'phase', 'complete',
        'storage_path', p_storage_path,
        'checksum_sha256', p_checksum_sha256,
        'row_count', p_row_count
      ),
      updated_at = now()
  where id = job.id;

  insert into audit.audit_logs(
    actor_person_id,
    mfa_aal,
    action_code,
    object_type,
    object_id,
    outcome,
    after_json
  ) values (
    job.created_by,
    'aal2',
    'unit.export.complete',
    'import_job',
    job.id,
    'success',
    jsonb_build_object('row_count', p_row_count)
  );

  return app_private.unit_file_job_payload(job.id);
end;
$_$;


ALTER FUNCTION "app_private"."superadmin_complete_unit_file_job"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) OWNER TO "postgres";


