CREATE OR REPLACE FUNCTION "app_private"."superadmin_confirm_institution_import"("p_request_id" "uuid", "p_import_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; job public.import_jobs%rowtype; source_row record;
 created_count integer:=0; rejected_count integer:=0;
begin
 actor:=app_private.assert_institution_file_access('institutions.import');
 if p_request_id is null then raise invalid_parameter_value using message='request required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_import_job_id::text,0));
 select * into job from public.import_jobs where id=p_import_job_id for update;
 if job.id is null then raise no_data_found using message='institution import not found'; end if;
 if job.target_domain<>'institutions' or job.created_by<>actor then
  raise insufficient_privilege using message='institution import outside actor scope';
 end if;
 if job.summary->>'confirm_request_id'=p_request_id::text
    or job.processing_state in('SUCESSO','REJEICAO') then
  return app_private.institution_file_job_payload(job.id);
 end if;
 if job.summary->>'phase'<>'preview' then
  raise object_not_in_prerequisite_state using message='preview required';
 end if;
 update public.import_jobs set processing_state='PROCESSANDO',status='active',
  started_at=coalesce(started_at,now()),updated_at=now() where id=job.id;
 for source_row in
  select * from public.import_rows r
  where r.import_job_id=job.id and r.error_code is null order by r.row_number
 loop
  begin
   perform app_private.create_institution_for_superadmin(gen_random_uuid(),source_row.payload_json);
   created_count:=created_count+1;
  exception when others then
   rejected_count:=rejected_count+1;
   update public.import_rows set status='archived',error_code='create_rejected'
   where id=source_row.id;
   insert into public.import_errors(import_job_id,row_number,error_code,message)
   values(job.id,source_row.row_number,'create_rejected',
    'Linha rejeitada durante a criaÃ§Ã£o segura da instituiÃ§Ã£o.');
  end;
 end loop;
 rejected_count:=rejected_count+(
  select count(*) from public.import_rows r
  where r.import_job_id=job.id and r.error_code is not null and r.error_code<>'create_rejected'
 );
 update public.import_results set
  created_count=created_count,rejected_count=rejected_count,completed_at=now()
 where import_job_id=job.id;
 update public.import_jobs set
  processing_state=case when rejected_count=0 then 'SUCESSO'::public.import_processing_state
    else 'REJEICAO'::public.import_processing_state end,
  status=case when rejected_count=0 then 'active'::public.record_status
    else 'draft'::public.record_status end,
  finished_at=now(),
  summary=summary||jsonb_build_object(
    'phase','complete','confirm_request_id',p_request_id,
    'created_count',created_count,'rejected_count',rejected_count
  ),updated_at=now()
 where id=job.id;
 return app_private.institution_file_job_payload(job.id);
end
$$;


