CREATE OR REPLACE FUNCTION "app_private"."superadmin_confirm_unit_import"("p_request_id" "uuid", "p_import_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; job public.import_jobs%rowtype; source_row record; v_created_count int:=0; v_rejected_count int:=0;
begin
 actor:=app_private.assert_unit_file_access('units.import',null);
 if p_request_id is null then raise invalid_parameter_value using message='request required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_import_job_id::text,0));
 select * into job from public.import_jobs where id=p_import_job_id for update;
 if job.id is null then raise no_data_found using message='unit import not found'; end if;
 if job.target_domain<>'units' or job.created_by<>actor then raise insufficient_privilege using message='unit import outside actor scope'; end if;
 if job.summary->>'confirm_request_id'=p_request_id::text or job.processing_state in('SUCESSO','REJEICAO') then return app_private.unit_file_job_payload(job.id); end if;
 if job.summary->>'phase'<>'preview' then raise object_not_in_prerequisite_state using message='preview required'; end if;
 update public.import_jobs set processing_state='PROCESSANDO',status='active',started_at=coalesce(started_at,now()),updated_at=now() where id=job.id;
 for source_row in select * from public.import_rows r where r.import_job_id=job.id and r.error_code is null order by r.row_number loop
  begin
   perform app_private.create_unit_for_superadmin((source_row.payload_json->>'request_id')::uuid,source_row.payload_json);
   v_created_count:=v_created_count+1;
   update public.import_rows set status='active' where id=source_row.id;
  exception when others then
   v_rejected_count:=v_rejected_count+1;
   update public.import_rows set status='archived',error_code='create_rejected' where id=source_row.id;
   insert into public.import_errors(import_job_id,row_number,error_code,message)
   values(job.id,source_row.row_number,'create_rejected','Linha rejeitada durante a criacao segura da unidade.');
  end;
 end loop;
 v_rejected_count:=v_rejected_count+(select count(*) from public.import_rows r where r.import_job_id=job.id and r.error_code is not null and r.error_code<>'create_rejected');
 update public.import_results set created_count=v_created_count,rejected_count=v_rejected_count,completed_at=now() where import_job_id=job.id;
 update public.import_jobs set processing_state=case when v_rejected_count=0 then'SUCESSO'::public.import_processing_state else'REJEICAO'::public.import_processing_state end,
  status=case when v_rejected_count=0 then'active'::public.record_status else'draft'::public.record_status end,
  finished_at=now(),summary=summary||jsonb_build_object('phase','complete','confirm_request_id',p_request_id),updated_at=now() where id=job.id;
 insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,after_json)
 values(actor,'aal2','unit.import.confirm','import_job',job.id,case when v_rejected_count=0 then 'success'::public.audit_outcome else 'failed'::public.audit_outcome end,
  jsonb_build_object('created',v_created_count,'rejected',v_rejected_count));
 return app_private.unit_file_job_payload(job.id);
end $$;


