CREATE OR REPLACE FUNCTION "app_private"."superadmin_copy_activity_template"("p_template_id" "uuid", "p_institution_id" "uuid", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 actor uuid:=app_private.current_person_id();
 source_template public.activity_templates%rowtype;
 copied_template public.activity_templates%rowtype;
 receipt app_private.activity_template_command_receipts%rowtype;
 request_hash bytea; result jsonb; copied_id uuid;
begin
 if (select auth.uid()) is null or actor is null then
  raise insufficient_privilege using message='authentication required';
 end if;
 if not app_private.has_platform_permission('activities.templates.manage') then
  raise insufficient_privilege using message='activities.templates.manage required';
 end if;
 if not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='MFA AAL2 required';
 end if;
 if p_template_id is null or p_institution_id is null or p_idempotency_key is null
    or not exists(select 1 from public.institutions institution
      where institution.id=p_institution_id) then
  raise invalid_parameter_value using message='invalid template copy request';
 end if;
 select * into source_template from public.activity_templates template_record
 where template_record.id=p_template_id and template_record.status='active'
  and (template_record.scope_kind='platform'
   or template_record.institution_id=p_institution_id);
 if source_template.id is null then
  raise no_data_found using message='template not found';
 end if;
 request_hash:=extensions.digest(convert_to(jsonb_build_object(
  'template_id',p_template_id,'institution_id',p_institution_id)::text,
  'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into receipt from app_private.activity_template_command_receipts
  where request_id=p_idempotency_key;
 if receipt.request_id is not null then
  if receipt.actor_person_id<>actor then
   raise insufficient_privilege using message='template receipt actor mismatch';
  end if;
  if receipt.command_kind<>'copy_template'
     or receipt.request_hash<>request_hash
     or receipt.source_template_id<>p_template_id then
   raise invalid_parameter_value using message='idempotency key reused';
  end if;
  return receipt.result_json;
 end if;
 copied_id:=app_private.activity_request_uuid(
  'activity-template-copy',p_idempotency_key);
 insert into public.activity_templates(
  id,scope_kind,institution_id,code,name,description,taxonomy_id,
  governance_kind,template_payload,status,created_by_person_id
 ) values(
  copied_id,'institution',p_institution_id,
  left(source_template.code,48)||'-'||left(replace(p_idempotency_key::text,'-',''),8),
  left('Cópia de '||source_template.name,120),
  source_template.description,source_template.taxonomy_id,
  source_template.governance_kind,source_template.template_payload,
  'active',actor
 ) returning * into copied_template;
 result:=to_jsonb(copied_template);
 insert into app_private.activity_template_command_receipts(
  request_id,command_kind,request_hash,actor_person_id,source_template_id,
  result_template_id,result_json
 ) values(p_idempotency_key,'copy_template',request_hash,actor,
  source_template.id,copied_template.id,result);
 insert into audit.audit_logs(
  actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,
  outcome,before_json,after_json
 ) values(actor,auth.jwt()->>'aal','activity.template.copy',
  'activity_template',copied_template.id,p_institution_id,'success',
  to_jsonb(source_template),result);
 return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_copy_activity_template"("p_template_id" "uuid", "p_institution_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_create_activity_import_job"("p_file_name" "text", "p_mime_type" "text", "p_source_format" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id(); request_hash bytea;
 job public.import_jobs%rowtype;
begin
 if (select auth.uid()) is null or actor is null
    or not app_private.has_platform_permission('activities.import') then
  raise insufficient_privilege using message='activities.import required';
 end if;
 if not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='MFA AAL2 required';
 end if;
 if p_idempotency_key is null or nullif(btrim(p_file_name),'') is null
    or length(p_file_name)>180 or p_source_format not in ('csv','xlsx')
    or p_mime_type not in (
      'text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') then
  raise invalid_parameter_value using message='invalid import request';
 end if;
 request_hash:=extensions.digest(convert_to(jsonb_build_object(
  'file_name',p_file_name,'mime_type',p_mime_type,'format',p_source_format)::text,'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into job from public.import_jobs job_record
  where job_record.request_id=p_idempotency_key;
 if job.id is not null then
  if job.created_by<>actor then
   raise insufficient_privilege using message='idempotency job actor mismatch';
  end if;
  if job.request_hash<>request_hash or job.target_domain<>'activities' then
   raise invalid_parameter_value using message='idempotency key reused';
  end if;
  return jsonb_build_object('job_id',job.id,'state',job.processing_state,
   'bucket','coelo-operations','upload_path',
   'imports/'||job.id::text||'/'||p_idempotency_key::text);
 end if;
 insert into public.import_jobs(
  request_id,request_hash,target_domain,target_table,source_format,source_locale,
  target_locale,status,processing_state,summary,created_by
 ) values(p_idempotency_key,request_hash,'activities','activity_definitions',
  p_source_format,'pt-BR','pt-BR','draft','PENDENTE',
  jsonb_build_object('operation','import','file_name',p_file_name,
   'mime_type',p_mime_type,'template_version','activities-v1','progress',0),actor)
 returning * into job;
 insert into public.import_results(import_job_id) values(job.id);
 insert into app_private.import_processing_queue(import_job_id) values(job.id);
 return jsonb_build_object('job_id',job.id,'state',job.processing_state,
  'bucket','coelo-operations',
  'upload_path','imports/'||job.id::text||'/'||p_idempotency_key::text);
end $$;


ALTER FUNCTION "app_private"."superadmin_create_activity_import_job"("p_file_name" "text", "p_mime_type" "text", "p_source_format" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_create_activity_locations"("p_institution_id" "uuid", "p_unit_ids" "uuid"[], "p_name" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id(); request_hash bytea;
 receipt app_private.activity_management_command_receipts%rowtype;
 current_unit_id uuid; result jsonb;
begin
 if (select auth.uid()) is null or actor is null
    or not app_private.has_platform_permission('activities.link_units')
    or not app_private.has_platform_permission('activities.manage') then
  raise insufficient_privilege using message='activity location management required';
 end if;
 if not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='MFA AAL2 required';
 end if;
 if p_idempotency_key is null or p_institution_id is null
    or cardinality(coalesce(p_unit_ids,'{}'))<1
    or nullif(btrim(p_name),'') is null or length(btrim(p_name))>120 then
  raise invalid_parameter_value using message='invalid location payload';
 end if;
 request_hash:=extensions.digest(convert_to(jsonb_build_object(
  'institution_id',p_institution_id,'unit_ids',p_unit_ids,'name',btrim(p_name))::text,'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into receipt from app_private.activity_management_command_receipts
  where request_id=p_idempotency_key;
 if receipt.request_id is not null then
  if receipt.actor_person_id<>actor then
   raise insufficient_privilege using message='idempotency receipt actor mismatch';
  end if;
  if receipt.command_kind<>'locations' or receipt.request_hash<>request_hash then
   raise invalid_parameter_value using message='idempotency key reused';
  end if;
  return receipt.result_json;
 end if;
 if (select count(*) from public.units unit
   where unit.id=any(p_unit_ids) and unit.institution_id=p_institution_id)
   <>cardinality(p_unit_ids) then
  raise foreign_key_violation using message='unit outside institution';
 end if;
 foreach current_unit_id in array p_unit_ids loop
  if not exists(select 1 from public.activity_locations location
    where location.unit_id=current_unit_id
      and lower(location.name)=lower(btrim(p_name)) and location.status<>'archived') then
   insert into public.activity_locations(
    institution_id,unit_id,name,created_by_person_id
   ) values(p_institution_id,current_unit_id,btrim(p_name),actor);
  end if;
 end loop;
 select coalesce(jsonb_agg(to_jsonb(location) order by location.name),'[]'::jsonb)
 into result from public.activity_locations location
 where location.unit_id=any(p_unit_ids)
  and lower(location.name)=lower(btrim(p_name)) and location.status<>'archived';
 insert into app_private.activity_management_command_receipts(
  request_id,command_kind,request_hash,actor_person_id,result_json
 ) values(p_idempotency_key,'locations',request_hash,actor,result);
 insert into audit.audit_logs(
  actor_person_id,mfa_aal,action_code,object_type,institution_id,outcome,after_json
 ) values(actor,auth.jwt()->>'aal','activity.locations.create','activity_location',
  p_institution_id,'success',result);
 return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_create_activity_locations"("p_institution_id" "uuid", "p_unit_ids" "uuid"[], "p_name" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_create_import_export_job"("p_domain" "text", "p_file_name" "text", "p_mime_type" "text", "p_source_format" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.assert_import_export_hub_actor();
  if p_domain <> 'units' then
    raise invalid_parameter_value using message = 'import domain unavailable';
  end if;
  return app_private.superadmin_create_unit_import_job(
    p_file_name, p_mime_type, p_source_format, p_idempotency_key
  );
end;
$$;


ALTER FUNCTION "app_private"."superadmin_create_import_export_job"("p_domain" "text", "p_file_name" "text", "p_mime_type" "text", "p_source_format" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_create_institution_import_job"("p_file_name" "text", "p_mime_type" "text", "p_source_format" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; job public.import_jobs%rowtype; request_hash bytea;
begin
 actor:=app_private.assert_institution_file_access('institutions.import');
 if p_idempotency_key is null or p_source_format not in('csv','xlsx')
    or length(coalesce(p_file_name,'')) not between 1 and 180
    or p_mime_type<>(case p_source_format when 'csv' then 'text/csv'
      else 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' end) then
  raise invalid_parameter_value using message='invalid institution import file contract';
 end if;
 request_hash:=extensions.digest(pg_catalog.convert_to(jsonb_build_object(
  'file_name',p_file_name,'mime_type',p_mime_type,'format',p_source_format
 )::text,'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into job from public.import_jobs where request_id=p_idempotency_key;
 if job.id is not null then
  if job.created_by<>actor or job.request_hash<>request_hash or job.target_domain<>'institutions' then
   raise invalid_parameter_value using message='idempotency key replay mismatch';
  end if;
  return app_private.institution_file_job_payload(job.id);
 end if;
 insert into public.import_jobs(
  request_id,request_hash,target_domain,target_table,source_format,source_locale,target_locale,
  status,processing_state,summary,created_by
 ) values(
  p_idempotency_key,request_hash,'institutions','institutions',p_source_format,'pt-BR','pt-BR',
  'draft','PENDENTE',jsonb_build_object('phase','upload','original_name',left(p_file_name,180)),actor
 ) returning * into job;
 insert into public.import_results(import_job_id) values(job.id);
 return app_private.institution_file_job_payload(job.id);
end
$$;


