CREATE OR REPLACE FUNCTION "app_private"."superadmin_create_unit_import_job"("p_file_name" "text", "p_mime_type" "text", "p_source_format" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; job public.import_jobs%rowtype; request_hash bytea; extension text;
begin
 actor:=app_private.assert_unit_file_access('units.import',null);
 if p_idempotency_key is null or p_source_format not in('csv','xlsx')
    or length(coalesce(p_file_name,'')) not between 1 and 180
    or p_mime_type <> (case p_source_format when 'csv' then 'text/csv' else 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' end) then
  raise invalid_parameter_value using message='invalid unit import file contract';
 end if;
 extension:=p_source_format;
 request_hash:=extensions.digest(pg_catalog.convert_to(jsonb_build_object(
  'file_name',p_file_name,'mime_type',p_mime_type,'format',p_source_format)::text,'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into job from public.import_jobs where request_id=p_idempotency_key;
 if job.id is not null then
  if job.created_by<>actor or job.request_hash<>request_hash or job.target_domain<>'units' then
   raise invalid_parameter_value using message='idempotency key replay mismatch';
  end if;
  return app_private.unit_file_job_payload(job.id)||jsonb_build_object(
   'bucket','coelo-operations','upload_path','imports/units/'||job.id||'/source.'||extension);
 end if;
 insert into public.import_jobs(request_id,request_hash,target_domain,target_table,source_format,
  source_locale,target_locale,status,processing_state,summary,created_by)
 values(p_idempotency_key,request_hash,'units','units',p_source_format,'pt-BR','pt-BR',
  'draft','PENDENTE',jsonb_build_object('phase','upload','original_name',left(p_file_name,180)),actor)
 returning * into job;
 insert into public.import_results(import_job_id) values(job.id);
 insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,after_json)
 values(actor,'aal2','unit.import.create','import_job',job.id,'success',jsonb_build_object('format',p_source_format));
 return app_private.unit_file_job_payload(job.id)||jsonb_build_object(
  'bucket','coelo-operations','upload_path','imports/units/'||job.id||'/source.'||extension);
end $$;


