CREATE OR REPLACE FUNCTION "app_private"."superadmin_internal_error_envelope"("p_code" "text", "p_correlation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select pg_catalog.jsonb_build_object('ok',false,'data',null,'error',
    pg_catalog.jsonb_build_object('code',case when p_code in(
      'SAI_AUTH_REQUIRED','SAI_SESSION_INVALID','SAI_INTERNAL_CONTEXT_DENIED',
      'SAI_MEMBERSHIP_SUSPENDED','SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED',
      'SAI_MFA_REQUIRED','SAI_LAST_OWNER_PROTECTED','SAI_CONCURRENT_CHANGE')
      then p_code else 'SAI_INTERNAL_ERROR' end,
      'message',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID') then 'Autenticação necessária.'
        when p_code='SAI_MFA_REQUIRED' then 'Confirme o segundo fator.'
        when p_code in('SAI_LAST_OWNER_PROTECTED','SAI_CONCURRENT_CHANGE') then 'O estado mudou. Recarregue e tente novamente.'
        when p_code like 'SAI_%DENIED' or p_code like 'SAI_MEMBERSHIP_%' then 'Acesso não autorizado.'
        else 'Não foi possível concluir a operação.' end,
      'correlation_id',p_correlation_id,
      'http_status',case
        when p_code in('SAI_AUTH_REQUIRED','SAI_SESSION_INVALID') then 401
        when p_code in('SAI_LAST_OWNER_PROTECTED','SAI_CONCURRENT_CHANGE') then 409
        when p_code in('SAI_INTERNAL_CONTEXT_DENIED','SAI_MEMBERSHIP_SUSPENDED',
          'SAI_MEMBERSHIP_REVOKED','SAI_PERMISSION_DENIED','SAI_MFA_REQUIRED') then 403
        else 500 end))
$$;


ALTER FUNCTION "app_private"."superadmin_internal_error_envelope"("p_code" "text", "p_correlation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_list_import_export_jobs"("p_domains" "text"[], "p_states" "text"[], "p_formats" "text"[], "p_search" "text", "p_created_from" timestamp with time zone, "p_created_to" timestamp with time zone, "p_before_created_at" timestamp with time zone, "p_before_job_id" "uuid", "p_page_size" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  normalized_search text := nullif(btrim(p_search), '');
  escaped_search text;
begin
  actor := app_private.assert_import_export_hub_actor();
  if p_page_size not between 1 and 100
    or (p_domains is not null and exists (
      select 1 from unnest(p_domains) domain_name where domain_name <> 'units'
    ))
    or (p_states is not null and exists (
      select 1 from unnest(p_states) state_name
      where state_name not in ('PENDENTE','PROCESSANDO','SUCESSO','REJEICAO','ERRO')
    ))
    or (p_formats is not null and exists (
      select 1 from unnest(p_formats) format_name where format_name not in ('csv','xlsx')
    ))
    or (normalized_search is not null and (
      char_length(normalized_search) > 120 or normalized_search ~ '[[:cntrl:]]'
    ))
    or (p_created_from is not null and p_created_to is not null
      and p_created_from > p_created_to)
  then
    raise invalid_parameter_value using message = 'invalid import/export list filters';
  end if;

  escaped_search := case when normalized_search is null then null else
    replace(replace(replace(normalized_search, chr(92), chr(92) || chr(92)),
      '%', chr(92) || '%'), '_', chr(92) || '_')
  end;

  return (
    with authorized as materialized (
      select job.id, job.target_domain, job.source_format, job.processing_state,
        job.summary, job.created_at, job.started_at, job.finished_at,
        source_file.file_name,
        result_record.created_count, result_record.updated_count,
        result_record.linked_count, result_record.ignored_count,
        result_record.rejected_count
      from public.import_jobs job
      left join public.import_results result_record on result_record.import_job_id = job.id
      left join lateral (
        select file_record.file_name
        from public.import_files file_record
        where file_record.import_job_id = job.id
        order by file_record.uploaded_at desc, file_record.id desc
        limit 1
      ) source_file on true
      where job.created_by = actor
        and job.target_domain in ('units', 'units_export')
        and app_private.can_access_import_export_job(job.target_domain)
        and (p_domains is null or cardinality(p_domains) = 0
          or app_private.import_export_job_domain(job.target_domain) = any(p_domains))
        and (p_states is null or cardinality(p_states) = 0
          or job.processing_state::text = any(p_states))
        and (p_formats is null or cardinality(p_formats) = 0
          or job.source_format = any(p_formats))
        and (p_created_from is null or job.created_at >= p_created_from)
        and (p_created_to is null or job.created_at <= p_created_to)
        and (escaped_search is null
          or job.target_domain ilike '%' || escaped_search || '%' escape chr(92)
          or job.source_format ilike '%' || escaped_search || '%' escape chr(92)
          or source_file.file_name ilike '%' || escaped_search || '%' escape chr(92))
    ), windowed as materialized (
      select * from authorized
      where p_before_created_at is null or (created_at, id) < (
        p_before_created_at,
        coalesce(p_before_job_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)
      )
      order by created_at desc, id desc
      limit p_page_size + 1
    ), visible as materialized (
      select * from windowed order by created_at desc, id desc limit p_page_size
    ), last_visible as (
      select created_at, id from visible order by created_at asc, id asc limit 1
    )
    select jsonb_build_object(
      'items', coalesce(jsonb_agg(jsonb_build_object(
        'job_id', visible.id,
        'domain', app_private.import_export_job_domain(visible.target_domain),
        'direction', app_private.import_export_job_direction(visible.target_domain),
        'format', visible.source_format,
        'file_name', visible.file_name,
        'state', visible.processing_state,
        'progress', case visible.processing_state
          when 'PENDENTE' then coalesce((visible.summary ->> 'progress')::integer, 0)
          when 'PROCESSANDO' then coalesce((visible.summary ->> 'progress')::integer, 50)
          else 100
        end,
        'created_at', visible.created_at,
        'started_at', visible.started_at,
        'finished_at', visible.finished_at,
        'summary', jsonb_strip_nulls(jsonb_build_object(
          'phase', visible.summary ->> 'phase',
          'valid_count', visible.summary -> 'valid_count',
          'rejected_count', visible.summary -> 'rejected_count',
          'row_count', visible.summary -> 'row_count'
        )),
        'result', jsonb_strip_nulls(jsonb_build_object(
          'created_count', visible.created_count,
          'updated_count', visible.updated_count,
          'linked_count', visible.linked_count,
          'ignored_count', visible.ignored_count,
          'rejected_count', visible.rejected_count
        ))
      ) order by visible.created_at desc, visible.id desc), '[]'::jsonb),
      'total_count', (select count(*) from authorized),
      'has_more', (select count(*) from windowed) > p_page_size,
      'next_cursor', case when (select count(*) from windowed) > p_page_size
        then (select jsonb_build_object('created_at', created_at, 'job_id', id)
          from last_visible)
        else null
      end
    ) from visible
  );
end;
$$;


ALTER FUNCTION "app_private"."superadmin_list_import_export_jobs"("p_domains" "text"[], "p_states" "text"[], "p_formats" "text"[], "p_search" "text", "p_created_from" timestamp with time zone, "p_created_to" timestamp with time zone, "p_before_created_at" timestamp with time zone, "p_before_job_id" "uuid", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_materialize_unit_export_from_edge"("p_export_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  job public.import_jobs%rowtype;
  actor_auth_user_id uuid;
  filters jsonb;
  view_data jsonb;
  page jsonb;
  item jsonb;
  page_items jsonb;
  page_offset integer := 0;
  item_ordinal bigint;
  sort_input text;
  sort_name text;
  uuid_regex constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  select *
  into job
  from public.import_jobs
  where id = p_export_job_id
  for update;

  if job.id is null or job.target_domain <> 'units_export' then
    raise no_data_found using message = 'unit export not found';
  end if;

  select auth_link.auth_user_id
  into actor_auth_user_id
  from public.person_auth_links auth_link
  where auth_link.person_id = job.created_by
    and auth_link.status = 'active'
    and auth_link.revoked_at is null
  order by auth_link.linked_at desc
  limit 1;

  if actor_auth_user_id is null then
    raise insufficient_privilege using message = 'unit export actor is not active';
  end if;

  perform pg_catalog.set_config(
    'request.jwt.claims',
    jsonb_build_object(
      'sub', actor_auth_user_id::text,
      'role', 'authenticated',
      'aal', 'aal2'
    )::text,
    true
  );

  filters := coalesce(job.summary -> 'filters', '{}'::jsonb);
  view_data := coalesce(job.summary -> 'current_view', '{}'::jsonb);
  sort_input := coalesce(nullif(btrim(view_data ->> 'sort'), ''), 'name');
  sort_name := case sort_input
    when 'institution_type' then 'institution_type_name'
    when 'unit_type' then 'unit_type_name'
    when 'status' then 'unit_status'
    when 'plan' then 'plan_name'
    when 'groups' then 'groups_count'
    when 'activities' then 'activities_count'
    else sort_input
  end;
  if sort_name not in (
    'name',
    'institution_name',
    'institution_type_name',
    'unit_type_name',
    'unit_status',
    'plan_name',
    'groups_count',
    'activities_count',
    'updated_at'
  ) then
    sort_name := 'name';
  end if;

  if exists (
    select 1
    from app_private.unit_export_snapshot_rows
    where export_job_id = job.id
  ) then
    return app_private.unit_file_job_payload(job.id);
  end if;

  loop
    page := app_private.list_units_for_superadmin(
      filters ->> 'search',
      coalesce(array(
        select value::uuid
        from jsonb_array_elements_text(coalesce(filters -> 'institution_ids', '[]'::jsonb)) value
        where value ~* uuid_regex
      ), array[]::uuid[]),
      coalesce(array(
        select value::uuid
        from jsonb_array_elements_text(coalesce(filters -> 'institution_type_ids', '[]'::jsonb)) value
        where value ~* uuid_regex
      ), array[]::uuid[]),
      coalesce(array(
        select value::uuid
        from jsonb_array_elements_text(coalesce(filters -> 'unit_type_ids', '[]'::jsonb)) value
        where value ~* uuid_regex
      ), array[]::uuid[]),
      coalesce(array(
        select nullif(btrim(value), '')
        from jsonb_array_elements_text(
          coalesce(filters -> 'unit_statuses', coalesce(filters -> 'statuses', '[]'::jsonb))
        ) value
        where nullif(btrim(value), '') is not null
      ), array[]::text[]),
      coalesce(array(
        select nullif(btrim(value), '')
        from jsonb_array_elements_text(coalesce(filters -> 'plan_ids', '[]'::jsonb)) value
        where nullif(btrim(value), '') is not null
      ), array[]::text[]),
      coalesce(array(
        select nullif(btrim(value), '')
        from jsonb_array_elements_text(coalesce(filters -> 'states', '[]'::jsonb)) value
        where nullif(btrim(value), '') is not null
      ), array[]::text[]),
      coalesce(array(
        select nullif(btrim(value), '')
        from jsonb_array_elements_text(coalesce(filters -> 'cities', '[]'::jsonb)) value
        where nullif(btrim(value), '') is not null
      ), array[]::text[]),
      coalesce(array(
        select nullif(btrim(value), '')
        from jsonb_array_elements_text(coalesce(filters -> 'districts', '[]'::jsonb)) value
        where nullif(btrim(value), '') is not null
      ), array[]::text[]),
      sort_name,
      coalesce((view_data ->> 'sort_ascending')::boolean, true),
      page_offset,
      100
    );

    page_items := coalesce(page -> 'items', '[]'::jsonb);
    exit when jsonb_array_length(page_items) = 0;

    for item, item_ordinal in
      select value, ordinality
      from jsonb_array_elements(page_items) with ordinality
    loop
      insert into app_private.unit_export_snapshot_rows(
        export_job_id,
        ordinal,
        unit_id,
        row_payload
      ) values (
        job.id,
        page_offset + item_ordinal,
        (item ->> 'id')::uuid,
        item
      );
    end loop;

    page_offset := page_offset + jsonb_array_length(page_items);
    if page_offset > 50000 then
      raise program_limit_exceeded using message = 'unit export exceeds maximum row count';
    end if;
    exit when coalesce((page ->> 'has_more')::boolean, false) is false;
  end loop;

  update public.import_jobs
  set summary = summary || jsonb_build_object(
        'phase', 'snapshot_ready',
        'snapshot_row_count', page_offset
      ),
      updated_at = now()
  where id = job.id;

  return app_private.unit_file_job_payload(job.id);
end;
$_$;


ALTER FUNCTION "app_private"."superadmin_materialize_unit_export_from_edge"("p_export_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_person_payload"("target_person_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', person.id,
    'first_name', person.first_name,
    'last_name', person.last_name,
    'display_name', person.display_name,
    'legal_name', person.legal_name,
    'type', person.person_type,
    'status', person.status,
    'auth_link', case
      when exists (
        select 1
        from public.person_auth_links auth_link
        where auth_link.person_id = person.id
          and auth_link.status = 'active'
          and auth_link.revoked_at is null
      ) then 'linked'
      when exists (
        select 1
        from public.person_auth_links auth_link
        where auth_link.person_id = person.id
          and auth_link.revoked_at is null
      ) then 'pending'
      else 'unlinked'
    end,
    'memberships', coalesce((
      select jsonb_agg(membership_payload order by membership_payload ->> 'institution_name')
      from (
        select jsonb_build_object(
          'id', assignment.id,
          'assignment_id', assignment.id,
          'membership_id', membership.id,
          'institution_id', membership.institution_id,
          'institution_name', institution.public_name,
          'unit_id', assignment.scope_unit_id,
          'unit_name', unit.name,
          'group_id', assignment.scope_group_id,
          'group_name', group_row.name,
          'role', role.code,
          'role_name', role.name,
          'is_platform', false
        ) as membership_payload
        from public.institution_memberships membership
        join public.institution_role_assignments assignment
          on assignment.membership_id = membership.id
          and assignment.status = 'active'
        join public.institution_roles role
          on role.id = assignment.role_id
        join public.institutions institution
          on institution.id = membership.institution_id
        left join public.units unit
          on unit.id = assignment.scope_unit_id
        left join public.groups group_row
          on group_row.id = assignment.scope_group_id
        where membership.person_id = person.id
          and membership.status = 'active'
          and membership.revoked_at is null
        union all
        select jsonb_build_object(
          'id', child_context.id,
          'institution_id', child_context.institution_id,
          'institution_name', institution.public_name,
          'unit_id', unit_link.unit_id,
          'unit_name', unit.name,
          'group_id', group_link.group_id,
          'group_name', group_row.name,
          'role', 'student',
          'is_platform', false
        )
        from public.child_contexts child_context
        join public.institutions institution
          on institution.id = child_context.institution_id
        left join public.child_unit_links unit_link
          on unit_link.child_context_id = child_context.id
          and unit_link.status in ('pending', 'awaiting_allocation', 'active')
          and unit_link.revoked_at is null
        left join public.units unit on unit.id = unit_link.unit_id
        left join public.child_group_links group_link
          on group_link.child_unit_link_id = unit_link.id
          and group_link.status = 'active'
        left join public.groups group_row on group_row.id = group_link.group_id
        where child_context.child_person_id = person.id
          and child_context.status = 'active'
      ) membership_rows
    ), '[]'::jsonb),
    'child_contexts', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', child_context.id,
          'institution_id', child_context.institution_id,
          'institution_name', institution.public_name,
          'status', child_context.status,
          'child_unit_link_id', (
            select unit_link.id
            from public.child_unit_links unit_link
            where unit_link.child_context_id = child_context.id
              and unit_link.status in (
                'pending', 'awaiting_allocation', 'active'
              )
              and unit_link.revoked_at is null
            order by unit_link.created_at, unit_link.id
            limit 1
          ),
          'child_group_link_id', (
            select group_link.id
            from public.child_unit_links unit_link
            join public.child_group_links group_link
              on group_link.child_unit_link_id = unit_link.id
              and group_link.status = 'active'
            where unit_link.child_context_id = child_context.id
              and unit_link.status in (
                'pending', 'awaiting_allocation', 'active'
              )
              and unit_link.revoked_at is null
            order by group_link.created_at, group_link.id
            limit 1
          ),
          'unit_id', (
            select unit_link.unit_id
            from public.child_unit_links unit_link
            where unit_link.child_context_id = child_context.id
              and unit_link.status in (
                'pending', 'awaiting_allocation', 'active'
              )
              and unit_link.revoked_at is null
            order by unit_link.created_at, unit_link.id
            limit 1
          ),
          'group_id', (
            select group_link.group_id
            from public.child_unit_links unit_link
            join public.child_group_links group_link
              on group_link.child_unit_link_id = unit_link.id
              and group_link.status = 'active'
            where unit_link.child_context_id = child_context.id
              and unit_link.status in (
                'pending', 'awaiting_allocation', 'active'
              )
              and unit_link.revoked_at is null
            order by group_link.created_at, group_link.id
            limit 1
          ),
          'unit_links', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'id', unit_link.id,
                'unit_id', unit_link.unit_id,
                'unit_name', unit.name,
                'status', unit_link.status,
                'group_links', coalesce((
                  select jsonb_agg(
                    jsonb_build_object(
                      'id', group_link.id,
                      'group_id', group_link.group_id,
                      'group_name', group_row.name,
                      'status', group_link.status
                    )
                    order by lower(group_row.name), group_link.id
                  )
                  from public.child_group_links group_link
                  join public.groups group_row
                    on group_row.id = group_link.group_id
                  where group_link.child_unit_link_id = unit_link.id
                    and group_link.status = 'active'
                ), '[]'::jsonb)
              )
              order by lower(unit.name), unit_link.id
            )
            from public.child_unit_links unit_link
            join public.units unit on unit.id = unit_link.unit_id
            where unit_link.child_context_id = child_context.id
              and unit_link.status in (
                'pending', 'awaiting_allocation', 'active'
              )
              and unit_link.revoked_at is null
          ), '[]'::jsonb)
        )
        order by lower(institution.public_name), child_context.id
      )
      from public.child_contexts child_context
      join public.institutions institution
        on institution.id = child_context.institution_id
      where child_context.child_person_id = person.id
        and child_context.status = 'active'
    ), '[]'::jsonb),
    'platform_membership_summary', (
      select string_agg(role.name, ', ' order by role.name)
      from public.platform_memberships membership
      join public.platform_roles role on role.id = membership.role_id
      where membership.person_id = person.id
        and membership.status in ('invited', 'active', 'suspended')
        and membership.revoked_at is null
    ),
    'guardian_links_summary', concat_ws(
      ' · ',
      case when (
        select count(*)
        from public.guardian_links guardian_link
        where guardian_link.guardian_person_id = person.id
          and guardian_link.status = 'active'
          and guardian_link.revoked_at is null
      ) > 0 then (
        select count(*)::text || ' criança(s)'
        from public.guardian_links guardian_link
        where guardian_link.guardian_person_id = person.id
          and guardian_link.status = 'active'
          and guardian_link.revoked_at is null
      ) end,
      case when (
        select count(*)
        from public.guardian_links guardian_link
        where guardian_link.child_person_id = person.id
          and guardian_link.status = 'active'
          and guardian_link.revoked_at is null
      ) > 0 then (
        select count(*)::text || ' responsável(is)'
        from public.guardian_links guardian_link
        where guardian_link.child_person_id = person.id
          and guardian_link.status = 'active'
          and guardian_link.revoked_at is null
      ) end
    ),
    'updated_at', person.updated_at
  )
  from public.people person
  where person.id = target_person_id
    and person.deleted_at is null
$$;


ALTER FUNCTION "app_private"."superadmin_person_payload"("target_person_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_prepare_activity_identity_upload"("p_activity_id" "uuid", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id(); extension text; request_hash bytea;
 receipt app_private.activity_management_command_receipts%rowtype; result jsonb; path text;
begin
 if (select auth.uid()) is null or actor is null
    or not app_private.has_platform_permission('activities.manage') then
  raise insufficient_privilege using message='activities.manage required';
 end if;
 if not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='MFA AAL2 required';
 end if;
 if not exists(select 1 from public.activity_definitions activity where activity.id=p_activity_id)
    or p_idempotency_key is null or nullif(btrim(p_file_name),'') is null
    or length(p_file_name)>180 or p_size_bytes not between 1 and 2097152
    or p_mime_type not in ('image/jpeg','image/png','image/webp') then
  raise invalid_parameter_value using message='invalid identity upload';
 end if;
 extension:=case p_mime_type when 'image/jpeg' then 'jpg'
  when 'image/png' then 'png' else 'webp' end;
 path:='activities/'||p_activity_id::text||'/'||p_idempotency_key::text||'.'||extension;
 request_hash:=extensions.digest(convert_to(jsonb_build_object(
  'activity_id',p_activity_id,'file_name',p_file_name,'mime_type',p_mime_type,
  'size_bytes',p_size_bytes)::text,'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into receipt from app_private.activity_management_command_receipts
  where request_id=p_idempotency_key;
 if receipt.request_id is not null then
  if receipt.actor_person_id<>actor then
   raise insufficient_privilege using message='idempotency receipt actor mismatch';
  end if;
  if receipt.command_kind<>'identity_prepare' or receipt.request_hash<>request_hash then
   raise invalid_parameter_value using message='idempotency key reused';
  end if;
  return receipt.result_json;
 end if;
 insert into app_private.activity_identity_upload_intents(
  request_id,activity_id,actor_person_id,storage_path,mime_type,size_bytes,expires_at
 ) values(p_idempotency_key,p_activity_id,actor,path,p_mime_type,p_size_bytes,
   now()+interval '10 minutes');
 result:=jsonb_build_object('bucket','coelo-identities','path',path,
  'mime_type',p_mime_type,'size_limit',2097152,'expires_at',now()+interval '10 minutes');
 insert into app_private.activity_management_command_receipts(
  request_id,command_kind,request_hash,actor_person_id,activity_id,result_json
 ) values(p_idempotency_key,'identity_prepare',request_hash,actor,p_activity_id,result);
 return result;
end $$;


ALTER FUNCTION "app_private"."superadmin_prepare_activity_identity_upload"("p_activity_id" "uuid", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_prepare_institution_identity_upload"("p_institution_id" "uuid", "p_kind" "text", "p_mime_type" "text", "p_size_bytes" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  media_id uuid := gen_random_uuid();
  extension text;
  storage_path text;
begin
  actor:=app_private.assert_institution_identity_access(p_institution_id);
  if p_kind not in('profile','cover')
     or p_mime_type not in('image/jpeg','image/png')
     or p_size_bytes not between 1 and 2097152 then
    raise invalid_parameter_value using message='invalid institution identity media';
  end if;
  extension:=case p_mime_type when 'image/png' then 'png' else 'jpg' end;
  storage_path:='institutions/'||p_institution_id||'/'||p_kind||'/'||media_id||'.'||extension;
  insert into public.institution_identity_media(
    id,institution_id,kind,storage_path,mime_type,size_bytes,created_by
  ) values(media_id,p_institution_id,p_kind,storage_path,p_mime_type,p_size_bytes,actor);
  insert into audit.audit_logs(
    actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,after_json
  ) values(
    actor,'aal2','institution.identity.prepare','institution_identity_media',
    media_id,'success',jsonb_build_object('institution_id',p_institution_id,'kind',p_kind)
  );
  return jsonb_build_object(
    'media_id',media_id,'bucket','coelo-institution-identities','storage_path',storage_path
  );
end
$$;


ALTER FUNCTION "app_private"."superadmin_prepare_institution_identity_upload"("p_institution_id" "uuid", "p_kind" "text", "p_mime_type" "text", "p_size_bytes" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_prepare_unit_identity_upload"("unit_id" "uuid", "kind" "text", "mime" "text", "bytes" bigint, "request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();institution uuid;media uuid;path text;ext text;
 prior app_private.unit_identity_upload_intents%rowtype;expiry timestamptz:=now()+interval'15 minutes';begin
 if(select auth.uid())is null or actor is null or request_id is null then raise insufficient_privilege using message='authentication required';end if;
 select u.institution_id into institution from public.units u where u.id=unit_id;
 if institution is null then raise no_data_found using message='unit not found';end if;
 if not app_private.has_scoped_platform_permission('units.update',institution)or not app_private.has_mfa_aal2()
 then raise insufficient_privilege using message='units.update and AAL2 required';end if;
 if kind not in('profile','cover','featured')or mime not in('image/jpeg','image/png')or bytes not between 1 and 5242880
 then raise invalid_parameter_value using message='invalid unit identity upload';end if;
 perform pg_advisory_xact_lock(hashtextextended(request_id::text,0));
 select*into prior from app_private.unit_identity_upload_intents i where i.request_id=superadmin_prepare_unit_identity_upload.request_id;
 if prior.request_id is not null then
  if prior.actor_person_id<>actor or prior.unit_id<>unit_id or prior.media_kind::text<>kind or prior.mime_type<>mime or prior.size_bytes<>bytes
  then raise invalid_parameter_value using message='idempotency key reused';end if;
  return jsonb_build_object('media_id',prior.media_id,'bucket','coelo-unit-identities','upload_path',prior.storage_path,'expires_at',prior.expires_at);end if;
 media:=gen_random_uuid();ext:=case mime when'image/jpeg'then'jpg'else'png'end;
 path:='institutions/'||institution||'/units/'||unit_id||'/'||kind||'/'||media||'.'||ext;
 insert into public.unit_identity_media(id,institution_id,unit_id,media_kind,storage_path,mime_type,size_bytes,created_by_person_id)
 values(media,institution,unit_id,kind::public.unit_identity_media_kind,path,mime,bytes,actor);
 insert into app_private.unit_identity_upload_intents values(request_id,media,institution,unit_id,kind::public.unit_identity_media_kind,actor,path,mime,bytes,expiry,null,now());
 insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,after_json)
 values(actor,auth.jwt()->>'aal','unit.identity.upload.prepare','unit_identity_media',media,institution,'success',
 jsonb_build_object('unit_id',unit_id,'kind',kind,'bucket','coelo-unit-identities','path',path,'mime_type',mime,'size_bytes',bytes));
 return jsonb_build_object('media_id',media,'bucket','coelo-unit-identities','upload_path',path,'expires_at',expiry);end$$;


ALTER FUNCTION "app_private"."superadmin_prepare_unit_identity_upload"("unit_id" "uuid", "kind" "text", "mime" "text", "bytes" bigint, "request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_preview_institution_import"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_file" "jsonb", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
 actor uuid; job public.import_jobs%rowtype; source_row jsonb; row_number integer;
 payload jsonb; error_code text; valid_count integer:=0; rejected_count integer:=0;
 expected_path text;
begin
 actor:=app_private.assert_institution_file_access('institutions.import');
 if p_request_id is null or jsonb_typeof(p_rows)<>'array'
    or jsonb_array_length(p_rows) not between 1 and 5000
    or jsonb_typeof(p_file)<>'object' then
  raise invalid_parameter_value using message='invalid institution import preview';
 end if;
 select * into job from public.import_jobs where id=p_import_job_id for update;
 if job.id is null or job.target_domain<>'institutions' or job.created_by<>actor then
  raise insufficient_privilege using message='institution import outside actor scope';
 end if;
 expected_path:='imports/institutions/'||job.id||'/source.'||job.source_format;
 if p_file->>'storage_path'<>expected_path
    or p_file->>'mime_type'<>(case job.source_format when 'csv' then 'text/csv'
       else 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' end)
    or coalesce((p_file->>'size_bytes')::bigint,0) not between 1 and 5242880
    or coalesce(p_file->>'checksum_sha256','')!~'^[0-9a-f]{64}$' then
  raise invalid_parameter_value using message='invalid institution import artifact';
 end if;
 delete from public.import_errors where import_job_id=job.id;
 delete from public.import_rows where import_job_id=job.id;
 for source_row in select value from jsonb_array_elements(p_rows) loop
  row_number:=coalesce((source_row->>'row_number')::integer,0);
  payload:=jsonb_strip_nulls(jsonb_build_object(
   'public_name',nullif(btrim(source_row->>'public_name'),''),
   'slug',app_private.normalize_institution_handle(source_row->>'slug'),
   'institution_type_name',nullif(btrim(source_row->>'institution_type_name'),''),
   'legal_name',nullif(btrim(source_row->>'legal_name'),''),
   'document_type',coalesce(nullif(btrim(source_row->>'document_type'),''),'CNPJ'),
   'document_ref',nullif(btrim(source_row->>'document_ref'),''),
   'status',coalesce(nullif(btrim(source_row->>'status'),''),'draft'),
   'timezone',coalesce(nullif(btrim(source_row->>'timezone'),''),'America/Sao_Paulo'),
   'locale',coalesce(nullif(btrim(source_row->>'locale'),''),'pt-BR'),
   'contact',jsonb_build_object('email',nullif(btrim(source_row->>'contact_email'),''))
  ));
  error_code:=null;
  if row_number<2
     or coalesce(payload->>'public_name','')=''
     or coalesce(payload->>'institution_type_name','')=''
     or coalesce(payload->>'slug','')!~'^[a-z0-9][a-z0-9._-]{2,29}$' then
   error_code:='invalid_required_fields';
  elsif exists(
    select 1 from public.institutions i
    where i.slug=payload->>'slug' and i.deleted_at is null
  ) or exists(
    select 1 from public.import_rows r
    where r.import_job_id=job.id and r.payload_json->>'slug'=payload->>'slug'
  ) then
   error_code:='handle_unavailable';
  end if;
  insert into public.import_rows(import_job_id,row_number,payload_json,status,error_code)
  values(
    job.id,row_number,payload,
    case when error_code is null then 'active'::public.record_status else 'archived'::public.record_status end,
    error_code
  );
  if error_code is null then
   valid_count:=valid_count+1;
  else
   rejected_count:=rejected_count+1;
   insert into public.import_errors(import_job_id,row_number,error_code,message)
   values(job.id,row_number,error_code,
    case error_code when 'handle_unavailable' then '@ indisponÃ­vel.'
    else 'Nome, @ e tipo da instituiÃ§Ã£o sÃ£o obrigatÃ³rios e devem ser vÃ¡lidos.' end);
  end if;
 end loop;
 insert into public.import_files(import_job_id,storage_path,file_name,mime_type,size_bytes)
 values(job.id,expected_path,left(p_file->>'file_name',180),p_file->>'mime_type',(p_file->>'size_bytes')::bigint)
 on conflict do nothing;
 update public.import_jobs set
  summary=summary||jsonb_build_object(
    'phase','preview','valid_count',valid_count,'rejected_count',rejected_count,
    'preview_request_id',p_request_id
  ),updated_at=now()
 where id=job.id;
 return app_private.institution_file_job_payload(job.id);
end
$_$;


ALTER FUNCTION "app_private"."superadmin_preview_institution_import"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_file" "jsonb", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_preview_unit_import"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_rows" "jsonb", "p_mapping" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor uuid; job public.import_jobs%rowtype; source_row jsonb; row_number int:=0;
 v_valid_count int:=0; v_rejected_count int:=0; institution uuid; type_id uuid; error_code text;
 storage_path text; expected_path text; file_data jsonb;
begin
 actor:=app_private.assert_unit_file_access('units.import',null);
 if p_request_id is null or p_import_job_id is null or jsonb_typeof(p_rows)<>'array'
    or jsonb_array_length(p_rows)>5000 or jsonb_typeof(p_mapping)<>'object' then
  raise invalid_parameter_value using message='invalid unit import preview';
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_import_job_id::text,0));
 select * into job from public.import_jobs where id=p_import_job_id for update;
 if job.id is null then raise no_data_found using message='unit import not found'; end if;
 if job.target_domain<>'units' or job.created_by<>actor then
  raise insufficient_privilege using message='unit import outside actor scope';
 end if;
 file_data:=p_mapping->'file'; storage_path:=file_data->>'storage_path';
 expected_path:='imports/units/'||job.id||'/source.'||job.source_format;
 if storage_path is distinct from expected_path
    or not exists(select 1 from storage.objects object_record
      where object_record.bucket_id='coelo-operations' and object_record.name=expected_path) then
  raise check_violation using message='unit import object not found';
 end if;
 delete from public.import_errors where import_job_id=job.id;
 delete from public.import_rows where import_job_id=job.id;
 delete from public.import_mappings where import_job_id=job.id;
 for source_row in select value from jsonb_array_elements(p_rows) loop
  row_number:=row_number+1; error_code:=null;
  begin institution:=nullif(source_row->>'institution_id','')::uuid;
  exception when others then error_code:='invalid_institution_id'; end;
  begin type_id:=nullif(source_row->>'unit_type_id','')::uuid;
  exception when others then error_code:=coalesce(error_code,'invalid_unit_type_id'); end;
  if error_code is null and not app_private.has_scoped_platform_permission('units.import',institution) then error_code:='institution_scope_denied'; end if;
  if error_code is null and not exists(select 1 from public.institutions i where i.id=institution and i.deleted_at is null) then error_code:='institution_not_found'; end if;
  if error_code is null and not exists(select 1 from public.unit_types t where t.id=type_id and t.status='active') then error_code:='unit_type_not_found'; end if;
  if error_code is null and (length(btrim(coalesce(source_row->>'name',''))) not between 1 and 160
    or (source_row->>'slug') !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$') then error_code:='invalid_identity'; end if;
  if error_code is null and coalesce(nullif(source_row->>'status',''),'active') not in('draft','active','inactive','suspended','archived') then error_code:='invalid_unit_status'; end if;
  if error_code is null and exists(select 1 from public.units u where u.institution_id=institution and u.slug=source_row->>'slug') then error_code:='slug_unavailable'; end if;
  if error_code is null and exists(select 1 from public.unit_types t where t.id=type_id and lower(t.code)='other')
     and nullif(btrim(source_row->>'unit_type_other_text'),'') is null then error_code:='other_description_required'; end if;
  source_row:=source_row||jsonb_build_object('request_id',coalesce(source_row->>'request_id',gen_random_uuid()::text));
  insert into public.import_rows(import_job_id,row_number,payload_json,status,error_code)
  values(job.id,row_number,source_row,case when error_code is null then'draft'::public.record_status else'archived'::public.record_status end,error_code);
  if error_code is null then v_valid_count:=v_valid_count+1; else
   v_rejected_count:=v_rejected_count+1;
   insert into public.import_errors(import_job_id,row_number,error_code,message)
   values(job.id,row_number,error_code,'Linha rejeitada pela validacao de Unidades.');
  end if;
 end loop;
 insert into public.import_files(import_job_id,storage_path,file_name,mime_type,size_bytes)
 values(job.id,expected_path,'source.'||job.source_format,file_data->>'mime_type',nullif(file_data->>'size_bytes','')::bigint)
 on conflict do nothing;
 update public.import_jobs set summary=summary||jsonb_build_object('phase','preview','mapping',coalesce(p_mapping->'columns','{}'::jsonb),
  'valid_count',v_valid_count,'rejected_count',v_rejected_count,'preview_request_id',p_request_id),updated_at=now() where id=job.id;
 insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,after_json)
 values(actor,'aal2','unit.import.preview','import_job',job.id,'success',jsonb_build_object('valid',v_valid_count,'rejected',v_rejected_count));
 return app_private.unit_file_job_payload(job.id);
end $_$;


ALTER FUNCTION "app_private"."superadmin_preview_unit_import"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_rows" "jsonb", "p_mapping" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_preview_unit_import_from_edge"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_rows" "jsonb", "p_mapping_columns" "jsonb", "p_checksum_sha256" "text", "p_size_bytes" bigint, "p_mime_type" "text", "p_parser_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  job public.import_jobs%rowtype;
  attestation app_private.unit_import_source_attestations%rowtype;
  actor_auth_user_id uuid;
  object_metadata jsonb;
  expected_path text;
  expected_mime text;
begin
  if p_request_id is null
    or p_import_job_id is null
    or jsonb_typeof(p_rows) <> 'array'
    or jsonb_array_length(p_rows) not between 1 and 5000
    or jsonb_typeof(p_mapping_columns) <> 'object'
    or p_checksum_sha256 !~ '^[0-9a-f]{64}$'
    or p_size_bytes not between 1 and 5242880
    or p_mime_type not in (
      'text/csv',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    )
    or nullif(btrim(p_parser_version), '') is null
  then
    raise invalid_parameter_value using message = 'invalid edge import attestation';
  end if;

  select *
  into job
  from public.import_jobs
  where id = p_import_job_id
  for update;

  if job.id is null or job.target_domain <> 'units' then
    raise no_data_found using message = 'unit import not found';
  end if;

  expected_path := 'imports/units/' || job.id || '/source.' || job.source_format;
  expected_mime := case job.source_format
    when 'csv' then 'text/csv'
    when 'xlsx' then 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    else null
  end;
  if p_mime_type is distinct from expected_mime then
    raise invalid_parameter_value using message = 'edge import MIME mismatch';
  end if;

  select object_record.metadata
  into object_metadata
  from storage.objects object_record
  where object_record.bucket_id = 'coelo-operations'
    and object_record.name = expected_path;

  if not found
    or coalesce((object_metadata ->> 'size')::bigint, -1) <> p_size_bytes
    or coalesce(object_metadata ->> 'mimetype', '') <> p_mime_type
  then
    raise check_violation using message = 'attested import object mismatch';
  end if;

  select *
  into attestation
  from app_private.unit_import_source_attestations
  where import_job_id = job.id
  for update;

  if attestation.import_job_id is null then
    insert into app_private.unit_import_source_attestations (
      import_job_id,
      storage_path,
      mime_type,
      size_bytes,
      checksum_sha256,
      parser_version
    ) values (
      job.id,
      expected_path,
      p_mime_type,
      p_size_bytes,
      p_checksum_sha256,
      btrim(p_parser_version)
    );
  elsif attestation.storage_path <> expected_path
    or attestation.mime_type <> p_mime_type
    or attestation.size_bytes <> p_size_bytes
    or attestation.checksum_sha256 <> p_checksum_sha256
    or attestation.parser_version <> btrim(p_parser_version)
  then
    raise invalid_parameter_value using message = 'unit import source replay mismatch';
  end if;

  select auth_link.auth_user_id
  into actor_auth_user_id
  from public.person_auth_links auth_link
  where auth_link.person_id = job.created_by
    and auth_link.status = 'active'
    and auth_link.revoked_at is null
  order by auth_link.linked_at desc
  limit 1;

  if actor_auth_user_id is null then
    raise insufficient_privilege using message = 'unit import actor is not active';
  end if;

  perform pg_catalog.set_config(
    'request.jwt.claims',
    jsonb_build_object(
      'sub', actor_auth_user_id::text,
      'role', 'authenticated',
      'aal', 'aal2'
    )::text,
    true
  );

  return app_private.superadmin_preview_unit_import(
    p_request_id,
    p_import_job_id,
    p_rows,
    jsonb_build_object(
      'columns', p_mapping_columns,
      'file', jsonb_build_object(
        'storage_path', expected_path,
        'mime_type', p_mime_type,
        'size_bytes', p_size_bytes
      )
    )
  );
end;
$_$;


ALTER FUNCTION "app_private"."superadmin_preview_unit_import_from_edge"("p_request_id" "uuid", "p_import_job_id" "uuid", "p_rows" "jsonb", "p_mapping_columns" "jsonb", "p_checksum_sha256" "text", "p_size_bytes" bigint, "p_mime_type" "text", "p_parser_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_activity_export"("p_format" "text", "p_filters" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id(); request_hash bytea;
 job public.import_jobs%rowtype;
begin
 if (select auth.uid()) is null or actor is null
    or not app_private.has_platform_permission('activities.export') then
  raise insufficient_privilege using message='activities.export required';
 end if;
 if not app_private.has_mfa_aal2() then
  raise insufficient_privilege using message='MFA AAL2 required';
 end if;
 if p_format not in ('csv','xlsx') or p_idempotency_key is null
    or jsonb_typeof(coalesce(p_filters,'{}'::jsonb))<>'object'
    or coalesce(p_filters,'{}'::jsonb)-array[
      'search','institution_ids','unit_ids','group_ids','statuses','origins'
    ]<>'{}'::jsonb then
  raise invalid_parameter_value using message='invalid export request';
 end if;
 request_hash:=extensions.digest(convert_to(jsonb_build_object(
  'format',p_format,'filters',coalesce(p_filters,'{}'))::text,'UTF8'),'sha256');
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into job from public.import_jobs job_record
  where job_record.request_id=p_idempotency_key;
 if job.id is not null then
  if job.created_by<>actor then
   raise insufficient_privilege using message='idempotency job actor mismatch';
  end if;
  if job.request_hash<>request_hash or job.target_domain<>'activities'
     or job.summary->>'operation'<>'export' then
   raise invalid_parameter_value using message='idempotency key reused';
  end if;
  return jsonb_build_object('job_id',job.id,'state',job.processing_state,'summary',job.summary);
 end if;
 insert into public.import_jobs(
  request_id,request_hash,target_domain,target_table,source_format,source_locale,
  target_locale,status,processing_state,summary,created_by
 ) values(p_idempotency_key,request_hash,'activities','activity_definitions',
  p_format,'pt-BR','pt-BR','draft','PENDENTE',
  jsonb_build_object('operation','export','filters',coalesce(p_filters,'{}'),
   'template_version','activities-v1','progress',0),actor)
 returning * into job;
 insert into public.import_results(import_job_id) values(job.id);
 insert into app_private.import_processing_queue(import_job_id) values(job.id);
 insert into audit.audit_logs(
  actor_person_id,mfa_aal,action_code,object_type,object_id,outcome,after_json
 ) values(actor,auth.jwt()->>'aal','activity.export.request','import_job',job.id,
  'success',jsonb_build_object('format',p_format,'state','PENDENTE'));
 return jsonb_build_object('job_id',job.id,'state',job.processing_state,'summary',job.summary);
end $$;


ALTER FUNCTION "app_private"."superadmin_request_activity_export"("p_format" "text", "p_filters" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_import_export"("p_domain" "text", "p_format" "text", "p_filters" "jsonb", "p_current_view" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.assert_import_export_hub_actor();
  if p_domain <> 'units' then
    raise invalid_parameter_value using message = 'export domain unavailable';
  end if;
  return app_private.superadmin_request_unit_export(
    p_format, p_filters, p_current_view, p_idempotency_key
  );
end;
$$;


ALTER FUNCTION "app_private"."superadmin_request_import_export"("p_domain" "text", "p_format" "text", "p_filters" "jsonb", "p_current_view" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_institution_export"("p_format" "text", "p_filters" "jsonb", "p_sort" "text", "p_sort_ascending" boolean, "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid; job public.import_jobs%rowtype; rows jsonb; request_hash bytea;
begin
 actor:=app_private.assert_institution_file_access('institutions.export');
 if p_format not in('csv','xlsx') or jsonb_typeof(p_filters)<>'object'
    or length(coalesce(p_filters->>'search',''))>200
    or p_sort not in('public_name','status','type_name','plan_name','city','state','updated_at') then
  raise invalid_parameter_value using message='invalid institution export contract';
 end if;
 select coalesce(jsonb_agg(to_jsonb(export_row)),'[]'::jsonb) into rows
 from (
  select d.id,d.public_name,d.legal_name,d.slug,d.type_name as institution_type_name,
   d.status,d.plan_name,d.contact_email,d.city,d.state,d.updated_at
  from public.institution_directory d
  where (coalesce(p_filters->>'search','')=''
    or d.search_name ilike '%'||replace(replace(replace(p_filters->>'search','\','\\'),'%','\%'),'_','\_')||'%' escape '\')
   and (jsonb_array_length(coalesce(p_filters->'statuses','[]'::jsonb))=0
    or d.status::text in(select jsonb_array_elements_text(p_filters->'statuses')))
   and (jsonb_array_length(coalesce(p_filters->'type_ids','[]'::jsonb))=0
    or d.institution_type_id::text in(select jsonb_array_elements_text(p_filters->'type_ids')))
   and (coalesce(p_filters->>'plan_id','')='' or d.plan_id::text=p_filters->>'plan_id')
   and (jsonb_array_length(coalesce(p_filters->'states','[]'::jsonb))=0
    or d.state in(select jsonb_array_elements_text(p_filters->'states')))
   and (jsonb_array_length(coalesce(p_filters->'cities','[]'::jsonb))=0
    or d.city in(select jsonb_array_elements_text(p_filters->'cities')))
   and (jsonb_array_length(coalesce(p_filters->'districts','[]'::jsonb))=0
    or d.district in(select jsonb_array_elements_text(p_filters->'districts')))
  order by
   case when p_sort='public_name' and p_sort_ascending then d.public_name end asc,
   case when p_sort='public_name' and not p_sort_ascending then d.public_name end desc,
   case when p_sort='status' and p_sort_ascending then d.status::text end asc,
   case when p_sort='status' and not p_sort_ascending then d.status::text end desc,
   case when p_sort='city' and p_sort_ascending then d.city end asc,
   case when p_sort='city' and not p_sort_ascending then d.city end desc,
   d.id asc
  limit 5001
 ) export_row;
 if jsonb_array_length(rows)=0 then return jsonb_build_object('empty',true); end if;
 if jsonb_array_length(rows)>5000 then
  raise program_limit_exceeded using message='institution export exceeds 5000 rows';
 end if;
 request_hash:=extensions.digest(pg_catalog.convert_to(jsonb_build_object(
  'format',p_format,'filters',p_filters,'sort',p_sort,'ascending',p_sort_ascending
 )::text,'UTF8'),'sha256');
 insert into public.import_jobs(
  request_id,request_hash,target_domain,target_table,source_format,source_locale,target_locale,
  status,processing_state,summary,created_by
 ) values(
  p_idempotency_key,request_hash,'institutions_export','institutions',p_format,'pt-BR','pt-BR',
  'draft','PROCESSANDO',jsonb_build_object('phase','generating','pii_included',true),actor
 ) returning * into job;
 insert into public.import_results(import_job_id) values(job.id);
 return jsonb_build_object('empty',false,'job_id',job.id,'format',p_format,'rows',rows);
end
$$;


ALTER FUNCTION "app_private"."superadmin_request_institution_export"("p_format" "text", "p_filters" "jsonb", "p_sort" "text", "p_sort_ascending" boolean, "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_institution_identity_delete"("p_institution_id" "uuid", "p_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare media public.institution_identity_media%rowtype;
begin
  perform app_private.assert_institution_identity_access(p_institution_id);
  if p_kind not in('profile','cover') then
    raise invalid_parameter_value using message='invalid identity kind';
  end if;
  select m.* into media
  from public.institution_identity_media m
  where m.institution_id=p_institution_id and m.kind=p_kind and m.state='active'
  for update;
  if media.id is null then
    return jsonb_build_object('bucket','coelo-institution-identities','storage_path',null);
  end if;
  update public.institution_branding
  set logo_media_asset_id=case when p_kind='profile' then null else logo_media_asset_id end,
      cover_media_asset_id=case when p_kind='cover' then null else cover_media_asset_id end,
      updated_at=now()
  where institution_id=p_institution_id;
  update public.institution_identity_media
  set state='archived',archived_at=now() where id=media.id;
  return jsonb_build_object('bucket',media.bucket_id,'storage_path',media.storage_path);
end
$$;


ALTER FUNCTION "app_private"."superadmin_request_institution_identity_delete"("p_institution_id" "uuid", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_unit_export"("p_format" "text", "p_filters" "jsonb", "p_current_view" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job public.import_jobs%rowtype;
  request_hash bytea;
begin
  actor := app_private.assert_unit_file_access('units.export', null);
  if p_idempotency_key is null
    or p_format not in ('csv', 'xlsx')
    or jsonb_typeof(p_filters) <> 'object'
    or jsonb_typeof(p_current_view) <> 'object'
    or p_filters - array[
      'search',
      'institution_ids',
      'institution_type_ids',
      'unit_type_ids',
      'statuses',
      'unit_statuses',
      'plan_ids',
      'states',
      'cities',
      'districts'
    ] <> '{}'::jsonb
    or p_current_view - array[
      'sort',
      'sort_ascending',
      'group_by_institution',
      'columns'
    ] <> '{}'::jsonb
  then
    raise invalid_parameter_value using message = 'invalid unit export contract';
  end if;

  if length(coalesce(p_filters->>'search', '')) > 200
    or coalesce(p_current_view->>'sort', 'name') not in (
      'name',
      'institution_name',
      'institution_type',
      'unit_type',
      'status',
      'plan',
      'groups',
      'activities'
    )
  then
    raise invalid_parameter_value using message = 'invalid unit export filters';
  end if;

  request_hash := extensions.digest(
    pg_catalog.convert_to(
      jsonb_build_object(
        'format', p_format,
        'filters', p_filters,
        'view', p_current_view
      )::text,
      'UTF8'
    ),
    'sha256'
  );
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text, 0));

  select *
  into job
  from public.import_jobs
  where request_id = p_idempotency_key;

  if job.id is not null then
    if job.created_by <> actor
      or job.request_hash <> request_hash
      or job.target_domain <> 'units_export'
    then
      raise invalid_parameter_value using message = 'idempotency key replay mismatch';
    end if;
    return app_private.unit_file_job_payload(job.id);
  end if;

  insert into public.import_jobs(
    request_id,
    request_hash,
    target_domain,
    target_table,
    source_format,
    source_locale,
    target_locale,
    status,
    processing_state,
    summary,
    created_by
  )
  values(
    p_idempotency_key,
    request_hash,
    'units_export',
    'units',
    p_format,
    'pt-BR',
    'pt-BR',
    'draft',
    'PENDENTE',
    jsonb_build_object(
      'phase', 'queued',
      'filters', p_filters,
      'current_view', p_current_view,
      'pii_included', false
    ),
    actor
  )
  returning * into job;

  insert into public.import_results(import_job_id) values(job.id);
  insert into audit.audit_logs(
    actor_person_id,
    mfa_aal,
    action_code,
    object_type,
    object_id,
    outcome,
    after_json
  )
  values(
    actor,
    'aal2',
    'unit.export.request',
    'import_job',
    job.id,
    'success',
    jsonb_build_object('format', p_format, 'pii_included', false)
  );

  return app_private.unit_file_job_payload(job.id);
end
$$;


ALTER FUNCTION "app_private"."superadmin_request_unit_export"("p_format" "text", "p_filters" "jsonb", "p_current_view" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_request_unit_identity_delete"("media_id" "uuid", "request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$declare actor uuid:=app_private.current_person_id();
 media public.unit_identity_media%rowtype;prior app_private.unit_identity_delete_requests%rowtype;begin
 if(select auth.uid())is null or actor is null or request_id is null then raise insufficient_privilege using message='authentication required';end if;
 perform pg_advisory_xact_lock(hashtextextended(request_id::text,0));select*into prior from app_private.unit_identity_delete_requests r
 where r.request_id=superadmin_request_unit_identity_delete.request_id;
 if prior.request_id is not null then if prior.actor_person_id<>actor or prior.media_id<>media_id then raise invalid_parameter_value using message='idempotency key reused';end if;
  return jsonb_build_object('media_id',prior.media_id,'bucket','coelo-unit-identities','delete_path',prior.storage_path);end if;
 select*into media from public.unit_identity_media m where m.id=media_id for update;
 if media.id is null then raise no_data_found using message='unit identity media not found';end if;
 if not app_private.has_scoped_platform_permission('units.update',media.institution_id)or not app_private.has_mfa_aal2()
 then raise insufficient_privilege using message='units.update and AAL2 required';end if;
 if media.status not in('active','pending_delete')then raise invalid_parameter_value using message='unit identity media cannot be deleted';end if;
 update public.unit_identity_media set status='pending_delete',pending_delete_at=coalesce(pending_delete_at,now())where id=media.id;
 if media.media_kind='profile'then update public.unit_branding set logo_media_asset_id=null,updated_by=actor,updated_at=now()
  where unit_id=media.unit_id and logo_media_asset_id=media.id;
 elsif media.media_kind='cover'then update public.unit_branding set cover_media_asset_id=null,updated_by=actor,updated_at=now()
  where unit_id=media.unit_id and cover_media_asset_id=media.id;end if;
 insert into app_private.unit_identity_delete_requests values(request_id,media.id,actor,media.storage_path,null,now());
 insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,before_json,after_json)
 values(actor,auth.jwt()->>'aal','unit.identity.delete.request','unit_identity_media',media.id,media.institution_id,'success',to_jsonb(media),jsonb_build_object('status','pending_delete'));
 return jsonb_build_object('media_id',media.id,'bucket','coelo-unit-identities','delete_path',media.storage_path);end$$;


ALTER FUNCTION "app_private"."superadmin_request_unit_identity_delete"("media_id" "uuid", "request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_retry_import_export_job"("p_import_job_id" "uuid", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job public.import_jobs%rowtype;
begin
  if p_request_id is null or p_import_job_id is null then
    raise invalid_parameter_value using message = 'request_id and import job are required';
  end if;

  actor := app_private.assert_unit_file_access('units.import', null);
  select * into job
  from public.import_jobs
  where id = p_import_job_id and created_by = actor;
  if job.id is null or job.target_domain <> 'units' then
    raise insufficient_privilege using message = 'import retry unavailable';
  end if;
  return app_private.superadmin_retry_unit_import(p_request_id, p_import_job_id);
end;
$$;


ALTER FUNCTION "app_private"."superadmin_retry_import_export_job"("p_import_job_id" "uuid", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_retry_unit_import"("p_request_id" "uuid", "p_import_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job public.import_jobs%rowtype;
  prior_job_id uuid;
begin
  if p_request_id is null or p_import_job_id is null then
    raise invalid_parameter_value using message = 'request_id and import job are required';
  end if;

  actor := app_private.assert_unit_file_access('units.import', null);
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('unit-import-retry:' || p_request_id::text, 0)
  );

  select candidate.id into prior_job_id
  from public.import_jobs candidate
  where candidate.target_domain = 'units'
    and candidate.summary ->> 'retry_request_id' = p_request_id::text
  limit 1;

  if prior_job_id is not null then
    if prior_job_id <> p_import_job_id then
      raise invalid_parameter_value using message = 'retry request_id already used';
    end if;
    select * into job
    from public.import_jobs
    where id = prior_job_id and created_by = actor;
    if job.id is null then
      raise insufficient_privilege using message = 'unit import outside actor scope';
    end if;
    return app_private.unit_file_job_payload(job.id);
  end if;

  select * into job
  from public.import_jobs
  where id = p_import_job_id
  for update;
  if job.id is null then
    raise no_data_found using message = 'unit import not found';
  end if;
  if job.created_by <> actor or job.target_domain <> 'units' then
    raise insufficient_privilege using message = 'unit import outside actor scope';
  end if;
  if job.processing_state not in ('ERRO', 'REJEICAO') then
    raise object_not_in_prerequisite_state using message = 'unit import is not retryable';
  end if;

  update public.import_jobs
  set processing_state = 'PENDENTE',
      status = 'draft',
      finished_at = null,
      summary = coalesce(summary, '{}'::jsonb) || jsonb_build_object(
        'phase', 'preview',
        'retry_request_id', p_request_id
      ),
      updated_at = now()
  where id = job.id;

  return app_private.unit_file_job_payload(job.id);
end;
$$;


ALTER FUNCTION "app_private"."superadmin_retry_unit_import"("p_request_id" "uuid", "p_import_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_unit_export_page"("p_import_job_id" "uuid", "p_cursor_text" "text", "p_cursor_id" "uuid", "p_page_size" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor uuid;
  job public.import_jobs%rowtype;
  filters jsonb;
  view_data jsonb;
  result jsonb;
  cursor_offset bigint := 0;
  page_limit integer;
  sort_input text;
  sort_name text;
  uuid_regex constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  perform p_cursor_id; -- Compatibility parameter retained by the public RPC contract.
  actor := app_private.assert_unit_file_access('units.export', null);

  select *
  into job
  from public.import_jobs
  where id = p_import_job_id;

  if job.id is null then
    raise no_data_found using message = 'unit export not found';
  end if;
  if job.created_by <> actor or job.target_domain <> 'units_export' then
    raise insufficient_privilege using message = 'unit export outside actor scope';
  end if;
  if p_page_size not between 1 and 500 then
    raise invalid_parameter_value using message = 'invalid export page size';
  end if;

  if p_cursor_text is null or btrim(p_cursor_text) = '' then
    cursor_offset := 0;
  elsif btrim(p_cursor_text) !~ '^[0-9]+$' then
    raise invalid_parameter_value using message = 'invalid export cursor';
  else
    cursor_offset := btrim(p_cursor_text)::bigint;
  end if;
  if cursor_offset < 0 or cursor_offset > 2147483647 then
    raise invalid_parameter_value using message = 'invalid export cursor';
  end if;

  page_limit := least(p_page_size, 100);
  filters := coalesce(job.summary->'filters', '{}'::jsonb);
  view_data := coalesce(job.summary->'current_view', '{}'::jsonb);
  sort_input := coalesce(nullif(btrim(view_data->>'sort'), ''), 'name');
  sort_name := case sort_input
    when 'institution_type' then 'institution_type_name'
    when 'unit_type' then 'unit_type_name'
    when 'status' then 'unit_status'
    when 'plan' then 'plan_name'
    when 'groups' then 'groups_count'
    when 'activities' then 'activities_count'
    else sort_input
  end;
  if sort_name not in (
    'name',
    'institution_name',
    'institution_type_name',
    'unit_type_name',
    'unit_status',
    'plan_name',
    'groups_count',
    'activities_count',
    'updated_at'
  ) then
    sort_name := 'name';
  end if;

  result := app_private.list_units_for_superadmin(
    filters->>'search',
    coalesce(array(
      select value::uuid
      from jsonb_array_elements_text(coalesce(filters->'institution_ids', '[]'::jsonb)) value
      where value ~* uuid_regex
    ), array[]::uuid[]),
    coalesce(array(
      select value::uuid
      from jsonb_array_elements_text(coalesce(filters->'institution_type_ids', '[]'::jsonb)) value
      where value ~* uuid_regex
    ), array[]::uuid[]),
    coalesce(array(
      select value::uuid
      from jsonb_array_elements_text(coalesce(filters->'unit_type_ids', '[]'::jsonb)) value
      where value ~* uuid_regex
    ), array[]::uuid[]),
    coalesce(array(
      select nullif(btrim(value), '')
      from jsonb_array_elements_text(
        coalesce(filters->'unit_statuses', coalesce(filters->'statuses', '[]'::jsonb))
      ) value
      where nullif(btrim(value), '') is not null
    ), array[]::text[]),
    coalesce(array(
      select nullif(btrim(value), '')
      from jsonb_array_elements_text(coalesce(filters->'plan_ids', '[]'::jsonb)) value
      where nullif(btrim(value), '') is not null
    ), array[]::text[]),
    coalesce(array(
      select nullif(btrim(value), '')
      from jsonb_array_elements_text(coalesce(filters->'states', '[]'::jsonb)) value
      where nullif(btrim(value), '') is not null
    ), array[]::text[]),
    coalesce(array(
      select nullif(btrim(value), '')
      from jsonb_array_elements_text(coalesce(filters->'cities', '[]'::jsonb)) value
      where nullif(btrim(value), '') is not null
    ), array[]::text[]),
    coalesce(array(
      select nullif(btrim(value), '')
      from jsonb_array_elements_text(coalesce(filters->'districts', '[]'::jsonb)) value
      where nullif(btrim(value), '') is not null
    ), array[]::text[]),
    sort_name,
    coalesce((view_data->>'sort_ascending')::boolean, true),
    cursor_offset::integer,
    page_limit
  );

  if coalesce((result->>'has_more')::boolean, false)
    and jsonb_array_length(coalesce(result->'items', '[]'::jsonb)) > 0
  then
    result := result || jsonb_build_object(
      'next_cursor',
      jsonb_build_object(
        'text',
        (cursor_offset + jsonb_array_length(result->'items'))::text,
        'id',
        null
      )
    );
  end if;
  return result;
end
$_$;


ALTER FUNCTION "app_private"."superadmin_unit_export_page"("p_import_job_id" "uuid", "p_cursor_text" "text", "p_cursor_id" "uuid", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."superadmin_unit_export_page_v2"("p_export_job_id" "uuid", "p_after_ordinal" bigint, "p_page_size" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job public.import_jobs%rowtype;
  items jsonb;
  last_ordinal bigint;
  total_count bigint;
  has_more boolean;
begin
  actor := app_private.assert_unit_file_access('units.export', null);

  if p_page_size not between 1 and 500 or coalesce(p_after_ordinal, 0) < 0 then
    raise invalid_parameter_value using message = 'invalid export keyset cursor';
  end if;

  select *
  into job
  from public.import_jobs
  where id = p_export_job_id;

  if job.id is null
    or job.target_domain <> 'units_export'
    or job.created_by <> actor
  then
    raise insufficient_privilege using message = 'unit export outside actor scope';
  end if;

  with page as (
    select ordinal, row_payload
    from app_private.unit_export_snapshot_rows
    where export_job_id = p_export_job_id
      and ordinal > coalesce(p_after_ordinal, 0)
    order by ordinal
    limit p_page_size
  )
  select coalesce(jsonb_agg(row_payload order by ordinal), '[]'::jsonb), max(ordinal)
  into items, last_ordinal
  from page;

  select count(*)
  into total_count
  from app_private.unit_export_snapshot_rows
  where export_job_id = p_export_job_id;

  has_more := last_ordinal is not null and exists (
    select 1
    from app_private.unit_export_snapshot_rows
    where export_job_id = p_export_job_id
      and ordinal > last_ordinal
  );

  return jsonb_build_object(
    'items', items,
    'total_count', total_count,
    'has_more', has_more,
    'next_cursor', case
      when has_more then jsonb_build_object('ordinal', last_ordinal)
      else null
    end
  );
end;
$$;


ALTER FUNCTION "app_private"."superadmin_unit_export_page_v2"("p_export_job_id" "uuid", "p_after_ordinal" bigint, "p_page_size" integer) OWNER TO "postgres";


