    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.updated_at := pg_catalog.now();
  return new;
end;
$$;


ALTER FUNCTION "app_private"."touch_institution_legal_representative_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."touch_people_context_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_person_id uuid;
  target_membership_id uuid;
  target_child_context_id uuid;
  target_child_unit_link_id uuid;
begin
  if tg_table_name = 'institution_memberships' then
    target_person_id := case
      when tg_op = 'DELETE' then old.person_id
      else new.person_id
    end;
  elsif tg_table_name = 'institution_role_assignments' then
    target_membership_id := case
      when tg_op = 'DELETE' then old.membership_id
      else new.membership_id
    end;
    select membership.person_id
    into target_person_id
    from public.institution_memberships membership
    where membership.id = target_membership_id;
  elsif tg_table_name = 'child_contexts' then
    target_person_id := case
      when tg_op = 'DELETE' then old.child_person_id
      else new.child_person_id
    end;
  elsif tg_table_name = 'child_unit_links' then
    target_child_context_id := case
      when tg_op = 'DELETE' then old.child_context_id
      else new.child_context_id
    end;
    select child_context.child_person_id
    into target_person_id
    from public.child_contexts child_context
    where child_context.id = target_child_context_id;
  elsif tg_table_name = 'child_group_links' then
    target_child_unit_link_id := case
      when tg_op = 'DELETE' then old.child_unit_link_id
      else new.child_unit_link_id
    end;
    select child_context.child_person_id
    into target_person_id
    from public.child_unit_links unit_link
    join public.child_contexts child_context
      on child_context.id = unit_link.child_context_id
    where unit_link.id = target_child_unit_link_id;
  end if;

  if target_person_id is not null then
    update public.people person
    set updated_at = greatest(
      clock_timestamp(),
      person.updated_at + interval '1 microsecond'
    )
    where person.id = target_person_id;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$$;


ALTER FUNCTION "app_private"."touch_people_context_owner"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."transfer_unit_institution_for_superadmin"("p_request_id" "uuid", "p_unit_id" "uuid", "p_destination_institution_id" "uuid", "p_expected_version" bigint, "p_confirmed" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();u public.units%rowtype;impact jsonb;h bytea;prior app_private.unit_management_command_receipts%rowtype;begin
if p_request_id is null or not coalesce(p_confirmed,false)then raise invalid_parameter_value using message='explicit transfer confirmation required';end if;
if actor is null or not app_private.has_mfa_aal2()then raise insufficient_privilege using message='AAL2 required';end if;
h:=app_private.unit_management_hash(jsonb_build_object('unit_id',p_unit_id,'destination_institution_id',p_destination_institution_id,'expected_version',p_expected_version,'confirmed',true));
perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,0));
select*into prior from app_private.unit_management_command_receipts where request_id=p_request_id;
if prior.request_id is not null then
 if prior.request_hash<>h or prior.actor_person_id<>actor or prior.command_kind<>'transfer' or prior.unit_id<>p_unit_id then raise invalid_parameter_value using message='request replay mismatch';end if;
 if not exists(select 1 from public.units where id=p_unit_id and app_private.has_scoped_platform_permission('units.read',institution_id))then raise insufficient_privilege using message='unit read scope required';end if;
 return app_private.unit_form_payload(p_unit_id);
end if;
select*into u from public.units where id=p_unit_id for update;if u.id is null then raise no_data_found using message='unit not found';end if;
if u.management_version<>p_expected_version then raise serialization_failure using message='stale unit version';end if;
impact:=app_private.preview_unit_institution_transfer(p_unit_id,p_destination_institution_id);
if jsonb_array_length(impact->'incompatible_dependencies')>0 then raise check_violation using message='unit transfer blocked by incompatible dependencies';end if;
update public.units set institution_id=p_destination_institution_id,management_version=management_version+1,updated_at=now()where id=p_unit_id;
insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,after_json)
values(actor,'aal2','unit.institution.transfer','unit',p_unit_id,p_destination_institution_id,'success',impact);
insert into app_private.unit_management_command_receipts(request_id,request_hash,actor_person_id,command_kind,unit_id,result_management_version)
values(p_request_id,h,actor,'transfer',p_unit_id,p_expected_version+1);
return app_private.unit_form_payload(p_unit_id);end$$;


ALTER FUNCTION "app_private"."transfer_unit_institution_for_superadmin"("p_request_id" "uuid", "p_unit_id" "uuid", "p_destination_institution_id" "uuid", "p_expected_version" bigint, "p_confirmed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."unit_directory_filter_options"("p_states" "text"[], "p_cities" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$begin
if(select auth.uid())is null or app_private.current_person_id()is null then raise insufficient_privilege using message='authentication required';end if;
return app_private.unit_directory_filter_options_payload(p_states,p_cities);end$$;


ALTER FUNCTION "app_private"."unit_directory_filter_options"("p_states" "text"[], "p_cities" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."unit_directory_filter_options_payload"("p_states" "text"[], "p_cities" "text"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
with au as(select d.* from public.unit_directory d where app_private.has_scoped_platform_permission('units.read',d.institution_id))
select jsonb_build_object(
'institutions',coalesce((select jsonb_agg(distinct jsonb_build_object('id',institution_id,'label',institution_name))from au),'[]'::jsonb),
'institution_types',coalesce((select jsonb_agg(distinct jsonb_build_object('id',institution_type_id,'label',institution_type_name))from au where institution_type_id is not null),'[]'::jsonb),
'unit_types',coalesce((select jsonb_agg(jsonb_build_object('id',id,'label',name))from public.unit_types where status='active'),'[]'::jsonb),
'plans',coalesce((select jsonb_agg(distinct jsonb_build_object('id',effective_plan_id::text,'label',effective_plan_name))from au where effective_plan_id is not null),'[]'::jsonb),
'states',coalesce((select jsonb_agg(distinct jsonb_build_object('id',address->>'state','label',address->>'state'))from au where address->>'state'is not null),'[]'::jsonb),
'cities',coalesce((select jsonb_agg(distinct jsonb_build_object('id',address->>'city','label',address->>'city'))from au where address->>'city'is not null and(app_private.unit_filter_is_empty(p_states)or address->>'state'=any(p_states))),'[]'::jsonb),
'districts',coalesce((select jsonb_agg(distinct jsonb_build_object('id',address->>'district','label',address->>'district'))from au where address->>'district'is not null and(app_private.unit_filter_is_empty(p_cities)or address->>'city'=any(p_cities))),'[]'::jsonb))$$;


ALTER FUNCTION "app_private"."unit_directory_filter_options_payload"("p_states" "text"[], "p_cities" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."unit_directory_row_payload"("d" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
select jsonb_build_object('id',d->>'id','institution_id',d->>'institution_id','institution_name',d->>'institution_name','name',d->>'name','slug',d->>'slug','unit_status',d->>'unit_status',
'institution_type',jsonb_build_object('id',d->>'institution_type_id','label',d->>'institution_type_name'),
'unit_type',jsonb_build_object('id',d->>'unit_type_id','label',d->>'unit_type_name','code',d->>'unit_type_code','other_description',d->>'unit_type_other_description'),
'address',d->'address','contact',d->'contact','branding',d->'branding',
'effective_plan',jsonb_build_object('id',d->>'effective_plan_id','code',d->>'effective_plan_code','label',d->>'effective_plan_name','override_id',d->>'plan_override_id','inherited',d->'inherit_plan'),
'inheritance',jsonb_build_object('address',d->'inherit_address','contact',d->'inherit_contact','branding',d->'inherit_branding','representatives',d->'inherit_representatives','administrators',d->'inherit_administrators','plan',d->'inherit_plan'),
'public_profile',jsonb_build_object('handle',d->>'handle','discovery_enabled',d->'public_discovery_enabled','address_visible',d->'public_address_visible','contact_visible',d->'public_contact_visible'),
'timezone',d->>'timezone','subtypes',d->'subtypes','groups_count',d->'groups_count','activities_count',d->'activities_count','management_version',d->'management_version')$$;


