CREATE OR REPLACE FUNCTION "app_private"."update_institution_for_superadmin"("p_request_id" "uuid", "p_institution_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_variable
declare
  actor_person_id uuid;
  institution_record public.institutions%rowtype;
  institution_type_id uuid;
  current_plan_id uuid;
  current_plan_code text;
  current_subscription_status text;
  current_starts_at timestamptz;
  current_trial_ends_at timestamptz;
  current_manual_reason text;
  current_paused_at timestamptz;
  current_cancelled_at timestamptz;
  requested_plan_id uuid;
  requested_plan_code text;
  requested_status public.institution_status;
  request_hash bytea;
  result jsonb;
  prior_hash bytea;
  request_record jsonb;
  prior_actor uuid;
  prior_command text;
  prior_institution_id uuid;
  prior_result_management_version bigint;
  changed_fields jsonb;
  effective_payload jsonb;
  subscription_changed boolean := false;
begin
  if p_request_id is null or p_institution_id is null
     or p_expected_version is null or p_expected_version < 1 then
    raise invalid_parameter_value using
      message = 'request_id, institution_id and positive expected_version are required';
  end if;
  if (select auth.uid()) is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;
  actor_person_id := app_private.current_person_id();
  if actor_person_id is null then
    raise insufficient_privilege using message = 'active person identity required';
  end if;
  if not app_private.has_scoped_platform_permission('institution.update', p_institution_id) then
    raise insufficient_privilege using message = 'institution.update required';
  end if;
  if not app_private.has_mfa_aal2() then
    raise insufficient_privilege using message = 'MFA AAL2 required';
  end if;

  effective_payload := p_payload;
  request_record := jsonb_build_object(
    'institution_id', p_institution_id,
    'expected_version', p_expected_version,
    'payload', p_payload
  );
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));
  request_hash := app_private.institution_management_request_hash(request_record);
  select receipt.request_hash, receipt.actor_person_id,
         receipt.command_kind, receipt.institution_id,
         receipt.result_management_version
    into prior_hash, prior_actor, prior_command, prior_institution_id,
         prior_result_management_version
  from app_private.institution_management_command_receipts receipt
  where receipt.request_id = p_request_id;
  if prior_institution_id is not null then
    if prior_actor is distinct from actor_person_id
       or prior_command is distinct from 'update'
       or prior_hash is distinct from request_hash then
      raise invalid_parameter_value using
        message = 'request_id already used with a different command payload';
    end if;
    result := app_private.institution_management_payload(prior_institution_id);
    if result is null then
      raise no_data_found using message = 'institution receipt target not found';
    end if;
    if (result ->> 'management_version')::bigint
       is distinct from prior_result_management_version then
      raise serialization_failure using
        message = 'receipt result version is no longer current';
    end if;
    return result;
  end if;

  perform app_private.assert_institution_management_payload(p_payload, false);
  select institution_row.* into institution_record
  from public.institutions institution_row
  where institution_row.id = p_institution_id
    and institution_row.deleted_at is null
  for update;
  if institution_record.id is null then
    raise no_data_found using message = 'institution not found';
  end if;
  if institution_record.management_version is distinct from p_expected_version then
    raise serialization_failure using message = 'stale institution version';
  end if;

  requested_status := institution_record.status;
  if p_payload ? 'status' then
    requested_status := (p_payload ->> 'status')::public.institution_status;
    if requested_status is distinct from institution_record.status
       and not app_private.has_scoped_platform_permission('institution.status.change', p_institution_id) then
      raise insufficient_privilege using message = 'institution.status.change required';
    end if;
  end if;

  institution_type_id := institution_record.institution_type_id;
  if p_payload ? 'institution_type_name' then
    select type_record.id into institution_type_id
    from public.institution_types type_record
    where lower(type_record.name) = lower(btrim(p_payload ->> 'institution_type_name'))
      and type_record.status = 'active'
    limit 1;
    if institution_type_id is null then
      raise invalid_parameter_value using message = 'unknown or inactive institution type';
    end if;
  end if;

  select subscription_record.plan_id, plan_record.code,
         subscription_record.status::text, subscription_record.starts_at,
         subscription_record.trial_ends_at, subscription_record.manual_reason,
         subscription_record.paused_at, subscription_record.cancelled_at
    into current_plan_id, current_plan_code, current_subscription_status,
         current_starts_at, current_trial_ends_at, current_manual_reason,
         current_paused_at, current_cancelled_at
  from public.institution_subscriptions subscription_record
  left join public.plans plan_record on plan_record.id = subscription_record.plan_id
  where subscription_record.institution_id = p_institution_id
  order by subscription_record.created_at desc, subscription_record.id desc
  limit 1;
  requested_plan_id := current_plan_id;
  requested_plan_code := current_plan_code;
  if p_payload ? 'subscription' then
    requested_plan_code := lower(btrim(p_payload -> 'subscription' ->> 'plan_code'));
    select plan_record.id into requested_plan_id
    from public.plans plan_record
    where plan_record.code = requested_plan_code and plan_record.status = 'active'
    limit 1;
    if requested_plan_id is null then
      raise invalid_parameter_value using message = 'unknown or inactive plan';
    end if;
    subscription_changed := current_plan_id is null
      or requested_plan_id is distinct from current_plan_id
      or coalesce(p_payload -> 'subscription' ->> 'status', 'draft')
           is distinct from current_subscription_status
      or nullif(p_payload -> 'subscription' ->> 'starts_at', '')::timestamptz
           is distinct from current_starts_at
      or nullif(p_payload -> 'subscription' ->> 'trial_ends_at', '')::timestamptz
           is distinct from current_trial_ends_at
      or nullif(btrim(p_payload -> 'subscription' ->> 'manual_reason'), '')
           is distinct from current_manual_reason
      or nullif(p_payload -> 'subscription' ->> 'paused_at', '')::timestamptz
           is distinct from current_paused_at
      or nullif(p_payload -> 'subscription' ->> 'cancelled_at', '')::timestamptz
           is distinct from current_cancelled_at;
    if subscription_changed
       and not app_private.has_scoped_platform_permission('plan.change', p_institution_id) then
      raise insufficient_privilege using message = 'plan.change required';
    end if;
    if not subscription_changed then
      effective_payload := p_payload - 'subscription';
    end if;
  end if;

  update public.institutions institution_row set
    public_name = case when p_payload ? 'public_name'
      then btrim(p_payload ->> 'public_name') else institution_row.public_name end,
    trade_name = case when p_payload ? 'trade_name'
      then nullif(btrim(p_payload ->> 'trade_name'), '') else institution_row.trade_name end,
    legal_name = case when p_payload ? 'legal_name'
      then nullif(btrim(p_payload ->> 'legal_name'), '') else institution_row.legal_name end,
    slug = case when p_payload ? 'slug'
      then lower(btrim(p_payload ->> 'slug')) else institution_row.slug end,
    primary_domain = case when p_payload ? 'primary_domain'
      then nullif(lower(btrim(p_payload ->> 'primary_domain')), '')
      else institution_row.primary_domain end,
    document_ref = case when p_payload ? 'document_ref'
      then nullif(btrim(p_payload ->> 'document_ref'), '')
      else institution_row.document_ref end,
    document_type = case when p_payload ? 'document_type'
      then btrim(p_payload ->> 'document_type') else institution_row.document_type end,
    status = requested_status,
    timezone = case when p_payload ? 'timezone'
      then btrim(p_payload ->> 'timezone') else institution_row.timezone end,
    locale = case when p_payload ? 'locale'
      then btrim(p_payload ->> 'locale') else institution_row.locale end,
    institution_type_id = institution_type_id,
    management_version = institution_row.management_version + 1,
    updated_at = greatest(
      clock_timestamp(), institution_row.updated_at + interval '1 microsecond'
    )
  where institution_row.id = p_institution_id;

  perform app_private.apply_institution_management_children(
    p_institution_id, actor_person_id, effective_payload, requested_plan_id
  );
  select coalesce(jsonb_agg(key_name order by key_name), '[]'::jsonb)
    into changed_fields from jsonb_object_keys(p_payload) key_name;
  result := app_private.institution_management_payload(p_institution_id);

  insert into audit.audit_logs(
    actor_person_id, mfa_aal, action_code, object_type, object_id,
    institution_id, outcome, before_json, after_json
  ) values (
    actor_person_id, 'aal2', 'institution.update', 'institution', p_institution_id,
    p_institution_id, 'success',
    jsonb_build_object(
      'status', institution_record.status::text,
      'plan_id', current_plan_id, 'plan_code', current_plan_code,
      'changed_fields', changed_fields
    ),
    jsonb_build_object(
      'status', result ->> 'status',
      'plan_id', result -> 'subscription' -> 'plan_id',
      'plan_code', result -> 'subscription' -> 'plan_code',
      'changed_fields', changed_fields
    )
  );
  insert into app_private.institution_management_command_receipts(
    request_id, actor_person_id, command_kind, institution_id,
    request_hash, result_management_version
  ) values (
    p_request_id, actor_person_id, 'update', p_institution_id,
    request_hash, (result ->> 'management_version')::bigint
  );
  return result;
exception
  when invalid_text_representation or datetime_field_overflow
    or check_violation or not_null_violation or foreign_key_violation
    or unique_violation then
    raise invalid_parameter_value using message = 'invalid institution payload';
end;
$$;


ALTER FUNCTION "app_private"."update_institution_for_superadmin"("p_request_id" "uuid", "p_institution_id" "uuid", "p_expected_version" bigint, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."update_superadmin_person"("p_person_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_identity_patch" "jsonb" DEFAULT '{}'::"jsonb", "p_context_changes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_variable
declare
  current_person public.people;
  updated_person public.people;
  change jsonb;
  membership public.institution_memberships;
  assignment public.institution_role_assignments;
  child_context public.child_contexts;
  institution_id uuid;
  unit_id uuid;
  group_id uuid;
  role_id uuid;
  role_scope_kind text;
  child_unit_link_id uuid;
  child_group_link_id uuid;
  child_unit_link_count integer;
  child_group_link_count integer;
  changed_fields text[];
  actor_person_id uuid;
  actor_platform_membership_id uuid;
begin
  perform app_private.assert_people_permission('people.update');

  if jsonb_typeof(coalesce(p_identity_patch, '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_context_changes, '[]'::jsonb)) <> 'array' then
    raise invalid_parameter_value using message = 'invalid patch shape';
  end if;
  if exists (
    select 1
    from jsonb_object_keys(coalesce(p_identity_patch, '{}'::jsonb)) key
    where key not in ('first_name', 'last_name', 'display_name', 'legal_name')
  ) then
    raise invalid_parameter_value using message = 'identity field is not editable';
  end if;

  select *
  into current_person
  from public.people person
  where person.id = p_person_id
    and person.deleted_at is null
  for update;
  if not found then
    raise no_data_found using message = 'person not found';
  end if;
  if current_person.person_type = 'service' then
    raise invalid_parameter_value using message = 'service people are read-only';
  end if;
  if current_person.updated_at <> p_expected_updated_at then
    raise serialization_failure using message = 'person was updated concurrently';
  end if;

  select coalesce(array_agg(key order by key), array[]::text[])
  into changed_fields
  from jsonb_object_keys(coalesce(p_identity_patch, '{}'::jsonb)) key;

  if jsonb_array_length(coalesce(p_context_changes, '[]'::jsonb)) > 0 then
    if current_person.person_type = 'adult' then
      perform app_private.assert_people_permission('people.memberships.manage');
    else
      perform app_private.assert_people_permission('people.child_contexts.manage');
    end if;
  end if;

  actor_person_id := app_private.current_person_id();
  actor_platform_membership_id :=
    app_private.platform_permission_membership_id('people.update');

  update public.people person
  set
    first_name = case
      when p_identity_patch ? 'first_name'
        then coalesce(nullif(btrim(p_identity_patch ->> 'first_name'), ''), person.first_name)
      else person.first_name
    end,
    last_name = case
      when p_identity_patch ? 'last_name'
        then coalesce(nullif(btrim(p_identity_patch ->> 'last_name'), ''), person.last_name)
      else person.last_name
    end,
    display_name = case
      when p_identity_patch ? 'display_name'
        then coalesce(nullif(btrim(p_identity_patch ->> 'display_name'), ''), person.display_name)
      else person.display_name
    end,
    legal_name = case
      when p_identity_patch ? 'legal_name'
        then nullif(btrim(p_identity_patch ->> 'legal_name'), '')
      else person.legal_name
    end,
    updated_at = greatest(
      clock_timestamp(),
      person.updated_at + interval '1 microsecond'
    )
  where person.id = p_person_id
  returning * into updated_person;

  for change in
    select value
    from jsonb_array_elements(coalesce(p_context_changes, '[]'::jsonb))
  loop
    if current_person.person_type = 'adult'
       and change ->> 'kind' = 'institution_membership' then
      if change ->> 'operation' = 'add' then
        institution_id := nullif(change ->> 'institution_id', '')::uuid;
        unit_id := nullif(change ->> 'scope_unit_id', '')::uuid;
        group_id := nullif(change ->> 'scope_group_id', '')::uuid;
        if institution_id is null
           or nullif(btrim(change ->> 'role_code'), '') is null then
          raise invalid_parameter_value using message = 'membership context is incomplete';
        end if;
        if unit_id is not null and not exists (
          select 1 from public.units unit
          where unit.id = unit_id and unit.institution_id = institution_id
        ) then
          raise check_violation using message = 'unit belongs to another institution';
        end if;
        if group_id is not null and not exists (
          select 1 from public.groups group_row
          where group_row.id = group_id
            and group_row.institution_id = institution_id
            and (unit_id is null or group_row.unit_id = unit_id)
        ) then
          raise check_violation using message = 'group belongs to another context';
        end if;
        select role.id
        into role_id
        from public.institution_roles role
        where role.institution_id = institution_id
          and role.code = btrim(change ->> 'role_code')
          and role.status = 'active'
        limit 1;
        if role_id is null then
          raise foreign_key_violation using
            message = 'contextual role does not belong to institution';
        end if;
        role_scope_kind := case
          when group_id is not null then 'group'
          when unit_id is not null then 'unit'
          else 'institution'
        end;
        if nullif(change ->> 'membership_id', '') is not null then
          select *
          into membership
          from public.institution_memberships target
          where target.id = (change ->> 'membership_id')::uuid
            and target.person_id = p_person_id
            and target.institution_id = institution_id
            and target.status = 'active'
            and target.revoked_at is null
          for update;
          if not found then
            raise no_data_found using
              message = 'membership not found for person and institution';
          end if;
        else
          select *
          into membership
          from public.institution_memberships target
          where target.person_id = p_person_id
            and target.institution_id = institution_id
            and target.status = 'active'
            and target.revoked_at is null
          for update;
          if not found then
            insert into public.institution_memberships(
              person_id,
              institution_id,
              role_code,
              status,
              scope_kind,
              scope_unit_id,
              scope_group_id
            ) values (
              p_person_id,
              institution_id,
              btrim(change ->> 'role_code'),
              'active',
              role_scope_kind,
              unit_id,
              group_id
            )
            returning * into membership;
          end if;
        end if;
        insert into public.institution_role_assignments(
          membership_id,
          role_id,
          scope_kind,
          scope_unit_id,
          scope_group_id
        )
        values (
          membership.id,
          role_id,
          role_scope_kind,
          unit_id,
          group_id
        )
        returning * into assignment;
      elsif change ->> 'operation' in ('update', 'revoke') then
        select *
        into membership
        from public.institution_memberships target
        where target.id = nullif(change ->> 'membership_id', '')::uuid
          and target.person_id = p_person_id
        for update;
        if not found then
          raise no_data_found using message = 'membership not found for person';
        end if;
        select *
        into assignment
        from public.institution_role_assignments target
        where target.id = nullif(change ->> 'assignment_id', '')::uuid
          and target.membership_id = membership.id
        for update;
        if not found then
          raise no_data_found using message = 'role assignment not found for membership';
        end if;
        if change ->> 'operation' = 'revoke' then
          update public.institution_role_assignments target
          set status = 'inactive', updated_at = clock_timestamp()
          where target.id = assignment.id;
          if not exists (
            select 1
            from public.institution_role_assignments remaining
            where remaining.membership_id = membership.id
              and remaining.status = 'active'
          ) then
            update public.institution_memberships target
            set status = 'inactive', revoked_at = clock_timestamp()
            where target.id = membership.id;
          end if;
        else
          institution_id := membership.institution_id;
          unit_id := case
            when change ? 'scope_unit_id'
              then nullif(change ->> 'scope_unit_id', '')::uuid
            else assignment.scope_unit_id
          end;
          group_id := case
            when change ? 'scope_group_id'
              then nullif(change ->> 'scope_group_id', '')::uuid
            else assignment.scope_group_id
          end;
          if unit_id is not null and not exists (
            select 1 from public.units unit
            where unit.id = unit_id and unit.institution_id = institution_id
          ) then
            raise check_violation using message = 'unit belongs to another institution';
          end if;
          if group_id is not null and not exists (
            select 1 from public.groups group_row
            where group_row.id = group_id
              and group_row.institution_id = institution_id
              and (unit_id is null or group_row.unit_id = unit_id)
          ) then
            raise check_violation using message = 'group belongs to another context';
          end if;
          select role.id
          into role_id
          from public.institution_roles role
          where role.institution_id = institution_id
            and role.code = coalesce(
              nullif(btrim(change ->> 'role_code'), ''),
              (
                select assigned_role.code
                from public.institution_roles assigned_role
                where assigned_role.id = assignment.role_id
              )
            )
            and role.status = 'active'
          limit 1;
          if role_id is null then
            raise foreign_key_violation using
              message = 'contextual role does not belong to institution';
          end if;
          role_scope_kind := case
            when group_id is not null then 'group'
            when unit_id is not null then 'unit'
            else 'institution'
          end;
          update public.institution_role_assignments target
          set
            role_id = role_id,
            scope_kind = role_scope_kind,
            scope_unit_id = unit_id,
            scope_group_id = group_id,
            updated_at = clock_timestamp()
          where target.id = assignment.id
          returning * into assignment;
        end if;
      else
        raise invalid_parameter_value using message = 'unsupported membership operation';
      end if;
    elsif current_person.person_type = 'child'
          and change ->> 'kind' = 'child_context' then
      if change ->> 'operation' = 'add' then
        institution_id := nullif(change ->> 'institution_id', '')::uuid;
        unit_id := nullif(change ->> 'unit_id', '')::uuid;
        group_id := nullif(change ->> 'group_id', '')::uuid;
        if institution_id is null then
          raise invalid_parameter_value using message = 'child context requires institution';
        end if;
        if unit_id is not null and not exists (
          select 1 from public.units unit
          where unit.id = unit_id and unit.institution_id = institution_id
        ) then
          raise check_violation using message = 'unit belongs to another institution';
        end if;
        if group_id is not null and (
          unit_id is null or not exists (
            select 1 from public.groups group_row
            where group_row.id = group_id
              and group_row.institution_id = institution_id
              and group_row.unit_id = unit_id
          )
        ) then
          raise check_violation using message = 'group belongs to another context';
        end if;
        select *
        into child_context
        from public.child_contexts target
        where target.child_person_id = p_person_id
          and target.institution_id = institution_id
        for update;
        if found then
          update public.child_contexts target
          set
            status = 'active',
            archived_at = null,
            updated_at = clock_timestamp()
          where target.id = child_context.id
          returning * into child_context;
        else
          insert into public.child_contexts(child_person_id, institution_id)
          values (p_person_id, institution_id)
          returning * into child_context;
        end if;
        if unit_id is not null then
          insert into public.child_unit_links(child_context_id, unit_id, status)
          values (child_context.id, unit_id, 'pending')
          on conflict on constraint child_unit_links_child_context_id_unit_id_key
          do update set
            status = 'pending',
            accepted_by = null,
            accepted_at = null,
            revoked_at = null,
            updated_at = clock_timestamp()
          returning id into child_unit_link_id;
        end if;
        if group_id is not null then
          insert into public.child_group_links(
            child_unit_link_id,
            group_id,
            status
          )
          values (child_unit_link_id, group_id, 'active')
          on conflict on constraint child_group_links_child_unit_link_id_group_id_key
          do update set
            status = 'active',
            ends_at = null,
            updated_at = clock_timestamp()
          returning id into child_group_link_id;
        end if;
      elsif change ->> 'operation' in ('update', 'revoke') then
        select *
        into child_context
        from public.child_contexts target
        where target.id = nullif(change ->> 'child_context_id', '')::uuid
          and target.child_person_id = p_person_id
        for update;
        if not found then
          raise no_data_found using message = 'child context not found for person';
        end if;
        if change ->> 'operation' = 'revoke' then
          update public.child_group_links group_link
          set status = 'inactive', updated_at = clock_timestamp()
          where group_link.child_unit_link_id in (
            select child_unit_link.id
            from public.child_unit_links child_unit_link
            where child_unit_link.child_context_id = child_context.id
          );
          update public.child_unit_links unit_link
          set status = 'inactive', revoked_at = clock_timestamp()
          where unit_link.child_context_id = child_context.id;
          update public.child_contexts target
          set status = 'inactive', updated_at = clock_timestamp()
          where target.id = child_context.id;
        else
          unit_id := case
            when change ? 'unit_id'
              then nullif(change ->> 'unit_id', '')::uuid
            else null
          end;
          group_id := case
            when change ? 'group_id'
              then nullif(change ->> 'group_id', '')::uuid
            else null
          end;
          child_unit_link_id :=
            nullif(change ->> 'child_unit_link_id', '')::uuid;
          child_group_link_id :=
            nullif(change ->> 'child_group_link_id', '')::uuid;

          if unit_id is null then
            raise invalid_parameter_value using
              message = 'child context update requires unit';
          end if;
          if child_unit_link_id is null then
            select count(*)
            into child_unit_link_count
            from public.child_unit_links unit_link
            where unit_link.child_context_id = child_context.id
              and unit_link.status in (
                'pending', 'awaiting_allocation', 'active'
              )
              and unit_link.revoked_at is null;
            if child_unit_link_count > 1 then
              raise invalid_parameter_value using
                message = 'child unit link id is required for ambiguous context';
            elsif child_unit_link_count = 0 then
              insert into public.child_unit_links(
                child_context_id,
                unit_id,
                status
              )
              values (child_context.id, unit_id, 'pending')
              returning id into child_unit_link_id;
            else
              select unit_link.id
              into child_unit_link_id
              from public.child_unit_links unit_link
              where unit_link.child_context_id = child_context.id
                and unit_link.status in (
                  'pending', 'awaiting_allocation', 'active'
                )
                and unit_link.revoked_at is null
              order by unit_link.created_at, unit_link.id
              limit 1;
            end if;
          end if;
          if not exists (
            select 1
            from public.child_unit_links unit_link
            where unit_link.id = child_unit_link_id
              and unit_link.child_context_id = child_context.id
          ) then
            raise no_data_found using
              message = 'child unit link not found for context';
          end if;
          if not exists (
            select 1
            from public.units unit
            where unit.id = unit_id
              and unit.institution_id = child_context.institution_id
          ) then
            raise check_violation using
              message = 'unit belongs to another institution';
          end if;
          if group_id is not null and not exists (
            select 1
            from public.groups group_row
            where group_row.id = group_id
              and group_row.institution_id = child_context.institution_id
              and group_row.unit_id = unit_id
          ) then
            raise check_violation using
              message = 'group belongs to another context';
          end if;

          update public.child_unit_links unit_link
          set
            unit_id = unit_id,
            status = 'pending',
            accepted_by = null,
            accepted_at = null,
            revoked_at = null,
            updated_at = clock_timestamp()
          where unit_link.id = child_unit_link_id;

          if child_group_link_id is null then
            select count(*)
            into child_group_link_count
            from public.child_group_links group_link
            where group_link.child_unit_link_id = child_unit_link_id
              and group_link.status = 'active';
            if child_group_link_count > 1 then
              raise invalid_parameter_value using
                message = 'child group link id is required for ambiguous context';
            elsif child_group_link_count = 1 then
              select group_link.id
              into child_group_link_id
              from public.child_group_links group_link
              where group_link.child_unit_link_id = child_unit_link_id
                and group_link.status = 'active'
              order by group_link.created_at, group_link.id
              limit 1;
            end if;
          end if;
          if child_group_link_id is not null then
            if not exists (
              select 1
              from public.child_group_links group_link
              where group_link.id = child_group_link_id
                and group_link.child_unit_link_id = child_unit_link_id
            ) then
              raise no_data_found using
                message = 'child group link not found for unit link';
            end if;
            update public.child_group_links group_link
            set
              group_id = coalesce(group_id, group_link.group_id),
              status = case
                when group_id is null
                  then 'inactive'::public.record_status
                else 'active'::public.record_status
              end,
              updated_at = clock_timestamp()
            where group_link.id = child_group_link_id;
          elsif group_id is not null then
            insert into public.child_group_links(
              child_unit_link_id,
              group_id,
              status
            )
            values (child_unit_link_id, group_id, 'active')
            on conflict on constraint child_group_links_child_unit_link_id_group_id_key
            do update set
              status = 'active',
              updated_at = clock_timestamp()
            returning id into child_group_link_id;
          end if;
        end if;
      else
        raise invalid_parameter_value using message = 'unsupported child context operation';
      end if;
    else
      raise invalid_parameter_value using
        message = 'context change does not match person type';
    end if;

    insert into audit.audit_logs(
      actor_person_id,
      actor_membership_id,
      mfa_aal,
      action_code,
      object_type,
      object_id,
      institution_id,
      outcome,
      after_json
    )
    values (
      actor_person_id,
      case
        when current_person.person_type = 'adult'
          then app_private.platform_permission_membership_id(
            'people.memberships.manage'
          )
        else app_private.platform_permission_membership_id(
          'people.child_contexts.manage'
        )
      end,
      auth.jwt() ->> 'aal',
      case
        when current_person.person_type = 'adult'
          then 'people.membership.context.' || (change ->> 'operation')
        else 'people.child_context.context.' || (change ->> 'operation')
      end,
      case
        when current_person.person_type = 'adult'
          then 'institution_role_assignments'
        else 'child_contexts'
      end,
      case
        when current_person.person_type = 'adult' then assignment.id
        else child_context.id
      end,
      case
        when current_person.person_type = 'adult'
          then membership.institution_id
        else child_context.institution_id
      end,
      'success',
      jsonb_build_object(
        'operation', change ->> 'operation',
        'changed_fields', case
          when current_person.person_type = 'adult'
            then jsonb_build_array('role', 'scope')
          else jsonb_build_array('institution', 'unit', 'group')
        end
      )
    );
  end loop;

  insert into audit.audit_logs(
    actor_person_id,
    actor_membership_id,
    mfa_aal,
    action_code,
    object_type,
    object_id,
    outcome,
    before_json,
    after_json
  )
  values (
    actor_person_id,
    actor_platform_membership_id,
    auth.jwt() ->> 'aal',
    'people.update',
    'people',
    p_person_id,
    'success',
    jsonb_build_object('expected_updated_at', p_expected_updated_at),
    jsonb_build_object(
      'changed_fields', to_jsonb(changed_fields),
      'context_operation_count',
        jsonb_array_length(coalesce(p_context_changes, '[]'::jsonb))
    )
  );

  return jsonb_build_object(
    'id', updated_person.id,
    'person_type', updated_person.person_type,
    'display_name', updated_person.display_name,
    'status', updated_person.status,
    'updated_at', updated_person.updated_at
  );
end
$$;


ALTER FUNCTION "app_private"."update_superadmin_person"("p_person_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_identity_patch" "jsonb", "p_context_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."update_unit_for_superadmin"("p_request_id" "uuid", "p_payload" "jsonb", "p_unit_id" "uuid", "p_expected_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=app_private.current_person_id();u public.units%rowtype;plan_id uuid;type_id uuid;h bytea;
prior app_private.unit_management_command_receipts%rowtype;result jsonb;begin
select*into u from public.units where id=p_unit_id;if u.id is null then raise no_data_found using message='unit not found';end if;
if p_request_id is null or actor is null or(select auth.uid())is null or not app_private.has_scoped_platform_permission('units.update',u.institution_id)
or not app_private.has_mfa_aal2()then raise insufficient_privilege using message='units.update and AAL2 required';end if;
if p_payload?'institution_id'and(p_payload->>'institution_id')::uuid<>u.institution_id then raise invalid_parameter_value using message='use transfer command';end if;
if p_payload?'handle'then raise invalid_parameter_value using message='use handle command';end if;
perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,0));
h:=app_private.unit_management_hash(jsonb_build_object('unit_id',p_unit_id,'expected_version',p_expected_version,'payload',p_payload));
select*into prior from app_private.unit_management_command_receipts where request_id=p_request_id;
if prior.request_id is not null then if prior.actor_person_id<>actor or prior.command_kind<>'update'or prior.unit_id<>p_unit_id or prior.request_hash<>h
then raise invalid_parameter_value using message='request replay mismatch';end if;return app_private.unit_form_payload(prior.unit_id);end if;
select*into u from public.units where id=p_unit_id for update;if u.management_version<>p_expected_version then raise serialization_failure using message='stale unit version';end if;
plan_id:=case when p_payload?'plan_override_id'then nullif(p_payload->>'plan_override_id','')::uuid else u.plan_override_id end;
type_id:=case when p_payload?'unit_type_id'then(p_payload->>'unit_type_id')::uuid else u.unit_type_id end;
if plan_id is distinct from u.plan_override_id and(not app_private.has_platform_permission('units.plan.manage')
or(plan_id is not null and not app_private.unit_plan_is_available(plan_id,u.institution_id)))
then raise insufficient_privilege using message='units.plan.manage and available plan required';end if;
update public.units x set name=coalesce(nullif(btrim(p_payload->>'name'),''),x.name),
slug=coalesce(nullif(lower(btrim(p_payload->>'slug')),''),x.slug),
status=case when p_payload?'unit_status'then(p_payload->>'unit_status')::public.record_status else x.status end,
unit_type_id=type_id,unit_type_other_description=case when p_payload?'unit_type_other_description'
then nullif(btrim(p_payload->>'unit_type_other_description'),'')else x.unit_type_other_description end,
plan_override_id=plan_id,timezone=case when p_payload?'timezone'then p_payload->>'timezone'else x.timezone end,
public_discovery_enabled=coalesce((p_payload#>>'{public_profile,discovery_enabled}')::boolean,x.public_discovery_enabled),
public_address_visible=coalesce((p_payload#>>'{public_profile,address_visible}')::boolean,x.public_address_visible),
public_contact_visible=coalesce((p_payload#>>'{public_profile,contact_visible}')::boolean,x.public_contact_visible),
inherit_address=coalesce((p_payload#>>'{inheritance,address}')::boolean,x.inherit_address),
inherit_contact=coalesce((p_payload#>>'{inheritance,contact}')::boolean,x.inherit_contact),
inherit_branding=coalesce((p_payload#>>'{inheritance,branding}')::boolean,x.inherit_branding),
inherit_representatives=coalesce((p_payload#>>'{inheritance,representatives}')::boolean,x.inherit_representatives),
inherit_administrators=coalesce((p_payload#>>'{inheritance,administrators}')::boolean,x.inherit_administrators),
inherit_plan=plan_id is null,management_version=x.management_version+1,updated_at=now()where id=p_unit_id;
perform app_private.persist_unit_children(p_unit_id,actor,p_payload);result:=app_private.unit_form_payload(p_unit_id);
insert into audit.audit_logs(actor_person_id,mfa_aal,action_code,object_type,object_id,institution_id,outcome,before_json,after_json)
values(actor,'aal2','unit.update','unit',p_unit_id,u.institution_id,'success',jsonb_build_object('management_version',u.management_version),
jsonb_build_object('management_version',result->'management_version'));
insert into app_private.unit_management_command_receipts values(p_request_id,h,actor,'update',p_unit_id,(result->>'management_version')::bigint,now());return result;end$$;


ALTER FUNCTION "app_private"."update_unit_for_superadmin"("p_request_id" "uuid", "p_payload" "jsonb", "p_unit_id" "uuid", "p_expected_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_access_request_child"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  requester_id uuid;
  linked_guardian_id uuid;
  linked_child_id uuid;
  link_status public.record_status;
begin
  select request.requested_by into requester_id
  from public.child_unit_access_requests request where request.id = new.request_id;
  select guardian_link.guardian_person_id, guardian_link.child_person_id, guardian_link.status
  into linked_guardian_id, linked_child_id, link_status
  from public.guardian_links guardian_link where guardian_link.id = new.guardian_link_id;

  if link_status <> 'active'
     or linked_guardian_id <> requester_id
     or linked_child_id <> new.child_person_id then
    raise check_violation using message = 'request child requires an active guardian link owned by requester';
  end if;
  return new;
end
$$;


ALTER FUNCTION "app_private"."validate_access_request_child"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_activity_governance_row"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_table_name = 'activity_capability_policies' then
    if not exists (
      select 1 from public.activity_definitions activity
      where activity.id = new.activity_id
        and activity.institution_id = new.institution_id
    ) then raise exception 'activity policy tenant mismatch'; end if;
  elsif tg_table_name = 'activity_group_capability_settings' then
    if exists (
      select 1
      from public.activity_group_links group_link
      join public.activity_capability_policies policy
        on policy.activity_id = group_link.activity_id
       and policy.capability_id = new.capability_id
      where group_link.id = new.activity_group_link_id
        and (
          (policy.policy_mode = 'required' and not new.is_enabled)
          or (policy.policy_mode = 'prohibited' and new.is_enabled)
        )
    ) then raise exception 'institution capability policy is locked'; end if;
  elsif tg_table_name = 'activity_group_participants' then
    if not exists (
      select 1
      from public.activity_group_links activity_link
      join public.child_group_links child_link
        on child_link.id = new.child_group_link_id
       and child_link.group_id = activity_link.group_id
      join public.child_unit_links child_unit
        on child_unit.id = child_link.child_unit_link_id
       and child_unit.unit_id = activity_link.unit_id
      join public.child_contexts child_context
        on child_context.id = child_unit.child_context_id
       and child_context.institution_id = activity_link.institution_id
      where activity_link.id = new.activity_group_link_id
    ) then raise exception 'activity participant is outside group context'; end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."validate_activity_governance_row"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_activity_group_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  profile_scope public.activity_permission_scope;
  profile_unit_id uuid;
begin
  if new.permission_profile_id is null then
    return new;
  end if;

  select profile.scope_kind, profile.unit_id
  into profile_scope, profile_unit_id
  from public.activity_permission_profiles profile
  where profile.id = new.permission_profile_id
    and profile.institution_id = new.institution_id;

  if profile_scope = 'unit' and profile_unit_id <> new.unit_id then
    raise check_violation using
      message = 'unit-scoped activity profile must match the activity group unit';
  end if;

  return new;
end
$$;


ALTER FUNCTION "app_private"."validate_activity_group_profile"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_attendance_context_row"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_table_name='attendance_reason_catalog' then
    if new.unit_id is not null and not exists (
      select 1 from public.units where id=new.unit_id
        and institution_id=new.institution_id
    ) then raise exception 'attendance reason tenant mismatch'; end if;
  elsif tg_table_name='attendance_sessions' then
    if not exists (
      select 1 from public.groups group_row
      where group_row.id=new.group_id and group_row.unit_id=new.unit_id
        and group_row.institution_id=new.institution_id
    ) then raise exception 'attendance session context mismatch'; end if;
    if new.activity_id is not null and not exists (
      select 1 from public.activity_group_links link
      where link.activity_id=new.activity_id and link.group_id=new.group_id
        and link.unit_id=new.unit_id and link.institution_id=new.institution_id
        and link.status='active'
    ) then raise exception 'attendance activity context mismatch'; end if;
  elsif tg_table_name='attendance_expected_participants' then
    if not exists (
      select 1
      from public.attendance_sessions session_row
      join public.child_group_links child_group
        on child_group.id=new.child_group_link_id
       and child_group.group_id=session_row.group_id
      join public.child_unit_links child_unit
        on child_unit.id=child_group.child_unit_link_id
       and child_unit.unit_id=session_row.unit_id
      join public.child_contexts child_context
        on child_context.id=child_unit.child_context_id
       and child_context.id=new.child_context_id
       and child_context.institution_id=session_row.institution_id
      where session_row.id=new.attendance_session_id
        and (
          session_row.activity_id is null
          or new.activity_group_participant_id is not null
        )
    ) then raise exception 'attendance participant context mismatch'; end if;
  elsif tg_table_name='attendance_notices' then
    if not exists (
      select 1
      from public.child_group_links child_group
      join public.child_unit_links child_unit
        on child_unit.id=child_group.child_unit_link_id
      join public.child_contexts child_context
        on child_context.id=child_unit.child_context_id
      join public.groups group_row on group_row.id=child_group.group_id
      where child_group.id=new.child_group_link_id
        and child_context.id=new.child_context_id
        and child_context.institution_id=new.institution_id
        and child_unit.unit_id=new.unit_id
        and group_row.id=new.group_id
    ) then raise exception 'attendance notice context mismatch'; end if;
    if new.activity_id is not null and not exists (
      select 1 from public.activity_group_links link
      where link.activity_id=new.activity_id and link.group_id=new.group_id
        and link.unit_id=new.unit_id and link.institution_id=new.institution_id
    ) then raise exception 'attendance notice activity mismatch'; end if;
  elsif tg_table_name='attendance_records' then
    if not exists (
      select 1 from public.attendance_expected_participants participant
      where participant.attendance_session_id=new.attendance_session_id
        and participant.child_context_id=new.child_context_id
        and participant.status='active'
    ) then raise exception 'official attendance requires expected participant'; end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."validate_attendance_context_row"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_chat_context_row"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target_institution_id uuid;
begin
  if tg_table_name = 'unit_chat_settings' then
    select institution_id into target_institution_id
    from public.units where id = new.unit_id;
    if target_institution_id is null or target_institution_id <> new.institution_id
    then raise exception 'unit chat tenant mismatch'; end if;
  elsif tg_table_name = 'conversation_routing_teams' then
    if new.unit_id is not null and not exists (
      select 1 from public.units
      where id = new.unit_id and institution_id = new.institution_id
    ) then raise exception 'routing team tenant mismatch'; end if;
  elsif tg_table_name = 'conversation_routing_team_members' then
    if not exists (
      select 1 from public.conversation_routing_teams team
      join public.institution_memberships membership
        on membership.id = new.membership_id
       and membership.institution_id = team.institution_id
      where team.id = new.team_id
    ) then raise exception 'routing member tenant mismatch'; end if;
  elsif tg_table_name = 'conversations' then
    if new.scope_kind not in ('institution', 'unit', 'group', 'activity') then
      raise exception 'invalid conversation scope';
    end if;
    if new.scope_kind = 'institution' and (
      new.unit_id is not null or new.group_id is not null
      or new.activity_id is not null
    ) then raise exception 'institution conversation has child scope'; end if;
    if new.scope_kind = 'unit' and (
      new.unit_id is null or new.group_id is not null
      or new.activity_id is not null
    ) then raise exception 'invalid unit conversation scope'; end if;
    if new.scope_kind = 'group' and (
      new.unit_id is null or new.group_id is null
      or new.activity_id is not null
    ) then raise exception 'invalid group conversation scope'; end if;
    if new.scope_kind = 'activity' and (
      new.unit_id is null or new.group_id is null
      or new.activity_id is null
    ) then raise exception 'invalid activity conversation scope'; end if;
    if new.unit_id is not null and not exists (
      select 1 from public.units
      where id = new.unit_id and institution_id = new.institution_id
    ) then raise exception 'conversation unit tenant mismatch'; end if;
    if new.group_id is not null and not exists (
      select 1 from public.groups
      where id = new.group_id and unit_id = new.unit_id
        and institution_id = new.institution_id
    ) then raise exception 'conversation group tenant mismatch'; end if;
    if new.activity_id is not null and not exists (
      select 1 from public.activity_group_links link
      where link.activity_id = new.activity_id and link.group_id = new.group_id
        and link.unit_id = new.unit_id
        and link.institution_id = new.institution_id
    ) then raise exception 'conversation activity context mismatch'; end if;
  elsif tg_table_name = 'conversation_participants' then
    if new.membership_id is not null and not exists (
      select 1 from public.conversations conversation_row
      join public.institution_memberships membership
        on membership.id = new.membership_id
       and membership.institution_id = conversation_row.institution_id
       and membership.person_id = new.person_id
      where conversation_row.id = new.conversation_id
    ) then raise exception 'participant membership mismatch'; end if;
  elsif tg_table_name = 'conversation_child_contexts' then
    if not exists (
      select 1 from public.conversations conversation_row
      join public.child_contexts child_context
        on child_context.id = new.child_context_id
       and child_context.institution_id = conversation_row.institution_id
      where conversation_row.id = new.conversation_id
    ) then raise exception 'conversation child tenant mismatch'; end if;
  elsif tg_table_name = 'message_child_contexts' then
    if not exists (
      select 1 from public.messages message_row
      join public.conversations conversation_row
        on conversation_row.id = message_row.conversation_id
      join public.child_contexts child_context
        on child_context.id = new.child_context_id
       and child_context.institution_id = conversation_row.institution_id
      where message_row.id = new.message_id
    ) then raise exception 'message child tenant mismatch'; end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."validate_chat_context_row"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_child_context"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not exists (
    select 1 from public.people person
    where person.id = new.child_person_id and person.person_type = 'child'
  ) then
    raise check_violation using message = 'child context requires a child person';
  end if;
  return new;
end
$$;


ALTER FUNCTION "app_private"."validate_child_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_child_group_link"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  linked_unit_id uuid;
  group_unit_id uuid;
begin
  select unit_link.unit_id into linked_unit_id
  from public.child_unit_links unit_link where unit_link.id = new.child_unit_link_id;
  select current_group.unit_id into group_unit_id
  from public.groups current_group where current_group.id = new.group_id;

  if group_unit_id is null or linked_unit_id <> group_unit_id then
    raise check_violation using message = 'group must belong to the child unit';
  end if;
  return new;
end
$$;


ALTER FUNCTION "app_private"."validate_child_group_link"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_child_unit_link"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  context_institution_id uuid;
  unit_institution_id uuid;
begin
  select context.institution_id into context_institution_id
  from public.child_contexts context where context.id = new.child_context_id;
  select unit.institution_id into unit_institution_id
  from public.units unit where unit.id = new.unit_id;

  if context_institution_id <> unit_institution_id then
    raise check_violation using message = 'child context and unit must belong to the same institution';
  end if;
  return new;
end
$$;


ALTER FUNCTION "app_private"."validate_child_unit_link"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_contextual_authorization_row"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  membership_institution_id uuid;
  target_institution_id uuid;
begin
  select membership.institution_id
    into membership_institution_id
  from public.institution_memberships membership
  where membership.id = new.membership_id;

  if membership_institution_id is null then
    raise exception 'membership does not exist';
  end if;

  if tg_table_name = 'professional_child_assignments' then
    select child_context.institution_id
      into target_institution_id
    from public.child_contexts child_context
    where child_context.id = new.child_context_id;
  elsif new.scope_kind = 'institution' then
    target_institution_id := membership_institution_id;
  elsif new.scope_kind = 'unit' then
    select unit_record.institution_id into target_institution_id
    from public.units unit_record where unit_record.id = new.scope_id;
  elsif new.scope_kind = 'group' then
    select group_record.institution_id into target_institution_id
    from public.groups group_record where group_record.id = new.scope_id;
  elsif new.scope_kind = 'activity' then
    select activity.institution_id into target_institution_id
    from public.activity_definitions activity where activity.id = new.scope_id;
  elsif new.scope_kind = 'child' then
    select child_context.institution_id into target_institution_id
    from public.child_contexts child_context where child_context.id = new.scope_id;
  end if;

  if target_institution_id is null
     or target_institution_id <> membership_institution_id then
    raise exception 'context must belong to membership institution';
  end if;

  return new;
end
$$;


ALTER FUNCTION "app_private"."validate_contextual_authorization_row"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_family_context_row"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  expected_institution uuid;
  related_institution uuid;
begin
  if tg_table_name = 'authorized_person_authorizations' then
    select child_context.institution_id into expected_institution
    from public.child_contexts child_context where child_context.id = new.child_context_id;
    select unit_record.institution_id into related_institution
    from public.units unit_record where unit_record.id = new.unit_id;
    if expected_institution is null or related_institution <> expected_institution
       or new.institution_id <> expected_institution
       or not exists (
         select 1 from public.authorized_people person_record
         where person_record.id = new.authorized_person_id
           and person_record.institution_id = expected_institution
       ) then
      raise exception 'authorization contexts must share one institution';
    end if;
  elsif tg_table_name = 'child_unit_transfer_requests' then
    select source_unit.institution_id into expected_institution
    from public.units source_unit where source_unit.id = new.source_unit_id;
    select destination_unit.institution_id into related_institution
    from public.units destination_unit where destination_unit.id = new.destination_unit_id;
    if expected_institution is null or related_institution <> expected_institution
       or new.institution_id <> expected_institution then
      raise exception 'transfer units must share one institution';
    end if;
  elsif tg_table_name = 'child_unit_transfer_items' then
    if not exists (
      select 1
      from public.child_unit_transfer_requests request_record
      join public.child_unit_links child_link on child_link.id = new.child_unit_link_id
      join public.child_contexts child_context
        on child_context.id = child_link.child_context_id
      where request_record.id = new.transfer_request_id
        and child_link.unit_id = request_record.source_unit_id
        and child_context.institution_id = request_record.institution_id
        and (
          new.suggested_group_id is null
          or exists (
            select 1 from public.groups group_record
            where group_record.id = new.suggested_group_id
              and group_record.unit_id = request_record.destination_unit_id
              and group_record.institution_id = request_record.institution_id
          )
        )
    ) then
      raise exception 'transfer item is outside request context';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."validate_family_context_row"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_form_definition"("p_version_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_has_cycle boolean;
  v_max_depth integer;
  v_form_kind text;
  v_quick_poll_intent text;
  v_quick_poll_item_count integer;
begin
  if (select count(*) from public.form_sections where form_version_id = p_version_id) > 20 then
    raise check_violation using message = 'maximum 20 form sections';
  end if;
  if (select count(*) from public.form_items where form_version_id = p_version_id) > 200 then
    raise check_violation using message = 'maximum 200 form items';
  end if;
  select form_row.kind, form_row.description
    into v_form_kind, v_quick_poll_intent
    from public.form_versions version_row
    join public.forms form_row on form_row.id = version_row.form_id
   where version_row.id = p_version_id;
  if v_form_kind = 'quick_poll' then
    if char_length(btrim(coalesce(v_quick_poll_intent, ''))) not between 1 and 280 then
      raise check_violation using message = 'quick poll intent requires between 1 and 280 characters';
    end if;
    select count(*) into v_quick_poll_item_count
      from public.form_items item where item.form_version_id = p_version_id;
    if v_quick_poll_item_count <> 1
       or exists(
         select 1 from public.form_items item
          where item.form_version_id = p_version_id and item.kind = 'information'
       ) then
      raise check_violation using message = 'quick poll requires exactly one question';
    end if;
  end if;
  if exists (
    select 1
      from public.form_items item
     where item.form_version_id = p_version_id
       and item.kind in ('single_choice', 'multiple_choice')
       and (select count(*) from public.form_question_options option_row where option_row.item_id = item.id) not between 2 and 50
  ) then
    raise check_violation using message = 'choice item requires between 2 and 50 options';
  end if;
  if exists (
    select 1
      from public.form_question_options option_row
      join public.form_items item on item.id = option_row.item_id
     where option_row.form_version_id = p_version_id
       and (item.form_version_id <> p_version_id or item.kind not in ('single_choice', 'multiple_choice'))
  ) then
    raise check_violation using message = 'form options require a choice item in the same version';
  end if;
  if exists (
    select 1
      from public.form_question_conditions condition_row
      join public.form_items source_item on source_item.id = condition_row.source_item_id
     where condition_row.form_version_id = p_version_id
       and (
         (condition_row.condition_kind = 'yes_no' and source_item.kind <> 'yes_no')
         or (condition_row.condition_kind = 'choice' and source_item.kind not in ('single_choice', 'multiple_choice'))
       )
  ) then
    raise check_violation using message = 'condition source kind is not allowed';
  end if;
  if exists (
    select 1
      from public.form_items item
      join public.form_sections section_row on section_row.id = item.section_id
     where item.form_version_id = p_version_id
       and section_row.form_version_id <> p_version_id
  ) or exists (
    select 1
      from public.form_question_conditions condition_row
      join public.form_items source_item on source_item.id = condition_row.source_item_id
      join public.form_items target_item on target_item.id = condition_row.target_item_id
     where condition_row.form_version_id = p_version_id
       and (source_item.form_version_id <> p_version_id or target_item.form_version_id <> p_version_id)
  ) then
    raise check_violation using message = 'form definition version mismatch';
  end if;

  with recursive walk(current_item_id, path, depth, cycle) as (
    select condition_row.target_item_id,
           array[condition_row.source_item_id, condition_row.target_item_id],
           1,
           condition_row.target_item_id = condition_row.source_item_id
      from public.form_question_conditions condition_row
     where condition_row.form_version_id = p_version_id
    union all
    select condition_row.target_item_id,
           walk.path || condition_row.target_item_id,
           walk.depth + 1,
           condition_row.target_item_id = any(walk.path)
      from walk
      join public.form_question_conditions condition_row
        on condition_row.source_item_id = walk.current_item_id
     where condition_row.form_version_id = p_version_id
       and not walk.cycle
       and walk.depth <= 4
  )
  select coalesce(bool_or(cycle), false), coalesce(max(depth), 0)
    into v_has_cycle, v_max_depth
    from walk;

  if v_has_cycle then
    raise check_violation using message = 'form condition cycle';
  end if;
  if v_max_depth > 4 then
    raise check_violation using message = 'maximum form condition depth is 4';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."validate_form_definition"("p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_form_distribution_cardinality"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_table_name = 'form_audience_rules' then
    if (
      select count(*) from public.form_audience_rules rule
       where rule.application_id = new.application_id
         and rule.id <> new.id
    ) >= 50 then
      raise check_violation using message = 'maximum 50 form audience rules';
    end if;
    return new;
  end if;

  if tg_table_name = 'form_schedules' then
    if new.status = 'active' and (
      select count(*) from public.form_schedules schedule
       where schedule.application_id = new.application_id
         and schedule.status = 'active'
         and schedule.id <> new.id
    ) >= 20 then
      raise check_violation using message = 'maximum 20 active form schedules per application';
    end if;
    return new;
  end if;

  if tg_table_name = 'form_schedule_reminders' then
    if (
      select count(*) from public.form_schedule_reminders reminder
       where reminder.schedule_id = new.schedule_id
         and reminder.id <> new.id
    ) >= 3 then
      raise check_violation using message = 'maximum 3 form schedule reminders';
    end if;
    return new;
  end if;

  raise check_violation using message = 'unsupported forms cardinality trigger table';
end;
$$;


ALTER FUNCTION "app_private"."validate_form_distribution_cardinality"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_form_tenant_links"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_table_name = 'form_applications' then
    if not exists(
      select 1 from public.forms form_row
       where form_row.id = new.form_id
         and form_row.institution_id = new.institution_id
    ) then
      raise check_violation using message = 'form application tenant mismatch';
    end if;
    return new;
  end if;

  if tg_table_name = 'form_audience_rules' then
    if (
      not exists(
        select 1 from public.form_applications application
         where application.id = new.application_id
           and application.institution_id = new.institution_id
      )
      or not case new.rule_kind
        when 'institution' then new.target_id = new.institution_id
        when 'unit' then exists(
          select 1 from public.units unit_row
           where unit_row.id = new.target_id
             and unit_row.institution_id = new.institution_id
        )
        when 'group' then exists(
          select 1 from public.groups group_row
           where group_row.id = new.target_id
             and group_row.institution_id = new.institution_id
        )
        when 'activity' then exists(
          select 1 from public.activity_definitions activity
           where activity.id = new.target_id
             and activity.institution_id = new.institution_id
        )
        when 'profile' then exists(
          select 1
            from public.institution_role_assignments assignment
            join public.institution_memberships membership
              on membership.id = assignment.membership_id
           where assignment.role_id = new.target_id
             and membership.institution_id = new.institution_id
        )
        else exists(
          select 1 from public.institution_memberships membership
           where membership.person_id = new.target_id
             and membership.institution_id = new.institution_id
          union all
          select 1
            from public.guardian_links guardian
            join public.child_contexts child_context
              on child_context.child_person_id = guardian.child_person_id
           where guardian.guardian_person_id = new.target_id
             and child_context.institution_id = new.institution_id
          union all
          select 1 from public.child_contexts child_context
           where child_context.child_person_id = new.target_id
             and child_context.institution_id = new.institution_id
        )
      end
    ) then
      raise check_violation using message = 'audience rule target tenant mismatch';
    end if;
    return new;
  end if;

  if tg_table_name = 'form_occurrences' then
    if not exists(
      select 1
        from public.form_applications application_row
        join public.forms form_row on form_row.id = application_row.form_id
        join public.form_versions version_row on version_row.id = new.form_version_id
        join public.form_schedules schedule_row on schedule_row.id = new.schedule_id
       where application_row.id = new.application_id
         and application_row.form_id = new.form_id
         and application_row.institution_id = new.institution_id
         and form_row.institution_id = new.institution_id
         and version_row.form_id = new.form_id
         and schedule_row.application_id = new.application_id
    ) then
      raise check_violation using message = 'form occurrence tenant or version mismatch';
    end if;
    return new;
  end if;

  if tg_table_name = 'form_responses' then
    if not exists(
      select 1 from public.form_occurrences occurrence_row
       where occurrence_row.id = new.occurrence_id
         and occurrence_row.institution_id = new.institution_id
         and occurrence_row.form_id = new.form_id
         and occurrence_row.form_version_id = new.form_version_id
    ) then
      raise check_violation using message = 'form response tenant or version mismatch';
    end if;
    return new;
  end if;

  if tg_table_name = 'form_answers' then
    if not exists(
      select 1
        from public.form_responses response_row
        join public.form_items item_row on item_row.id = new.item_id
       where response_row.id = new.response_id
         and response_row.form_version_id = new.form_version_id
         and item_row.form_version_id = new.form_version_id
    ) then
      raise check_violation using message = 'form answer version mismatch';
    end if;
    return new;
  end if;

  if tg_table_name = 'form_participations' then
    if (
      not exists(
        select 1 from public.form_occurrences occurrence
         where occurrence.id = new.occurrence_id
           and occurrence.institution_id = new.institution_id
      )
      or (
        new.child_context_id is not null
        and not exists(
          select 1 from public.child_contexts child_context
           where child_context.id = new.child_context_id
             and child_context.institution_id = new.institution_id
        )
      )
      or (
        new.person_id is not null
        and not exists(
          select 1 from public.institution_memberships membership
           where membership.person_id = new.person_id
             and membership.institution_id = new.institution_id
          union all
          select 1 from public.child_contexts child_context
           where child_context.child_person_id = new.person_id
             and child_context.institution_id = new.institution_id
          union all
          select 1
            from public.guardian_links guardian
            join public.child_contexts child_context
              on child_context.child_person_id = guardian.child_person_id
           where guardian.guardian_person_id = new.person_id
             and child_context.institution_id = new.institution_id
        )
      )
    ) then
      raise check_violation using message = 'form participation tenant mismatch';
    end if;
    return new;
  end if;

  if tg_table_name = 'form_participation_responders' then
    if not exists(
      select 1
        from public.form_participations participation
        join public.child_contexts child_context
          on child_context.id = participation.child_context_id
        join public.guardian_links guardian
          on guardian.child_person_id = child_context.child_person_id
         and guardian.guardian_person_id = new.person_id
        join public.guardian_context_permissions permission
          on permission.guardian_link_id = guardian.id
         and permission.child_context_id = child_context.id
       where participation.id = new.participation_id
         and participation.institution_id = new.institution_id
         and guardian.status = 'active'
         and guardian.revoked_at is null
         and permission.status = 'active'
         and permission.can_view
         and (permission.starts_at is null or permission.starts_at <= now())
         and (permission.expires_at is null or permission.expires_at > now())
    ) then
      raise check_violation using message = 'form participation responder tenant mismatch';
    end if;
    return new;
  end if;

  if tg_table_name = 'form_assets' then
    if not exists(
      select 1
        from public.form_occurrences occurrence
        join public.form_items item on item.id = new.item_id
       where occurrence.id = new.occurrence_id
         and occurrence.institution_id = new.institution_id
         and item.form_version_id = occurrence.form_version_id
    ) then
      raise check_violation using message = 'form asset tenant or version mismatch';
    end if;
    return new;
  end if;

  if tg_table_name = 'form_file_jobs' then
    if not exists(
      select 1 from public.forms form_row
       where form_row.id = new.form_id
         and form_row.institution_id = new.institution_id
         and (
           new.occurrence_id is null
           or exists(
             select 1 from public.form_occurrences occurrence
              where occurrence.id = new.occurrence_id
                and occurrence.form_id = new.form_id
                and occurrence.institution_id = new.institution_id
           )
         )
    ) then
      raise check_violation using message = 'form file job tenant mismatch';
    end if;
    return new;
  end if;

  raise check_violation using message = 'unsupported forms tenant trigger table';
end;
$$;


ALTER FUNCTION "app_private"."validate_form_tenant_links"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_guardian_context_permission"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  linked_child_id uuid;
  context_child_id uuid;
begin
  select guardian_link.child_person_id into linked_child_id
  from public.guardian_links guardian_link where guardian_link.id = new.guardian_link_id;
  select context.child_person_id into context_child_id
  from public.child_contexts context where context.id = new.child_context_id;

  if linked_child_id <> context_child_id then
    raise check_violation using message = 'guardian link and child context must reference the same child';
  end if;
  return new;
end
$$;


ALTER FUNCTION "app_private"."validate_guardian_context_permission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_guardian_link"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  guardian_type public.person_type;
  child_type public.person_type;
begin
  select person.person_type into guardian_type
  from public.people person where person.id = new.guardian_person_id;
  select person.person_type into child_type
  from public.people person where person.id = new.child_person_id;

  if guardian_type <> 'adult' or child_type <> 'child' then
    raise check_violation using message = 'guardian must be adult and child must be child';
  end if;
  return new;
end
$$;


ALTER FUNCTION "app_private"."validate_guardian_link"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_institution_legal_representative"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  representative public.people%rowtype;
  representative_membership public.institution_memberships%rowtype;
begin
  if new.status = 'active' then
    select *
      into representative
    from public.people
    where id = new.person_id;

    if representative.id is null
       or representative.person_type <> 'adult'
       or representative.date_of_birth is null
       or representative.date_of_birth > (
         new.starts_on - interval '18 years'
       )::date then
      raise check_violation using
        message =
          'active legal representative must be an adult at starts_on';
    end if;

    select *
      into representative_membership
    from public.institution_memberships
    where id = new.membership_id;

    if representative_membership.id is null
       or representative_membership.status <> 'active'
       or representative_membership.revoked_at is not null then
      raise check_violation using
        message = 'active legal representative membership must be active';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."validate_institution_legal_representative"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_institution_role_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare membership_institution uuid; role_institution uuid; maximum text;
  unit_institution uuid; group_institution uuid; group_unit uuid;
begin
  select institution_id into membership_institution
    from public.institution_memberships where id=new.membership_id;
  select institution_id,max_scope_kind into role_institution,maximum
    from public.institution_roles where id=new.role_id;
  if role_institution is not null and role_institution<>membership_institution then
    raise check_violation using message='role and membership tenant mismatch';
  end if;
  if app_private.access_scope_rank(new.scope_kind)>
     app_private.access_scope_rank(maximum) then
    raise check_violation using message='assignment scope exceeds profile maximum';
  end if;
  if new.scope_unit_id is not null then
    select institution_id into unit_institution from public.units where id=new.scope_unit_id;
    if unit_institution<>membership_institution then
      raise check_violation using message='unit tenant mismatch';
    end if;
  end if;
  if new.scope_group_id is not null then
    select institution_id,unit_id into group_institution,group_unit
      from public.groups where id=new.scope_group_id;
    if group_institution<>membership_institution or group_unit is distinct from new.scope_unit_id then
      raise check_violation using message='group scope mismatch';
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "app_private"."validate_institution_role_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_invitation_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  unit_institution_id uuid;
  group_institution_id uuid;
  group_unit_id uuid;
begin
  if new.unit_id is not null then
    select unit.institution_id into unit_institution_id
    from public.units unit where unit.id = new.unit_id;
    if new.institution_id is null then
      new.institution_id := unit_institution_id;
    elsif new.institution_id <> unit_institution_id then
      raise check_violation using message = 'invitation unit must belong to invitation institution';
    end if;
  end if;

  if new.group_id is not null then
    select current_group.institution_id, current_group.unit_id
    into group_institution_id, group_unit_id
    from public.groups current_group where current_group.id = new.group_id;
    if new.institution_id is null then
      new.institution_id := group_institution_id;
    elsif new.institution_id <> group_institution_id then
      raise check_violation using message = 'invitation group must belong to invitation institution';
    end if;
    if new.unit_id is null then
      new.unit_id := group_unit_id;
    elsif new.unit_id is distinct from group_unit_id then
      raise check_violation using message = 'invitation group must belong to invitation unit';
    end if;
  end if;

  return new;
end
$$;


ALTER FUNCTION "app_private"."validate_invitation_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."validate_platform_profile_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare maximum text;
begin
  select max_scope_kind into maximum from public.platform_roles where id=new.role_id;
  if app_private.access_scope_rank(new.scope_kind)>
     app_private.access_scope_rank(maximum) then
    raise check_violation using message='membership scope exceeds profile maximum';
  end if;
  if (new.scope_kind='platform' and new.scope_institution_id is not null)
     or (new.scope_kind='institution' and new.scope_institution_id is null)
     or new.scope_kind not in ('platform','institution') then
    raise check_violation using message='inconsistent platform membership scope';
  end if;
  return new;
end $$;


ALTER FUNCTION "app_private"."validate_platform_profile_scope"() OWNER TO "postgres";


