if c is null or(c='other'and nullif(btrim(new.unit_type_other_description),'')is null)
or(c<>'other'and new.unit_type_other_description is not null)
then raise check_violation using message='invalid unit type or Other description';end if;return new;end$$;


ALTER FUNCTION "app_private"."validate_unit_type_selection"() OWNER TO "postgres";


