CREATE OR REPLACE FUNCTION "public"."create_institution_for_superadmin"("p_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise insufficient_privilege using message = 'authentication required';
  end if;

  if p_payload ? 'status'
     and coalesce(p_payload ->> 'status', '') <> 'draft'
     and not app_private.has_scoped_platform_permission(
       'institution.status.change', null
     ) then
    raise insufficient_privilege using
      message = 'institution.status.change required for non-draft create';
  end if;

  return app_private.create_institution_for_superadmin(p_request_id, p_payload);
end;
$$;


