CREATE OR REPLACE FUNCTION "public"."get_profile_about"("p_subject_type" "text", "p_subject_id" "uuid", "p_preview_audience" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p public.profile_about_pages; audience text; can_manage boolean; can_read boolean; editor_load boolean; actor uuid:=app_private.current_person_id();
begin
 if actor is null then raise insufficient_privilege; end if;
 if p_subject_type='person' then raise insufficient_privilege using message='person About is not released'; end if;
 p:=app_private.profile_about_page_for(p_subject_type,p_subject_id);
 if p.id is null then return null; end if;
 can_manage:=app_private.profile_about_can(p.institution_id,'profiles.about.manage',p.unit_subject_id,p.group_subject_id,p.activity_subject_id);
 can_read:=app_private.profile_about_can(p.institution_id,'profiles.about.read',p.unit_subject_id,p.group_subject_id,p.activity_subject_id);
 if p_preview_audience is not null and not can_manage then raise insufficient_privilege using message='preview requires profiles.about.manage'; end if;
 if not can_manage and not can_read
  and not exists(
   select 1 from public.institution_memberships m
   where m.person_id=actor and m.institution_id=p.institution_id and m.status='active' and m.revoked_at is null
    and case p.subject_type
     when 'institution' then true
     when 'unit' then m.scope_unit_id is null or m.scope_unit_id=p.unit_subject_id
     when 'group' then m.scope_group_id=p.group_subject_id or
       (m.scope_group_id is null and (m.scope_unit_id is null or m.scope_unit_id=(select g.unit_id from public.groups g where g.id=p.group_subject_id)))
     when 'activity' then m.scope_unit_id is null and m.scope_group_id is null or
       exists(select 1 from public.activity_unit_links l where l.activity_id=p.activity_subject_id and l.status='active' and l.unit_id=m.scope_unit_id) or
       exists(select 1 from public.activity_group_links l where l.activity_id=p.activity_subject_id and l.status='active' and l.group_id=m.scope_group_id)
     else false end
  )
 then raise insufficient_privilege; end if;
 if not can_manage and p.state<>'published' then return null; end if;
 audience:=coalesce(p_preview_audience,case when can_manage or can_read then 'team' else 'linked' end);
 if audience not in('profile_access','linked','team') then raise check_violation using message='invalid audience'; end if;
 editor_load:=can_manage and p_preview_audience is null;
 return jsonb_build_object('id',p.id,'subject_type',p.subject_type,'subject_id',p_subject_id,'version',p.version,'state',p.state,
  'fields',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'key',f.field_key,'value',f.value,'latitude',f.latitude,'longitude',f.longitude,'visibility',f.visibility,'origin',f.origin,'source_label',f.source_label) order by f.field_key)
   from public.profile_about_structured_fields f where f.page_id=p.id and
    (editor_load or f.visibility<>'hidden' and (f.visibility='profile_access' or audience in('linked','team') and f.visibility='linked' or audience='team' and f.visibility='team'))),'[]'::jsonb),
  'sections',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'type',s.section_type,'title',s.title,'body',s.body,'items',s.items,'position',s.position,'visibility',s.visibility,'state',s.state,'origin',s.origin) order by s.position)
   from public.profile_about_sections s where s.page_id=p.id and
    (editor_load and s.state<>'archived' or not editor_load and s.state='published' and s.visibility<>'hidden' and
     (s.visibility='profile_access' or audience in('linked','team') and s.visibility='linked' or audience='team' and s.visibility='team'))),'[]'::jsonb));
end$$;


ALTER FUNCTION "public"."get_profile_about"("p_subject_type" "text", "p_subject_id" "uuid", "p_preview_audience" "text") OWNER TO "postgres";


