CREATE OR REPLACE FUNCTION "public"."meal_plan_finalize_image_upload"("p_request_id" "uuid", "p_checksum_sha256" "text", "p_alt_text" "text" DEFAULT NULL::"text", "p_replace_asset_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.meal_plan_finalize_image_upload(
    p_request_id, p_checksum_sha256, p_alt_text, p_replace_asset_id
  );
$$;


ALTER FUNCTION "public"."meal_plan_finalize_image_upload"("p_request_id" "uuid", "p_checksum_sha256" "text", "p_alt_text" "text", "p_replace_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."meal_plan_get"("p_meal_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare plan public.meal_plans;
begin
  if auth.uid() is null or not app_private.has_platform_permission('meal_plans.read') then
    raise insufficient_privilege using message = 'meal plans read permission required';
  end if;
  select * into plan from public.meal_plans where id = p_meal_plan_id;
  if not found then raise no_data_found using message = 'meal plan not found'; end if;
  return public.meal_plan_json(plan);
end;
$$;


