CREATE OR REPLACE FUNCTION "public"."meal_plan_image_download_descriptor"("p_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.meal_plan_image_download_descriptor(p_asset_id);
$$;


