CREATE TABLE IF NOT EXISTS "public"."meal_plans" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "institution_id" "uuid",
    "unit_id" "uuid",
    "class_id" "uuid",
    "person_id" "uuid",
    "name" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "source_type" "text" DEFAULT 'global'::"text" NOT NULL,
    "scope_level" "text" DEFAULT 'global'::"text" NOT NULL,
    "scope_id" "text" DEFAULT ''::"text" NOT NULL,
    "start_date" "date" NOT NULL,
    "end_date" "date" NOT NULL,
    "recurrence" "jsonb" DEFAULT '{"kind": "singleWeek", "excludedDates": []}'::"jsonb" NOT NULL,
    "menu" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "allergens" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "alerts" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "attachments_meta" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "priority" integer DEFAULT 0 NOT NULL,
    "conflict_state" boolean DEFAULT false NOT NULL,
    "revision" integer DEFAULT 1 NOT NULL,
    "is_draft" boolean DEFAULT true NOT NULL,
    "requires_review" boolean DEFAULT false NOT NULL,
    "inheritance_origin_id" "uuid",
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "plan_variant" "text" DEFAULT 'simple'::"text" NOT NULL,
    "audience_segment" "text" DEFAULT 'students'::"text" NOT NULL,
    "visibility_mode" "text" DEFAULT 'immediate'::"text" NOT NULL,
    "visible_from" timestamp with time zone,
    "source_template_id" "uuid",
    "source_template_version" integer,
    "scope_rules" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "excluded_dates" "date"[] DEFAULT '{}'::"date"[] NOT NULL,
    "exceptions" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "simple_image_meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "simple_image_alt" "text",
    "simple_notes" "text",
    CONSTRAINT "meal_plans_audience_segment_check" CHECK (("audience_segment" = ANY (ARRAY['students'::"text", 'staff'::"text", 'all'::"text"]))),
    CONSTRAINT "meal_plans_check" CHECK (("end_date" >= "start_date")),
    CONSTRAINT "meal_plans_check1" CHECK (((("scope_level" = 'global'::"text") AND ("scope_id" = ''::"text")) OR ("scope_id" <> ''::"text"))),
    CONSTRAINT "meal_plans_name_check" CHECK ((("length"("btrim"("name")) >= 1) AND ("length"("btrim"("name")) <= 240))),
    CONSTRAINT "meal_plans_plan_variant_check" CHECK (("plan_variant" = ANY (ARRAY['simple'::"text", 'complete'::"text"]))),
    CONSTRAINT "meal_plans_priority_check" CHECK (("priority" >= 0)),
    CONSTRAINT "meal_plans_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "meal_plans_scope_level_check" CHECK (("scope_level" = ANY (ARRAY['global'::"text", 'institution'::"text", 'unit'::"text", 'classLevel'::"text", 'activity'::"text", 'person'::"text"]))),
    CONSTRAINT "meal_plans_scope_rules_array_check" CHECK (("jsonb_typeof"("scope_rules") = 'object'::"text")),
    CONSTRAINT "meal_plans_source_template_version_check" CHECK (((("source_template_id" IS NULL) AND ("source_template_version" IS NULL)) OR (("source_template_id" IS NOT NULL) AND ("source_template_version" > 0)))),
    CONSTRAINT "meal_plans_source_type_check" CHECK (("source_type" = ANY (ARRAY['global'::"text", 'institution'::"text", 'unit'::"text", 'classLevel'::"text", 'person'::"text", 'exception'::"text"]))),
    CONSTRAINT "meal_plans_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'inReview'::"text", 'scheduled'::"text", 'published'::"text", 'updated'::"text", 'closed'::"text", 'archived'::"text"]))),
    CONSTRAINT "meal_plans_visibility_check" CHECK (((("visibility_mode" = 'immediate'::"text") AND ("visible_from" IS NULL)) OR (("visibility_mode" = 'scheduled'::"text") AND ("visible_from" IS NOT NULL))))
);

