CREATE OR REPLACE FUNCTION "public"."meal_plan_template_list"("p_query" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  search_text text := btrim(coalesce(p_query ->> 'search', ''));
  page_number integer := greatest(coalesce((p_query ->> 'page')::integer, 0), 0);
  page_size integer := least(greatest(coalesce((p_query ->> 'pageSize')::integer, 12), 1), 100);
  total_count bigint;
  result_items jsonb;
begin
  if auth.uid() is null or not app_private.has_platform_permission('meal_plans.read') then
    raise insufficient_privilege using message = 'meal plans read permission required';
  end if;

  select count(*) into total_count
  from public.meal_plan_templates template
  where app_private.meal_plan_scope_allowed(template.tenant_id, template.institution_id)
    and (search_text = '' or template.name ilike '%' || search_text || '%')
    and (nullif(p_query ->> 'institutionId', '') is null or template.institution_id = (p_query ->> 'institutionId')::uuid)
    and (nullif(p_query ->> 'status', '') is null or template.status = p_query ->> 'status')
    and (nullif(p_query ->> 'planVariant', '') is null or template.plan_variant = p_query ->> 'planVariant')
    and (nullif(p_query ->> 'audienceSegment', '') is null or template.audience_segment = p_query ->> 'audienceSegment');

  select coalesce(jsonb_agg(row_payload order by updated_at desc), '[]'::jsonb)
  into result_items
  from (
    select jsonb_build_object(
      'id', template.id,
      'tenantId', template.tenant_id,
      'institutionId', template.institution_id,
      'name', template.name,
      'description', template.description,
      'planVariant', template.plan_variant,
      'audienceSegment', template.audience_segment,
      'status', template.status,
      'version', template.current_version,
      'payload', template.payload,
      'sourceMealPlanId', template.source_meal_plan_id,
      'createdBy', template.created_by,
      'updatedBy', template.updated_by,
      'publishedAt', template.published_at,
      'createdAt', template.created_at,
      'updatedAt', template.updated_at
    ) as row_payload, template.updated_at
    from public.meal_plan_templates template
    where app_private.meal_plan_scope_allowed(template.tenant_id, template.institution_id)
      and (search_text = '' or template.name ilike '%' || search_text || '%')
      and (nullif(p_query ->> 'institutionId', '') is null or template.institution_id = (p_query ->> 'institutionId')::uuid)
      and (nullif(p_query ->> 'status', '') is null or template.status = p_query ->> 'status')
      and (nullif(p_query ->> 'planVariant', '') is null or template.plan_variant = p_query ->> 'planVariant')
      and (nullif(p_query ->> 'audienceSegment', '') is null or template.audience_segment = p_query ->> 'audienceSegment')
    order by template.updated_at desc
    offset page_number * page_size limit page_size
  ) page_rows;

  return jsonb_build_object(
    'items', result_items,
    'total', total_count,
    'limit', page_size,
    'offset', page_number * page_size
  );
end;
$$;


ALTER FUNCTION "public"."meal_plan_template_list"("p_query" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."meal_plan_template_save"("p_template_id" "uuid", "p_payload" "jsonb", "p_expected_version" integer DEFAULT 0, "p_publish" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'app_private'
    AS $$
declare
  actor_id uuid := app_private.current_person_id();
  requested_institution_id uuid := nullif(p_payload ->> 'institutionId', '')::uuid;
  requested_tenant_id uuid := coalesce(requested_institution_id, nullif(p_payload ->> 'tenantId', '')::uuid);
  template public.meal_plan_templates;
  next_version integer;
  template_name text := btrim(coalesce(p_payload ->> 'name', ''));
  template_variant text := coalesce(p_payload ->> 'planVariant', 'simple');
  template_audience text := coalesce(p_payload ->> 'audienceSegment', 'students');
begin
  if auth.uid() is null or actor_id is null or not app_private.has_platform_permission('meal_plans.manage') then
    raise insufficient_privilege using message = 'meal plans manage permission required';
  end if;
  if requested_tenant_id is null or template_name = '' then
    raise invalid_parameter_value using message = 'template tenant and name are required';
  end if;
  if template_variant not in ('simple', 'complete') or template_audience not in ('students', 'staff', 'all') then
    raise invalid_parameter_value using message = 'invalid template variant or audience';
  end if;
  if not app_private.meal_plan_scope_allowed(requested_tenant_id, requested_institution_id) then
    raise insufficient_privilege using message = 'template scope is not allowed';
  end if;

  if p_template_id is null then
    insert into public.meal_plan_templates(
      tenant_id, institution_id, name, description, plan_variant, audience_segment,
      status, current_version, payload, source_meal_plan_id, created_by, updated_by,
      published_at
    ) values (
      requested_tenant_id, requested_institution_id, template_name, nullif(p_payload ->> 'description', ''),
      template_variant, template_audience, case when p_publish then 'published' else 'draft' end,
      1, p_payload, nullif(p_payload ->> 'sourceMealPlanId', '')::uuid, actor_id, actor_id,
      case when p_publish then now() else null end
    ) returning * into template;
    next_version := 1;
  else
    select candidate.* into template
    from public.meal_plan_templates candidate
    where candidate.id = p_template_id
      and app_private.meal_plan_scope_allowed(candidate.tenant_id, candidate.institution_id)
    for update;
    if not found then
      raise no_data_found using message = 'meal plan template not found';
    end if;
    if template.current_version <> p_expected_version then
      raise exception 'meal plan template version conflict' using errcode = 'P0003';
    end if;
    if template.tenant_id <> requested_tenant_id then
      raise insufficient_privilege using message = 'template tenant cannot be changed';
    end if;
    next_version := template.current_version + 1;
    update public.meal_plan_templates set
      institution_id = requested_institution_id,
      name = template_name,
      description = nullif(p_payload ->> 'description', ''),
      plan_variant = template_variant,
      audience_segment = template_audience,
      status = case when p_publish then 'published' else 'draft' end,
      current_version = next_version,
      payload = p_payload,
      updated_by = actor_id,
      published_at = case when p_publish then coalesce(published_at, now()) else null end,
      archived_at = null,
      updated_at = now()
    where id = template.id
    returning * into template;
  end if;

  insert into public.meal_plan_template_versions(
    template_id, tenant_id, version, name, plan_variant, audience_segment,
    payload, change_summary, created_by
  ) values (
    template.id, template.tenant_id, next_version, template.name, template.plan_variant,
    template.audience_segment, template.payload, nullif(p_payload ->> 'changeSummary', ''), actor_id
  );

  return public.meal_plan_template_get(template.id);
end;
$$;


ALTER FUNCTION "public"."meal_plan_template_save"("p_template_id" "uuid", "p_payload" "jsonb", "p_expected_version" integer, "p_publish" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_circular_media_upload"("p_request_id" "uuid", "p_institution_id" "uuid", "p_circular_id" "uuid", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor record; target public.circulars%rowtype; asset public.circular_media_assets%rowtype; max_bytes bigint;
begin
  select * into target from public.circulars c where c.id=p_circular_id and c.institution_id=p_institution_id and c.working_revision_id is not null and c.deleted_at is null;
  if target.id is null then raise insufficient_privilege using message='circular_not_authorized'; end if;
  select * into actor from app_private.circular_actor(p_institution_id,'circulars.circulars.create',target.unit_id,target.group_id);
  if target.author_person_id<>actor.person_id then raise insufficient_privilege using message='circular_not_authorized'; end if;
  max_bytes:=case when p_mime_type in ('image/jpeg','image/png','image/webp') then 10485760 when p_mime_type='video/mp4' then 26214400 when p_mime_type='application/pdf' then 5242880 end;
  if max_bytes is null or p_byte_size not between 1 and max_bytes then raise check_violation using message='circular_media_invalid'; end if;
  select * into asset from public.circular_media_assets m where m.circular_id=target.id and m.upload_request_id=p_request_id;
  if asset.id is null then
    if (select count(*) from public.circular_media_assets m where m.circular_id=target.id and m.status<>'deleted')>=4 then raise check_violation using message='circular_media_limit'; end if;
    insert into public.circular_media_assets(circular_id,institution_id,owner_person_id,upload_request_id,object_key,original_name,mime_type,byte_size)
    values(target.id,p_institution_id,actor.person_id,p_request_id,p_institution_id::text||'/circulars/'||target.id::text||'/'||gen_random_uuid()::text,p_name,p_mime_type,p_byte_size)
    returning * into asset;
  elsif asset.owner_person_id<>actor.person_id or asset.mime_type<>p_mime_type or asset.byte_size<>p_byte_size then
    raise insufficient_privilege using message='upload_request_conflict';
  elsif asset.status not in ('pending','ready') then
    raise insufficient_privilege using message='upload_request_expired';
  end if;
  if asset.status='pending' then
    update public.circular_media_assets set upload_authorized_until=now()+interval '2 hours' where id=asset.id returning * into asset;
  end if;
  return jsonb_build_object('asset_id',asset.id,'bucket_id',asset.bucket_id,'object_key',asset.object_key,'expected_mime_type',asset.mime_type,'expected_byte_size',asset.byte_size,'status',asset.status,'upload_authorized_until',asset.upload_authorized_until);
end $$;


ALTER FUNCTION "public"."prepare_circular_media_upload"("p_request_id" "uuid", "p_institution_id" "uuid", "p_circular_id" "uuid", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_happens_media_upload"("p_request_id" "text", "p_institution_id" "uuid", "p_post_id" "uuid", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor record;asset public.media_assets%rowtype;target public.posts%rowtype;key text;
begin
  select * into target from public.posts where id=p_post_id and institution_id=p_institution_id and status='draft';
  if target.id is null then raise insufficient_privilege using message='post_not_authorized';end if;
  select * into actor from app_private.happens_actor(p_institution_id,'happens.posts.create',target.unit_id,target.group_id);
  if target.author_person_id<>actor.person_id then raise insufficient_privilege using message='post_not_authorized';end if;
  if p_mime_type not in('image/jpeg','image/png','image/webp','video/mp4') then raise check_violation using message='unsupported_media_type';end if;
  select * into asset from public.media_assets where post_id=p_post_id and upload_request_id=p_request_id;
  if asset.id is not null then
    if asset.owner_person_id<>actor.person_id or asset.mime_type<>p_mime_type or asset.byte_size<>p_byte_size then raise insufficient_privilege using message='upload_request_conflict';end if;
    return jsonb_build_object('asset_id',asset.id,'bucket_id',asset.bucket_id,'object_key',asset.object_key);
  end if;
  key:=p_institution_id::text||'/'||p_post_id::text||'/'||gen_random_uuid()::text;
  insert into public.media_assets(institution_id,post_id,owner_person_id,upload_request_id,object_key,original_name,mime_type,byte_size) values(p_institution_id,p_post_id,actor.person_id,p_request_id,key,p_name,p_mime_type,p_byte_size) returning * into asset;
  return jsonb_build_object('asset_id',asset.id,'bucket_id',asset.bucket_id,'object_key',asset.object_key);
end $$;


ALTER FUNCTION "public"."prepare_happens_media_upload"("p_request_id" "text", "p_institution_id" "uuid", "p_post_id" "uuid", "p_name" "text", "p_mime_type" "text", "p_byte_size" bigint) OWNER TO "postgres";


