CREATE OR REPLACE FUNCTION "public"."superadmin_complete_institution_export"("p_import_job_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_checksum_sha256" "text", "p_row_count" integer) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
