CREATE OR REPLACE FUNCTION "public"."superadmin_people_filter_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.assert_people_permission('people.read');
  return jsonb_build_object(
    'institutions', coalesce((
      select jsonb_agg(
        jsonb_build_object('id', institution.id, 'label', institution.public_name)
        order by lower(institution.public_name), institution.id
      )
      from public.institutions institution
      where institution.deleted_at is null
    ), '[]'::jsonb),
    'units', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', unit.id,
          'label', unit.name,
          'institution_id', unit.institution_id
        )
        order by lower(unit.name), unit.id
      )
      from public.units unit
      where unit.status = 'active'
    ), '[]'::jsonb),
    'groups', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', group_row.id,
          'label', group_row.name,
          'institution_id', group_row.institution_id,
          'unit_id', group_row.unit_id
        )
        order by lower(group_row.name), group_row.id
      )
      from public.groups group_row
      where group_row.status = 'active'
    ), '[]'::jsonb),
    'roles', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', role.id,
          'label', role.name,
          'code', role.code,
          'institution_id', role.institution_id
        )
        order by lower(role.name), role.institution_id, role.id
      )
      from public.institution_roles role
      where role.status = 'active'
    ), '[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "public"."superadmin_people_filter_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_people_list"("p_search" "text" DEFAULT ''::"text", "p_types" "public"."person_type"[] DEFAULT ARRAY[]::"public"."person_type"[], "p_statuses" "public"."record_status"[] DEFAULT ARRAY[]::"public"."record_status"[], "p_institution_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_unit_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_group_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_contextual_roles" "text"[] DEFAULT ARRAY[]::"text"[], "p_auth_links" "text"[] DEFAULT ARRAY[]::"text"[], "p_sort" "text" DEFAULT 'display_name'::"text", "p_sort_ascending" boolean DEFAULT true, "p_offset" integer DEFAULT 0, "p_limit" integer DEFAULT 11) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
begin
  perform app_private.assert_people_permission('people.read');
  if p_offset < 0 then
    raise invalid_parameter_value using message = 'offset must not be negative';
  end if;
  if p_limit not in (8, 11, 20, 50, 100) then
    raise invalid_parameter_value using
      message = 'limit must be 8, 11, 20, 50 or 100';
  end if;
  if p_sort not in (
    'display_name', 'type', 'status', 'institution_name', 'unit_name',
    'group_name', 'contextual_role', 'auth_link'
  ) then
    raise invalid_parameter_value using message = 'unsupported people sort';
  end if;
  if exists (
    select 1
    from public.units unit
    where unit.id = any(coalesce(p_unit_ids, array[]::uuid[]))
      and cardinality(coalesce(p_institution_ids, array[]::uuid[])) > 0
      and not unit.institution_id = any(p_institution_ids)
  ) then
    raise check_violation using message = 'unit filter crosses institution selection';
  end if;
  if exists (
    select 1
    from public.groups group_row
    where group_row.id = any(coalesce(p_group_ids, array[]::uuid[]))
      and (
        (
          cardinality(coalesce(p_institution_ids, array[]::uuid[])) > 0
          and not group_row.institution_id = any(p_institution_ids)
        )
        or (
          cardinality(coalesce(p_unit_ids, array[]::uuid[])) > 0
          and not group_row.unit_id = any(p_unit_ids)
        )
      )
  ) then
    raise check_violation using message = 'group filter crosses selected context';
  end if;

  with context_rows as (
    select
      membership.person_id,
      assignment.id as row_id,
      assignment.id as assignment_id,
      membership.id as membership_id,
      null::uuid as child_context_id,
      membership.institution_id,
      institution.public_name as institution_name,
      assignment.scope_unit_id as unit_id,
      unit.name as unit_name,
      assignment.scope_group_id as group_id,
      group_row.name as group_name,
      role.code as contextual_role,
      role.name as contextual_role_name
    from public.institution_memberships membership
    join public.institution_role_assignments assignment
      on assignment.membership_id = membership.id
      and assignment.status = 'active'
    join public.institution_roles role on role.id = assignment.role_id
    join public.institutions institution
      on institution.id = membership.institution_id
    left join public.units unit on unit.id = assignment.scope_unit_id
    left join public.groups group_row on group_row.id = assignment.scope_group_id
    where membership.status = 'active'
      and membership.revoked_at is null
    union all
    select
      child_context.child_person_id,
      child_context.id,
      null::uuid,
      null::uuid,
      child_context.id,
      child_context.institution_id,
      institution.public_name,
      unit_link.unit_id,
      unit.name,
      group_link.group_id,
      group_row.name,
      'student',
      'Aluno'
    from public.child_contexts child_context
    join public.institutions institution
      on institution.id = child_context.institution_id
    left join public.child_unit_links unit_link
      on unit_link.child_context_id = child_context.id
      and unit_link.status in ('pending', 'awaiting_allocation', 'active')
      and unit_link.revoked_at is null
    left join public.units unit on unit.id = unit_link.unit_id
    left join public.child_group_links group_link
      on group_link.child_unit_link_id = unit_link.id
      and group_link.status = 'active'
    left join public.groups group_row on group_row.id = group_link.group_id
    where child_context.status = 'active'
  ),
  context_summary as (
    select
      context_row.person_id,
      min(lower(context_row.institution_name)) as institution_sort,
      min(lower(context_row.unit_name)) as unit_sort,
      min(lower(context_row.group_name)) as group_sort,
      min(lower(context_row.contextual_role_name)) as role_sort
    from context_rows context_row
    group by context_row.person_id
  ),
  filtered as (
    select
      person.id,
      person.display_name,
      person.person_type,
      person.status,
      person.updated_at,
      coalesce(context_summary.institution_sort, '') as institution_sort,
      coalesce(context_summary.unit_sort, '') as unit_sort,
      coalesce(context_summary.group_sort, '') as group_sort,
      coalesce(context_summary.role_sort, '') as role_sort,
      case
        when exists (
          select 1 from public.person_auth_links auth_link
          where auth_link.person_id = person.id
            and auth_link.status = 'active'
            and auth_link.revoked_at is null
        ) then 'linked'
        when exists (
          select 1 from public.person_auth_links auth_link
          where auth_link.person_id = person.id
            and auth_link.revoked_at is null
        ) then 'pending'
        else 'unlinked'
      end as auth_link_state
    from public.people person
    left join context_summary on context_summary.person_id = person.id
    where person.deleted_at is null
      and (
        nullif(btrim(coalesce(p_search, '')), '') is null
        or person.display_name ilike '%' || btrim(p_search) || '%'
      )
      and (
        cardinality(coalesce(p_types, array[]::public.person_type[])) = 0
        or person.person_type = any(p_types)
      )
      and (
        cardinality(coalesce(p_statuses, array[]::public.record_status[])) = 0
        or person.status = any(p_statuses)
      )
      and (
        cardinality(coalesce(p_auth_links, array[]::text[])) = 0
        or (
          case
            when exists (
              select 1 from public.person_auth_links auth_link
              where auth_link.person_id = person.id
                and auth_link.status = 'active'
                and auth_link.revoked_at is null
            ) then 'linked'
            when exists (
              select 1 from public.person_auth_links auth_link
              where auth_link.person_id = person.id
                and auth_link.revoked_at is null
            ) then 'pending'
            else 'unlinked'
          end
        ) = any(p_auth_links)
      )
      and (
        (
          cardinality(coalesce(p_institution_ids, array[]::uuid[])) = 0
          and cardinality(coalesce(p_unit_ids, array[]::uuid[])) = 0
          and cardinality(coalesce(p_group_ids, array[]::uuid[])) = 0
          and cardinality(coalesce(p_contextual_roles, array[]::text[])) = 0
        )
        or exists (
          select 1
          from context_rows context_row
          where context_row.person_id = person.id
            and (
              cardinality(coalesce(p_institution_ids, array[]::uuid[])) = 0
              or context_row.institution_id = any(p_institution_ids)
            )
            and (
              cardinality(coalesce(p_unit_ids, array[]::uuid[])) = 0
              or context_row.unit_id = any(p_unit_ids)
            )
            and (
              cardinality(coalesce(p_group_ids, array[]::uuid[])) = 0
              or context_row.group_id = any(p_group_ids)
            )
            and (
              cardinality(coalesce(p_contextual_roles, array[]::text[])) = 0
              or context_row.contextual_role = any(p_contextual_roles)
            )
        )
      )
  ),
  ranked as (
    select
      filtered.*,
      row_number() over (
        order by
          case when p_sort_ascending and p_sort = 'display_name'
            then lower(display_name) end asc,
          case when not p_sort_ascending and p_sort = 'display_name'
            then lower(display_name) end desc,
          case when p_sort_ascending and p_sort = 'type'
            then person_type::text end asc,
          case when not p_sort_ascending and p_sort = 'type'
            then person_type::text end desc,
          case when p_sort_ascending and p_sort = 'status'
            then status::text end asc,
          case when not p_sort_ascending and p_sort = 'status'
            then status::text end desc,
          case when p_sort_ascending and p_sort = 'institution_name'
            then institution_sort end asc,
          case when not p_sort_ascending and p_sort = 'institution_name'
            then institution_sort end desc,
          case when p_sort_ascending and p_sort = 'unit_name'
            then unit_sort end asc,
          case when not p_sort_ascending and p_sort = 'unit_name'
            then unit_sort end desc,
          case when p_sort_ascending and p_sort = 'group_name'
            then group_sort end asc,
          case when not p_sort_ascending and p_sort = 'group_name'
            then group_sort end desc,
          case when p_sort_ascending and p_sort = 'contextual_role'
            then role_sort end asc,
          case when not p_sort_ascending and p_sort = 'contextual_role'
            then role_sort end desc,
          case when p_sort_ascending and p_sort = 'auth_link'
            then auth_link_state end asc,
          case when not p_sort_ascending and p_sort = 'auth_link'
            then auth_link_state end desc,
          lower(display_name),
          id
      ) as ordinal
    from filtered
  ),
  page_rows as (
    select *
    from ranked
    where ordinal > p_offset
      and ordinal <= p_offset + p_limit
  ),
  membership_payloads as (
    select
      page_row.id as person_id,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', context_row.row_id,
            'assignment_id', context_row.assignment_id,
            'membership_id', context_row.membership_id,
            'child_context_id', context_row.child_context_id,
            'institution_id', context_row.institution_id,
            'institution_name', context_row.institution_name,
            'unit_id', context_row.unit_id,
            'unit_name', context_row.unit_name,
            'group_id', context_row.group_id,
            'group_name', context_row.group_name,
            'role', context_row.contextual_role,
            'role_name', context_row.contextual_role_name
          )
          order by
            lower(context_row.institution_name),
            lower(context_row.unit_name),
            lower(context_row.group_name),
            context_row.row_id
        ) filter (where context_row.row_id is not null),
        '[]'::jsonb
      ) as memberships
    from page_rows page_row
    left join context_rows context_row on context_row.person_id = page_row.id
    group by page_row.id
  )
  select jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', page_row.id,
          'display_name', page_row.display_name,
          'type', page_row.person_type,
          'status', page_row.status,
          'auth_link', page_row.auth_link_state,
          'memberships', membership_payload.memberships,
          'updated_at', page_row.updated_at
        )
        order by page_row.ordinal
      )
      from page_rows page_row
      join membership_payloads membership_payload
        on membership_payload.person_id = page_row.id
    ), '[]'::jsonb),
    'total_count', (select count(*) from filtered)
  )
  into result;
  return result;
end
$$;


ALTER FUNCTION "public"."superadmin_people_list"("p_search" "text", "p_types" "public"."person_type"[], "p_statuses" "public"."record_status"[], "p_institution_ids" "uuid"[], "p_unit_ids" "uuid"[], "p_group_ids" "uuid"[], "p_contextual_roles" "text"[], "p_auth_links" "text"[], "p_sort" "text", "p_sort_ascending" boolean, "p_offset" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_people_update"("p_update" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_variable
declare
  person_id uuid;
  expected_updated_at timestamptz;
  person_type public.person_type;
  normalized_changes jsonb;
begin
  perform app_private.assert_people_permission('people.update');
  if jsonb_typeof(coalesce(p_update, '{}'::jsonb)) <> 'object' then
    raise invalid_parameter_value using message = 'update must be an object';
  end if;
  if exists (
    select 1
    from jsonb_object_keys(coalesce(p_update, '{}'::jsonb)) key
    where key not in (
      'person_id',
      'expected_updated_at',
      'first_name',
      'last_name',
      'display_name',
      'legal_name',
      'context_changes',
      'membership_changes',
      'child_context_changes'
    )
  ) then
    raise invalid_parameter_value using message = 'update field is not editable';
  end if;
  person_id := nullif(p_update ->> 'person_id', '')::uuid;
  expected_updated_at :=
    nullif(p_update ->> 'expected_updated_at', '')::timestamptz;
  select person.person_type
  into person_type
  from public.people person
  where person.id = person_id
    and person.deleted_at is null;
  if not found then
    raise no_data_found using message = 'person not found';
  end if;
  if expected_updated_at is null then
    raise invalid_parameter_value using message = 'expected_updated_at is required';
  end if;

  if p_update ? 'context_changes' then
    if jsonb_typeof(p_update -> 'context_changes') <> 'array' then
      raise invalid_parameter_value using message = 'context_changes must be an array';
    end if;
    normalized_changes := p_update -> 'context_changes';
  else
    select coalesce(jsonb_agg(jsonb_build_object(
      'kind', case
        when person_type = 'adult' then 'institution_membership'
        else 'child_context'
      end,
      'operation', case
        when change ->> 'operation' = 'remove' then 'revoke'
        else change ->> 'operation'
      end,
      'membership_id', change ->> 'membership_id',
      'assignment_id', change ->> 'assignment_id',
      'child_context_id', coalesce(
        change ->> 'child_context_id',
        change ->> 'membership_id'
      ),
      'child_unit_link_id', change ->> 'child_unit_link_id',
      'child_group_link_id', change ->> 'child_group_link_id',
      'institution_id', change ->> 'institution_id',
      'scope_unit_id', change ->> 'unit_id',
      'scope_group_id', change ->> 'group_id',
      'unit_id', change ->> 'unit_id',
      'group_id', change ->> 'group_id',
      'role_code', coalesce(change ->> 'role_code', change ->> 'role')
    )), '[]'::jsonb)
    into normalized_changes
    from jsonb_array_elements(case
      when person_type = 'child'
        then coalesce(p_update -> 'child_context_changes', '[]'::jsonb)
      else coalesce(p_update -> 'membership_changes', '[]'::jsonb)
    end) change;
  end if;

  perform app_private.update_superadmin_person(
    person_id,
    expected_updated_at,
    p_update
      - 'person_id'
      - 'expected_updated_at'
      - 'context_changes'
      - 'membership_changes'
      - 'child_context_changes',
    normalized_changes
  );

  return app_private.superadmin_person_payload(person_id);
end
$$;


ALTER FUNCTION "public"."superadmin_people_update"("p_update" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_plan_get"("p_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_result jsonb;
begin
  perform app_private.assert_plan_permission('platform.read',false);
  select jsonb_build_object(
    'id',p.id,'name',p.name,'code',p.code,'description',p.description,'status',p.status::text,'revision',p.revision,
    'used_by_institution_count',(select count(*) from public.institution_subscriptions s where s.plan_id=p.id and s.status in ('active','draft')),
    'entitlements',coalesce((select jsonb_object_agg(pe.entitlement_key,pe.value_json) from public.plan_entitlements pe where pe.plan_id=p.id and pe.status='active'),'{}'::jsonb),
    'linked_institutions',coalesce((select jsonb_agg(jsonb_build_object(
      'id',i.id,'name',i.legal_name,'subscription_status',s.status::text,'starts_at',s.starts_at,'units_with_override',0
    ) order by i.legal_name,i.id) from public.institution_subscriptions s join public.institutions i on i.id=s.institution_id where s.plan_id=p.id),'[]'::jsonb)
  ) into v_result from public.plans p where p.id=p_plan_id;
  if v_result is null then raise exception using errcode='P0002',message='plan_not_found'; end if;
  return v_result;
end; $$;


ALTER FUNCTION "public"."superadmin_plan_get"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_plan_save"("p_request_id" "uuid", "p_plan_id" "uuid", "p_expected_revision" bigint, "p_payload" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor uuid; v_plan public.plans%rowtype; v_existing public.plans%rowtype; v_key text; v_value jsonb; v_action text;
begin
  v_actor:=app_private.assert_plan_permission('plan.change',true);
  if p_request_id is null then raise exception using errcode='22023',message='request_id_required'; end if;
  if coalesce(char_length(trim(p_reason)),0) not between 1 and 1000 then raise exception using errcode='22023',message='reason_required'; end if;
  if coalesce(char_length(trim(p_payload->>'name')),0) not between 1 and 160 or coalesce(char_length(trim(p_payload->>'description')),0) not between 1 and 2000 then
    raise exception using errcode='22023',message='invalid_plan_identity';
  end if;
  if coalesce(p_payload->>'status','active') not in ('active','archived') then raise exception using errcode='22023',message='invalid_status'; end if;
  select p.* into v_existing from public.plans p join public.plan_change_receipts r on r.plan_id=p.id where r.request_id=p_request_id;
  if found then return public.superadmin_plan_get(v_existing.id); end if;
  if p_plan_id is null then
    if coalesce(p_payload->>'code','') !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then raise exception using errcode='22023',message='invalid_plan_code'; end if;
    insert into public.plans(code,name,description,status,billing_mode,revision,created_by_person_id,updated_by_person_id)
    values(p_payload->>'code',trim(p_payload->>'name'),trim(p_payload->>'description'),(p_payload->>'status')::public.record_status,'manual',1,v_actor,v_actor)
    returning * into v_plan;
    v_action:='create';
  else
    select * into v_existing from public.plans where id=p_plan_id for update;
    if not found then raise exception using errcode='P0002',message='plan_not_found'; end if;
    if p_expected_revision is null or p_expected_revision<>v_existing.revision then raise exception using errcode='40001',message='plan_revision_conflict'; end if;
    if p_payload?'code' and p_payload->>'code'<>v_existing.code then raise exception using errcode='22023',message='plan_code_immutable'; end if;
    update public.plans set name=trim(p_payload->>'name'),description=trim(p_payload->>'description'),
      status=(p_payload->>'status')::public.record_status,revision=revision+1,updated_at=now(),updated_by_person_id=v_actor
    where id=p_plan_id returning * into v_plan;
    v_action:=case when v_existing.status='active' and v_plan.status='archived' then 'archive'
      when v_existing.status='archived' and v_plan.status='active' then 'restore' else 'update' end;
  end if;
  delete from public.plan_entitlements where plan_id=v_plan.id;
  for v_key,v_value in select key,value from jsonb_each(coalesce(p_payload->'entitlements','{}'::jsonb)) loop
    if v_key not in ('feature.communication','feature.agenda','feature.invitations','feature.chat','feature.notices','feature.routine','feature.happens','feature.now','feature.moments','limit.units','limit.memberships','limit.storage_gb','limit.media_gb') then
      raise exception using errcode='22023',message='invalid_entitlement';
    end if;
    if v_key like 'feature.%' and jsonb_typeof(v_value->'enabled')<>'boolean' then raise exception using errcode='22023',message='invalid_feature_value'; end if;
    if v_key like 'limit.%' and (jsonb_typeof(v_value->'value')<>'number' or (v_value->>'value')::numeric<0 or (v_value->>'value')::numeric>100000000) then
      raise exception using errcode='22023',message='invalid_limit_value';
    end if;
    insert into public.plan_entitlements(plan_id,entitlement_key,value_kind,value_json,status)
    values(v_plan.id,v_key,case when v_key like 'feature.%' then 'boolean' else 'integer' end,v_value,'active');
  end loop;
  insert into public.plan_change_receipts(request_id,plan_id,actor_person_id,action,previous_revision,next_revision,reason)
  values(p_request_id,v_plan.id,v_actor,v_action,v_existing.revision,v_plan.revision,trim(p_reason));
  return public.superadmin_plan_get(v_plan.id);
exception when unique_violation then raise exception using errcode='23505',message='plan_code_or_request_conflict';
end; $_$;


ALTER FUNCTION "public"."superadmin_plan_save"("p_request_id" "uuid", "p_plan_id" "uuid", "p_expected_revision" bigint, "p_payload" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."superadmin_plans_list"("p_search" "text" DEFAULT ''::"text", "p_status" "text" DEFAULT NULL::"text", "p_feature" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 11) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_offset integer; v_result jsonb;
begin
  perform app_private.assert_plan_permission('platform.read',false);
  if p_page<1 or p_page_size<1 or p_page_size>100 then raise exception using errcode='22023',message='invalid_pagination'; end if;
  if p_status is not null and p_status not in ('active','archived') then raise exception using errcode='22023',message='invalid_status'; end if;
  if p_feature is not null and p_feature not in ('communication','agenda','invitations','chat','notices','routine','happens','now','moments') then
    raise exception using errcode='22023',message='invalid_feature';
  end if;
  v_offset := (p_page-1)*p_page_size;
  with filtered as (
    select p.* from public.plans p
    where (coalesce(trim(p_search),'')='' or p.name ilike '%'||trim(p_search)||'%' or p.code ilike '%'||trim(p_search)||'%')
      and (p_status is null or p.status::text=p_status)
      and (p_feature is null or exists(
        select 1 from public.plan_entitlements pe where pe.plan_id=p.id and pe.entitlement_key='feature.'||p_feature
          and pe.status='active' and coalesce((pe.value_json->>'enabled')::boolean,false)
      ))
  ), page_rows as (
    select * from filtered order by name,id limit p_page_size offset v_offset
  )
  select jsonb_build_object(
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'id',pr.id,'name',pr.name,'code',pr.code,'description',pr.description,'status',pr.status::text,'revision',pr.revision,
      'used_by_institution_count',(select count(*) from public.institution_subscriptions s where s.plan_id=pr.id and s.status in ('active','draft')),
      'entitlements',coalesce((select jsonb_object_agg(pe.entitlement_key,pe.value_json) from public.plan_entitlements pe where pe.plan_id=pr.id and pe.status='active'),'{}'::jsonb)
    ) order by pr.name,pr.id),'[]'::jsonb),
    'total_items',(select count(*) from filtered),'page',p_page,'page_size',p_page_size
  ) into v_result from page_rows pr;
  return v_result;
end; $$;


