    CONSTRAINT "form_multipart_uploads_bucket_ck" CHECK (("bucket_id" = 'coelo-forms-private'::"text")),
    CONSTRAINT "form_multipart_uploads_path_ck" CHECK (("object_path" ~ '^[0-9a-f]{2}/[0-9a-f-]{36}$'::"text")),
    CONSTRAINT "form_multipart_uploads_progress_ck" CHECK (((("next_part_number" >= 1) AND ("next_part_number" <= 10001)) AND ("uploaded_bytes" >= 0))),
    CONSTRAINT "form_multipart_uploads_state_ck" CHECK (("state" = ANY (ARRAY['initiated'::"text", 'uploading'::"text", 'completed'::"text", 'aborted'::"text"]))),
    CONSTRAINT "form_multipart_uploads_terminal_ck" CHECK (((("state" = 'completed'::"text") = ("completed_at" IS NOT NULL)) AND (("state" = 'aborted'::"text") = ("aborted_at" IS NOT NULL)))),
    CONSTRAINT "form_multipart_uploads_upload_id_ck" CHECK (((("length"("btrim"("upload_id")) >= 1) AND ("length"("btrim"("upload_id")) <= 1024)) AND ("upload_id" !~ '[[:cntrl:]]'::"text")))
);


