    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "gate_code" "text" NOT NULL,
    "gate_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "evidence_reference" "text",
    "decision_reason" "text",
    "decided_by_person_id" "uuid",
    "decided_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "health_domain_release_gates_code_check" CHECK (("gate_code" = ANY (ARRAY['legal_basis_and_retention'::"text", 'private_document_storage'::"text", 'security_lgpd_review'::"text", 'technical_spec'::"text", 'threat_model'::"text"]))),
    CONSTRAINT "health_domain_release_gates_decision_check" CHECK (((("gate_status" = 'pending'::"text") AND ("decided_by_person_id" IS NULL) AND ("decided_at" IS NULL)) OR (("gate_status" = ANY (ARRAY['approved'::"text", 'rejected'::"text"])) AND ("decided_by_person_id" IS NOT NULL) AND ("decided_at" IS NOT NULL) AND (NULLIF("btrim"("evidence_reference"), ''::"text") IS NOT NULL) AND (NULLIF("btrim"("decision_reason"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "health_domain_release_gates_status_check" CHECK (("gate_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text"])))
);


ALTER TABLE "app_private"."health_domain_release_gates" OWNER TO "postgres";


