    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "person_id" "uuid" NOT NULL,
    "identifier_kind" "text" NOT NULL,
    "normalized_value_hmac" "bytea" NOT NULL,
    "hmac_key_version" smallint NOT NULL,
    "masked_value" "text" NOT NULL,
    "verification_method" "text",
    "verified_at" timestamp with time zone,
    "status" "public"."record_status" DEFAULT 'active'::"public"."record_status" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "revoked_at" timestamp with time zone,
    CONSTRAINT "person_identity_identifiers_hmac_check" CHECK ((("octet_length"("normalized_value_hmac") = 32) AND ("hmac_key_version" > 0))),
    CONSTRAINT "person_identity_identifiers_kind_check" CHECK (("identifier_kind" = 'cpf'::"text")),
    CONSTRAINT "person_identity_identifiers_lifecycle_check" CHECK (((("status" = 'active'::"public"."record_status") AND ("revoked_at" IS NULL)) OR (("status" <> 'active'::"public"."record_status") AND ("revoked_at" IS NOT NULL)))),
    CONSTRAINT "person_identity_identifiers_mask_check" CHECK (("masked_value" ~ '^\*{3}\.\*{3}\.\*{3}-[0-9]{2}$'::"text")),
    CONSTRAINT "person_identity_identifiers_verification_check" CHECK (((("verified_at" IS NULL) AND ("verification_method" IS NULL)) OR (("verified_at" IS NOT NULL) AND ("verification_method" = ANY (ARRAY['document_evidence'::"text", 'authoritative_source'::"text"])))))
);


ALTER TABLE "app_private"."person_identity_identifiers" OWNER TO "postgres";


COMMENT ON TABLE "app_private"."person_identity_identifiers" IS 'Keyed HMAC identity catalog. Raw CPF values are forbidden.';



