CREATE TABLE IF NOT EXISTS "public"."agenda_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "context_kind" "text" NOT NULL,
    "context_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "item_type" "text" NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "origin" "text" DEFAULT 'institution'::"text" NOT NULL,
    "starts_at" timestamp with time zone NOT NULL,
    "ends_at" timestamp with time zone NOT NULL,
    "all_day" boolean DEFAULT false NOT NULL,
    "time_zone_id" "text" DEFAULT 'America/Sao_Paulo'::"text" NOT NULL,
    "location" "text" DEFAULT ''::"text" NOT NULL,
    "description" "text" DEFAULT ''::"text" NOT NULL,
    "response_mode" "text" DEFAULT 'none'::"text" NOT NULL,
    "guardian_response_policy" "text" DEFAULT 'oneIsEnough'::"text" NOT NULL,
    "recurrence" "jsonb",
    "audience" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "reminders" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "questions" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "created_by_person_id" "uuid" NOT NULL,
    "updated_by_person_id" "uuid" NOT NULL,
    "revision" bigint DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "agenda_events_audience_check" CHECK (("jsonb_typeof"("audience") = 'object'::"text")),
    CONSTRAINT "agenda_events_check" CHECK (("ends_at" > "starts_at")),
    CONSTRAINT "agenda_events_context_kind_check" CHECK (("context_kind" = ANY (ARRAY['institution'::"text", 'unit'::"text", 'group'::"text", 'activity'::"text"]))),
    CONSTRAINT "agenda_events_description_check" CHECK (("char_length"("description") <= 10000)),
    CONSTRAINT "agenda_events_guardian_response_policy_check" CHECK (("guardian_response_policy" = ANY (ARRAY['oneIsEnough'::"text", 'allMustRespond'::"text"]))),
    CONSTRAINT "agenda_events_item_type_check" CHECK (("item_type" = ANY (ARRAY['event'::"text", 'recurringRoutine'::"text", 'birthday'::"text", 'holidayOrBreak'::"text", 'appointment'::"text", 'deadline'::"text", 'operationalChange'::"text", 'resourceReservation'::"text", 'other'::"text"]))),
    CONSTRAINT "agenda_events_location_check" CHECK (("char_length"("location") <= 500)),
    CONSTRAINT "agenda_events_origin_check" CHECK (("origin" = ANY (ARRAY['institution'::"text", 'guardianRequest'::"text"]))),
    CONSTRAINT "agenda_events_priority_check" CHECK (("priority" = ANY (ARRAY['normal'::"text", 'important'::"text", 'urgent'::"text"]))),
    CONSTRAINT "agenda_events_questions_check" CHECK (("jsonb_typeof"("questions") = 'array'::"text")),
    CONSTRAINT "agenda_events_recurrence_check" CHECK ((("recurrence" IS NULL) OR ("jsonb_typeof"("recurrence") = 'object'::"text"))),
    CONSTRAINT "agenda_events_reminders_check" CHECK (("jsonb_typeof"("reminders") = 'array'::"text")),
    CONSTRAINT "agenda_events_response_mode_check" CHECK (("response_mode" = ANY (ARRAY['none'::"text", 'rsvp'::"text", 'acknowledgement'::"text", 'authorization'::"text"]))),
    CONSTRAINT "agenda_events_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "agenda_events_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'scheduled'::"text", 'published'::"text", 'canceled'::"text"]))),
    CONSTRAINT "agenda_events_time_zone_id_check" CHECK ((("char_length"("time_zone_id") >= 1) AND ("char_length"("time_zone_id") <= 100))),
    CONSTRAINT "agenda_events_title_check" CHECK ((("char_length"("title") >= 1) AND ("char_length"("title") <= 240)))
);

