    "session_kind" "text" NOT NULL,
    "session_date" "date" NOT NULL,
    "starts_at" timestamp with time zone,
    "ends_at" timestamp with time zone,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "created_by_person_id" "uuid" NOT NULL,
    "closed_by_person_id" "uuid",
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "attendance_sessions_dates_check" CHECK ((("ends_at" IS NULL) OR ("starts_at" IS NULL) OR ("ends_at" > "starts_at"))),
    CONSTRAINT "attendance_sessions_kind_check" CHECK (((("session_kind" = 'group'::"text") AND ("activity_id" IS NULL)) OR (("session_kind" = 'activity'::"text") AND ("activity_id" IS NOT NULL)))),
    CONSTRAINT "attendance_sessions_session_kind_check" CHECK (("session_kind" = ANY (ARRAY['group'::"text", 'activity'::"text"]))),
    CONSTRAINT "attendance_sessions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'open'::"text", 'closed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."attendance_sessions" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."attendance_summary" WITH ("security_invoker"='true') AS
 SELECT "session_row"."institution_id",
    "session_row"."unit_id",
    "session_row"."group_id",
    "session_row"."activity_id",
    "record_row"."child_context_id",
    "count"(*) FILTER (WHERE ("record_row"."outcome" = 'present'::"text")) AS "present_count",
    "count"(*) FILTER (WHERE ("record_row"."outcome" = 'absent'::"text")) AS "absent_count",
    "count"(*) AS "official_count",
    "round"(((100.0 * ("count"(*) FILTER (WHERE ("record_row"."outcome" <> 'absent'::"text")))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "attendance_percentage"
   FROM ("public"."attendance_records" "record_row"
     JOIN "public"."attendance_sessions" "session_row" ON (("session_row"."id" = "record_row"."attendance_session_id")))
  WHERE ("record_row"."status" = 'active'::"public"."record_status")
  GROUP BY "session_row"."institution_id", "session_row"."unit_id", "session_row"."group_id", "session_row"."activity_id", "record_row"."child_context_id";


ALTER VIEW "public"."attendance_summary" OWNER TO "postgres";


