CREATE TABLE IF NOT EXISTS "public"."form_schedules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "application_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "time_zone" "text" NOT NULL,
    "starts_at_local" timestamp without time zone NOT NULL,
    "recurrence_kind" "text" NOT NULL,
    "interval_value" integer DEFAULT 1 NOT NULL,
    "weekdays" smallint[] DEFAULT '{}'::smallint[] NOT NULL,
    "monthly_day" smallint,
    "monthly_last_day" boolean DEFAULT false NOT NULL,
    "end_kind" "text" DEFAULT 'never'::"text" NOT NULL,
    "ends_on" "date",
    "occurrence_count" integer,
    "management_version" bigint DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "form_schedules_end_ck" CHECK (((("end_kind" = 'never'::"text") AND ("ends_on" IS NULL) AND ("occurrence_count" IS NULL)) OR (("end_kind" = 'date'::"text") AND ("ends_on" IS NOT NULL) AND ("occurrence_count" IS NULL)) OR (("end_kind" = 'count'::"text") AND ("ends_on" IS NULL) AND (("occurrence_count" >= 1) AND ("occurrence_count" <= 10000))))),
    CONSTRAINT "form_schedules_interval_ck" CHECK ((("interval_value" >= 1) AND ("interval_value" <= 365))),
    CONSTRAINT "form_schedules_monthly_ck" CHECK ((("recurrence_kind" <> 'monthly'::"text") OR ("monthly_last_day" AND ("monthly_day" IS NULL)) OR ((NOT "monthly_last_day") AND (("monthly_day" >= 1) AND ("monthly_day" <= 31))))),
    CONSTRAINT "form_schedules_recurrence_ck" CHECK (("recurrence_kind" = ANY (ARRAY['once'::"text", 'daily'::"text", 'weekly'::"text", 'monthly'::"text"]))),
    CONSTRAINT "form_schedules_status_ck" CHECK (("status" = ANY (ARRAY['active'::"text", 'archived'::"text"]))),
    CONSTRAINT "form_schedules_timezone_ck" CHECK (("btrim"("time_zone") <> ''::"text")),
    CONSTRAINT "form_schedules_version_ck" CHECK (("management_version" > 0)),
    CONSTRAINT "form_schedules_weekdays_ck" CHECK ((("weekdays" <@ ARRAY[(1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint, (7)::smallint]) AND (("recurrence_kind" <> 'weekly'::"text") OR (("cardinality"("weekdays") >= 1) AND ("cardinality"("weekdays") <= 7)))))
);

