    CONSTRAINT "institution_contacts_website_url_length_check" CHECK ((("website_url" IS NULL) OR ("char_length"("website_url") <= 2048))),
    CONSTRAINT "institution_contacts_website_url_not_blank" CHECK ((("website_url" IS NULL) OR ("btrim"("website_url") <> ''::"text"))),
    CONSTRAINT "institution_contacts_website_url_shape" CHECK ((("website_url" IS NULL) OR ("btrim"("website_url") ~* '^https?://[[:alnum:]]([[:alnum:].-]*[[:alnum:]])?(:[0-9]{1,5})?([/?#][^[:space:]]*)?$'::"text"))),
    CONSTRAINT "institution_contacts_whatsapp_number_e164_check" CHECK ((("whatsapp_number" IS NULL) OR ("whatsapp_number" ~ '^\+[1-9][0-9]{7,14}$'::"text"))),
    CONSTRAINT "institution_contacts_whatsapp_number_not_blank" CHECK ((("whatsapp_number" IS NULL) OR ("btrim"("whatsapp_number") <> ''::"text")))
