CREATE TABLE IF NOT EXISTS "public"."person_avatar_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "person_id" "uuid" NOT NULL,
    "storage_bucket" "text" DEFAULT 'coelo-person-identities'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "size_bytes" bigint NOT NULL,
    "checksum_sha256" "text",
    "pixel_width" integer NOT NULL,
    "pixel_height" integer NOT NULL,
    "crop_rect" "jsonb" NOT NULL,
    "status" "public"."record_status" DEFAULT 'draft'::"public"."record_status" NOT NULL,
    "created_by_person_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "activated_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    CONSTRAINT "person_avatar_assets_bucket_check" CHECK (("storage_bucket" = 'coelo-person-identities'::"text")),
    CONSTRAINT "person_avatar_assets_checksum_check" CHECK ((("checksum_sha256" IS NULL) OR ("checksum_sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "person_avatar_assets_crop_check" CHECK ((("jsonb_typeof"("crop_rect") = 'object'::"text") AND ("crop_rect" ?& ARRAY['x'::"text", 'y'::"text", 'width'::"text", 'height'::"text"]) AND (((("crop_rect" ->> 'x'::"text"))::numeric >= (0)::numeric) AND ((("crop_rect" ->> 'x'::"text"))::numeric <= (1)::numeric)) AND (((("crop_rect" ->> 'y'::"text"))::numeric >= (0)::numeric) AND ((("crop_rect" ->> 'y'::"text"))::numeric <= (1)::numeric)) AND ((("crop_rect" ->> 'width'::"text"))::numeric > (0)::numeric) AND ((("crop_rect" ->> 'width'::"text"))::numeric <= (1)::numeric) AND ((("crop_rect" ->> 'height'::"text"))::numeric > (0)::numeric) AND ((("crop_rect" ->> 'height'::"text"))::numeric <= (1)::numeric) AND (((("crop_rect" ->> 'x'::"text"))::numeric + (("crop_rect" ->> 'width'::"text"))::numeric) <= (1)::numeric) AND (((("crop_rect" ->> 'y'::"text"))::numeric + (("crop_rect" ->> 'height'::"text"))::numeric) <= (1)::numeric))),
    CONSTRAINT "person_avatar_assets_dimensions_check" CHECK ((("pixel_width" >= 320) AND ("pixel_height" >= 320))),
    CONSTRAINT "person_avatar_assets_mime_check" CHECK (("mime_type" = ANY (ARRAY['image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text"]))),
    CONSTRAINT "person_avatar_assets_path_check" CHECK ((("storage_path" ~ '^people/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/avatars/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$'::"text") AND ("storage_path" !~~ '%..%'::"text"))),
    CONSTRAINT "person_avatar_assets_size_check" CHECK ((("size_bytes" >= 1) AND ("size_bytes" <= 5242880)))
);

