CREATE OR REPLACE VIEW "public"."unit_directory" WITH ("security_invoker"='true') AS
 WITH "gc" AS (
         SELECT "groups"."unit_id",
            ("count"(*))::integer AS "groups_count"
           FROM "public"."groups"
          WHERE ("groups"."status" <> 'archived'::"public"."record_status")
          GROUP BY "groups"."unit_id"
        ), "ac" AS (
         SELECT "activity_unit_links"."unit_id",
            ("count"(DISTINCT "activity_unit_links"."activity_id"))::integer AS "activities_count"
           FROM "public"."activity_unit_links"
          WHERE ("activity_unit_links"."status" <> 'archived'::"public"."record_status")
          GROUP BY "activity_unit_links"."unit_id"
        ), "sc" AS (
         SELECT "l"."unit_id",
            "jsonb_agg"("jsonb_build_object"('id', "s"."id", 'label', "s"."name", 'code', "s"."code") ORDER BY "s"."name") AS "subtypes"
           FROM ("public"."unit_subtype_links" "l"
             JOIN "public"."unit_subtypes" "s" ON (("s"."id" = "l"."unit_subtype_id")))
          WHERE ("s"."status" = 'active'::"public"."record_status")
          GROUP BY "l"."unit_id"
        )
 SELECT "u"."id",
    "u"."institution_id",
    "i"."public_name" AS "institution_name",
    "i"."institution_type_id",
    "it"."name" AS "institution_type_name",
    "u"."name",
    "u"."slug",
    ("u"."status")::"text" AS "unit_status",
    "u"."unit_type_id",
    "ut"."name" AS "unit_type_name",
    "ut"."code" AS "unit_type_code",
    "u"."unit_type_other_description",
    "u"."timezone",
    "u"."handle",
    "u"."public_discovery_enabled",
    "u"."public_address_visible",
    "u"."public_contact_visible",
    "u"."inherit_address",
    "u"."inherit_contact",
    "u"."inherit_branding",
    "u"."inherit_representatives",
    "u"."inherit_administrators",
    "u"."inherit_plan",
    "u"."plan_override_id",
    COALESCE("u"."plan_override_id", "sub"."plan_id") AS "effective_plan_id",
    "p"."code" AS "effective_plan_code",
    "p"."name" AS "effective_plan_name",
    ("to_jsonb"("addr".*) - 'unit_id'::"text") AS "address",
    ("to_jsonb"("contact_record".*) - 'unit_id'::"text") AS "contact",
    ("to_jsonb"("brand".*) - 'unit_id'::"text") AS "branding",
    COALESCE("sc"."subtypes", '[]'::"jsonb") AS "subtypes",
    COALESCE("gc"."groups_count", 0) AS "groups_count",
    COALESCE("ac"."activities_count", 0) AS "activities_count",
    "u"."management_version",
    "u"."created_at",
    "u"."updated_at"
   FROM ((((((((((("public"."units" "u"
     JOIN "public"."institutions" "i" ON (("i"."id" = "u"."institution_id")))
     LEFT JOIN "public"."institution_types" "it" ON (("it"."id" = "i"."institution_type_id")))
     JOIN "public"."unit_types" "ut" ON (("ut"."id" = "u"."unit_type_id")))
     LEFT JOIN LATERAL ( SELECT "s"."plan_id"
           FROM "public"."institution_subscriptions" "s"
          WHERE (("s"."institution_id" = "i"."id") AND ("s"."status" <> ALL (ARRAY['cancelled'::"public"."subscription_status", 'suspended'::"public"."subscription_status"])))
          ORDER BY "s"."created_at" DESC, "s"."id" DESC
         LIMIT 1) "sub" ON (true))
     LEFT JOIN "public"."plans" "p" ON (("p"."id" = COALESCE("u"."plan_override_id", "sub"."plan_id"))))
     LEFT JOIN "public"."unit_addresses" "addr" ON (("addr"."unit_id" = "u"."id")))
     LEFT JOIN "public"."unit_contacts" "contact_record" ON (("contact_record"."unit_id" = "u"."id")))
     LEFT JOIN "public"."unit_branding" "brand" ON (("brand"."unit_id" = "u"."id")))
     LEFT JOIN "sc" ON (("sc"."unit_id" = "u"."id")))
     LEFT JOIN "gc" ON (("gc"."unit_id" = "u"."id")))
     LEFT JOIN "ac" ON (("ac"."unit_id" = "u"."id")))
  WHERE ("i"."deleted_at" IS NULL);


ALTER VIEW "public"."unit_directory" OWNER TO "postgres";


