CREATE TABLE IF NOT EXISTS "public"."unit_identity_media" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "institution_id" "uuid" NOT NULL,
    "unit_id" "uuid" NOT NULL,
    "media_kind" "public"."unit_identity_media_kind" NOT NULL,
    "storage_bucket" "text" DEFAULT 'coelo-unit-identities'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "size_bytes" bigint NOT NULL,
    "checksum_sha256" "text",
    "status" "public"."unit_identity_media_status" DEFAULT 'pending_upload'::"public"."unit_identity_media_status" NOT NULL,
    "replaced_media_id" "uuid",
    "created_by_person_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "activated_at" timestamp with time zone,
    "pending_delete_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "unit_identity_media_bucket_check" CHECK (("storage_bucket" = 'coelo-unit-identities'::"text")),
    CONSTRAINT "unit_identity_media_checksum_check" CHECK ((("checksum_sha256" IS NULL) OR ("checksum_sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "unit_identity_media_mime_check" CHECK (("mime_type" = ANY (ARRAY['image/jpeg'::"text", 'image/png'::"text"]))),
    CONSTRAINT "unit_identity_media_size_check" CHECK ((("size_bytes" >= 1) AND ("size_bytes" <= 5242880))),
    CONSTRAINT "unit_identity_media_storage_path_check" CHECK (("app_private"."unit_identity_path_is_valid"("storage_path") AND ("app_private"."unit_identity_path_institution_id"("storage_path") = "institution_id") AND ("app_private"."unit_identity_path_unit_id"("storage_path") = "unit_id") AND ("app_private"."unit_identity_path_kind"("storage_path") = "media_kind")))
);

