  WHERE (("membership"."id" = "professional_child_assignments"."membership_id") AND "app_private"."has_context_permission"("membership"."institution_id", 'people.assign_children'::"text", NULL::"uuid", NULL::"uuid", NULL::"uuid", "child_context"."id", false)))));



