   FROM ("public"."institution_memberships" "membership"
     JOIN "public"."child_contexts" "child_context" ON ((("child_context"."id" = "professional_child_assignments"."child_context_id") AND ("child_context"."institution_id" = "membership"."institution_id"))))
  WHERE (("membership"."id" = "professional_child_assignments"."membership_id") AND (("membership"."person_id" = "app_private"."current_person_id"()) OR "app_private"."has_context_permission"("membership"."institution_id", 'people.read'::"text", NULL::"uuid", NULL::"uuid", NULL::"uuid", "child_context"."id", false))))));



